import { toast } from './ui/toast';

/**
 * Registers the service worker (production builds only). `sw.js` sits next to index.html, so a
 * relative URL keeps the app working from a subfolder; its scope is that folder.
 *
 * When a new version has been installed while this page runs, says so. The new worker takes over
 * once every tab is closed, so a running game never mixes files from two versions.
 */
export function registerServiceWorker(): void {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  window.addEventListener('load', () => {
    navigator.serviceWorker
      .register(new URL('sw.js', document.baseURI), { scope: './' })
      .then((reg) => {
        reg.addEventListener('updatefound', () => {
          const worker = reg.installing;
          worker?.addEventListener('statechange', () => {
            if (worker.state === 'installed' && navigator.serviceWorker.controller) announceUpdate();
          });
        });
      })
      .catch((err: unknown) => console.warn('Service worker registration failed', err));
  });
}

function announceUpdate(): void {
  toast('A new version of Blockwright is ready. Close every Blockwright tab and reopen it to update.', 'info', 10000);
}
