/**
 * Snapshot interpolation for remote entities (Milestone 10). Remote players and mobs are drawn
 * ~100 ms in the past, between the two snapshots around that time, so 10-20 Hz updates look
 * smooth and network jitter is hidden.
 */

/** Interpolated fields of one remote entity. */
export interface EntityPose {
  x: number;
  y: number;
  z: number;
  yaw: number;
  pitch: number;
  headYaw: number;
}

export interface TimedPose extends EntityPose {
  /** Server time of the snapshot, ms. */
  time: number;
}

/** Default render delay behind the newest server time, ms. */
export const INTERPOLATION_DELAY_MS = 100;

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t;
}

/** Shortest-path angle interpolation (radians). */
export function lerpAngle(a: number, b: number, t: number): number {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
}

function copyPose(p: EntityPose, out: EntityPose): EntityPose {
  out.x = p.x;
  out.y = p.y;
  out.z = p.z;
  out.yaw = p.yaw;
  out.pitch = p.pitch;
  out.headYaw = p.headYaw;
  return out;
}

/** A short history of poses for one entity, sampled at a render time. */
export class InterpolationBuffer {
  private readonly poses: TimedPose[] = [];

  constructor(private readonly capacity = 32) {}

  get length(): number {
    return this.poses.length;
  }

  get latest(): TimedPose | undefined {
    return this.poses[this.poses.length - 1];
  }

  /** Adds a snapshot; out-of-order or duplicate times are ignored. */
  push(p: TimedPose): void {
    const last = this.latest;
    if (last && p.time <= last.time) return;
    this.poses.push({ ...p });
    if (this.poses.length > this.capacity) this.poses.shift();
  }

  /**
   * Pose at `time`: interpolated between the snapshots around it, clamped to the first / last
   * (no extrapolation, so a late packet freezes the entity instead of overshooting).
   */
  sample(time: number, out: EntityPose): EntityPose | undefined {
    const ps = this.poses;
    if (ps.length === 0) return undefined;
    const first = ps[0]!;
    if (time <= first.time || ps.length === 1) return copyPose(first, out);
    const last = ps[ps.length - 1]!;
    if (time >= last.time) return copyPose(last, out);
    let i = ps.length - 2;
    while (i > 0 && ps[i]!.time > time) i--;
    const a = ps[i]!, b = ps[i + 1]!;
    const t = (time - a.time) / (b.time - a.time);
    out.x = lerp(a.x, b.x, t);
    out.y = lerp(a.y, b.y, t);
    out.z = lerp(a.z, b.z, t);
    out.yaw = lerpAngle(a.yaw, b.yaw, t);
    out.pitch = lerp(a.pitch, b.pitch, t);
    out.headYaw = lerpAngle(a.headYaw, b.headYaw, t);
    // Drop history that can no longer be needed (keep one snapshot before `time`).
    if (i > 1) ps.splice(0, i - 1);
    return out;
  }
}

/**
 * Maps local time to server time from snapshot arrivals. The offset follows the fastest arrival
 * (lowest latency) immediately and drifts up slowly, so jitter does not shake the render time.
 */
export class ServerClock {
  /** localMs - serverMs of the fastest recent arrival; NaN until the first sample. */
  offset = Number.NaN;

  constructor(private readonly drift = 0.02) {}

  observe(serverMs: number, localMs: number): void {
    const o = localMs - serverMs;
    if (Number.isNaN(this.offset) || o < this.offset) this.offset = o;
    else this.offset += (o - this.offset) * this.drift;
  }

  /** Estimated current server time (ms) at local time `localMs`. */
  serverTime(localMs: number): number {
    return Number.isNaN(this.offset) ? 0 : localMs - this.offset;
  }

  /** The time remote entities are drawn at. */
  renderTime(localMs: number, delayMs = INTERPOLATION_DELAY_MS): number {
    return this.serverTime(localMs) - delayMs;
  }
}
