export interface LoopCallbacks {
  /** Optional: once per animation frame, before that frame's ticks (sample input here). */
  beginFrame?(frameDt: number): void;
  /** Fixed-timestep simulation step. `dt` is always the tick length in seconds. */
  update(dt: number): void;
  /**
   * Called once per animation frame. `alpha` in [0, 1) is how far we are between the
   * previous and current tick (use it to interpolate). `frameDt` is real elapsed seconds.
   */
  render(alpha: number, frameDt: number): void;
}

/** Fixed-timestep update with requestAnimationFrame rendering ("fix your timestep"). */
export class GameLoop {
  private rafId = 0;
  private lastTime = 0;
  private accumulator = 0;
  private running = false;
  readonly tickSeconds: number;

  constructor(
    tickRate: number,
    private readonly callbacks: LoopCallbacks,
    /** Clamp for long frames (tab switch, breakpoints) to avoid a spiral of death. */
    private readonly maxFrameSeconds = 0.25,
  ) {
    this.tickSeconds = 1 / tickRate;
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.lastTime = performance.now();
    this.accumulator = 0;
    this.rafId = requestAnimationFrame(this.frame);
  }

  get isRunning(): boolean {
    return this.running;
  }

  stop(): void {
    this.running = false;
    cancelAnimationFrame(this.rafId);
  }

  private readonly frame = (now: number): void => {
    if (!this.running) return;
    const frameDt = Math.min((now - this.lastTime) / 1000, this.maxFrameSeconds);
    this.lastTime = now;
    this.callbacks.beginFrame?.(frameDt);
    this.accumulator += frameDt;
    while (this.accumulator >= this.tickSeconds) {
      this.callbacks.update(this.tickSeconds);
      this.accumulator -= this.tickSeconds;
    }
    this.callbacks.render(this.accumulator / this.tickSeconds, frameDt);
    this.rafId = requestAnimationFrame(this.frame);
  };
}
