import { mobTextureNames, mulberry32 } from '@voxel/shared';
import { TEXTURE_SIZE } from './proceduralTextures';

/*
 * Procedural 16x16 mob textures (Milestone 8), generated in code: a noisy base colour per part plus
 * original string pixel art for the faces. One texture-array layer per name used by the shared mob
 * models (`mobTextureNames()`); an unknown name gets a magenta checker.
 */

const S = TEXTURE_SIZE;
type RGB = readonly [number, number, number];
type Rand = () => number;

function noisy(palette: readonly RGB[], rand: Rand): Uint8Array {
  const d = new Uint8Array(S * S * 4);
  for (let i = 0; i < S * S; i++) {
    const c = palette[Math.floor(rand() * palette.length)]!;
    d[i * 4] = c[0];
    d[i * 4 + 1] = c[1];
    d[i * 4 + 2] = c[2];
    d[i * 4 + 3] = 255;
  }
  return d;
}

/** Paints string art over `base`: '.' keeps the base pixel, other characters index `pal`. */
function overlay(base: Uint8Array, rows: readonly string[], pal: Record<string, RGB>): Uint8Array {
  for (let y = 0; y < S; y++) {
    const row = rows[y] ?? '';
    for (let x = 0; x < S; x++) {
      const c = pal[row[x] ?? '.'];
      if (!c) continue;
      const i = (y * S + x) * 4;
      base[i] = c[0];
      base[i + 1] = c[1];
      base[i + 2] = c[2];
      base[i + 3] = 255;
    }
  }
  return base;
}

