/**
 * Inventory screen operations (Milestone 10), shared by the client UI and the server. A click in
 * the inventory screen becomes an `InventoryOp`; single-player applies it directly, multiplayer
 * applies it optimistically and sends it to the server, which applies the same function to its
 * own copy and sends back the authoritative inventory.
 */
import { ITEMS, ITEM_COUNT, maxStackOf, stacksMatch, type ItemStack, type Slot } from '../items/items';
import { INVENTORY_SIZE, type Inventory } from '../items/inventory';
import { consumeIngredients, matchRecipe } from '../items/crafting';

/** Slot groups of the inventory screen: player slots, crafting grid, crafting output, creative palette. */
export const INV_GROUPS = ['inv', 'grid', 'out', 'palette'] as const;
export type InvGroup = (typeof INV_GROUPS)[number];

export type InventoryOp =
  /** Left click / right click (half or one) / shift-click on a slot. `ctrl`: palette takes one. */
  | { kind: 'click' | 'right' | 'shift'; group: InvGroup; index: number; ctrl?: boolean }
  /** Throws the cursor stack (or one of it) into the world: clicked outside the panel. */
  | { kind: 'throw'; one: boolean };

export interface InventoryHolder {
  readonly inventory: Inventory;
  /** The open crafting grid (2x2 = 4 slots, 3x3 = 9) or empty when no screen is open. */
  craftGrid: Slot[];
  readonly creative: boolean;
}

export interface InventoryOpResult {
  ok: boolean;
  /** A stack to throw into the world (cursor dropped outside the panel). */
  thrown?: ItemStack;
}

const REJECT: InventoryOpResult = { ok: false };
const OK: InventoryOpResult = { ok: true };

/** Side length of the open crafting grid (0 when closed). */
export function craftSizeOf(grid: readonly Slot[]): number {
  return grid.length === 9 ? 3 : grid.length === 4 ? 2 : 0;
}

/** What the crafting output slot shows. */
export function craftResult(h: InventoryHolder): Slot {
  const size = craftSizeOf(h.craftGrid);
  return size ? (matchRecipe(h.craftGrid, size)?.result ?? null) : null;
}

/** Whether `op` is well formed for this holder (indices in range, palette only in creative). */
export function validateInventoryOp(h: InventoryHolder, op: InventoryOp): boolean {
  if (op.kind === 'throw') return true;
  if (!Number.isInteger(op.index) || op.index < 0) return false;
  switch (op.group) {
    case 'inv':
      return op.index < INVENTORY_SIZE;
    case 'grid':
      return op.index < h.craftGrid.length;
    case 'out':
      return op.index === 0 && h.craftGrid.length > 0;
    case 'palette':
      return h.creative && op.index < ITEM_COUNT;
    default:
      return false;
  }
}

/** Applies one inventory screen operation. Invalid ops change nothing and return `ok: false`. */
export function applyInventoryOp(h: InventoryHolder, op: InventoryOp): InventoryOpResult {
  if (!validateInventoryOp(h, op)) return REJECT;
  const inv = h.inventory;
  if (op.kind === 'throw') {
    const c = inv.cursor;
    if (!c) return REJECT;
    let thrown: ItemStack;
    if (op.one) {
      thrown = { ...c, count: 1 };
      if (--c.count <= 0) inv.cursor = null;
    } else {
      thrown = c;
      inv.cursor = null;
    }
    inv.touch();
    return { ok: true, thrown };
  }
  const { group, index } = op;
  if (op.kind === 'click') {
    switch (group) {
      case 'inv':
        inv.click(index);
        break;
      case 'grid':
        inv.clickExternal(h.craftGrid, index);
        break;
      case 'out':
        takeOutput(h, false);
        break;
      case 'palette':
        // Holding something: the palette works as a bin. Otherwise take a full stack.
        if (inv.cursor) inv.cursor = null;
        else {
          const def = ITEMS[index]!;
          inv.cursor = { item: def.id, count: op.ctrl ? 1 : def.maxStack, damage: 0 };
        }
        inv.touch();
        break;
    }
    return OK;
  }
  if (op.kind === 'right') {
    switch (group) {
      case 'inv':
        inv.rightClick(index);
        break;
      case 'grid':
        inv.rightClickExternal(h.craftGrid, index);
        break;
      case 'out':
        takeOutput(h, false);
        break;
      case 'palette': {
        const c = inv.cursor;
        if (!c) inv.cursor = { item: index, count: 1, damage: 0 };
        else if (c.item === index && c.count < maxStackOf(c)) c.count++;
        else inv.cursor = null;
        inv.touch();
        break;
      }
    }
    return OK;
  }
  switch (group) {
    case 'inv':
      inv.shiftClick(index);
      break;
    case 'grid':
      inv.shiftFromExternal(h.craftGrid, index);
      break;
    case 'out':
      takeOutput(h, true);
      break;
    case 'palette': {
      const def = ITEMS[index]!;
      inv.add({ item: def.id, count: def.maxStack, damage: 0 });
      break;
    }
  }
  return OK;
}

/** Takes one craft onto the cursor, or (all) crafts as many as fit into the inventory. */
function takeOutput(h: InventoryHolder, all: boolean): void {
  const inv = h.inventory;
  const grid = h.craftGrid;
  const size = craftSizeOf(grid);
  if (!size) return;
  let m = matchRecipe(grid, size);
  if (!m) return;
  if (all) {
    for (let guard = 0; m && guard < 64; guard++) {
      if (inv.spaceFor(m.result) < m.result.count) break;
      inv.add(m.result);
      consumeIngredients(grid);
      m = matchRecipe(grid, size);
    }
    inv.touch();
    return;
  }
  const c = inv.cursor;
  if (!c) inv.cursor = { ...m.result };
  else if (stacksMatch(c, m.result) && c.count + m.result.count <= maxStackOf(c)) c.count += m.result.count;
  else return;
  consumeIngredients(grid);
  inv.touch();
}

/**
 * Closes the screen: the crafting grid and the cursor go back into the inventory. Returns what did
 * not fit (to be thrown into the world).
 */
export function closeCraftGrid(h: InventoryHolder): ItemStack[] {
  const inv = h.inventory;
  const back = [...h.craftGrid.filter((s): s is ItemStack => !!s), ...(inv.cursor ? [inv.cursor] : [])];
  inv.cursor = null;
  h.craftGrid = [];
  const left: ItemStack[] = [];
  for (const stack of back) {
    const rest = inv.add(stack);
    if (rest) left.push(rest);
  }
  inv.touch();
  return left;
}
