/**
 * Pure helpers for the sound system (Milestone 11): block materials and simple positional audio
 * (distance attenuation + stereo pan). No Web Audio here, so it is unit tested in Node.
 */
import { BLOCK_COUNT, BlockId, getBlockDef } from '@voxel/shared';

/** What a block sounds like when broken, placed or walked on. */
export type Material = 'stone' | 'wood' | 'dirt' | 'grass' | 'sand' | 'glass' | 'wool' | 'leaves';

export const MATERIALS: readonly Material[] = ['stone', 'wood', 'dirt', 'grass', 'sand', 'glass', 'wool', 'leaves'];

/** Material of a block id; undefined for air, water and unknown ids (no sound). */
export function blockMaterial(id: number): Material | undefined {
  switch (id) {
    case BlockId.Stone:
    case BlockId.CoalOre:
    case BlockId.IronOre:
    case BlockId.Bedrock:
    case BlockId.Rubble:
    case BlockId.StoneBricks:
    case BlockId.Sandstone:
      return 'stone';
    case BlockId.Log:
    case BlockId.Planks:
    case BlockId.Workbench:
    case BlockId.Torch:
      return 'wood';
    case BlockId.Dirt:
      return 'dirt';
    case BlockId.Grass:
      return 'grass';
    case BlockId.Sand:
      return 'sand';
    case BlockId.Glass:
    case BlockId.LumenBlock:
      return 'glass';
    case BlockId.Wool:
      return 'wool';
    case BlockId.Leaves:
      return 'leaves';
    default:
      return id > 0 && id < BLOCK_COUNT ? getBlockDef(id).sound : undefined;
  }
}

/** Where the listener is (camera eye) and which way is "right" (horizontal unit vector). */
export interface Listener {
  x: number;
  y: number;
  z: number;
  rightX: number;
  rightZ: number;
}

/** Sounds farther away than this (blocks) are not played at all. */
export const MAX_SOUND_DISTANCE = 32;
/** Within this distance a sound plays at full volume. */
export const FULL_VOLUME_DISTANCE = 2;

/**
 * Gain (0..1) and stereo pan (-1 left .. 1 right) of a sound at (x, y, z) heard from `l`.
 * Gain falls off smoothly to 0 at `maxDistance`; pan is the horizontal direction projected on the
 * listener's right vector, kept a little away from the hard edges, and centred for close sounds.
 */
export function spatialize(l: Listener, x: number, y: number, z: number, maxDistance = MAX_SOUND_DISTANCE): { gain: number; pan: number; distance: number } {
  const dx = x - l.x, dy = y - l.y, dz = z - l.z;
  const distance = Math.hypot(dx, dy, dz);
  if (distance >= maxDistance) return { gain: 0, pan: 0, distance };
  const t = Math.max(0, distance - FULL_VOLUME_DISTANCE) / (maxDistance - FULL_VOLUME_DISTANCE);
  const gain = (1 - t) * (1 - t);
  const h = Math.hypot(dx, dz);
  let pan = h > 1e-6 ? (dx * l.rightX + dz * l.rightZ) / h : 0;
  // Fade the pan in over the first couple of blocks so sounds at your feet are centred.
  pan *= Math.min(1, h / FULL_VOLUME_DISTANCE) * 0.85;
  return { gain, pan: Math.max(-1, Math.min(1, pan)), distance };
}

/**
 * Ambient mix from where the camera is: open sky brings wind (stronger higher up), being shut in
 * deep underground brings the cave drone. `skyLight` is the sky light 0..15 at the eye.
 */
export function ambientMix(skyLight: number, eyeY: number): { wind: number; cave: number } {
  const open = Math.max(0, Math.min(1, skyLight / 15));
  const height = Math.max(0, Math.min(1, (eyeY - 55) / 60));
  const wind = open * (0.35 + 0.65 * height);
  const depth = Math.max(0, Math.min(1, (64 - eyeY) / 24));
  const cave = (1 - open) * (0.4 + 0.6 * depth);
  return { wind, cave };
}
