/**
 * Binary reader/writer for the multiplayer protocol (Milestone 10): little-endian DataView access
 * with strict bounds checks. Every read past the end, non-finite float, invalid UTF-8 or
 * oversized string throws `ProtocolError`, so a decoder can never return garbage.
 */

export class ProtocolError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ProtocolError';
  }
}

/** UTF-8 encode (no TextEncoder dependency: shared code runs without DOM typings). */
export function utf8Encode(s: string): Uint8Array {
  const out: number[] = [];
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00);
        i++;
      }
    }
    if (c >= 0xd800 && c <= 0xdfff) c = 0xfffd; // lone surrogate
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return Uint8Array.from(out);
}

/** Strict UTF-8 decode: throws on malformed or overlong sequences. */
export function utf8Decode(b: Uint8Array): string {
  let s = '';
  for (let i = 0; i < b.length; ) {
    const c = b[i++]!;
    let cp: number;
    let need: number;
    let min: number;
    if (c < 0x80) {
      s += String.fromCharCode(c);
      continue;
    } else if ((c & 0xe0) === 0xc0) {
      cp = c & 31; need = 1; min = 0x80;
    } else if ((c & 0xf0) === 0xe0) {
      cp = c & 15; need = 2; min = 0x800;
    } else if ((c & 0xf8) === 0xf0) {
      cp = c & 7; need = 3; min = 0x10000;
    } else {
      throw new ProtocolError('invalid UTF-8');
    }
    if (i + need > b.length) throw new ProtocolError('truncated UTF-8');
    for (let k = 0; k < need; k++) {
      const d = b[i++]!;
      if ((d & 0xc0) !== 0x80) throw new ProtocolError('invalid UTF-8');
      cp = (cp << 6) | (d & 63);
    }
    if (cp < min || cp > 0x10ffff || (cp >= 0xd800 && cp <= 0xdfff)) throw new ProtocolError('invalid UTF-8');
    s += String.fromCodePoint(cp);
  }
  return s;
}

export class ByteWriter {
  private buf: Uint8Array;
  private view: DataView;
  length = 0;

  constructor(initial = 256) {
    this.buf = new Uint8Array(initial);
    this.view = new DataView(this.buf.buffer);
  }

  private ensure(n: number): void {
    if (this.length + n <= this.buf.length) return;
    let size = this.buf.length * 2;
    while (size < this.length + n) size *= 2;
    const next = new Uint8Array(size);
    next.set(this.buf.subarray(0, this.length));
    this.buf = next;
    this.view = new DataView(next.buffer);
  }

  u8(v: number): this {
    this.ensure(1);
    this.view.setUint8(this.length, v);
    this.length += 1;
    return this;
  }

  i8(v: number): this {
    this.ensure(1);
    this.view.setInt8(this.length, v);
    this.length += 1;
    return this;
  }

  u16(v: number): this {
    this.ensure(2);
    this.view.setUint16(this.length, v, true);
    this.length += 2;
    return this;
  }

  i16(v: number): this {
    this.ensure(2);
    this.view.setInt16(this.length, v, true);
    this.length += 2;
    return this;
  }

  u32(v: number): this {
    this.ensure(4);
    this.view.setUint32(this.length, v >>> 0, true);
    this.length += 4;
    return this;
  }

  i32(v: number): this {
    this.ensure(4);
    this.view.setInt32(this.length, v | 0, true);
    this.length += 4;
    return this;
  }

  f32(v: number): this {
    this.ensure(4);
    this.view.setFloat32(this.length, v, true);
    this.length += 4;
    return this;
  }

  f64(v: number): this {
    this.ensure(8);
    this.view.setFloat64(this.length, v, true);
    this.length += 8;
    return this;
  }

  bool(v: boolean): this {
    return this.u8(v ? 1 : 0);
  }

  bytes(b: Uint8Array): this {
    this.ensure(b.length);
    this.buf.set(b, this.length);
    this.length += b.length;
    return this;
  }

  /** u16 byte length + UTF-8. */
  string(s: string): this {
    const b = utf8Encode(s);
    if (b.length > 0xffff) throw new ProtocolError('string too long');
    this.u16(b.length);
    return this.bytes(b);
  }

  finish(): Uint8Array {
    return this.buf.slice(0, this.length);
  }
}

export class ByteReader {
  private readonly view: DataView;
  offset = 0;

  constructor(private readonly buf: Uint8Array) {
    this.view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  }

  get remaining(): number {
    return this.buf.length - this.offset;
  }

  private need(n: number): number {
    if (this.offset + n > this.buf.length) throw new ProtocolError('message truncated');
    const o = this.offset;
    this.offset += n;
    return o;
  }

  u8(): number {
    return this.view.getUint8(this.need(1));
  }

  i8(): number {
    return this.view.getInt8(this.need(1));
  }

  u16(): number {
    return this.view.getUint16(this.need(2), true);
  }

  i16(): number {
    return this.view.getInt16(this.need(2), true);
  }

  u32(): number {
    return this.view.getUint32(this.need(4), true);
  }

  i32(): number {
    return this.view.getInt32(this.need(4), true);
  }

  /** A finite float32 (NaN / Infinity are rejected). */
  f32(): number {
    const v = this.view.getFloat32(this.need(4), true);
    if (!Number.isFinite(v)) throw new ProtocolError('non-finite number');
    return v;
  }

  f64(): number {
    const v = this.view.getFloat64(this.need(8), true);
    if (!Number.isFinite(v)) throw new ProtocolError('non-finite number');
    return v;
  }

  bool(): boolean {
    const v = this.u8();
    if (v > 1) throw new ProtocolError('invalid boolean');
    return v === 1;
  }

  bytes(n: number): Uint8Array {
    const o = this.need(n);
    return this.buf.slice(o, o + n);
  }

  /** A string of at most `maxBytes` UTF-8 bytes. */
  string(maxBytes: number): string {
    const n = this.u16();
    if (n > maxBytes) throw new ProtocolError('string too long');
    return utf8Decode(this.bytes(n));
  }

  /** Throws unless every byte was consumed. */
  end(): void {
    if (this.offset !== this.buf.length) throw new ProtocolError('trailing bytes');
  }
}
