/**
 * Generic physics for non-player entities (item drops now, mobs from Milestone 8): an upright box
 * with gravity, drag, water buoyancy and swept voxel collision (same `sweepAxis` as the player).
 * Position is the bottom centre of the box.
 */
import { BlockId } from '../world/blocks';
import { boxHitsSolid, boxTouches, sweepAxis, type Aabb, type BlockGetter } from './player';

export interface BodyState {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  onGround: boolean;
  inWater: boolean;
}

export interface BodyParams {
  halfWidth: number;
  height: number;
  /** Downward acceleration, blocks/s^2. */
  gravity: number;
  /** Maximum fall speed. */
  terminal: number;
  /** Horizontal damping rate (1/s) on the ground. */
  groundFriction: number;
  /** Horizontal damping rate (1/s) in the air. */
  airDrag: number;
  /** Damping rate (1/s) of all velocity in water. */
  waterDrag: number;
  /** Upward acceleration in water (net of gravity); > 0 floats. */
  buoyancy: number;
}

const box: Aabb = { minX: 0, minY: 0, minZ: 0, maxX: 0, maxY: 0, maxZ: 0 };

function setBox(b: BodyState, p: BodyParams): Aabb {
  box.minX = b.x - p.halfWidth;
  box.maxX = b.x + p.halfWidth;
  box.minY = b.y;
  box.maxY = b.y + p.height;
  box.minZ = b.z - p.halfWidth;
  box.maxZ = b.z + p.halfWidth;
  return box;
}

/** Advances a body by `dt` seconds. Mutates and returns it. */
export function stepBody(b: BodyState, p: BodyParams, getBlock: BlockGetter, dt: number): BodyState {
  setBox(b, p);
  // Pushed out upward when a block appears inside the body (placed on top of a dropped item).
  if (boxHitsSolid(getBlock, box)) {
    b.y = Math.floor(b.y) + 1;
    b.vy = Math.max(b.vy, 0);
    setBox(b, p);
    if (boxHitsSolid(getBlock, box)) return b; // still stuck: wait for the world to change
  }
  b.inWater = boxTouches(getBlock, box, BlockId.Water);
  if (b.inWater) {
    const k = Math.exp(-p.waterDrag * dt);
    b.vx *= k;
    b.vz *= k;
    b.vy = b.vy * k + p.buoyancy * dt;
  } else {
    b.vy = Math.max(-p.terminal, b.vy - p.gravity * dt);
    const k = Math.exp(-(b.onGround ? p.groundFriction : p.airDrag) * dt);
    b.vx *= k;
    b.vz *= k;
  }

  const dy = b.vy * dt;
  const movedY = sweepAxis(getBlock, box, 1, dy);
  b.onGround = movedY !== dy && dy < 0;
  if (movedY !== dy) b.vy = 0;
  const dx = b.vx * dt;
  if (sweepAxis(getBlock, box, 0, dx) !== dx) b.vx = 0;
  const dz = b.vz * dt;
  if (sweepAxis(getBlock, box, 2, dz) !== dz) b.vz = 0;

  b.x = (box.minX + box.maxX) / 2;
  b.y = box.minY;
  b.z = (box.minZ + box.maxZ) / 2;
  return b;
}
