import {
  ACTION,
  CorrectionSmoother,
  DAMAGE_CAUSES,
  InputHistory,
  MOB_TYPES,
  STATE_FLAG,
  TICK_SECONDS,
  applyInventoryOp,
  applyPredictedInput,
  checkBreak,
  closeCraftGrid,
  getItemDef,
  isPlaceableVariant,
  reconcile,
  emitAll,
  type BlockPos,
  type EditCheck,
  type GameMode,
  type HurtResult,
  type InventoryMsg,
  type InventoryOp,
  type InventoryOpResult,
  type ItemStack,
  type LightEngine,
  type Mob,
  type PickupEvent,
  type PlayerInput,
  type PlayerStateMsg,
  type Vec3,
  type WelcomeMsg,
  type World,
} from '@voxel/shared';
import { GameSession, type TickEnv } from '../game/session';
import type { NetClient } from './netClient';

/**
 * The local player in a multiplayer world (Milestone 10). Same API as the single-player
 * `GameSession`, but the server is authoritative:
 * - movement is *predicted*: each tick runs the shared physics on the local input, remembers it
 *   and sends it; every `playerState` from the server reconciles (snap + replay unacknowledged
 *   inputs, small errors smoothed on the camera);
 * - block edits are applied optimistically and sent; the server's block changes are always
 *   applied on arrival, so a rejected edit is rolled back by the server's resync;
 * - inventory clicks are applied optimistically (the shared op) and sent; the UI follows the
 *   server's inventory messages;
 * - attacks, eating, drops, respawn and the crafting screen are requests;
 * - vitals, damage and death come from the server.
 * The WorldSim here only holds what the client renders (no mob or item simulation).
 */
export class RemoteGameSession extends GameSession {
  readonly history = new InputHistory();
  readonly smoother = new CorrectionSmoother();
  inputTick = 0;
  /** Reconciliation error of the last server state (debug). */
  lastError = 0;
  corrections = 0;
  /** Server tick of the last state (debug). */
  ackTick = 0;
  private flyRequested = false;
  /** When the last optimistic inventory change was made locally (ms, performance.now clock). */
  private lastInvOpMs = -Infinity;
  /** Newest server inventory held back while local clicks are still in flight. */
  private heldInventory: InventoryMsg | undefined;
  /** Round-trip time to the server (ms); sizes the hold-back window. Set by MultiplayerLink. */
  rttMs = 100;
  /** Server inventories applied / held back (debug, tests). */
  readonly invStats = { applied: 0, held: 0 };

  constructor(
    world: World,
    light: LightEngine,
    gameMode: GameMode,
    readonly net: NetClient,
    welcome: WelcomeMsg,
    name: string,
  ) {
    super(world, welcome.x, welcome.z, light, gameMode, Math.random, welcome.playerId, name);
    const p = this.player;
    p.x = welcome.x;
    p.y = welcome.y;
    p.z = welcome.z;
    p.flying = welcome.flying && gameMode === 'creative';
    this.flyRequested = p.flying;
    this.yaw = welcome.yaw;
    this.pitch = welcome.pitch;
    // The server already placed us: "spawned" here means "has a position".
    this.spawnPoint = { x: welcome.x, y: welcome.y, z: welcome.z, wet: false };
  }

  override trySpawn(): boolean {
    return true;
  }

  // --- Movement (prediction) ---------------------------------------------------------------------

  override movePlayer(input: PlayerInput, dt: number): boolean {
    if (this.dead) return false;
    if (input.sprint && !this.canSprint()) input.sprint = false;
    // A fly toggle from the controller changed `player.flying`; that is the request.
    this.flyRequested = this.player.flying;
    const tick = ++this.inputTick;
    this.history.push(tick, input, this.flyRequested);
    applyPredictedInput(this.player, { tick, input, flying: this.flyRequested }, this.getBlock, dt, this.creative);
    const p = this.player;
    this.net.send({
      type: 'input',
      tick,
      moveX: input.strafe,
      moveZ: input.forward,
      jump: input.jump,
      sneak: input.sneak,
      sprint: input.sprint,
      flying: this.flyRequested,
      yaw: input.yaw,
      pitch: this.pitch,
      x: p.x,
      y: p.y,
      z: p.z,
    });
    return false;
  }

  /**
   * Applies an authoritative player state. Returns true when the camera should snap (teleport,
   * respawn, anti-cheat correction or a large error) instead of smoothing.
   */
  applyServerState(m: PlayerStateMsg): boolean {
    const v = this.vitals;
    const prevHealth = v.health;
    v.health = m.health;
    v.hunger = m.hunger;
    v.saturation = m.saturation;
    v.air = m.air;
    v.exhaustion = m.exhaustion;
    v.fallDistance = m.fallDistance;
    this.gameMode = m.gameMode;
    this.ackTick = m.ackTick;
    if (m.health < prevHealth && !this.creative) emitAll(this.damageListeners, prevHealth - m.health, 'other');
    const dead = (m.flags & STATE_FLAG.dead) !== 0;
    if (dead && !this.dead) {
      this.dead = true;
      this.deathCause = DAMAGE_CAUSES[m.deathCause - 1] ?? 'other';
      this.deathAttacker = m.deathAttacker > 0 ? MOB_TYPES[m.deathAttacker - 1] : undefined;
      emitAll(this.deathListeners, this.deathCause);
    } else if (!dead && this.dead) {
      this.dead = false;
      this.deathCause = undefined;
      this.deathAttacker = undefined;
    }
    const body = {
      x: m.x,
      y: m.y,
      z: m.z,
      vx: m.vx,
      vy: m.vy,
      vz: m.vz,
      onGround: (m.flags & STATE_FLAG.onGround) !== 0,
      inWater: (m.flags & STATE_FLAG.inWater) !== 0,
      flying: (m.flags & STATE_FLAG.flying) !== 0,
    };
    const p = this.player;
    const bx = p.x, by = p.y, bz = p.z;
    if ((m.flags & STATE_FLAG.correction) !== 0 || this.dead) {
      // Hard correction: forget the predicted inputs and take the server's body as-is.
      this.history.clear();
      Object.assign(p, body);
      this.flyRequested = body.flying;
      this.smoother.reset();
      if ((m.flags & STATE_FLAG.correction) !== 0) this.corrections++;
      this.lastError = Math.hypot(p.x - bx, p.y - by, p.z - bz);
      return this.lastError > 0.01;
    }
    this.lastError = reconcile(p, body, m.ackTick, this.history, this.getBlock, TICK_SECONDS, this.creative);
    if (this.history.length === 0) this.flyRequested = p.flying;
    if (this.lastError > this.smoother.snapDistance) {
      this.smoother.reset();
      return true;
    }
    if (this.lastError > 1e-4) this.smoother.correct(bx, by, bz, p.x, p.y, p.z);
    return false;
  }

  /**
   * How long after a local inventory click server inventories are held back. The server sends its
   * inventory once per tick, so while clicks are in flight a message can reflect only the earlier
   * ones; applying it would briefly undo the later optimistic clicks (the Milestone 10 flicker).
   */
  get inventoryHoldMs(): number {
    return Math.max(150, Math.min(1500, this.rttMs * 1.5 + 120));
  }

  /**
   * The server's inventory replaces ours (optimistic clicks converge here). Within
   * `inventoryHoldMs` of a local click only the newest message is kept; `flushInventory` applies
   * it once the clicks have had time to reach the server, so a rejected click still rolls back.
   */
  applyInventory(m: InventoryMsg, now = performance.now()): void {
    if (now - this.lastInvOpMs < this.inventoryHoldMs) {
      this.heldInventory = m;
      this.invStats.held++;
      return;
    }
    this.heldInventory = undefined;
    this.replaceInventory(m);
  }

  /** Per frame: applies a held-back server inventory once local clicks have settled. */
  flushInventory(now = performance.now()): void {
    const m = this.heldInventory;
    if (m && now - this.lastInvOpMs >= this.inventoryHoldMs) {
      this.heldInventory = undefined;
      this.replaceInventory(m);
    }
  }

  private replaceInventory(m: InventoryMsg): void {
    this.invStats.applied++;
    const inv = this.inventory;
    for (let i = 0; i < inv.slots.length; i++) inv.slots[i] = m.slots[i] ?? null;
    inv.cursor = m.cursor;
    // A grid of another size is a screen we opened / closed that the server has not seen yet.
    if (m.grid.length === this.craftGrid.length) this.craftGrid = m.grid;
    inv.touch();
  }

  // --- World / vitals: authoritative on the server ------------------------------------------------

  override tick(dt: number, env?: TickEnv): PickupEvent[] {
    // No local world simulation; only the attack cooldown clock runs.
    this.sim.simTime += dt;
    if (env) this.yaw = Math.atan2(env.lookX, -env.lookZ);
    return [];
  }

  override damage(): number {
    return 0;
  }

  override kill(): void {}

  override knockback(): void {}

  override respawnPlayer(): void {
    if (this.dead) this.net.action(ACTION.respawn);
  }

  // --- Requests -----------------------------------------------------------------------------------

  /** Survival mining started / stopped on a block (the server times it). */
  sendBreakProgress(target: BlockPos | null): void {
    if (target) this.net.action(ACTION.breakStart, target.x, target.y, target.z);
    else this.net.action(ACTION.breakCancel);
  }

  sendSelectedSlot(slot: number): void {
    this.net.action(ACTION.selectSlot, 0, 0, 0, -1, slot);
  }

  sendEatStart(): void {
    this.net.action(ACTION.eatStart);
  }

  override requestBreak(pos: BlockPos): EditCheck {
    if (this.dead) return this.reject({ ok: false, reason: 'not_loaded' });
    if (!this.isLoadedAt(pos.x, pos.z)) return this.reject({ ok: false, reason: 'not_loaded' });
    const check = checkBreak(this.getBlock, pos.x, pos.y, pos.z);
    if (!check.ok) return this.reject(check);
    this.net.action(ACTION.breakFinish, pos.x, pos.y, pos.z);
    this.sim.applyBlockChange(pos.x, pos.y, pos.z, 0); // optimistic
    return check;
  }

  override requestPlace(pos: BlockPos, against?: BlockPos & { face: number }, variant?: number): EditCheck {
    const held = this.heldStack;
    const item = held ? getItemDef(held.item).block : undefined;
    if (this.dead || item === undefined || !against || against.face < 0) return this.reject({ ok: false, reason: 'invalid_block' });
    const block = variant ?? item;
    if (!isPlaceableVariant(item, block)) return this.reject({ ok: false, reason: 'invalid_block' });
    if (!this.isLoadedAt(pos.x, pos.z)) return this.reject({ ok: false, reason: 'not_loaded' });
    const check = this.sim.checkPlace(pos.x, pos.y, pos.z, block);
    if (!check.ok) return this.reject(check);
    this.net.action(ACTION.place, against.x, against.y, against.z, against.face, block === item ? 0 : block);
    this.sim.applyBlockChange(pos.x, pos.y, pos.z, block); // optimistic
    if (!this.creative) this.inventory.removeFromSlot(this.selectedSlot, 1);
    return check;
  }

  override attackMob(mob: Mob): HurtResult {
    if (this.dead) return 'ignored';
    this.lastAttackTime = this.sim.simTime;
    this.stats.attacks++;
    this.net.action(ACTION.attack, 0, 0, 0, -1, mob.id);
    return 'hurt';
  }

  override dropHeld(all: boolean, _dir: Vec3): boolean {
    if (this.dead || !this.heldStack) return false;
    this.net.action(ACTION.drop, 0, 0, 0, -1, all ? 1 : 0);
    return true;
  }

  override throwStack(_stack: ItemStack, _dir: Vec3): void {
    // The server throws items (it owns item entities).
  }

  override eatHeld(): boolean {
    if (!this.canEatHeld()) return false;
    this.net.action(ACTION.eatFinish);
    return true;
  }

  override openScreen(size: 2 | 3, workbench?: { x: number; y: number; z: number }): void {
    this.lastInvOpMs = performance.now();
    this.craftGrid = new Array(size * size).fill(null);
    this.net.action(ACTION.openScreen, workbench?.x ?? 0, workbench?.y ?? 0, workbench?.z ?? 0, -1, size);
  }

  override closeScreen(): void {
    this.lastInvOpMs = performance.now();
    closeCraftGrid(this); // optimistic; leftovers are thrown by the server
    this.net.action(ACTION.closeScreen);
  }

  override inventoryOp(op: InventoryOp): InventoryOpResult {
    if (this.dead) return { ok: false };
    const r = applyInventoryOp(this, op); // optimistic; a thrown stack is spawned by the server
    if (r.ok) {
      this.lastInvOpMs = performance.now();
      this.net.invOp(op);
    }
    return r;
  }
}
