/**
 * Player inventory (Milestone 7). Pure and DOM-free so it can be unit tested and, later, run on the
 * server. 36 slots: hotbar 0-8, then the main grid 9-35. A separate `cursor` stack is what the UI
 * is "holding" between clicks (drag and drop).
 *
 * The slot operations (`clickSlot`, `rightClickSlot`, ...) work on any `Slot[]`, so crafting grids
 * use exactly the same rules as inventory slots.
 */
import {
  cloneStack,
  getItemDef,
  maxStackOf,
  stackFromSaved,
  stackToSaved,
  stacksMatch,
  type ItemStack,
  type SavedStack,
  type Slot,
} from './items';

export const HOTBAR_SIZE = 9;
export const MAIN_SIZE = 27;
export const INVENTORY_SIZE = HOTBAR_SIZE + MAIN_SIZE;

/** Slot index range [start, end). */
export interface SlotRange {
  start: number;
  end: number;
}

export const HOTBAR_RANGE: SlotRange = { start: 0, end: HOTBAR_SIZE };
export const MAIN_RANGE: SlotRange = { start: HOTBAR_SIZE, end: INVENTORY_SIZE };
export const ALL_RANGE: SlotRange = { start: 0, end: INVENTORY_SIZE };

// --- Generic slot operations ---------------------------------------------------------------------

/**
 * Moves as much of `stack` as fits into `slots[range]`: first onto matching stacks, then into empty
 * slots, both in index order. Mutates `stack.count`; returns the count that did not fit.
 */
export function insertStack(slots: Slot[], stack: ItemStack, range: SlotRange = { start: 0, end: slots.length }): number {
  const max = maxStackOf(stack);
  if (max > 1) {
    for (let i = range.start; i < range.end && stack.count > 0; i++) {
      const s = slots[i];
      if (!s || !stacksMatch(s, stack) || s.count >= max) continue;
      const moved = Math.min(max - s.count, stack.count);
      s.count += moved;
      stack.count -= moved;
    }
  }
  for (let i = range.start; i < range.end && stack.count > 0; i++) {
    if (slots[i]) continue;
    const moved = Math.min(max, stack.count);
    slots[i] = { item: stack.item, count: moved, damage: stack.damage };
    stack.count -= moved;
  }
  return stack.count;
}

/** Left click on a slot holding `cursor`: pick up, put down, merge or swap. Returns the new cursor. */
export function clickSlot(slots: Slot[], i: number, cursor: Slot): Slot {
  const s = slots[i] ?? null;
  if (!cursor) {
    slots[i] = null;
    return s;
  }
  if (!s) {
    slots[i] = cursor;
    return null;
  }
  if (stacksMatch(s, cursor)) {
    const max = maxStackOf(s);
    const moved = Math.min(max - s.count, cursor.count);
    if (moved > 0) {
      s.count += moved;
      cursor.count -= moved;
      return cursor.count > 0 ? cursor : null;
    }
  }
  slots[i] = cursor;
  return s;
}

/** Removes half of a slot's stack (rounded up) and returns it. */
export function splitSlot(slots: Slot[], i: number): Slot {
  const s = slots[i];
  if (!s) return null;
  const take = Math.ceil(s.count / 2);
  s.count -= take;
  if (s.count === 0) slots[i] = null;
  return { item: s.item, count: take, damage: s.damage };
}

/**
 * Right click: with an empty cursor, pick up half the stack; otherwise put one item down (onto an
 * empty or matching slot), or swap when the slot holds something else. Returns the new cursor.
 */
export function rightClickSlot(slots: Slot[], i: number, cursor: Slot): Slot {
  const s = slots[i] ?? null;
  if (!cursor) return splitSlot(slots, i);
  if (!s) {
    slots[i] = { item: cursor.item, count: 1, damage: cursor.damage };
    cursor.count--;
  } else if (stacksMatch(s, cursor)) {
    if (s.count < maxStackOf(s)) {
      s.count++;
      cursor.count--;
    }
  } else {
    slots[i] = cursor;
    return s;
  }
  return cursor.count > 0 ? cursor : null;
}

// --- Inventory -----------------------------------------------------------------------------------

export interface SavedInventory {
  /** INVENTORY_SIZE entries (null = empty). */
  slots: (SavedStack | null)[];
}

export class Inventory {
  readonly slots: Slot[] = new Array<Slot>(INVENTORY_SIZE).fill(null);
  /** The stack held by the mouse in the inventory screen. */
  cursor: Slot = null;
  /** Bumped on every change, so UIs can redraw only when needed. */
  version = 0;

  get(i: number): Slot {
    return this.slots[i] ?? null;
  }

  set(i: number, stack: Slot): void {
    this.slots[i] = stack && stack.count > 0 ? stack : null;
    this.version++;
  }

  /** Marks the inventory changed after editing a stack in place. */
  touch(): void {
    this.version++;
  }

  clear(): void {
    this.slots.fill(null);
    this.cursor = null;
    this.version++;
  }

  /**
   * Adds a stack: merges into matching stacks (hotbar first), then fills empty slots (hotbar first).
   * Does not modify `stack`. Returns the leftover that did not fit, or null.
   */
  add(stack: ItemStack): Slot {
    const rest = cloneStack(stack);
    const before = rest.count;
    // Merge pass over all slots first so a new pickup tops up an existing stack anywhere.
    const max = maxStackOf(rest);
    if (max > 1) {
      for (let i = 0; i < INVENTORY_SIZE && rest.count > 0; i++) {
        const s = this.slots[i];
        if (!s || !stacksMatch(s, rest) || s.count >= max) continue;
        const moved = Math.min(max - s.count, rest.count);
        s.count += moved;
        rest.count -= moved;
      }
    }
    insertStack(this.slots, rest, ALL_RANGE);
    if (rest.count !== before) this.version++;
    return rest.count > 0 ? rest : null;
  }

  /** How many more of `stack` would fit. */
  spaceFor(stack: ItemStack): number {
    const max = maxStackOf(stack);
    let space = 0;
    for (const s of this.slots) {
      if (!s) space += max;
      else if (max > 1 && stacksMatch(s, stack)) space += max - s.count;
    }
    return space;
  }

  /** Total count of an item (any wear). */
  countItem(item: number): number {
    let n = 0;
    for (const s of this.slots) if (s && s.item === item) n += s.count;
    return n;
  }

  /** Removes up to `count` of `item` (main slots last). Returns how many were removed. */
  removeItem(item: number, count: number): number {
    let left = count;
    for (let i = 0; i < INVENTORY_SIZE && left > 0; i++) {
      const s = this.slots[i];
      if (!s || s.item !== item) continue;
      const take = Math.min(left, s.count);
      s.count -= take;
      left -= take;
      if (s.count === 0) this.slots[i] = null;
    }
    if (left !== count) this.version++;
    return count - left;
  }

  /** Removes up to `count` items from one slot and returns them. */
  removeFromSlot(i: number, count: number): Slot {
    const s = this.slots[i];
    if (!s || count <= 0) return null;
    const take = Math.min(count, s.count);
    s.count -= take;
    if (s.count === 0) this.slots[i] = null;
    this.version++;
    return { item: s.item, count: take, damage: s.damage };
  }

  /**
   * Moves the stack in `from` onto `to`: merges when they match (anything left stays in `from`),
   * moves into an empty slot, otherwise swaps.
   */
  move(from: number, to: number): void {
    if (from === to) return;
    const a = this.slots[from];
    if (!a) return;
    const b = this.slots[to];
    if (!b) {
      this.slots[to] = a;
      this.slots[from] = null;
    } else if (stacksMatch(a, b) && maxStackOf(b) > 1) {
      const moved = Math.min(maxStackOf(b) - b.count, a.count);
      b.count += moved;
      a.count -= moved;
      if (a.count === 0) this.slots[from] = null;
    } else {
      this.swap(from, to);
      return;
    }
    this.version++;
  }

  swap(a: number, b: number): void {
    const t = this.slots[a] ?? null;
    this.slots[a] = this.slots[b] ?? null;
    this.slots[b] = t;
    this.version++;
  }

  /** Splits half of slot `i` off into a new stack (returned; not placed anywhere). */
  split(i: number): Slot {
    const out = splitSlot(this.slots, i);
    if (out) this.version++;
    return out;
  }

  // UI operations on the inventory's own slots, using `cursor`.

  click(i: number): void {
    this.cursor = clickSlot(this.slots, i, this.cursor);
    this.version++;
  }

  rightClick(i: number): void {
    this.cursor = rightClickSlot(this.slots, i, this.cursor);
    this.version++;
  }

  /** Shift-click: moves a stack between the hotbar and the main grid (as much as fits). */
  shiftClick(i: number): void {
    const s = this.slots[i];
    if (!s) return;
    const target = i < HOTBAR_SIZE ? MAIN_RANGE : HOTBAR_RANGE;
    insertStack(this.slots, s, target);
    if (s.count === 0) this.slots[i] = null;
    this.version++;
  }

  /** The same UI operations on another container (crafting grid), sharing this cursor. */
  clickExternal(slots: Slot[], i: number): void {
    this.cursor = clickSlot(slots, i, this.cursor);
    this.version++;
  }

  rightClickExternal(slots: Slot[], i: number): void {
    this.cursor = rightClickSlot(slots, i, this.cursor);
    this.version++;
  }

  /** Shift-click in another container: moves that stack into the inventory (main grid first). */
  shiftFromExternal(slots: Slot[], i: number): void {
    const s = slots[i];
    if (!s) return;
    insertStack(this.slots, s, MAIN_RANGE);
    insertStack(this.slots, s, HOTBAR_RANGE);
    if (s.count === 0) slots[i] = null;
    this.version++;
  }

  /** Every non-empty stack (slots and cursor), removing them; used when the player dies. */
  takeAll(): ItemStack[] {
    const out: ItemStack[] = [];
    for (let i = 0; i < INVENTORY_SIZE; i++) {
      const s = this.slots[i];
      if (s) out.push(s);
      this.slots[i] = null;
    }
    if (this.cursor) out.push(this.cursor);
    this.cursor = null;
    this.version++;
    return out;
  }

  /**
   * Saved form, by item name. The cursor stack and any `extra` stacks (an open crafting grid) are
   * folded into a copy of the slots where they fit, so an autosave never loses them.
   */
  toSaved(extra: readonly Slot[] = []): SavedInventory {
    const slots = this.slots.map((s) => (s ? cloneStack(s) : null));
    for (const s of [this.cursor, ...extra]) if (s) insertStack(slots, cloneStack(s));
    return { slots: slots.map((s) => (s ? stackToSaved(s) : null)) };
  }

  /** Restores from a save by item name. Unknown items are dropped; missing slots stay empty. */
  static fromSaved(saved: SavedInventory | undefined): Inventory {
    const inv = new Inventory();
    if (!saved || !Array.isArray(saved.slots)) return inv;
    for (let i = 0; i < INVENTORY_SIZE; i++) inv.slots[i] = stackFromSaved(saved.slots[i]);
    return inv;
  }

  /** Short description for debugging, e.g. "planks x12". */
  static describe(s: Slot): string {
    if (!s) return 'empty';
    const d = getItemDef(s.item);
    const dur = d.tool ? ` (${d.tool.durability - s.damage}/${d.tool.durability})` : '';
    return `${d.name} x${s.count}${dur}`;
  }
}
