// Version / author shown on the title screen and in the in-game corner, and the Follow dialog's QR
// codes.

export const APP_VERSION = __APP_VERSION__;
export const APP_AUTHOR = __APP_AUTHOR__;

/** "v1.1.0 · by Huaichao Wang" (no author part when package.json has none). */
export function byline(): string {
  return APP_AUTHOR ? `v${APP_VERSION} · by ${APP_AUTHOR}` : `v${APP_VERSION}`;
}

export interface FollowCode {
  /** Caption under the code, e.g. the platform name. */
  label: string;
  /** Image path relative to index.html, e.g. `qr/wechat.png` (files live in public/qr/). */
  src: string;
}

/**
 * QR codes shown by the Follow dialog. Put the images in `public/qr/` and list them here; they are
 * precached by the service worker so the dialog also works offline.
 */
export const FOLLOW_CODES: readonly FollowCode[] = [
  { label: '抖音 / Douyin', src: 'qr/douyin-qr.png' },
  { label: '视频号 / WeChat Channels', src: 'qr/wechat-channels-qr.jpg' },
  { label: '快手 / Kuaishou', src: 'qr/kuaishou-qr.jpg' },
  { label: '小红书 / RedNote', src: 'qr/xiaohongshu-qr.jpg' },
  { label: '哔哩哔哩 / Bilibili', src: 'qr/bilibili-qr.png' },
];

/** Shown when there are no QR codes yet, or as a text link under them. */
export const FOLLOW_URL = 'https://github.com/huaichaow';

/** Adds the small version / author label to the bottom-right corner of the game screen. */
export function mountVersionTag(): void {
  const el = document.createElement('div');
  el.className = 'version-tag';
  el.textContent = byline();
  el.setAttribute('aria-hidden', 'true');
  document.body.appendChild(el);
}
