/**
 * Mob entities (Milestone 8): a small component-style layout on top of `EntityBase`.
 *
 *  - transform + body: the `EntityBase` / `BodyState` fields (x, y, z, velocity, ground/water) plus
 *    `yaw` and the previous tick's transform for render interpolation,
 *  - `type`: the shared `MobTypeDef` (data: size, speed, model, drops, behaviour),
 *  - `health`: hit points, hurt flash / invulnerability, death animation, daylight burning,
 *  - `ai`: the state machine (see ai.ts) and path-following state,
 *  - `anim`: head look and walk cycle, written by the simulation and read by the renderer.
 *
 * Systems (`MobSystem`) iterate these; the renderer only reads them.
 */
import { allocateEntityId, type EntityBase } from '../entity/entities';
import type { PathNode } from './pathfinding';
import type { MobTypeDef } from './mobTypes';

export type AiState = 'idle' | 'wander' | 'flee' | 'chase' | 'attack' | 'dead';

export interface HealthComponent {
  hp: number;
  max: number;
  /** Seconds left of the red hurt flash (also the invulnerability window). */
  hurtTime: number;
  /** Seconds since death, or -1 while alive. */
  deathTime: number;
  /** Currently burning in daylight. */
  burning: boolean;
  burnTimer: number;
}

export interface AiComponent {
  state: AiState;
  /** Seconds spent in the current state. */
  stateTime: number;
  /** How long to stay idle / wander / flee before reconsidering. */
  stateDuration: number;
  /** Current path (feet cells) and the index of the next waypoint. */
  path: PathNode[] | null;
  pathIndex: number;
  /** Seconds until the path may be recomputed. */
  repathTimer: number;
  /** Cell the current path was computed toward. */
  goal: PathNode | null;
  /** Hit since the last AI update; where the hit came from. */
  hurtFrom: { x: number; z: number } | null;
  /** Point to run away from while fleeing. */
  fleeFrom: { x: number; z: number } | null;
  attackCooldown: number;
  /** Seconds of reduced steering after a knockback. */
  knockbackTime: number;
  /** Line-of-sight cache (refreshed a few times a second). */
  canSee: boolean;
  losTimer: number;
  /** Blocked by a wall last tick while trying to move (triggers a jump). */
  blocked: boolean;
  /** Seconds without progress toward the next waypoint. */
  stuckTime: number;
  /** Seconds left of the attack swing animation. */
  swingTime: number;
}

export interface AnimComponent {
  /** Head yaw relative to the body, radians. */
  headYaw: number;
  headPitch: number;
  /** Walk cycle phase (radians) and amplitude 0..1. */
  walkPhase: number;
  walkAmount: number;
}

export interface Mob extends EntityBase {
  readonly kind: 'mob';
  readonly type: MobTypeDef;
  /** Body facing; 0 faces -Z, positive turns toward +X (like the player). */
  yaw: number;
  prevX: number;
  prevY: number;
  prevZ: number;
  prevYaw: number;
  health: HealthComponent;
  ai: AiComponent;
  anim: AnimComponent;
}

export function createMob(type: MobTypeDef, x: number, y: number, z: number, yaw = 0): Mob {
  return {
    id: allocateEntityId(),
    kind: 'mob',
    type,
    x, y, z,
    vx: 0, vy: 0, vz: 0,
    onGround: false,
    inWater: false,
    age: 0,
    removed: false,
    yaw,
    prevX: x, prevY: y, prevZ: z, prevYaw: yaw,
    health: { hp: type.maxHealth, max: type.maxHealth, hurtTime: 0, deathTime: -1, burning: false, burnTimer: 0 },
    ai: {
      state: 'idle',
      stateTime: 0,
      stateDuration: 1,
      path: null,
      pathIndex: 0,
      repathTimer: 0,
      goal: null,
      hurtFrom: null,
      fleeFrom: null,
      attackCooldown: 0,
      knockbackTime: 0,
      canSee: false,
      losTimer: 0,
      blocked: false,
      stuckTime: 0,
      swingTime: 0,
    },
    anim: { headYaw: 0, headPitch: 0, walkPhase: 0, walkAmount: 0 },
  };
}

export function isAlive(m: Mob): boolean {
  return m.health.deathTime < 0 && !m.removed;
}

/** The mob's collision box (feet-centred). */
export function mobAabb(m: { x: number; y: number; z: number; type: MobTypeDef }): { minX: number; minY: number; minZ: number; maxX: number; maxY: number; maxZ: number } {
  const w = m.type.halfWidth;
  return { minX: m.x - w, minY: m.y, minZ: m.z - w, maxX: m.x + w, maxY: m.y + m.type.height, maxZ: m.z + w };
}
