import type { PlayerIntent } from './intent';
import {
  JOYSTICK_RADIUS,
  clampToRadius,
  endGesture,
  joystickVector,
  startGesture,
  stickSprints,
  updateGesture,
  type Gesture,
} from './touchMath';

/** Radians per CSS pixel of finger drag at sensitivity 1. */
export const TOUCH_LOOK_SENSITIVITY = 0.006;

/** The movement stick lives in this fraction of the screen width, from the left. */
const MOVE_ZONE_FRACTION = 0.4;

export interface TouchControlHooks {
  /** A hold on the look area eats (secondary) instead of mining (primary): food is held. */
  holdUsesSecondary(): boolean;
  /** A tap on the look area attacks (primary) instead of placing / using: a mob is targeted. */
  tapIsAttack(): boolean;
  /** A mouse (not a finger) pressed the look area: hand it to pointer lock instead. */
  mouseOnLookArea(): void;
}

type ButtonName = 'jump' | 'sneak' | 'sprint' | 'fly' | 'flyDown' | 'inventory' | 'drop' | 'pause';

interface ButtonDef {
  name: ButtonName;
  label: string;
  title: string;
  /** Toggle buttons latch on tap; the others are held (or fire once on press). */
  kind: 'hold' | 'toggle' | 'press';
}

const BUTTONS: readonly ButtonDef[] = [
  { name: 'jump', label: '⤒', title: 'Jump / swim up / fly up', kind: 'hold' },
  { name: 'sneak', label: '⤓', title: 'Sneak (toggle)', kind: 'toggle' },
  { name: 'sprint', label: '»', title: 'Sprint (toggle)', kind: 'toggle' },
  { name: 'fly', label: '✈', title: 'Fly (creative)', kind: 'press' },
  { name: 'flyDown', label: '▼', title: 'Fly down', kind: 'hold' },
  { name: 'inventory', label: '▦', title: 'Inventory', kind: 'press' },
  { name: 'drop', label: '⇣', title: 'Drop held item', kind: 'press' },
  { name: 'pause', label: 'II', title: 'Pause', kind: 'press' },
];

/**
 * DOM overlay for phones and tablets (shown only while `body.touch` is set). Pointer events with
 * multi-touch: one finger on the left drives a floating joystick while another on the right looks,
 * taps (place / use, or attack a targeted mob) and holds (mine with the crack overlay, or eat).
 * Actions aim at the crosshair (screen centre), exactly like the desktop.
 */
export class TouchControls {
  readonly root: HTMLDivElement;
  private readonly lookArea: HTMLDivElement;
  private readonly stickBase: HTMLDivElement;
  private readonly stickKnob: HTMLDivElement;
  private readonly progressEl: HTMLDivElement;
  private readonly buttons = new Map<ButtonName, HTMLButtonElement>();
  private readonly abort = new AbortController();

  // Movement stick.
  private stickId = -1;
  private stickX = 0;
  private stickY = 0;
  private stickDX = 0;
  private stickDY = 0;
  // Look finger.
  private lookId = -1;
  private gesture: Gesture | null = null;
  /** Which action the current hold drives (decided when the hold starts). */
  private holdAction: 'primary' | 'secondary' | null = null;
  private holdStarted = false;
  private lookDX = 0;
  private lookDY = 0;
  private pendingTap = false;
  // Buttons.
  private readonly held = new Set<ButtonName>();
  private readonly pressed = new Set<ButtonName>();
  private readonly toggled = new Set<ButtonName>();
  private hotbarTap = -1;
  /** Look sensitivity multiplier (settings). */
  sensitivity = 1;

  constructor(
    private readonly hooks: TouchControlHooks,
    parent: HTMLElement = document.body,
  ) {
    const root = document.createElement('div');
    root.className = 'touch-ui';
    this.lookArea = document.createElement('div');
    this.lookArea.className = 'touch-look';
    this.stickBase = document.createElement('div');
    this.stickBase.className = 'touch-stick';
    this.stickBase.hidden = true;
    this.stickKnob = document.createElement('div');
    this.stickKnob.className = 'touch-knob';
    this.stickBase.appendChild(this.stickKnob);
    this.progressEl = document.createElement('div');
    this.progressEl.className = 'touch-progress';
    this.progressEl.hidden = true;
    const rotate = document.createElement('div');
    rotate.className = 'rotate-hint';
    rotate.textContent = 'Rotate your device to landscape to play';
    root.append(this.lookArea, this.stickBase, this.progressEl, rotate);
    for (const def of BUTTONS) root.appendChild(this.makeButton(def));
    parent.appendChild(root);
    this.root = root;

    const signal = this.abort.signal;
    const look = this.lookArea;
    look.addEventListener('pointerdown', (e) => this.onDown(e), { signal });
    look.addEventListener('pointermove', (e) => this.onMove(e), { signal });
    look.addEventListener('pointerup', (e) => this.onUp(e, false), { signal });
    look.addEventListener('pointercancel', (e) => this.onUp(e, true), { signal });
    look.addEventListener('contextmenu', (e) => e.preventDefault(), { signal });
  }

  private makeButton(def: ButtonDef): HTMLButtonElement {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = `touch-btn touch-${def.name}`;
    b.textContent = def.label;
    b.title = def.title;
    b.setAttribute('aria-label', def.title);
    const signal = this.abort.signal;
    b.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      e.stopPropagation();
      try {
        b.setPointerCapture(e.pointerId);
      } catch {
        // synthetic events may have no active pointer
      }
      if (def.kind === 'hold') this.held.add(def.name);
      else if (def.kind === 'toggle') {
        if (this.toggled.has(def.name)) this.toggled.delete(def.name);
        else this.toggled.add(def.name);
      } else this.pressed.add(def.name);
      this.refreshButtons();
    }, { signal });
    const release = (): void => {
      if (def.kind === 'hold') this.held.delete(def.name);
      this.refreshButtons();
    };
    b.addEventListener('pointerup', release, { signal });
    b.addEventListener('pointercancel', release, { signal });
    b.addEventListener('contextmenu', (e) => e.preventDefault(), { signal });
    this.buttons.set(def.name, b);
    return b;
  }

  private refreshButtons(): void {
    for (const [name, b] of this.buttons) b.classList.toggle('active', this.held.has(name) || this.toggled.has(name));
  }

  /** The hotbar was tapped. */
  selectHotbar(slot: number): void {
    this.hotbarTap = slot;
  }

  /** Per frame: shows the creative buttons and the mining / eating progress ring (0..1, or <0 to hide). */
  update(creative: boolean, flying: boolean, progress: number): void {
    this.root.classList.toggle('creative', creative);
    this.root.classList.toggle('flying', flying);
    const show = progress > 0;
    if (this.progressEl.hidden === show) this.progressEl.hidden = !show;
    if (show) this.progressEl.style.setProperty('--p', `${Math.min(1, progress) * 360}deg`);
  }

  /** Drops every finger and toggle (screen opened, paused, died). */
  releaseAll(): void {
    this.stickId = this.lookId = -1;
    this.stickDX = this.stickDY = 0;
    this.stickBase.hidden = true;
    this.gesture = null;
    this.holdAction = null;
    this.holdStarted = false;
    this.pendingTap = false;
    this.lookDX = this.lookDY = 0;
    this.held.clear();
    this.pressed.clear();
    this.toggled.delete('sprint');
    this.hotbarTap = -1;
    this.refreshButtons();
  }

  /** Adds this frame's touch intent to `out`. `now` in ms. */
  fill(out: PlayerIntent, now: number): void {
    // Joystick.
    if (this.stickId >= 0) {
      const v = joystickVector(this.stickDX, this.stickDY);
      out.moveX += v.x;
      out.moveZ += v.z;
      if (stickSprints(v)) out.sprint = true;
    }
    if (this.toggled.has('sprint')) out.sprint = true;
    if (this.toggled.has('sneak') || this.held.has('flyDown')) out.sneak = true;
    if (this.held.has('jump')) out.jump = true;

    // Look finger: time alone can turn a still finger into a hold.
    const g = this.gesture;
    if (g) {
      const d = updateGesture(g, g.lastX, g.lastY, now);
      this.lookDX += d.dx;
      this.lookDY += d.dy;
      if (g.phase === 'hold') {
        if (!this.holdStarted) {
          this.holdStarted = true;
          this.holdAction = this.hooks.holdUsesSecondary() ? 'secondary' : 'primary';
          if (this.holdAction === 'primary') out.primaryPressed = true;
          else out.secondaryPressed = true;
        }
        if (this.holdAction === 'primary') out.primary = true;
        else out.secondary = true;
      }
    }
    const k = TOUCH_LOOK_SENSITIVITY * this.sensitivity;
    out.lookYaw += this.lookDX * k;
    out.lookPitch -= this.lookDY * k;
    this.lookDX = this.lookDY = 0;

    if (this.pendingTap) {
      this.pendingTap = false;
      if (this.hooks.tapIsAttack()) out.primary = out.primaryPressed = true;
      else out.secondary = out.secondaryPressed = true;
    }

    if (this.pressed.has('fly')) out.toggleFly = !out.toggleFly;
    if (this.pressed.has('inventory')) out.openInventory = true;
    if (this.pressed.has('drop')) out.drop = true;
    if (this.pressed.has('pause')) out.pause = true;
    this.pressed.clear();
    if (this.hotbarTap >= 0) {
      out.hotbarSlot = this.hotbarTap;
      this.hotbarTap = -1;
    }
  }

  dispose(): void {
    this.abort.abort();
    this.root.remove();
  }

  // --- Pointer handling on the look / move area ---------------------------------------------------

  private onDown(e: PointerEvent): void {
    if (e.pointerType === 'mouse') {
      this.hooks.mouseOnLookArea();
      return;
    }
    e.preventDefault();
    try {
      this.lookArea.setPointerCapture(e.pointerId);
    } catch {
      // synthetic events may have no active pointer
    }
    const w = this.lookArea.clientWidth || window.innerWidth;
    if (e.clientX < w * MOVE_ZONE_FRACTION && this.stickId < 0) {
      // Floating joystick: the base appears under the finger.
      this.stickId = e.pointerId;
      this.stickX = e.clientX;
      this.stickY = e.clientY;
      this.stickDX = this.stickDY = 0;
      this.stickBase.hidden = false;
      this.stickBase.style.transform = `translate(${this.stickX}px, ${this.stickY}px)`;
      this.stickKnob.style.transform = 'translate(0px, 0px)';
      return;
    }
    if (this.lookId >= 0) return; // one look finger at a time
    this.lookId = e.pointerId;
    this.gesture = startGesture(e.clientX, e.clientY, e.timeStamp || performance.now());
    this.holdStarted = false;
    this.holdAction = null;
  }

  private onMove(e: PointerEvent): void {
    if (e.pointerId === this.stickId) {
      let dx = e.clientX - this.stickX;
      let dy = e.clientY - this.stickY;
      // Dragging past the rim pulls the base along, so reversing direction responds at once.
      const len = Math.hypot(dx, dy);
      const max = JOYSTICK_RADIUS * 1.6;
      if (len > max) {
        this.stickX += (dx / len) * (len - max);
        this.stickY += (dy / len) * (len - max);
        dx = e.clientX - this.stickX;
        dy = e.clientY - this.stickY;
        this.stickBase.style.transform = `translate(${this.stickX}px, ${this.stickY}px)`;
      }
      this.stickDX = dx;
      this.stickDY = dy;
      const k = clampToRadius(dx, dy);
      this.stickKnob.style.transform = `translate(${k.x}px, ${k.y}px)`;
      return;
    }
    if (e.pointerId === this.lookId && this.gesture) {
      const d = updateGesture(this.gesture, e.clientX, e.clientY, e.timeStamp || performance.now());
      this.lookDX += d.dx;
      this.lookDY += d.dy;
    }
  }

  private onUp(e: PointerEvent, cancelled: boolean): void {
    if (e.pointerId === this.stickId) {
      this.stickId = -1;
      this.stickDX = this.stickDY = 0;
      this.stickBase.hidden = true;
      return;
    }
    if (e.pointerId !== this.lookId || !this.gesture) return;
    const result = endGesture(this.gesture, e.clientX, e.clientY, e.timeStamp || performance.now());
    if (!cancelled && result === 'tap') this.pendingTap = true;
    this.lookId = -1;
    this.gesture = null;
    this.holdAction = null;
    this.holdStarted = false;
  }
}
