// "Create world from map" (MAP_WORLDS.md phase F): pick a rectangle on an OpenStreetMap map,
// see the area, world size and expected download / package sizes, choose scale, name and mode,
// then follow the download -> prepare -> save progress (cancellable while downloading).
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { MAX_MAP_AREA_KM2, WARN_MAP_AREA_KM2, estimateMap, formatBytes, parseBBox } from '@voxel/mapgen';
import type { GeoBBox } from '@voxel/shared';
import type { GameMode } from '../storage/worldStore';
import { h } from './dom';

/** Where a map world's creation is. */
export type MapStage = 'download' | 'elevation' | 'prepare' | 'save' | 'enter';

export interface MapProgress {
  stage: MapStage;
  /** Bytes of OSM data received so far (download). */
  bytes?: number;
  /** Mirror being tried (download). */
  host?: string;
  /** Elevation tiles downloaded so far and needed (elevation). */
  done?: number;
  total?: number;
}

export interface CreateMapInput {
  name: string;
  mode: GameMode;
  bbox: GeoBBox;
  /** Blocks per metre. */
  scale: number;
  signal: AbortSignal;
  onProgress: (p: MapProgress) => void;
}

export interface MapPickerOptions {
  create(input: CreateMapInput): Promise<void>;
  back(): void;
}

/** Where the picker opens the first time: Bryant Park, New York (the phase E test area). */
export const DEFAULT_MAP_BBOX: GeoBBox = [40.7505, -73.987, 40.756, -73.979];
const STORAGE_KEY = 'blockwright.mapPicker';
const CREDIT = '© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors';

/**
 * OpenStreetMap-based tile servers, tried in order: some networks cannot reach one of them (e.g.
 * tile.openstreetmap.org resets connections from some regions), so the picker falls back to the
 * next when the current one fails before showing any tile. `VITE_MAP_TILE_URL` puts a server first.
 */
const TILE_SOURCES: readonly string[] = [
  ...(import.meta.env['VITE_MAP_TILE_URL'] ? [String(import.meta.env['VITE_MAP_TILE_URL'])] : []),
  'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
  'https://tile.openstreetmap.de/{z}/{x}/{y}.png',
  'https://{s}.tile.openstreetmap.fr/osmfr/{z}/{x}/{y}.png',
];

/** Adds the first tile source that works (switching on errors until a tile loads). */
function addTiles(map: L.Map, i = 0): void {
  const url = TILE_SOURCES[i];
  if (!url) return;
  const layer = L.tileLayer(url, { maxZoom: 19, attribution: CREDIT, subdomains: 'abc' });
  let loaded = false;
  let errors = 0;
  layer.on('tileload', () => (loaded = true));
  layer.on('tileerror', () => {
    if (loaded || ++errors < 3 || i + 1 >= TILE_SOURCES.length) return;
    console.warn(`Map tiles from ${new URL(url.replace('{s}', 'a').replace(/\{[xyz]\}/g, '0')).host} failed; trying the next server`);
    map.removeLayer(layer);
    addTiles(map, i + 1);
  });
  layer.addTo(map);
}

function loadLastBBox(): GeoBBox {
  try {
    const v = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? 'null') as unknown;
    if (Array.isArray(v) && v.length === 4 && v.every((n) => typeof n === 'number')) return v as GeoBBox;
  } catch {
    // storage blocked or junk: use the default
  }
  return DEFAULT_MAP_BBOX;
}

function saveLastBBox(b: GeoBBox): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(b));
  } catch {
    // not remembered, that's all
  }
}

const fmt = (v: number): string => v.toFixed(5).replace(/0+$/, '').replace(/\.$/, '');
const bboxText = (b: GeoBBox): string => b.map(fmt).join(', ');
const toBounds = (b: GeoBBox): L.LatLngBounds => L.latLngBounds([b[0], b[1]], [b[2], b[3]]);
const fromBounds = (lb: L.LatLngBounds): GeoBBox => [lb.getSouth(), lb.getWest(), lb.getNorth(), lb.getEast()];

/** Progress bar position per stage (the download fills most of it). */
const STAGE_RANGE: Record<MapStage, [number, number]> = { download: [0.02, 0.7], elevation: [0.72, 0.84], prepare: [0.87, 0.87], save: [0.94, 0.94], enter: [1, 1] };

/**
 * Builds the screen. Call `mount()` once the element is in the document (Leaflet needs its size),
 * and `dispose()` when leaving it.
 */
export function createMapPicker(opts: MapPickerOptions): { el: HTMLElement; mount(): void; dispose(): void } {
  let bbox = loadLastBBox();
  let map: L.Map | undefined;
  let rect: L.Rectangle | undefined;
  const handles: L.Marker[] = [];
  let abort: AbortController | undefined;

  const mapEl = h('div', { class: 'map-picker', role: 'application', 'aria-label': 'Map: drag the orange corners, or Draw area, to choose the place' });
  const bboxInput = h('input', { type: 'text', id: 'map-bbox', spellcheck: 'false', value: bboxText(bbox) });
  const estimate = h('p', { class: 'map-estimate', role: 'status' });
  const scale = h(
    'select',
    { id: 'map-scale' },
    h('option', { value: '1' }, '1 block = 1 m (default)'),
    h('option', { value: '0.5' }, '1 block = 2 m (larger areas, less detail)'),
  );
  const name = h('input', { type: 'text', id: 'map-name', maxlength: '40', value: '' });
  const mode = h('select', { id: 'map-mode' }, h('option', { value: 'creative' }, 'Creative (fly, every item, no damage)'), h('option', { value: 'survival' }, 'Survival (health, hunger, crafting)'));
  const fill = h('div', { class: 'map-progress-fill' });
  const stageText = h('p', { class: 'map-progress-text' });
  const progress = h('div', { class: 'map-progress', hidden: true, role: 'progressbar', 'aria-valuemin': '0', 'aria-valuemax': '100' }, h('div', { class: 'map-progress-bar' }, fill), stageText);
  const error = h('p', { class: 'menu-error', role: 'alert' });
  const drawBtn = h('button', { class: 'btn', type: 'button', id: 'map-draw' }, 'Draw area');
  const viewBtn = h('button', { class: 'btn', type: 'button', id: 'map-use-view' }, 'Use visible area');
  const backBtn = h('button', { class: 'btn', type: 'button', id: 'map-back' }, 'Back');
  const createBtn = h('button', { class: 'btn primary', type: 'submit', id: 'map-create' }, 'Create & play');

  const scaleValue = (): number => (scale.value === '0.5' ? 0.5 : 1);
  const defaultName = (b: GeoBBox): string => `Map ${fmt((b[0] + b[2]) / 2).slice(0, 7)}, ${fmt((b[1] + b[3]) / 2).slice(0, 8)}`;
  let nameEdited = false;
  name.addEventListener('input', () => (nameEdited = name.value.trim() !== ''));

  /** Too-large areas cannot be created; returns a reason, or '' when fine. */
  const refuse = (b: GeoBBox): string => {
    const e = estimateMap(b, scaleValue());
    return e.areaKm2 > MAX_MAP_AREA_KM2 ? `That is ${e.areaKm2.toFixed(1)} km²; the limit is ${MAX_MAP_AREA_KM2} km². Pick a smaller area.` : '';
  };

  const refresh = (): void => {
    const e = estimateMap(bbox, scaleValue());
    const big = e.areaKm2 > WARN_MAP_AREA_KM2;
    estimate.className = `map-estimate${e.areaKm2 > MAX_MAP_AREA_KM2 ? ' too-big' : big ? ' warn' : ''}`;
    estimate.textContent =
      `${e.areaKm2 < 0.1 ? e.areaKm2.toFixed(3) : e.areaKm2.toFixed(2)} km² · world ${e.widthBlocks} × ${e.depthBlocks} blocks · ` +
      `download ≈ ${formatBytes(e.osmBytes)} · map data ≈ ${formatBytes(e.packageBytes)}` +
      (e.areaKm2 > MAX_MAP_AREA_KM2 ? ` · too large (max ${MAX_MAP_AREA_KM2} km²)` : big ? ' · large: downloading and preparing will be slow' : '');
    if (!nameEdited) name.value = defaultName(bbox);
    createBtn.disabled = e.areaKm2 > MAX_MAP_AREA_KM2 || !!abort;
  };

  /** Moves the rectangle, its corner handles and the text field to `b`. */
  const setBBox = (b: GeoBBox, from: 'map' | 'text' | 'init'): void => {
    bbox = b;
    if (from !== 'text') bboxInput.value = bboxText(b);
    if (rect) {
      rect.setBounds(toBounds(b));
      handles[0]?.setLatLng([b[2], b[1]]); // north-west
      handles[1]?.setLatLng([b[0], b[3]]); // south-east
    }
    refresh();
  };

  bboxInput.addEventListener('change', () => {
    try {
      const b = parseBBox(bboxInput.value);
      error.textContent = '';
      setBBox(b, 'text');
      map?.fitBounds(toBounds(b), { padding: [30, 30] });
    } catch (err) {
      error.textContent = err instanceof Error ? err.message : String(err);
    }
  });
  scale.addEventListener('change', refresh);

  viewBtn.addEventListener('click', () => {
    if (!map) return;
    // The middle 60% of the view, so the corners stay easy to grab.
    const v = map.getBounds();
    const dLat = (v.getNorth() - v.getSouth()) * 0.2;
    const dLon = (v.getEast() - v.getWest()) * 0.2;
    setBBox([v.getSouth() + dLat, v.getWest() + dLon, v.getNorth() - dLat, v.getEast() - dLon], 'map');
  });

  drawBtn.addEventListener('click', () => {
    if (!map || mapEl.classList.contains('drawing')) return;
    const m = map;
    m.dragging.disable();
    mapEl.classList.add('drawing');
    drawBtn.textContent = 'Drag on the map...';
    // Plain pointer events on the map element (captured, so the corner handle that follows the
    // pointer cannot swallow them), converted to coordinates by Leaflet.
    let start: L.LatLng | undefined;
    const at = (e: PointerEvent): L.LatLng => m.mouseEventToLatLng(e as unknown as MouseEvent);
    const down = (e: PointerEvent): void => {
      e.preventDefault();
      e.stopPropagation();
      start = at(e);
      mapEl.setPointerCapture(e.pointerId);
    };
    const move = (e: PointerEvent): void => {
      if (start) setBBox(fromBounds(L.latLngBounds(start, at(e))), 'map');
    };
    const up = (e: PointerEvent): void => {
      if (!start) return;
      setBBox(fromBounds(L.latLngBounds(start, at(e))), 'map');
      mapEl.removeEventListener('pointerdown', down, true);
      mapEl.removeEventListener('pointermove', move, true);
      mapEl.removeEventListener('pointerup', up, true);
      m.dragging.enable();
      mapEl.classList.remove('drawing');
      drawBtn.textContent = 'Draw area';
    };
    mapEl.addEventListener('pointerdown', down, true);
    mapEl.addEventListener('pointermove', move, true);
    mapEl.addEventListener('pointerup', up, true);
  });

  const setProgress = (p: MapProgress): void => {
    const [lo, hi] = STAGE_RANGE[p.stage];
    let f = lo;
    if (p.stage === 'download') {
      const expected = Math.max(1, estimateMap(bbox, scaleValue()).osmBytes);
      f = lo + (hi - lo) * Math.min(0.97, (p.bytes ?? 0) / expected);
    } else if (p.stage === 'elevation' && p.total) {
      f = lo + (hi - lo) * ((p.done ?? 0) / p.total);
    }
    fill.style.width = `${Math.round(f * 100)}%`;
    progress.setAttribute('aria-valuenow', String(Math.round(f * 100)));
    stageText.textContent =
      p.stage === 'download'
        ? `Downloading OpenStreetMap data${p.host ? ` from ${p.host}` : ''}... ${p.bytes ? formatBytes(p.bytes) : 'waiting for the server'}`
        : p.stage === 'elevation'
          ? `Downloading elevation data... ${p.done ?? 0} of ${p.total ?? 0} tiles`
          : p.stage === 'prepare'
          ? 'Preparing the map...'
          : p.stage === 'save'
            ? 'Saving the map...'
            : 'Starting the world...';
  };

  const busy = (on: boolean): void => {
    for (const el of [bboxInput, scale, name, mode, drawBtn, viewBtn]) el.disabled = on;
    backBtn.textContent = on ? 'Cancel' : 'Back';
    progress.hidden = !on;
    refresh();
  };

  backBtn.addEventListener('click', () => {
    if (abort) {
      abort.abort();
      return;
    }
    opts.back();
  });

  const submit = async (e: Event): Promise<void> => {
    e.preventDefault();
    if (abort) return;
    const reason = refuse(bbox);
    if (reason) {
      error.textContent = reason;
      return;
    }
    error.textContent = '';
    saveLastBBox(bbox);
    abort = new AbortController();
    busy(true);
    setProgress({ stage: 'download' });
    try {
      await opts.create({
        name: name.value.trim() || defaultName(bbox),
        mode: mode.value === 'survival' ? 'survival' : 'creative',
        bbox,
        scale: scaleValue(),
        signal: abort.signal,
        onProgress: setProgress,
      });
    } catch (err) {
      const aborted = abort?.signal.aborted;
      console.warn('Map world creation failed', err);
      error.textContent = aborted ? 'Cancelled.' : err instanceof Error ? err.message : String(err);
    } finally {
      abort = undefined;
      busy(false);
    }
  };

  const el = h(
    'form',
    { class: 'menu-panel map-panel', onsubmit: (e: Event) => void submit(e) },
    h('h2', {}, 'Create world from map'),
    h('p', { class: 'map-help' }, 'Choose a place: drag the orange corners, use Draw area, or type the coordinates. Small areas (under 1 km²) load fastest.'),
    mapEl,
    h('div', { class: 'map-tools' }, drawBtn, viewBtn),
    h('label', { for: 'map-bbox' }, 'Area (south, west, north, east in degrees)'),
    bboxInput,
    estimate,
    h('div', { class: 'map-fields' }, h('div', {}, h('label', { for: 'map-name' }, 'Name'), name), h('div', {}, h('label', { for: 'map-mode' }, 'Mode'), mode), h('div', {}, h('label', { for: 'map-scale' }, 'Scale'), scale)),
    progress,
    h('div', { class: 'menu-buttons' }, backBtn, createBtn),
    error,
    h('p', { class: 'map-credit' }, 'Map data © OpenStreetMap contributors (ODbL), downloaded from Overpass. Map worlds keep this credit in the world list and the F3 screen.'),
  );

  return {
    el,
    mount(): void {
      map = L.map(mapEl, { zoomControl: true, attributionControl: true, boxZoom: false });
      addTiles(map);
      map.fitBounds(toBounds(bbox), { padding: [30, 30] });
      rect = L.rectangle(toBounds(bbox), { color: '#f59e0b', weight: 2, fillOpacity: 0.12, interactive: false }).addTo(map);
      const icon = L.divIcon({ className: 'map-handle', iconSize: [16, 16] });
      const nw = L.marker([bbox[2], bbox[1]], { draggable: true, icon, keyboard: true, title: 'North-west corner' }).addTo(map);
      const se = L.marker([bbox[0], bbox[3]], { draggable: true, icon, keyboard: true, title: 'South-east corner' }).addTo(map);
      handles.push(nw, se);
      const onDrag = (): void => setBBox(fromBounds(L.latLngBounds(nw.getLatLng(), se.getLatLng())), 'map');
      nw.on('drag', onDrag);
      se.on('drag', onDrag);
      setBBox(bbox, 'init');
      // The panel may still be laying out.
      requestAnimationFrame(() => map?.invalidateSize());
    },
    dispose(): void {
      abort?.abort();
      map?.remove();
      map = undefined;
    },
  };
}
