import type { GameMode, GeneratorKind, WorldMeta } from '../storage/worldStore';
import { createMapPicker, type CreateMapInput } from './mapPicker';
import { LIMITS, type Settings, type TouchMode } from '../settings/settings';
import { h } from './dom';
import { APP_AUTHOR, APP_VERSION, FOLLOW_CODES, FOLLOW_URL, byline } from './about';

/** The game's (original) name, shown on the title screen and tab title. */
export const GAME_TITLE = 'Blockwright';

export interface CreateWorldInput {
  name: string;
  /** Raw seed text; empty means random (hashed by the caller). */
  seedText: string;
  mode: GameMode;
  /** `map`: the stub test area (phase A); real places go through `createMap`. */
  generator: GeneratorKind;
}

export interface JoinServerInput {
  /** Server address as typed (normalized by the app). */
  address: string;
  name: string;
}

/** Remembered multiplayer form values plus recently joined addresses (newest first). */
export interface MultiplayerDefaults extends JoinServerInput {
  recent: string[];
}

/** What the menus ask the app to do. Errors thrown here are shown in the menu. */
export interface MenuActions {
  /** Connects to a multiplayer server (Milestone 10). */
  joinServer(input: JoinServerInput): Promise<void>;
  /** Last used server address and player name (remembered in localStorage). */
  multiplayerDefaults(): MultiplayerDefaults;
  listWorlds(): Promise<WorldMeta[]>;
  play(meta: WorldMeta): Promise<void>;
  create(input: CreateWorldInput): Promise<void>;
  /** Downloads, prepares and stores a real place, then starts the world (phase F picker). */
  createMap(input: CreateMapInput): Promise<void>;
  rename(id: string, name: string): Promise<void>;
  remove(id: string): Promise<void>;
  resume(): void;
  saveAndQuit(): Promise<void>;
  setViewDistance(chunks: number): void;
  /** Current settings (Milestone 9 settings screen). */
  getSettings(): Settings;
  /** Applies and stores a change; returns false if it could not be saved (storage blocked). */
  updateSettings(patch: Partial<Settings>): boolean;
  /** Detected device quality preset, shown on the settings screen. */
  qualityName: string;
}

/** The logo: one span per letter so CSS can give each its own block-like tilt and colour. */
function titleLetters(text: string): HTMLElement[] {
  return [...text].map((ch, i) => h('span', { class: 'logo-letter', style: `--i:${i};--tilt:${((i % 3) - 1) * 3}deg`, 'aria-hidden': 'true' }, ch));
}

const pct = (v: number): string => (v <= 0 ? 'off' : `${Math.round(v * 100)}%`);

function formatDate(ms: number): string {
  const d = new Date(ms);
  const sameDay = d.toDateString() === new Date().toDateString();
  return sameDay ? `today ${d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}` : d.toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' });
}

/**
 * DOM overlay for the title screen (world list, create, rename, delete) and the pause menu.
 * Everything lives under one root element; `hide()` removes the overlay but keeps the root.
 */
export class Menus {
  private readonly root: HTMLDivElement;
  private busy = false;
  /** Live-updating bits of the current screen (ping); cleared whenever the screen changes. */
  private ticker: number | undefined;
  /** Cleanup of the current screen (the map picker's Leaflet map), run when it is replaced. */
  private leave: (() => void) | undefined;

  constructor(
    private readonly actions: MenuActions,
    private readonly savingEnabled: boolean,
    parent: HTMLElement = document.body,
  ) {
    this.root = h('div', { class: 'menu-root', hidden: true });
    parent.appendChild(this.root);
  }

  get isOpen(): boolean {
    return !this.root.hidden;
  }

  hide(): void {
    this.stopTicker();
    this.runLeave();
    this.root.hidden = true;
    this.root.replaceChildren();
    document.body.classList.remove('in-menu', 'in-title');
  }

  private runLeave(): void {
    const f = this.leave;
    this.leave = undefined;
    f?.();
  }

  private stopTicker(): void {
    if (this.ticker !== undefined) window.clearInterval(this.ticker);
    this.ticker = undefined;
  }

  private show(screen: HTMLElement, title: boolean): void {
    this.stopTicker();
    this.runLeave();
    this.root.replaceChildren(screen);
    this.root.hidden = false;
    document.body.classList.add('in-menu');
    document.body.classList.toggle('in-title', title);
    screen.querySelector<HTMLElement>('[autofocus]')?.focus();
  }

  /** Shows a short status screen ("Saving..."). */
  showStatus(text: string): void {
    this.show(h('div', { class: 'menu-panel menu-status' }, h('p', {}, text)), true);
  }

  private notice(): HTMLElement | null {
    return this.savingEnabled
      ? null
      : h('div', { class: 'menu-notice', role: 'status' }, 'Saving disabled: storage is unavailable (private mode or blocked). Worlds you create are temporary.');
  }

  /** Runs an action with the buttons locked; shows its error in `errorEl`. */
  private async run(errorEl: HTMLElement, fn: () => Promise<void>): Promise<void> {
    if (this.busy) return;
    this.busy = true;
    this.root.classList.add('busy');
    errorEl.textContent = '';
    try {
      await fn();
    } catch (err) {
      console.error(err);
      errorEl.textContent = err instanceof Error ? err.message : String(err);
    } finally {
      this.busy = false;
      this.root.classList.remove('busy');
    }
  }

  // --- Follow (QR codes) -------------------------------------------------------------------------

  showFollow(): void {
    const who = APP_AUTHOR || GAME_TITLE;
    const link = h('a', { class: 'follow-link', href: FOLLOW_URL, target: '_blank', rel: 'noopener' }, FOLLOW_URL.replace(/^https?:\/\//, ''));
    const screen = h(
      'div',
      { class: 'menu-panel follow-screen' },
      h('h2', {}, `Follow ${who}`),
      FOLLOW_CODES.length > 0
        ? h('p', {}, 'Scan a code to follow along for updates.')
        : h('p', {}, 'Follow along for updates at ', link, '.'),
      FOLLOW_CODES.length > 0
        ? h(
            'div',
            { class: 'follow-codes' },
            ...FOLLOW_CODES.map((c) =>
              h('figure', { class: 'follow-code' }, h('img', { src: c.src, alt: `${c.label} QR code`, loading: 'lazy', decoding: 'async' }), h('figcaption', {}, c.label)),
            ),
          )
        : null,
      h('p', { class: 'follow-version' }, `${GAME_TITLE} v${APP_VERSION}`),
      h(
        'div',
        { class: 'menu-buttons' },
        h('button', { class: 'btn', type: 'button', autofocus: true, onclick: () => void this.showTitle() }, 'Back'),
      ),
    );
    this.show(screen, true);
  }

  // --- Title / world list ---------------------------------------------------------------------

  async showTitle(): Promise<void> {
    const error = h('p', { class: 'menu-error', role: 'alert' });
    const list = h('ul', { class: 'world-list' }, h('li', { class: 'world-empty' }, 'Loading worlds...'));
    const screen = h(
      'div',
      { class: 'menu-panel title-screen' },
      h('h1', { class: 'game-title', 'aria-label': GAME_TITLE }, ...titleLetters(GAME_TITLE)),
      h('p', { class: 'game-subtitle' }, 'build anything, block by block'),
      this.notice(),
      h(
        'div',
        { class: 'menu-row' },
        h('h2', {}, 'Worlds'),
        h(
          'div',
          { class: 'menu-row-buttons' },
          h('button', { class: 'btn', id: 'title-settings', onclick: () => this.showSettings(() => void this.showTitle(), true) }, 'Settings'),
          h('button', { class: 'btn', id: 'title-multiplayer', onclick: () => this.showMultiplayer() }, 'Multiplayer'),
          h('button', { class: 'btn', id: 'create-map-world', onclick: () => this.showCreateMap() }, 'Create world from map'),
          h('button', { class: 'btn primary', id: 'create-world', onclick: () => this.showCreate() }, 'Create world'),
        ),
      ),
      list,
      error,
      h(
        'div',
        { class: 'title-footer' },
        h('span', { class: 'title-byline' }, byline()),
        h('button', { class: 'btn', id: 'title-follow', onclick: () => this.showFollow() }, 'Follow'),
      ),
    );
    this.show(screen, true);
    let worlds: WorldMeta[] = [];
    try {
      worlds = await this.actions.listWorlds();
    } catch (err) {
      error.textContent = `Could not read saved worlds: ${err instanceof Error ? err.message : String(err)}`;
    }
    list.replaceChildren(
      ...(worlds.length === 0
        ? [h('li', { class: 'world-empty' }, this.savingEnabled ? 'No worlds yet. Create one to start.' : 'No saved worlds.')]
        : worlds.map((w) =>
            h(
              'li',
              { class: 'world-item', 'data-world-id': w.id },
              h(
                'div',
                { class: 'world-info' },
                h('span', { class: 'world-name' }, w.name),
                h('span', { class: 'world-detail' }, `${w.generator !== 'map' ? `Seed ${w.seed}` : w.bbox ? `Map ${((w.bbox[0] + w.bbox[2]) / 2).toFixed(4)}, ${((w.bbox[1] + w.bbox[3]) / 2).toFixed(4)}` : 'Map (test area)'} · ${w.gameMode === 'creative' ? 'Creative' : 'Survival'} · played ${formatDate(w.lastPlayed)}`),
                w.bbox ? h('span', { class: 'world-credit' }, 'Map data © OpenStreetMap contributors') : null,
              ),
              h(
                'div',
                { class: 'world-actions' },
                h('button', { class: 'btn primary', 'data-action': 'play', onclick: () => void this.run(error, () => this.actions.play(w)) }, 'Play'),
                h('button', { class: 'btn', 'data-action': 'rename', onclick: () => this.showRename(w) }, 'Rename'),
                h('button', { class: 'btn danger', 'data-action': 'delete', onclick: () => this.showDelete(w) }, 'Delete'),
              ),
            ),
          )),
    );
  }

  showCreate(): void {
    const error = h('p', { class: 'menu-error', role: 'alert' });
    const name = h('input', { type: 'text', id: 'world-name', maxlength: '40', value: 'New World', autofocus: true });
    const seed = h('input', { type: 'text', id: 'world-seed', maxlength: '64', placeholder: 'random' });
    const mode = h(
      'select',
      { id: 'world-mode' },
      h('option', { value: 'survival' }, 'Survival (health, hunger, crafting)'),
      h('option', { value: 'creative' }, 'Creative (fly, every item, no damage)'),
    );
    const type = h(
      'select',
      { id: 'world-type' },
      h('option', { value: 'terrain' }, 'Terrain (random landscape from the seed)'),
      h('option', { value: 'map' }, 'Map test area (flat ground, roads, buildings)'),
    );
    const submit = (e: Event): void => {
      e.preventDefault();
      const n = name.value.trim() || 'New World';
      const generator: GeneratorKind = type.value === 'map' ? 'map' : 'terrain';
      void this.run(error, () => this.actions.create({ name: n, seedText: seed.value, mode: mode.value === 'creative' ? 'creative' : 'survival', generator }));
    };
    const form = h(
      'form',
      { class: 'menu-panel', onsubmit: submit },
      h('h2', {}, 'Create world'),
      this.notice(),
      h('label', { for: 'world-name' }, 'Name'),
      name,
      h('label', { for: 'world-seed' }, 'Seed (number or any text; empty = random)'),
      seed,
      h('label', { for: 'world-mode' }, 'Mode'),
      mode,
      h('label', { for: 'world-type' }, 'World type'),
      type,
      h('p', { class: 'menu-hint' }, 'For a real place, use Create world from map on the title screen.'),
      h(
        'div',
        { class: 'menu-buttons' },
        h('button', { class: 'btn', type: 'button', onclick: () => void this.showTitle() }, 'Cancel'),
        h('button', { class: 'btn primary', type: 'submit', id: 'create-submit' }, 'Create & play'),
      ),
      error,
    );
    this.show(form, true);
    name.select();
  }

  /** Phase F: pick a real place on a map and create a world from it. */
  showCreateMap(): void {
    const picker = createMapPicker({
      create: (input) => this.actions.createMap(input),
      back: () => void this.showTitle(),
    });
    this.show(picker.el, true);
    picker.mount();
    this.leave = () => picker.dispose();
  }

  showRename(w: WorldMeta): void {
    const error = h('p', { class: 'menu-error', role: 'alert' });
    const name = h('input', { type: 'text', id: 'rename-input', maxlength: '40', value: w.name, autofocus: true });
    const form = h(
      'form',
      {
        class: 'menu-panel',
        onsubmit: (e: Event) => {
          e.preventDefault();
          const n = name.value.trim();
          if (!n) {
            error.textContent = 'Name cannot be empty.';
            return;
          }
          void this.run(error, async () => {
            await this.actions.rename(w.id, n);
            await this.showTitle();
          });
        },
      },
      h('h2', {}, 'Rename world'),
      name,
      h(
        'div',
        { class: 'menu-buttons' },
        h('button', { class: 'btn', type: 'button', onclick: () => void this.showTitle() }, 'Cancel'),
        h('button', { class: 'btn primary', type: 'submit' }, 'Rename'),
      ),
      error,
    );
    this.show(form, true);
    name.select();
  }

  showDelete(w: WorldMeta): void {
    const error = h('p', { class: 'menu-error', role: 'alert' });
    const dialog = h(
      'div',
      { class: 'menu-panel menu-dialog', role: 'alertdialog', 'aria-labelledby': 'delete-title' },
      h('h2', { id: 'delete-title' }, 'Delete world?'),
      h('p', {}, `"${w.name}" and everything built in it will be gone for good.`),
      h(
        'div',
        { class: 'menu-buttons' },
        h('button', { class: 'btn', type: 'button', autofocus: true, onclick: () => void this.showTitle() }, 'Keep it'),
        h(
          'button',
          {
            class: 'btn danger',
            type: 'button',
            id: 'confirm-delete',
            onclick: () =>
              void this.run(error, async () => {
                await this.actions.remove(w.id);
                await this.showTitle();
              }),
          },
          'Delete forever',
        ),
      ),
      error,
    );
    this.show(dialog, true);
  }

  // --- Multiplayer (Milestone 10) ------------------------------------------------------------------

  /** Server address + player name form. */
  showMultiplayer(errorText = ''): void {
    const error = h('p', { class: 'menu-error', role: 'alert' }, errorText);
    const d = this.actions.multiplayerDefaults();
    const address = h('input', { type: 'text', id: 'mp-address', maxlength: '200', value: d.address, placeholder: 'localhost:25580', autofocus: true, autocomplete: 'off', spellcheck: 'false' });
    const name = h('input', { type: 'text', id: 'mp-name', maxlength: '16', value: d.name, placeholder: 'Your name', autocomplete: 'off', spellcheck: 'false', pattern: '[A-Za-z0-9_]{1,16}' });
    const join = (): void => {
      const n = name.value.trim();
      if (!/^[A-Za-z0-9_]{1,16}$/.test(n)) {
        error.textContent = 'Names are 1-16 letters, digits or _.';
        return;
      }
      void this.run(error, () => this.actions.joinServer({ address: address.value.trim(), name: n }));
    };
    const submit = (e: Event): void => {
      e.preventDefault();
      join();
    };
    const recent =
      d.recent.length > 0
        ? h(
            'div',
            { class: 'recent-servers' },
            h('span', { class: 'world-detail' }, 'Recent servers'),
            h(
              'ul',
              { class: 'recent-list' },
              ...d.recent.map((a) =>
                h(
                  'li',
                  {},
                  h('button', { class: 'btn recent-server', type: 'button', title: `Join ${a}`, 'data-address': a, onclick: () => {
                    address.value = a;
                    join();
                  } }, a),
                ),
              ),
            ),
          )
        : null;
    const form = h(
      'form',
      { class: 'menu-panel', onsubmit: submit },
      h('h2', {}, 'Multiplayer'),
      h('p', { class: 'world-detail' }, 'Join a Blockwright server (start one with "npm run server"). There is no login: play with people you trust.'),
      h('label', { for: 'mp-address' }, 'Server address'),
      address,
      h('label', { for: 'mp-name' }, 'Player name'),
      name,
      recent,
      h(
        'div',
        { class: 'menu-buttons' },
        h('button', { class: 'btn', type: 'button', onclick: () => void this.showTitle() }, 'Back'),
        h('button', { class: 'btn primary', type: 'submit', id: 'mp-join' }, 'Join server'),
      ),
      error,
    );
    this.show(form, true);
  }

  /**
   * Shown when a multiplayer connection ends (kicked, server stopped, connection lost). With
   * `last`, a Reconnect button joins the same address with the same name again.
   */
  showDisconnected(reason: string, last?: JoinServerInput): void {
    const error = h('p', { class: 'menu-error', role: 'alert' });
    const panel = h(
      'div',
      { class: 'menu-panel menu-dialog', role: 'alertdialog', 'aria-labelledby': 'disc-title' },
      h('h2', { id: 'disc-title' }, 'Disconnected'),
      h('p', { class: 'disconnect-reason' }, reason || 'Connection closed.'),
      h(
        'div',
        { class: 'menu-buttons' },
        h('button', { class: 'btn', type: 'button', id: 'disc-title-btn', onclick: () => void this.showTitle() }, 'Back to title'),
        h('button', { class: 'btn', type: 'button', id: 'disc-retry', onclick: () => this.showMultiplayer() }, 'Multiplayer...'),
        last
          ? h('button', { class: 'btn primary', type: 'button', id: 'disc-reconnect', autofocus: true, title: `Join ${last.address} as ${last.name}`, onclick: () => void this.run(error, () => this.actions.joinServer(last)) }, 'Reconnect')
          : null,
      ),
      error,
    );
    this.show(panel, true);
  }

  // --- Pause -------------------------------------------------------------------------------------

  /**
   * `multiplayer`: the world keeps running behind the menu and leaving disconnects; `ping` (if
   * given) is shown and refreshed every half second.
   */
  showPause(worldName: string, viewDistance: number, saveNote: string, multiplayer = false, ping?: () => string): void {
    const pingLine = ping ? h('p', { class: 'world-detail ping-line', id: 'pause-ping' }, ping()) : null;
    const error = h('p', { class: 'menu-error', role: 'alert' });
    const value = h('span', { class: 'range-value' }, String(viewDistance));
    const range = h('input', { type: 'range', id: 'view-distance', min: '2', max: '16', step: '1', value: String(viewDistance) });
    range.addEventListener('input', () => {
      value.textContent = range.value;
      this.actions.setViewDistance(Number(range.value));
    });
    const panel = h(
      'div',
      { class: 'menu-panel pause-menu' },
      h('h2', {}, multiplayer ? 'Game menu' : 'Paused'),
      h('p', { class: 'world-detail' }, worldName),
      pingLine,
      h('button', { class: 'btn primary wide', id: 'resume', autofocus: true, onclick: () => this.actions.resume() }, 'Resume'),
      h('label', { for: 'view-distance' }, 'View distance: ', value, ' chunks'),
      range,
      h(
        'button',
        { class: 'btn wide', id: 'pause-settings', onclick: () => this.showSettings(() => this.showPause(worldName, this.actions.getSettings().viewDistance, saveNote, multiplayer, ping), false) },
        'Settings',
      ),
      h(
        'button',
        { class: 'btn wide', id: 'save-quit', onclick: () => void this.run(error, () => this.actions.saveAndQuit()) },
        multiplayer ? 'Disconnect' : 'Save & quit to title',
      ),
      h('p', { class: 'world-detail' }, saveNote),
      error,
    );
    this.show(panel, false);
    if (ping && pingLine) this.ticker = window.setInterval(() => (pingLine.textContent = ping()), 500);
  }

  // --- Settings (Milestone 9) ---------------------------------------------------------------------

  /** Settings screen; `back` returns to the screen it was opened from (title or pause). */
  showSettings(back: () => void, title: boolean): void {
    const status = h('p', { class: 'world-detail settings-status', role: 'status' });
    const cur = this.actions.getSettings();
    const update = (patch: Partial<Settings>): void => {
      const ok = this.actions.updateSettings(patch);
      status.textContent = ok ? 'Saved.' : 'Applied, but not saved: storage is unavailable.';
    };
    const slider = (
      id: string,
      label: string,
      lim: { min: number; max: number; step: number },
      value: number,
      fmt: (v: number) => string,
      apply: (v: number) => void,
    ): HTMLElement[] => {
      const shown = h('span', { class: 'range-value' }, fmt(value));
      const input = h('input', { type: 'range', id, min: String(lim.min), max: String(lim.max), step: String(lim.step), value: String(value) });
      input.addEventListener('input', () => {
        shown.textContent = fmt(Number(input.value));
        apply(Number(input.value));
      });
      return [h('label', { for: id }, `${label}: `, shown), input];
    };
    const touchSel = h(
      'select',
      { id: 'set-touch' },
      h('option', { value: 'auto' }, 'Auto (touch screens)'),
      h('option', { value: 'on' }, 'Always show'),
      h('option', { value: 'off' }, 'Never show'),
    );
    touchSel.value = cur.touchControls;
    touchSel.addEventListener('change', () => update({ touchControls: touchSel.value as TouchMode }));
    const panel = h(
      'div',
      { class: 'menu-panel settings-menu' },
      h('h2', {}, 'Settings'),
      h('p', { class: 'world-detail' }, `Quality preset: ${this.actions.qualityName} (detected; sets the defaults, worker count and mob draw distance)`),
      ...slider('set-view', 'View distance', LIMITS.viewDistance, cur.viewDistance, (v) => `${v} chunks`, (v) => update({ viewDistance: v })),
      ...slider('set-dpr', 'Render scale (pixel ratio cap)', LIMITS.maxDpr, cur.maxDpr, (v) => `${v.toFixed(2)}x`, (v) => update({ maxDpr: v })),
      ...slider('set-fov', 'Field of view', LIMITS.fov, cur.fov, (v) => `${v}°`, (v) => update({ fov: v })),
      ...slider('set-sens', 'Look sensitivity', LIMITS.sensitivity, cur.sensitivity, (v) => `${v.toFixed(1)}x`, (v) => update({ sensitivity: Math.round(v * 10) / 10 })),
      ...slider('set-master', 'Master volume', LIMITS.volume, cur.masterVolume, pct, (v) => update({ masterVolume: v })),
      ...slider('set-effects', 'Effects volume', LIMITS.volume, cur.effectsVolume, pct, (v) => update({ effectsVolume: v })),
      ...slider('set-ambient', 'Ambient volume (wind, caves)', LIMITS.volume, cur.ambientVolume, pct, (v) => update({ ambientVolume: v })),
      h('label', { for: 'set-touch' }, 'Touch controls'),
      touchSel,
      status,
      h('div', { class: 'menu-buttons' }, h('button', { class: 'btn primary', type: 'button', id: 'settings-done', autofocus: true, onclick: () => back() }, 'Done')),
    );
    this.show(panel, title);
  }
}
