/**
 * Minimal entity storage (Milestone 7). Every entity is a plain object with a unique numeric `id`,
 * a `kind` tag and a physics body. Systems own an `EntityStore` of their kind and iterate it each
 * tick; renderers read the same objects. Milestone 8's ECS can grow out of this: the store keeps
 * ids stable and removal deferred-safe (removing while iterating is allowed).
 */
import type { BodyState } from '../physics/body';

export interface EntityBase extends BodyState {
  readonly id: number;
  readonly kind: string;
  /** Seconds since spawn. */
  age: number;
  /** Set when removed; systems skip removed entities. */
  removed: boolean;
}

let nextEntityId = 1;

/** Process-wide unique entity id (ids are never reused within a session). */
export function allocateEntityId(): number {
  return nextEntityId++;
}

/**
 * Iterator over a store's dense array, captured when the pass starts: entities added during the pass
 * are not visited (they were not there when it started) and entities removed during the pass are
 * skipped once removed. No array is copied per pass.
 */
class StoreIterator<T extends EntityBase> implements IterableIterator<T> {
  private i = 0;

  constructor(
    private readonly list: readonly T[],
    private readonly end: number,
  ) {}

  next(): IteratorResult<T> {
    const { list, end } = this;
    while (this.i < end) {
      const e = list[this.i++]!;
      if (!e.removed) return { value: e, done: false };
    }
    return { value: undefined, done: true };
  }

  [Symbol.iterator](): IterableIterator<T> {
    return this;
  }
}

/**
 * Entities of one kind: a Map by id plus a dense array for iteration (Milestone 9: no per-pass
 * array copy). Removal is deferred-safe: `remove` marks the entity `removed` and drops it from the
 * map; the dense array is compacted into a NEW array lazily (at the start of the next pass or
 * add), so any pass already running keeps walking its own array untouched. Adding during a pass
 * appends past the pass's captured end, so the new entity is first visited by the next pass.
 */
export class EntityStore<T extends EntityBase> implements Iterable<T> {
  private readonly byId = new Map<number, T>();
  private list: T[] = [];
  /** `list` holds removed entities waiting for compaction. */
  private dirty = false;

  get size(): number {
    return this.byId.size;
  }

  add(e: T): T {
    if (this.byId.has(e.id)) return e;
    this.compact();
    e.removed = false;
    this.byId.set(e.id, e);
    this.list.push(e);
    return e;
  }

  get(id: number): T | undefined {
    return this.byId.get(id);
  }

  remove(e: T): void {
    e.removed = true;
    if (this.byId.delete(e.id)) this.dirty = true;
  }

  clear(): void {
    for (const e of this.list) e.removed = true;
    this.byId.clear();
    // A new array, so a pass in progress still ends cleanly (everything in it is now removed).
    this.list = [];
    this.dirty = false;
  }

  /** Fills `out` with the live entities (reuse one scratch array per caller); returns `out`. */
  collect(out: T[]): T[] {
    this.compact();
    out.length = 0;
    for (const e of this.list) out.push(e);
    return out;
  }

  /** Calls `fn` for each live entity; same add/remove rules as `for...of`. */
  forEach(fn: (e: T) => void): void {
    this.compact();
    const list = this.list;
    const end = list.length;
    for (let i = 0; i < end; i++) {
      const e = list[i]!;
      if (!e.removed) fn(e);
    }
  }

  [Symbol.iterator](): IterableIterator<T> {
    this.compact();
    return new StoreIterator(this.list, this.list.length);
  }

  private compact(): void {
    if (!this.dirty) return;
    this.dirty = false;
    // Always into a new array: a pass may still hold the old one.
    this.list = this.list.filter((e) => !e.removed);
  }
}
