import {
  PlayerSim,
  WorldSim,
  type BlockChangeListener,
  type GameMode,
  type InventoryOp,
  type InventoryOpResult,
  type ItemEntitySystem,
  type LightEngine,
  type MobSystem,
  type PickupEvent,
  type World,
} from '@voxel/shared';

export { VOID_Y, type BlockPos, type DamageListener, type DeathListener } from '@voxel/shared';
export type { BlockChangeListener } from '@voxel/shared';

/** World conditions the per-tick simulation needs from the game. */
export interface TickEnv {
  /** Daylight factor 0.16..1 (see shared `daylightFactor`). */
  daylight: number;
  /** Horizontal look direction (mobs never spawn in view). */
  lookX: number;
  lookZ: number;
  /** Natural mob spawning (default on). */
  spawning?: boolean;
}

/** Id of the local player in a single-player world. */
export const LOCAL_PLAYER_ID = 1;

/**
 * The client's view of the game: the local player (a shared `PlayerSim`) plus the world
 * simulation it lives in (a shared `WorldSim`).
 *
 * Single-player (Milestone 10): the whole authoritative simulation runs in-process, exactly the
 * code the Node server runs; this class only adds the world-level accessors the client uses.
 * Every edit is a *request*, validated with the shared rules and applied through the WorldSim
 * (`applyBlockChange` marks sections dirty so the mesh pool re-meshes them).
 *
 * Multiplayer uses `RemoteGameSession` (net/remoteSession.ts), which overrides the request
 * methods to go to the server instead.
 */
export class GameSession extends PlayerSim {
  constructor(
    world: World,
    spawnX = 0,
    spawnZ = 0,
    /** Relights the world after each applied edit, before listeners run. */
    light?: LightEngine,
    gameMode: GameMode = 'survival',
    rand: () => number = Math.random,
    id = LOCAL_PLAYER_ID,
    name = 'player',
  ) {
    super(new WorldSim(world, light, rand, () => performance.now()), id, name, gameMode, spawnX, spawnZ);
    this.sim.addPlayer(this);
    this.sim.onBlockChange(() => this.stats.edits++);
  }

  get world(): World {
    return this.sim.world;
  }

  get light(): LightEngine | undefined {
    return this.sim.light;
  }

  /** Dropped items in the world. */
  get items(): ItemEntitySystem {
    return this.sim.items;
  }

  /** Mobs and their projectiles. */
  get mobs(): MobSystem {
    return this.sim.mobs;
  }

  /** Whether the chunk holding (x, z) is loaded. */
  readonly isLoadedAt = (x: number, z: number): boolean => this.sim.isLoadedAt(x, z);

  onBlockChange(listener: BlockChangeListener): void {
    this.sim.onBlockChange(listener);
  }

  /** Whether the chunk containing (x, z) and its 8 neighbours are loaded. */
  isAreaLoaded(x: number, z: number): boolean {
    return this.sim.isAreaLoaded(x, z);
  }

  /** Per-tick world simulation: vitals, mobs and item entities. Returns this tick's pickups. */
  tick(dt: number, env: TickEnv = { daylight: 1, lookX: 0, lookZ: -1 }): PickupEvent[] {
    if (!this.spawned) return [];
    this.yaw = Math.atan2(env.lookX, -env.lookZ);
    return this.sim.tick(dt, { daylight: env.daylight, spawning: env.spawning });
  }

  /** Applies an already-validated change (locally; multiplayer: what the server sent). */
  applyBlockChange(x: number, y: number, z: number, id: number): void {
    this.sim.applyBlockChange(x, y, z, id);
  }

  /** Opens the crafting grid of the inventory (2) or workbench (3) screen. */
  openScreen(size: 2 | 3, _workbench?: { x: number; y: number; z: number }): void {
    this.openCraft(size);
  }

  /** Closes the inventory screen (grid and cursor go back; leftovers are thrown). */
  closeScreen(): void {
    this.closeCraft();
  }

  override inventoryOp(op: InventoryOp): InventoryOpResult {
    return super.inventoryOp(op);
  }
}
