import type { Vec3 } from './vec3';

/**
 * 4x4 matrix, column-major (OpenGL convention): element (row r, col c) is at index c*4 + r.
 * All ops write into `out` and return it; `out` may alias inputs unless noted.
 */
export type Mat4 = Float32Array;

export function create(): Mat4 {
  return identity(new Float32Array(16));
}

export function identity(out: Mat4): Mat4 {
  out.fill(0);
  out[0] = 1;
  out[5] = 1;
  out[10] = 1;
  out[15] = 1;
  return out;
}

/** out = a * b (applies b first, then a). Safe when out aliases a or b. */
export function multiply(out: Mat4, a: Mat4, b: Mat4): Mat4 {
  const r = new Float32Array(16);
  for (let c = 0; c < 4; c++) {
    for (let row = 0; row < 4; row++) {
      let s = 0;
      for (let k = 0; k < 4; k++) s += a[k * 4 + row]! * b[c * 4 + k]!;
      r[c * 4 + row] = s;
    }
  }
  out.set(r);
  return out;
}

export function fromTranslation(out: Mat4, v: Vec3): Mat4 {
  identity(out);
  out[12] = v[0]!;
  out[13] = v[1]!;
  out[14] = v[2]!;
  return out;
}

/** Right-handed perspective projection mapping view-space -z to clip depth [-1, 1]. */
export function perspective(out: Mat4, fovY: number, aspect: number, near: number, far: number): Mat4 {
  const f = 1 / Math.tan(fovY / 2);
  const nf = 1 / (near - far);
  out.fill(0);
  out[0] = f / aspect;
  out[5] = f;
  out[10] = (far + near) * nf;
  out[11] = -1;
  out[14] = 2 * far * near * nf;
  return out;
}

/** Right-handed view matrix looking from `eye` toward `target`. */
export function lookAt(out: Mat4, eye: Vec3, target: Vec3, up: Vec3): Mat4 {
  const ex = eye[0]!, ey = eye[1]!, ez = eye[2]!;
  // z axis = normalize(eye - target)
  let zx = ex - target[0]!, zy = ey - target[1]!, zz = ez - target[2]!;
  let len = Math.hypot(zx, zy, zz);
  if (len === 0) return identity(out);
  zx /= len; zy /= len; zz /= len;
  // x axis = normalize(up x z)
  let xx = up[1]! * zz - up[2]! * zy;
  let xy = up[2]! * zx - up[0]! * zz;
  let xz = up[0]! * zy - up[1]! * zx;
  len = Math.hypot(xx, xy, xz);
  if (len > 0) { xx /= len; xy /= len; xz /= len; }
  // y axis = z x x
  const yx = zy * xz - zz * xy;
  const yy = zz * xx - zx * xz;
  const yz = zx * xy - zy * xx;

  out[0] = xx; out[1] = yx; out[2] = zx; out[3] = 0;
  out[4] = xy; out[5] = yy; out[6] = zy; out[7] = 0;
  out[8] = xz; out[9] = yz; out[10] = zz; out[11] = 0;
  out[12] = -(xx * ex + xy * ey + xz * ez);
  out[13] = -(yx * ex + yy * ey + yz * ez);
  out[14] = -(zx * ex + zy * ey + zz * ez);
  out[15] = 1;
  return out;
}

/** Transforms point (x, y, z, 1) by m, returning the homogeneous result [x, y, z, w]. */
export function transformPoint(m: Mat4, p: Vec3): [number, number, number, number] {
  const x = p[0]!, y = p[1]!, z = p[2]!;
  return [
    m[0]! * x + m[4]! * y + m[8]! * z + m[12]!,
    m[1]! * x + m[5]! * y + m[9]! * z + m[13]!,
    m[2]! * x + m[6]! * y + m[10]! * z + m[14]!,
    m[3]! * x + m[7]! * y + m[11]! * z + m[15]!,
  ];
}
