import type { TouchMode } from '../settings/settings';
import type { Input } from './input';
import { KeyboardMouseSource, clampMove, createIntent, resetIntent, type PlayerIntent } from './intent';
import type { TouchControls } from './touchControls';

/**
 * Decides whether touch controls are on: the settings override ('on' / 'off'), or in 'auto' a
 * coarse primary pointer (`pointer: coarse`) or the first touch event seen on the page. Sets
 * `body.touch`, which shows the touch overlay and the touch-friendly menu sizes.
 */
export class TouchModeDetector {
  private sawTouch = false;
  private readonly coarse: boolean;
  private readonly listeners = new Set<(active: boolean) => void>();
  private lastActive: boolean | undefined;

  constructor(private mode: TouchMode) {
    let coarse = false;
    try {
      coarse = typeof matchMedia === 'function' && matchMedia('(pointer: coarse)').matches;
    } catch {
      coarse = false;
    }
    this.coarse = coarse;
    if (typeof window !== 'undefined') {
      const onTouch = (): void => {
        if (this.sawTouch) return;
        this.sawTouch = true;
        this.apply();
      };
      window.addEventListener('touchstart', onTouch, { passive: true, capture: true });
      window.addEventListener('pointerdown', (e) => {
        if (e.pointerType === 'touch') onTouch();
      }, { passive: true, capture: true });
    }
    this.apply();
  }

  /** True when touch controls should be shown. */
  get active(): boolean {
    return this.mode === 'on' || (this.mode === 'auto' && (this.coarse || this.sawTouch));
  }

  /** The device reports a coarse primary pointer (for the quality preset). */
  get coarsePointer(): boolean {
    return this.coarse;
  }

  setMode(mode: TouchMode): void {
    this.mode = mode;
    this.apply();
  }

  onChange(fn: (active: boolean) => void): () => void {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  private apply(): void {
    const active = this.active;
    if (typeof document !== 'undefined') document.body.classList.toggle('touch', active);
    if (active === this.lastActive) return;
    this.lastActive = active;
    for (const fn of this.listeners) fn(active);
  }
}

/**
 * Samples every input source into one `PlayerIntent` per animation frame (before that frame's
 * ticks): keyboard + mouse always, touch while touch mode is active. Moves and looks add up
 * (clamped), held buttons OR together, one-shot actions from either source fire.
 */
export class Controls {
  readonly intent: PlayerIntent = createIntent();
  readonly keyboard = new KeyboardMouseSource();
  /** Look sensitivity multiplier for both sources (settings). */
  sensitivity = 1;

  constructor(
    private readonly input: Input,
    private readonly touch: TouchControls | undefined,
    private readonly touchActive: () => boolean,
  ) {}

  /** Refills `intent`; `nowMs` is performance.now(). */
  sample(nowMs: number): PlayerIntent {
    const i = resetIntent(this.intent);
    this.keyboard.fill(i, this.input, nowMs / 1000, this.sensitivity);
    if (this.touch && this.touchActive()) {
      this.touch.sensitivity = this.sensitivity;
      this.touch.fill(i, nowMs);
    }
    clampMove(i);
    return i;
  }
}
