import { chunkKey } from '../world/world';

/** A snapshot of one chunk's blocks waiting to reach storage. */
export interface PendingChunkSave {
  readonly cx: number;
  readonly cz: number;
  readonly key: number;
  /** Owned by the tracker (a copy, or an unloaded chunk's array that nothing edits any more). */
  readonly blocks: Uint16Array;
  /** Increments per snapshot of the same chunk; a newer snapshot supersedes older ones. */
  readonly seq: number;
}

/**
 * Pure bookkeeping for which chunks need saving (no storage, no timers).
 *
 * - `dirty`: loaded chunks edited since their last snapshot.
 * - `pending`: snapshots taken (on unload or at flush time) that are not yet confirmed on disk.
 *   Loads of a chunk with a pending snapshot must use it instead of reading storage, which may
 *   still hold an older version.
 * - `saved`: chunks confirmed present in storage (seeded from storage when a world opens).
 *
 * Flushing: `beginFlush` snapshots dirty loaded chunks and returns every pending snapshot;
 * write the ones `isCurrent` still accepts right before opening the transaction, then call
 * `endFlush`. A snapshot is removed from `pending` only once it is written and still current, so
 * an edit made during a flush is never lost and a stale write can't land after a newer one.
 */
export class ChunkSaveTracker {
  private readonly dirty = new Map<number, { cx: number; cz: number }>();
  private readonly pending = new Map<number, PendingChunkSave>();
  private readonly saved = new Set<number>();
  private seq = 0;

  constructor(savedKeys: Iterable<readonly [number, number]> = []) {
    for (const [cx, cz] of savedKeys) this.saved.add(chunkKey(cx, cz));
  }

  /** Records that a loaded chunk was edited. */
  markDirty(cx: number, cz: number): void {
    this.dirty.set(chunkKey(cx, cz), { cx, cz });
  }

  isDirty(cx: number, cz: number): boolean {
    return this.dirty.has(chunkKey(cx, cz));
  }

  /**
   * Call when a chunk is unloaded, with its (no longer edited) block array. If it had unsaved
   * edits it becomes a pending snapshot. Returns true when something now needs flushing.
   */
  onUnload(cx: number, cz: number, blocks: Uint16Array): boolean {
    const key = chunkKey(cx, cz);
    if (!this.dirty.delete(key)) return false;
    this.pending.set(key, { cx, cz, key, blocks, seq: ++this.seq });
    return true;
  }

  /** Whether chunk (cx, cz) must come from the save (stored or pending) instead of the generator. */
  hasSaved(cx: number, cz: number): boolean {
    const key = chunkKey(cx, cz);
    return this.pending.has(key) || this.saved.has(key);
  }

  /** The newest not-yet-written snapshot for a chunk, if any. Copy before handing it to a Chunk. */
  pendingBlocks(cx: number, cz: number): Uint16Array | undefined {
    return this.pending.get(chunkKey(cx, cz))?.blocks;
  }

  /**
   * Snapshots dirty chunks (via `getLoadedBlocks`, copied) into `pending` and returns all pending
   * snapshots to write.
   */
  beginFlush(getLoadedBlocks: (cx: number, cz: number) => Uint16Array | undefined): PendingChunkSave[] {
    for (const [key, { cx, cz }] of this.dirty) {
      const blocks = getLoadedBlocks(cx, cz);
      this.dirty.delete(key);
      if (blocks) this.pending.set(key, { cx, cz, key, blocks: blocks.slice(), seq: ++this.seq });
    }
    return [...this.pending.values()];
  }

  /** True if `entry` is still the newest snapshot for its chunk (worth writing). */
  isCurrent(entry: PendingChunkSave): boolean {
    return this.pending.get(entry.key) === entry;
  }

  /**
   * Marks `written` as stored. Entries still current leave `pending`; superseded ones stay
   * superseded (their newer snapshot is written by a later flush).
   */
  endFlush(written: readonly PendingChunkSave[]): void {
    for (const e of written) {
      this.saved.add(e.key);
      if (this.pending.get(e.key) === e) this.pending.delete(e.key);
    }
  }

  /** Forgets a chunk everywhere (e.g. after it is deleted from storage). */
  forget(cx: number, cz: number): void {
    const key = chunkKey(cx, cz);
    this.dirty.delete(key);
    this.pending.delete(key);
    this.saved.delete(key);
  }

  /** Chunks that differ from what the generator would make: saved, pending or dirty. */
  get modifiedCount(): number {
    let n = this.saved.size;
    for (const k of this.pending.keys()) if (!this.saved.has(k)) n++;
    for (const k of this.dirty.keys()) if (!this.saved.has(k) && !this.pending.has(k)) n++;
    return n;
  }

  /** Chunks with edits not yet confirmed on disk. */
  get unsavedCount(): number {
    let n = this.pending.size;
    for (const k of this.dirty.keys()) if (!this.pending.has(k)) n++;
    return n;
  }

  get hasUnsaved(): boolean {
    return this.dirty.size > 0 || this.pending.size > 0;
  }
}
