import { daylightFactor, sunHeight, type Vec3 } from '@voxel/shared';
import { createProgram, type ShaderProgram } from './shader';

type RGB = [number, number, number];

/** Everything that depends on the time of day, for one frame. */
export interface SkyState {
  /** Colour straight up. */
  zenith: RGB;
  /** Colour at the horizon; also the fog colour, so distant terrain melts into the sky. */
  horizon: RGB;
  /** Sky light multiplier 0..1 for the chunk shader. */
  daylight: number;
  /** Colour of sky light on terrain. */
  skyTint: RGB;
  /** Unit vector toward the sun (the moon is opposite). */
  sunDir: RGB;
  /** 0 by day, 1 in full night (stars). */
  night: number;
}

const DAY_ZENITH: RGB = [0.3, 0.55, 0.92];
const DAY_HORIZON: RGB = [0.66, 0.81, 0.96];
const NIGHT_ZENITH: RGB = [0.008, 0.012, 0.04];
const NIGHT_HORIZON: RGB = [0.035, 0.05, 0.11];
const DUSK_ZENITH: RGB = [0.24, 0.28, 0.52];
const DUSK_HORIZON: RGB = [0.96, 0.54, 0.3];
const DAY_TINT: RGB = [1, 1, 1];
const DUSK_TINT: RGB = [1, 0.82, 0.66];
const NIGHT_TINT: RGB = [0.62, 0.72, 1];

function mix(a: RGB, b: RGB, t: number): RGB {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function smoothstep(e0: number, e1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
}

/** Sky colours and lighting for a time of day (0 sunrise, 0.25 noon, 0.5 sunset, 0.75 midnight). */
export function computeSky(dayFraction: number): SkyState {
  const s = sunHeight(dayFraction);
  const day = smoothstep(-0.22, 0.22, s);
  // Peaks when the sun is at the horizon.
  const twilight = Math.exp(-((s / 0.17) ** 2));
  const zenith = mix(mix(NIGHT_ZENITH, DAY_ZENITH, day), DUSK_ZENITH, twilight * 0.45);
  const horizon = mix(mix(NIGHT_HORIZON, DAY_HORIZON, day), DUSK_HORIZON, twilight * 0.7);
  const skyTint = mix(mix(NIGHT_TINT, DAY_TINT, day), DUSK_TINT, twilight * 0.8);
  const a = dayFraction * Math.PI * 2;
  // The sun rises in the east (+X), sets in the west, tilted a little toward -Z.
  const sx = Math.cos(a);
  const sy = Math.sin(a);
  const sz = -0.25;
  const len = Math.hypot(sx, sy, sz);
  return {
    zenith,
    horizon,
    daylight: daylightFactor(dayFraction),
    skyTint,
    sunDir: [sx / len, sy / len, sz / len],
    night: 1 - smoothstep(-0.3, 0.0, s),
  };
}

const VS = `#version 300 es
uniform vec3 u_forward;
/** Camera right and up, pre-scaled by the half-extent of the view at distance 1. */
uniform vec3 u_right;
uniform vec3 u_up;
out vec3 v_dir;
void main() {
  // Fullscreen triangle.
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2)) * 2.0 - 1.0;
  v_dir = u_forward + p.x * u_right + p.y * u_up;
  gl_Position = vec4(p, 1.0, 1.0);
}
`;

const FS = `#version 300 es
precision highp float;
uniform vec3 u_zenith;
uniform vec3 u_horizon;
uniform vec3 u_sunDir;
uniform float u_night;
in vec3 v_dir;
out vec4 outColor;

/** Square disc of half-size \`size\` (in tangent units) around direction \`c\`; 0..1 coverage. */
float squareDisc(vec3 dir, vec3 c, float size) {
  float d = dot(dir, c);
  if (d <= 0.0) return 0.0;
  vec3 t1 = normalize(cross(c, vec3(0.0, 0.0, 1.0)));
  vec3 t2 = cross(t1, c);
  vec2 uv = vec2(dot(dir, t1), dot(dir, t2)) / d;
  float m = max(abs(uv.x), abs(uv.y));
  return 1.0 - smoothstep(size * 0.94, size, m);
}

float hash(vec3 p) {
  p = fract(p * 0.3183099 + 0.1);
  p *= 17.0;
  return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

void main() {
  vec3 dir = normalize(v_dir);
  float h = clamp(dir.y, 0.0, 1.0);
  vec3 col = mix(u_horizon, u_zenith, sqrt(h));
  float above = smoothstep(-0.02, 0.03, dir.y);

  // Stars.
  vec3 cell = floor(dir * 220.0);
  float star = step(0.9975, hash(cell)) * u_night * above;
  col += vec3(star * 0.85);

  // Sun: square disc plus a soft halo.
  float sd = max(dot(dir, u_sunDir), 0.0);
  col += vec3(1.0, 0.8, 0.5) * pow(sd, 48.0) * 0.35 * above;
  col = mix(col, vec3(1.0, 0.96, 0.82), squareDisc(dir, u_sunDir, 0.075) * above);
  // Moon, opposite the sun.
  vec3 moonDir = -u_sunDir;
  float moon = squareDisc(dir, moonDir, 0.05) * above;
  col = mix(col, vec3(0.86, 0.88, 0.95), moon);

  outColor = vec4(col, 1.0);
}
`;

/** Draws the sky gradient, sun, moon and stars as a fullscreen pass behind the world. */
export class SkyRenderer {
  private readonly shader: ShaderProgram;
  private readonly vao: WebGLVertexArrayObject;

  constructor(private readonly gl: WebGL2RenderingContext) {
    this.shader = createProgram(gl, VS, FS);
    const vao = gl.createVertexArray();
    if (!vao) throw new Error('Failed to create sky VAO');
    this.vao = vao;
  }

  /**
   * @param forward Camera look direction (unit).
   * @param right Horizontal camera right (unit).
   */
  draw(sky: SkyState, forward: Vec3, right: Vec3, fovY: number, aspect: number): void {
    const { gl, shader } = this;
    const ty = Math.tan(fovY / 2);
    const tx = ty * aspect;
    const fx = forward[0]!, fy = forward[1]!, fz = forward[2]!;
    const rx = right[0]!, ry = right[1]!, rz = right[2]!;
    // up = right x forward
    const ux = ry * fz - rz * fy;
    const uy = rz * fx - rx * fz;
    const uz = rx * fy - ry * fx;
    gl.useProgram(shader.program);
    const u = shader.uniforms;
    const set3 = (name: string, x: number, y: number, z: number): void => {
      const loc = u[name];
      if (loc) gl.uniform3f(loc, x, y, z);
    };
    set3('u_forward', fx, fy, fz);
    set3('u_right', rx * tx, ry * tx, rz * tx);
    set3('u_up', ux * ty, uy * ty, uz * ty);
    set3('u_zenith', ...sky.zenith);
    set3('u_horizon', ...sky.horizon);
    set3('u_sunDir', ...sky.sunDir);
    const night = u['u_night'];
    if (night) gl.uniform1f(night, sky.night);
    gl.disable(gl.DEPTH_TEST);
    gl.depthMask(false);
    gl.bindVertexArray(this.vao);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    gl.bindVertexArray(null);
    gl.depthMask(true);
    gl.enable(gl.DEPTH_TEST);
  }
}
