/**
 * The authoritative world simulation (Milestone 10, extracted from the client's GameSession):
 * the World and its lighting, item entities, mobs, the simulation clock, block edits and every
 * player in the world. Pure TS and DOM-free, so the same code runs single-player in the browser
 * and on the Node multiplayer server.
 *
 * - Block edits go through `applyBlockChange` (relight, then listeners).
 * - `tick(dt, env)` advances every spawned player's vitals, the mobs (targeting the nearest
 *   player) and the dropped items (picked up by the nearest player).
 * - Players are `PlayerSim`s; movement is stepped per player by whoever owns the input (the
 *   client controller in single-player, the server's input queue in multiplayer).
 */
import { CHUNK_SIZE } from '../world/chunk';
import type { World } from '../world/world';
import type { LightEngine } from '../world/lighting';
import { checkPlace, type EditCheck } from '../world/editRules';
import { isSolidBlock, PLAYER_EYE_HEIGHT, PLAYER_HALF_WIDTH, PLAYER_HEIGHT } from '../physics/player';
import { ItemEntitySystem, type ItemCollector, type PickupEvent } from '../entity/itemEntity';
import { MobSystem, type MobTarget } from '../mob/mobSystem';
import { isAlive, mobAabb } from '../mob/mob';
import { mulberry32 } from '../math/random';
import type { ItemStack } from '../items/items';
import { PlayerSim } from './playerSim';

/** Fired after a block edit has been applied to the World. */
export type BlockChangeListener = (x: number, y: number, z: number, oldId: number, newId: number) => void;

export interface WorldTickEnv {
  /** Daylight factor 0.16..1 (see shared `daylightFactor`). */
  daylight: number;
  /** Natural mob spawning (default on). */
  spawning?: boolean;
}

export interface PlayerPickup extends PickupEvent {
  player: PlayerSim;
}

export class WorldSim {
  /** Dropped items in the world. */
  readonly items: ItemEntitySystem;
  /** Mobs and their projectiles. */
  readonly mobs: MobSystem;
  /** Every player, by id (single-player has exactly one). */
  readonly players = new Map<number, PlayerSim>();
  /** Seconds of simulation since the sim started (attack cooldown clock). */
  simTime = 0;
  /** World-wide accepted edit counter. */
  edits = 0;
  private readonly listeners: BlockChangeListener[] = [];
  private readonly targets: MobTarget[] = [];
  private readonly collectors: (ItemCollector | undefined)[] = [];
  private readonly collectorPlayers: PlayerSim[] = [];

  constructor(
    readonly world: World,
    /** Relights the world after each applied edit, before listeners run. */
    readonly light?: LightEngine,
    readonly rand: () => number = Math.random,
    /** Clock in ms for stats only (performance.now in the browser); never affects the simulation. */
    now: () => number = () => 0,
  ) {
    this.items = new ItemEntitySystem(rand);
    this.mobs = new MobSystem(
      {
        getBlock: this.getBlock,
        isLoaded: this.isLoadedAt,
        getSkyLight: (x, y, z) => world.getSkyLight(x, y, z),
        getBlockLight: (x, y, z) => world.getBlockLight(x, y, z),
      },
      mulberry32(Math.floor(rand() * 0x100000000)),
      now,
    );
    this.mobs.hooks = {
      hurtPlayer: (amount, attacker, kx, kz, target) => {
        const p = this.playerFor(target);
        if (p && p.damage(amount, 'mob', attacker) > 0) p.knockback(kx, kz);
      },
      dropItem: (stack: ItemStack, x, y, z) => {
        this.items.spawn(stack, x, y, z);
      },
    };
  }

  readonly getBlock = (x: number, y: number, z: number): number => this.world.getBlock(x, y, z);

  /** Whether the chunk holding (x, z) is loaded. */
  readonly isLoadedAt = (x: number, z: number): boolean => !!this.world.getChunk(Math.floor(x / CHUNK_SIZE), Math.floor(z / CHUNK_SIZE));

  /** Whether the chunk containing (x, z) and its 8 neighbours are loaded. */
  isAreaLoaded(x: number, z: number): boolean {
    const cx = Math.floor(x / CHUNK_SIZE);
    const cz = Math.floor(z / CHUNK_SIZE);
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (!this.world.getChunk(cx + dx, cz + dz)) return false;
    return true;
  }

  onBlockChange(listener: BlockChangeListener): void {
    this.listeners.push(listener);
  }

  addPlayer(p: PlayerSim): PlayerSim {
    this.players.set(p.id, p);
    return p;
  }

  removePlayer(id: number): void {
    this.players.delete(id);
  }

  private playerFor(target: MobTarget | undefined): PlayerSim | undefined {
    if (target?.id !== undefined) return this.players.get(target.id);
    for (const p of this.players.values()) return p;
    return undefined;
  }

  /** Per-tick world simulation: every player's vitals, mobs and item entities. Returns pickups. */
  tick(dt: number, env: WorldTickEnv = { daylight: 1 }): PlayerPickup[] {
    const targets = this.targets;
    const collectors = this.collectors;
    const owners = this.collectorPlayers;
    targets.length = collectors.length = owners.length = 0;
    for (const p of this.players.values()) {
      if (!p.spawned) continue;
      p.tickVitals(dt);
      const b = p.player;
      targets.push({
        id: p.id,
        x: b.x,
        y: b.y,
        z: b.z,
        halfWidth: PLAYER_HALF_WIDTH,
        height: PLAYER_HEIGHT,
        eyeHeight: PLAYER_EYE_HEIGHT,
        targetable: !p.dead && !p.creative,
        lookX: Math.sin(p.yaw),
        lookZ: -Math.cos(p.yaw),
      });
      owners.push(p);
      collectors.push(
        p.dead
          ? undefined
          : { x: b.x, y: b.y, z: b.z, height: PLAYER_HEIGHT, collect: (s: ItemStack): number => s.count - (p.inventory.add(s)?.count ?? 0) },
      );
    }
    if (targets.length === 0) return [];
    this.simTime += dt;
    this.mobs.tick(dt, { daylight: env.daylight, spawning: env.spawning, players: targets });
    const picked = this.items.tick(dt, this.getBlock, this.isLoadedAt, collectors);
    const out: PlayerPickup[] = [];
    for (const e of picked) {
      const p = owners[e.collector];
      if (!p) continue;
      p.stats.pickups++;
      out.push({ ...e, player: p });
    }
    return out;
  }

  /**
   * Placement check against blocks, every spawned living player and every living mob: a solid
   * block may not be placed where it would intersect any of them.
   */
  checkPlace(x: number, y: number, z: number, block: number): EditCheck {
    const feet: { x: number; y: number; z: number }[] = [];
    for (const p of this.players.values()) if (p.spawned && !p.dead) feet.push(p.player);
    const check = checkPlace(this.getBlock, x, y, z, block, feet);
    if (!check.ok || !isSolidBlock(block)) return check;
    for (const m of this.mobs.entities) {
      if (!isAlive(m)) continue;
      const b = mobAabb(m);
      const eps = 1e-6;
      if (b.minX < x + 1 - eps && b.maxX > x + eps && b.minY < y + 1 - eps && b.maxY > y + eps && b.minZ < z + 1 - eps && b.maxZ > z + eps) {
        return { ok: false, reason: 'intersects_player' };
      }
    }
    return check;
  }

  /** Applies an already-validated change: relights, then notifies listeners. */
  applyBlockChange(x: number, y: number, z: number, id: number): void {
    const old = this.world.getBlock(x, y, z);
    if (!this.world.setBlock(x, y, z, id)) return;
    // Sky/block light updates mark every section whose light changed dirty for re-meshing.
    this.light?.onBlockChanged(x, y, z, old, id);
    this.edits++;
    for (const l of this.listeners) l(x, y, z, old, id);
  }
}
