/**
 * Spawn rule predicates (Milestone 8). Pure functions of light, distance and view, so they are easy
 * to test and identical on the server.
 *
 * - Hostile: effective sky light (sky light x daylight factor) below HOSTILE_MAX_SKY and block
 *   light below HOSTILE_MAX_BLOCK_LIGHT, 24-64 blocks from the player and outside the player's view
 *   cone. In practice: on the surface at night, and in unlit caves at any time.
 * - Passive: on grass with open sky (sky light >= PASSIVE_MIN_SKY), 12-64 blocks from the player.
 */
import { BlockId } from '../world/blocks';

export const HOSTILE_MIN_DISTANCE = 24;
export const HOSTILE_MAX_DISTANCE = 64;
/** Effective sky light (0..15 scaled by daylight) must be below this. */
export const HOSTILE_MAX_SKY = 4;
export const HOSTILE_MAX_BLOCK_LIGHT = 7;
/** Hostiles are not spawned where the player is looking: within this angle of the view direction. */
export const VIEW_HALF_ANGLE = (55 * Math.PI) / 180;

export const PASSIVE_MIN_DISTANCE = 12;
export const PASSIVE_MAX_DISTANCE = 64;
export const PASSIVE_MIN_SKY = 10;

export interface SpawnSite {
  skyLight: number;
  blockLight: number;
  /** World daylight factor, 0.16 (night) .. 1 (day); see `daylightFactor`. */
  daylight: number;
  /** Distance from the player, blocks. */
  distance: number;
  /** Whether the site is inside the player's view cone (see `inViewCone`). */
  inView?: boolean;
  /** Block the mob would stand on (passive rule). */
  ground?: number;
}

/** Whether the light level counts as dark enough for hostiles. */
export function isDarkForHostiles(skyLight: number, blockLight: number, daylight: number): boolean {
  return skyLight * daylight < HOSTILE_MAX_SKY && blockLight < HOSTILE_MAX_BLOCK_LIGHT;
}

export function hostileSpawnAllowed(s: SpawnSite): boolean {
  if (s.distance < HOSTILE_MIN_DISTANCE || s.distance > HOSTILE_MAX_DISTANCE) return false;
  if (s.inView) return false;
  return isDarkForHostiles(s.skyLight, s.blockLight, s.daylight);
}

export function passiveSpawnAllowed(s: SpawnSite): boolean {
  if (s.distance < PASSIVE_MIN_DISTANCE || s.distance > PASSIVE_MAX_DISTANCE) return false;
  if (s.ground !== undefined && s.ground !== BlockId.Grass) return false;
  return s.skyLight >= PASSIVE_MIN_SKY;
}

/** Whether direction (dx, dz) from the player lies within VIEW_HALF_ANGLE of the look (lx, lz). */
export function inViewCone(dx: number, dz: number, lx: number, lz: number): boolean {
  const a = Math.hypot(dx, dz);
  const b = Math.hypot(lx, lz);
  if (a === 0 || b === 0) return false;
  return (dx * lx + dz * lz) / (a * b) > Math.cos(VIEW_HALF_ANGLE);
}
