const HANDLE: Palette = { h: [140, 100, 56], k: [96, 66, 36] };

const MATERIALS: Record<string, Palette> = {
  wooden: { m: [176, 134, 80], d: [120, 86, 48], l: [206, 166, 108] },
  stone: { m: [128, 128, 134], d: [84, 84, 90], l: [170, 170, 176] },
  iron: { m: [212, 212, 218], d: [146, 146, 156], l: [246, 246, 250] },
};

const TEMPLATES: Record<string, string[]> = { pickaxe: PICKAXE, axe: AXE, shovel: SHOVEL, sword: SWORD };

/** Rasterises a string art into RGBA. Short rows/columns are padded with transparency. */
function paint(rows: readonly string[], palette: Palette): Uint8Array {
  const S = ITEM_ICON_SIZE;
  const data = new Uint8Array(S * S * 4);
  for (let y = 0; y < S; y++) {
    const row = rows[y] ?? '';
    for (let x = 0; x < S; x++) {
      const c = palette[row[x] ?? '.'];
      if (!c) continue;
      const i = (y * S + x) * 4;
      data[i] = c[0];
      data[i + 1] = c[1];
      data[i + 2] = c[2];
      data[i + 3] = 255;
    }
  }
  return data;
}

/** Icon pixels for a non-block item, or undefined for block items (drawn from block textures). */
export function itemIconPixels(def: ItemDef): Uint8Array | undefined {
  if (def.block !== undefined) return undefined;
  if (def.tool) {
    const mat = def.name.slice(0, def.name.indexOf('_'));
    return paint(TEMPLATES[def.tool.kind] ?? STICK, { ...HANDLE, ...(MATERIALS[mat] ?? MATERIALS['wooden']!) });
  }
  switch (def.name) {
    case 'stick':
      return paint(STICK, HANDLE);
    case 'coal':
      return paint(COAL, { a: [44, 44, 48], b: [24, 24, 26], c: [96, 96, 104] });
    case 'iron_ingot':
      return paint(INGOT, { l: [250, 250, 252], w: [226, 226, 232], m: [196, 196, 204], d: [130, 130, 140] });
    case 'apple':
      return paint(APPLE, { r: [206, 36, 40], d: [150, 22, 28], l: [240, 110, 100], w: [255, 220, 210], k: [92, 62, 30], g: [70, 150, 50] });
    case 'raw_meat':
      return paint(MEAT, { m: [214, 92, 96], l: [240, 150, 150], f: [246, 214, 206], d: [160, 58, 62], b: [236, 226, 214], w: [250, 246, 238] });
    case 'cooked_meat':
      return paint(MEAT, { m: [150, 88, 46], l: [196, 132, 76], f: [214, 170, 110], d: [100, 56, 28], b: [226, 214, 196], w: [244, 238, 226] });
    case 'feather':
      return paint(FEATHER, { w: [244, 244, 240], l: [196, 196, 192], k: [150, 140, 120] });
    default:
      // Unknown non-block item: a magenta/black checker so it is obvious in game.
      return paint(Array.from({ length: 16 }, (_, y) => Array.from({ length: 16 }, (_, x) => ((x >> 2) + (y >> 2)) % 2 ? 'a' : 'b').join('')), { a: [255, 0, 255], b: [0, 0, 0] });
  }
}

export interface ItemIconAtlas {
  /** One RGBA layer per non-block item. */
  layers: Uint8Array[];
  /** Layer per item ID, or -1 for block items. */
  layerOf: Int16Array;
}

let atlas: ItemIconAtlas | undefined;

/** All non-block item icons as texture-array layers (cached). */
export function itemIconAtlas(): ItemIconAtlas {
  if (atlas) return atlas;
  const layers: Uint8Array[] = [];
  const layerOf = new Int16Array(ITEMS.length).fill(-1);
  for (const def of ITEMS) {
    const px = itemIconPixels(def);
    if (!px) continue;
    layerOf[def.id] = layers.length;
    layers.push(px);
  }
  atlas = { layers, layerOf };
  return atlas;
}
