/**
 * Multiplayer wire protocol (Milestone 10). Every message is one binary frame:
 * `[type: u8][payload...]`, little-endian, decoded strictly (exact length, ranges, finite numbers;
 * see codec.ts). Client and server types use disjoint numbers so a frame sent the wrong way is
 * rejected too.
 *
 * Client -> server: hello (handshake: protocol version + name), input (one per client tick: move,
 * flags, absolute yaw/pitch and the predicted position for divergence checks), action (discrete
 * gameplay requests carrying the client-side target), invOp (inventory screen clicks), chat, ping.
 *
 * Server -> client: welcome, chunk (codec-compressed blocks; the client computes light),
 * unloadChunk, blockChanges, entities (snapshot of nearby players / mobs / items / projectiles
 * plus removals), playerState (authoritative body for reconciliation + vitals), inventory, chat,
 * time, playerList (join / leave), actionAck, pong and disconnect (reason).
 */
import { PROTOCOL_VERSION } from '../constants';
import type { GameMode } from '../survival/vitals';
import { GENERATOR_KINDS, type GeneratorKind } from '../worldgen/generator';
import type { Slot } from '../items/items';
import { ITEM_COUNT } from '../items/items';
import { INVENTORY_SIZE } from '../items/inventory';
import { INV_GROUPS, type InventoryOp } from '../sim/invOps';
import { ByteReader, ByteWriter, ProtocolError } from './codec';

export { PROTOCOL_VERSION };

/** Largest frame a client may send (inputs, actions and chat are tiny). */
export const MAX_CLIENT_MESSAGE_BYTES = 2048;
/** Largest frame the server sends (a chunk is usually 2-20 KB). */
export const MAX_SERVER_MESSAGE_BYTES = 1 << 20;
export const MAX_NAME_LENGTH = 16;
export const MAX_CHAT_LENGTH = 256;
/** Player names: 1-16 of A-Z a-z 0-9 _ (no spaces, nothing that needs escaping). */
export const NAME_PATTERN = /^[A-Za-z0-9_]{1,16}$/;
export const MAX_VIEW_DISTANCE = 16;
const MAX_REASON_BYTES = 512;
const MAX_PALETTE = 4096;
const MAX_BLOCK_CHANGES = 8192;
const MAX_ENTITIES = 4096;

export function isValidName(name: string): boolean {
  return NAME_PATTERN.test(name);
}

// --- Message type numbers -------------------------------------------------------------------------

export const C2S = { hello: 1, input: 2, action: 3, invOp: 4, chat: 5, ping: 6 } as const;
export const S2C = {
  welcome: 101,
  chunk: 102,
  unloadChunk: 103,
  blockChanges: 104,
  entities: 105,
  playerState: 106,
  inventory: 107,
  chat: 108,
  time: 109,
  playerList: 110,
  actionAck: 111,
  pong: 112,
  disconnect: 113,
} as const;

/** Discrete gameplay actions. Each carries the client-side target (block pos + face or entity id). */
export const ACTION = {
  breakStart: 1,
  breakCancel: 2,
  breakFinish: 3,
  place: 4,
  attack: 5,
  drop: 6,
  eatStart: 7,
  eatFinish: 8,
  selectSlot: 9,
  respawn: 10,
  openScreen: 11,
  closeScreen: 12,
} as const;
export type ActionKind = (typeof ACTION)[keyof typeof ACTION];
const ACTION_MAX = 12;

export const ENTITY_KIND = { player: 1, mob: 2, item: 3, projectile: 4 } as const;
export type EntityKind = (typeof ENTITY_KIND)[keyof typeof ENTITY_KIND];

export const ENTITY_FLAG = { hurt: 1, burning: 2, dying: 4, swinging: 8, sneaking: 16, onGround: 32, flying: 64 } as const;
export const STATE_FLAG = { onGround: 1, inWater: 2, flying: 4, dead: 8, correction: 16 } as const;

export const DAMAGE_CAUSES = ['fall', 'drown', 'starve', 'void', 'mob', 'other'] as const;
const GAME_MODES: readonly GameMode[] = ['survival', 'creative'];

// --- Client messages ------------------------------------------------------------------------------

export interface HelloMsg {
  type: 'hello';
  version: number;
  name: string;
  viewDistance: number;
}

export interface InputMsg {
  type: 'input';
  /** Client tick number (monotonic); the server acknowledges the last one it simulated. */
  tick: number;
  /** -1..1 (sent as i8 / 127). */
  moveX: number;
  moveZ: number;
  jump: boolean;
  sneak: boolean;
  sprint: boolean;
  /** Wants to fly (only honoured in creative). */
  flying: boolean;
  yaw: number;
  pitch: number;
  /** The client's predicted feet position after this input (divergence check only). */
  x: number;
  y: number;
  z: number;
}

export interface ActionMsg {
  type: 'action';
  seq: number;
  action: ActionKind;
  x: number;
  y: number;
  z: number;
  /** Block face 0..5 (+X -X +Y -Y +Z -Z) for place, else -1. */
  face: number;
  /**
   * Entity id (attack), slot (selectSlot), 1 = whole stack (drop), grid size (openScreen), block
   * variant to place (place; 0 = the held item's own block).
   */
  arg: number;
}

export interface InvOpMsg {
  type: 'invOp';
  seq: number;
  op: InventoryOp;
}

export interface ChatMsg {
  type: 'chat';
  text: string;
}

export interface PingMsg {
  type: 'ping';
  time: number;
}

export type ClientMessage = HelloMsg | InputMsg | ActionMsg | InvOpMsg | ChatMsg | PingMsg;

// --- Server messages ------------------------------------------------------------------------------

export interface WelcomeMsg {
  type: 'welcome';
  playerId: number;
  worldName: string;
  seed: number;
  /** How the server's world is generated (clients use it only for the F3 overlay). */
  generator: GeneratorKind;
  tickRate: number;
  serverTick: number;
  timeTicks: number;
  dayTicks: number;
  gameMode: GameMode;
  viewDistance: number;
  x: number;
  y: number;
  z: number;
  yaw: number;
  pitch: number;
  flying: boolean;
}

export interface ChunkMsg {
  type: 'chunk';
  cx: number;
  cz: number;
  palette: string[];
  rle: Uint8Array;
}

export interface UnloadChunkMsg {
  type: 'unloadChunk';
  cx: number;
  cz: number;
}

export interface BlockChange {
  x: number;
  y: number;
  z: number;
  id: number;
}

export interface BlockChangesMsg {
  type: 'blockChanges';
  changes: BlockChange[];
}

export interface EntitySnapshot {
  id: number;
  kind: EntityKind;
  /** Mob type index (MOB_TYPES), item id, or 0. */
  type: number;
  x: number;
  y: number;
  z: number;
  yaw: number;
  /** Head / look pitch. */
  pitch: number;
  /** Mobs: head yaw relative to the body. */
  headYaw: number;
  flags: number;
  /** Item stack count (capped at 255). */
  count: number;
}

export interface EntitiesMsg {
  type: 'entities';
  serverTick: number;
  entities: EntitySnapshot[];
  removed: number[];
}

export interface PlayerStateMsg {
  type: 'playerState';
  /** Last client input tick the server simulated (0 = none yet). */
  ackTick: number;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  flags: number;
  health: number;
  hunger: number;
  saturation: number;
  air: number;
  exhaustion: number;
  fallDistance: number;
  gameMode: GameMode;
  selectedSlot: number;
  /** Index into DAMAGE_CAUSES + 1, or 0. */
  deathCause: number;
  /** MOB_TYPES index + 1 of the killer, or 0. */
  deathAttacker: number;
}

export interface InventoryMsg {
  type: 'inventory';
  slots: Slot[];
  cursor: Slot;
  /** Crafting grid of the open screen: 0, 4 or 9 slots. */
  grid: Slot[];
}

export interface ServerChatMsg {
  type: 'chat';
  /** 0 = player message, 1 = system (join / leave / server). */
  kind: number;
  from: string;
  text: string;
}

export interface TimeMsg {
  type: 'time';
  timeTicks: number;
}

export interface PlayerListMsg {
  type: 'playerList';
  joined: boolean;
  id: number;
  name: string;
}

export interface ActionAckMsg {
  type: 'actionAck';
  seq: number;
  ok: boolean;
  reason: string;
}

export interface PongMsg {
  type: 'pong';
  time: number;
}

export interface DisconnectMsg {
  type: 'disconnect';
  reason: string;
}

export type ServerMessage =
  | WelcomeMsg
  | ChunkMsg
  | UnloadChunkMsg
  | BlockChangesMsg
  | EntitiesMsg
  | PlayerStateMsg
  | InventoryMsg
  | ServerChatMsg
  | TimeMsg
  | PlayerListMsg
  | ActionAckMsg
  | PongMsg
  | DisconnectMsg;

// --- Helpers --------------------------------------------------------------------------------------

function clampUnit(v: number): number {
  return Math.max(-1, Math.min(1, Number.isFinite(v) ? v : 0));
}

function writeSlot(w: ByteWriter, s: Slot): void {
  if (!s || s.count <= 0) {
    w.u16(0xffff);
    return;
  }
  w.u16(s.item).u8(Math.min(255, s.count)).u16(Math.max(0, Math.min(0xffff, s.damage)));
}

function readSlot(r: ByteReader): Slot {
  const item = r.u16();
  if (item === 0xffff) return null;
  if (item >= ITEM_COUNT) throw new ProtocolError('unknown item');
  const count = r.u8();
  const damage = r.u16();
  if (count === 0) throw new ProtocolError('empty stack');
  return { item, count, damage };
}

function gameModeIndex(m: GameMode): number {
  return m === 'creative' ? 1 : 0;
}

function readGameMode(r: ByteReader): GameMode {
  const v = r.u8();
  const m = GAME_MODES[v];
  if (!m) throw new ProtocolError('invalid game mode');
  return m;
}

function intIn(v: number, min: number, max: number, what: string): number {
  if (!Number.isInteger(v) || v < min || v > max) throw new ProtocolError(`invalid ${what}`);
  return v;
}

// --- Client encode / decode -----------------------------------------------------------------------

export function encodeClientMessage(m: ClientMessage): Uint8Array {
  const w = new ByteWriter(64);
  switch (m.type) {
    case 'hello':
      w.u8(C2S.hello).u16(m.version).string(m.name).u8(m.viewDistance);
      break;
    case 'input': {
      const flags = (m.jump ? 1 : 0) | (m.sneak ? 2 : 0) | (m.sprint ? 4 : 0) | (m.flying ? 8 : 0);
      w.u8(C2S.input).u32(m.tick).i8(Math.round(clampUnit(m.moveX) * 127)).i8(Math.round(clampUnit(m.moveZ) * 127)).u8(flags);
      w.f32(m.yaw).f32(m.pitch).f64(m.x).f64(m.y).f64(m.z);
      break;
    }
    case 'action':
      w.u8(C2S.action).u32(m.seq).u8(m.action).i32(m.x).i32(m.y).i32(m.z).i8(m.face).u32(m.arg);
      break;
    case 'invOp': {
      const op = m.op;
      w.u8(C2S.invOp).u32(m.seq);
      if (op.kind === 'throw') w.u8(3).u8(0).u16(0).u8(op.one ? 1 : 0);
      else w.u8(op.kind === 'click' ? 0 : op.kind === 'right' ? 1 : 2).u8(INV_GROUPS.indexOf(op.group)).u16(op.index).u8(op.ctrl ? 1 : 0);
      break;
    }
    case 'chat':
      w.u8(C2S.chat).string(m.text);
      break;
    case 'ping':
      w.u8(C2S.ping).f64(m.time);
      break;
  }
  return w.finish();
}

/** Decodes and validates a client frame. Throws `ProtocolError` on anything malformed. */
export function decodeClientMessage(data: Uint8Array): ClientMessage {
  if (data.length === 0) throw new ProtocolError('empty message');
  if (data.length > MAX_CLIENT_MESSAGE_BYTES) throw new ProtocolError('message too large');
  const r = new ByteReader(data);
  const type = r.u8();
  let m: ClientMessage;
  switch (type) {
    case C2S.hello: {
      const version = r.u16();
      const name = r.string(MAX_NAME_LENGTH * 4);
      const viewDistance = r.u8();
      m = { type: 'hello', version, name, viewDistance: Math.max(2, Math.min(MAX_VIEW_DISTANCE, viewDistance)) };
      break;
    }
    case C2S.input: {
      const tick = r.u32();
      const mx = r.i8();
      const mz = r.i8();
      const flags = r.u8();
      if (mx < -127 || mz < -127 || flags > 15) throw new ProtocolError('invalid input');
      const yaw = r.f32();
      const pitch = r.f32();
      const x = r.f64();
      const y = r.f64();
      const z = r.f64();
      if (Math.abs(yaw) > 1e4 || Math.abs(pitch) > Math.PI) throw new ProtocolError('invalid look');
      if (Math.abs(x) > 3e7 || Math.abs(z) > 3e7 || Math.abs(y) > 1e5) throw new ProtocolError('invalid position');
      m = {
        type: 'input',
        tick,
        moveX: mx / 127,
        moveZ: mz / 127,
        jump: (flags & 1) !== 0,
        sneak: (flags & 2) !== 0,
        sprint: (flags & 4) !== 0,
        flying: (flags & 8) !== 0,
        yaw,
        pitch: Math.max(-Math.PI / 2, Math.min(Math.PI / 2, pitch)),
        x,
        y,
        z,
      };
      break;
    }
    case C2S.action: {
      const seq = r.u32();
      const action = intIn(r.u8(), 1, ACTION_MAX, 'action') as ActionKind;
      const x = r.i32();
      const y = r.i32();
      const z = r.i32();
      const face = intIn(r.i8(), -1, 5, 'face');
      const arg = r.u32();
      m = { type: 'action', seq, action, x, y, z, face, arg };
      break;
    }
    case C2S.invOp: {
      const seq = r.u32();
      const kind = intIn(r.u8(), 0, 3, 'inventory op');
      const group = INV_GROUPS[r.u8()];
      const index = r.u16();
      const flag = r.u8();
      if (!group || flag > 1) throw new ProtocolError('invalid inventory op');
      const op: InventoryOp =
        kind === 3 ? { kind: 'throw', one: flag === 1 } : { kind: kind === 0 ? 'click' : kind === 1 ? 'right' : 'shift', group, index, ctrl: flag === 1 };
      m = { type: 'invOp', seq, op };
      break;
    }
    case C2S.chat: {
      const text = r.string(MAX_CHAT_LENGTH * 4);
      if (text.length > MAX_CHAT_LENGTH) throw new ProtocolError('chat too long');
      m = { type: 'chat', text };
      break;
    }
    case C2S.ping:
      m = { type: 'ping', time: r.f64() };
      break;
    default:
      throw new ProtocolError(`unknown client message type ${type}`);
  }
  r.end();
  return m;
}

// --- Server encode / decode -----------------------------------------------------------------------

export function encodeServerMessage(m: ServerMessage): Uint8Array {
  const w = new ByteWriter(m.type === 'chunk' ? 8192 : 128);
  switch (m.type) {
    case 'welcome':
      w.u8(S2C.welcome).u32(m.playerId).string(m.worldName).u32(m.seed).u8(GENERATOR_KINDS.indexOf(m.generator)).u8(m.tickRate).u32(m.serverTick).f64(m.timeTicks).u32(m.dayTicks);
      w.u8(gameModeIndex(m.gameMode)).u8(m.viewDistance).f64(m.x).f64(m.y).f64(m.z).f32(m.yaw).f32(m.pitch).bool(m.flying);
      break;
    case 'chunk':
      w.u8(S2C.chunk).i32(m.cx).i32(m.cz).u16(m.palette.length);
      for (const n of m.palette) w.string(n);
      w.u32(m.rle.length).bytes(m.rle);
      break;
    case 'unloadChunk':
      w.u8(S2C.unloadChunk).i32(m.cx).i32(m.cz);
      break;
    case 'blockChanges':
      w.u8(S2C.blockChanges).u16(m.changes.length);
      for (const c of m.changes) w.i32(c.x).i16(c.y).i32(c.z).u16(c.id);
      break;
    case 'entities':
      w.u8(S2C.entities).u32(m.serverTick).u16(m.entities.length);
      for (const e of m.entities) {
        w.u32(e.id).u8(e.kind).u16(e.type).f32(e.x).f32(e.y).f32(e.z).f32(e.yaw).f32(e.pitch).f32(e.headYaw).u8(e.flags).u8(Math.min(255, e.count));
      }
      w.u16(m.removed.length);
      for (const id of m.removed) w.u32(id);
      break;
    case 'playerState':
      w.u8(S2C.playerState).u32(m.ackTick).f64(m.x).f64(m.y).f64(m.z).f64(m.vx).f64(m.vy).f64(m.vz).u8(m.flags);
      w.f32(m.health).u8(m.hunger).f32(m.saturation).f32(m.air).f32(m.exhaustion).f32(m.fallDistance);
      w.u8(gameModeIndex(m.gameMode)).u8(m.selectedSlot).u8(m.deathCause).u8(m.deathAttacker);
      break;
    case 'inventory':
      w.u8(S2C.inventory);
      for (let i = 0; i < INVENTORY_SIZE; i++) writeSlot(w, m.slots[i] ?? null);
      writeSlot(w, m.cursor);
      w.u8(m.grid.length);
      for (const s of m.grid) writeSlot(w, s);
      break;
    case 'chat':
      w.u8(S2C.chat).u8(m.kind).string(m.from).string(m.text);
      break;
    case 'time':
      w.u8(S2C.time).f64(m.timeTicks);
      break;
    case 'playerList':
      w.u8(S2C.playerList).bool(m.joined).u32(m.id).string(m.name);
      break;
    case 'actionAck':
      w.u8(S2C.actionAck).u32(m.seq).bool(m.ok).string(m.reason);
      break;
    case 'pong':
      w.u8(S2C.pong).f64(m.time);
      break;
    case 'disconnect':
      w.u8(S2C.disconnect).string(m.reason);
      break;
  }
  return w.finish();
}

/** Decodes and validates a server frame. Throws `ProtocolError` on anything malformed. */
export function decodeServerMessage(data: Uint8Array): ServerMessage {
  if (data.length === 0) throw new ProtocolError('empty message');
  if (data.length > MAX_SERVER_MESSAGE_BYTES) throw new ProtocolError('message too large');
  const r = new ByteReader(data);
  const type = r.u8();
  let m: ServerMessage;
  switch (type) {
    case S2C.welcome: {
      const playerId = r.u32();
      const worldName = r.string(256);
      const seed = r.u32();
      const generator = GENERATOR_KINDS[r.u8()];
      if (!generator) throw new ProtocolError('invalid generator');
      const tickRate = r.u8();
      const serverTick = r.u32();
      const timeTicks = r.f64();
      const dayTicks = r.u32();
      const gameMode = readGameMode(r);
      const viewDistance = r.u8();
      const x = r.f64(), y = r.f64(), z = r.f64();
      const yaw = r.f32(), pitch = r.f32();
      const flying = r.bool();
      if (tickRate === 0 || dayTicks === 0) throw new ProtocolError('invalid welcome');
      m = { type: 'welcome', playerId, worldName, seed, generator, tickRate, serverTick, timeTicks, dayTicks, gameMode, viewDistance, x, y, z, yaw, pitch, flying };
      break;
    }
    case S2C.chunk: {
      const cx = r.i32();
      const cz = r.i32();
      const n = r.u16();
      if (n === 0 || n > MAX_PALETTE) throw new ProtocolError('invalid palette');
      const palette: string[] = [];
      for (let i = 0; i < n; i++) palette.push(r.string(128));
      const len = r.u32();
      if (len > r.remaining) throw new ProtocolError('message truncated');
      m = { type: 'chunk', cx, cz, palette, rle: r.bytes(len) };
      break;
    }
    case S2C.unloadChunk:
      m = { type: 'unloadChunk', cx: r.i32(), cz: r.i32() };
      break;
    case S2C.blockChanges: {
      const n = r.u16();
      if (n > MAX_BLOCK_CHANGES) throw new ProtocolError('too many block changes');
      const changes: BlockChange[] = [];
      for (let i = 0; i < n; i++) changes.push({ x: r.i32(), y: r.i16(), z: r.i32(), id: r.u16() });
      m = { type: 'blockChanges', changes };
      break;
    }
    case S2C.entities: {
      const serverTick = r.u32();
      const n = r.u16();
      if (n > MAX_ENTITIES) throw new ProtocolError('too many entities');
      const entities: EntitySnapshot[] = [];
      for (let i = 0; i < n; i++) {
        const id = r.u32();
        const kind = intIn(r.u8(), 1, 4, 'entity kind') as EntityKind;
        entities.push({ id, kind, type: r.u16(), x: r.f32(), y: r.f32(), z: r.f32(), yaw: r.f32(), pitch: r.f32(), headYaw: r.f32(), flags: r.u8(), count: r.u8() });
      }
      const k = r.u16();
      if (k > MAX_ENTITIES) throw new ProtocolError('too many removals');
      const removed: number[] = [];
      for (let i = 0; i < k; i++) removed.push(r.u32());
      m = { type: 'entities', serverTick, entities, removed };
      break;
    }
    case S2C.playerState: {
      const ackTick = r.u32();
      const x = r.f64(), y = r.f64(), z = r.f64(), vx = r.f64(), vy = r.f64(), vz = r.f64();
      const flags = r.u8();
      const health = r.f32();
      const hunger = r.u8();
      const saturation = r.f32();
      const air = r.f32();
      const exhaustion = r.f32();
      const fallDistance = r.f32();
      const gameMode = readGameMode(r);
      const selectedSlot = intIn(r.u8(), 0, 8, 'slot');
      const deathCause = intIn(r.u8(), 0, DAMAGE_CAUSES.length, 'death cause');
      const deathAttacker = r.u8();
      m = { type: 'playerState', ackTick, x, y, z, vx, vy, vz, flags, health, hunger, saturation, air, exhaustion, fallDistance, gameMode, selectedSlot, deathCause, deathAttacker };
      break;
    }
    case S2C.inventory: {
      const slots: Slot[] = [];
      for (let i = 0; i < INVENTORY_SIZE; i++) slots.push(readSlot(r));
      const cursor = readSlot(r);
      const n = r.u8();
      if (n !== 0 && n !== 4 && n !== 9) throw new ProtocolError('invalid grid');
      const grid: Slot[] = [];
      for (let i = 0; i < n; i++) grid.push(readSlot(r));
      m = { type: 'inventory', slots, cursor, grid };
      break;
    }
    case S2C.chat: {
      const kind = intIn(r.u8(), 0, 1, 'chat kind');
      m = { type: 'chat', kind, from: r.string(MAX_NAME_LENGTH * 4), text: r.string(MAX_CHAT_LENGTH * 4 + 256) };
      break;
    }
    case S2C.time:
      m = { type: 'time', timeTicks: r.f64() };
      break;
    case S2C.playerList:
      m = { type: 'playerList', joined: r.bool(), id: r.u32(), name: r.string(MAX_NAME_LENGTH * 4) };
      break;
    case S2C.actionAck:
      m = { type: 'actionAck', seq: r.u32(), ok: r.bool(), reason: r.string(64) };
      break;
    case S2C.pong:
      m = { type: 'pong', time: r.f64() };
      break;
    case S2C.disconnect:
      m = { type: 'disconnect', reason: r.string(MAX_REASON_BYTES) };
      break;
    default:
      throw new ProtocolError(`unknown server message type ${type}`);
  }
  r.end();
  return m;
}
