import {
  PROTOCOL_VERSION,
  ProtocolError,
  decodeServerMessage,
  encodeClientMessage,
  type ActionKind,
  type ClientMessage,
  type Connection,
  type InventoryOp,
  type ServerMessage,
  type WelcomeMsg,
} from '@voxel/shared';

export const DEFAULT_SERVER_PORT = 25580;

/**
 * Normalizes what a player types as the server address: "host", "host:port", "ws://host:port"
 * or "wss://...". Missing scheme = ws://, missing port = 25580. Throws on garbage.
 */
export function normalizeServerUrl(input: string): string {
  let s = input.trim();
  if (!s) throw new Error('Enter a server address, e.g. localhost:25580');
  if (!/^wss?:\/\//i.test(s)) {
    if (/^[a-z]+:\/\//i.test(s)) throw new Error('Server addresses start with ws:// or wss://');
    s = `ws://${s}`;
  }
  let url: URL;
  try {
    url = new URL(s);
  } catch {
    throw new Error(`"${input}" is not a valid server address`);
  }
  if (!url.port) url.port = String(DEFAULT_SERVER_PORT);
  url.hash = '';
  return url.toString().replace(/\/$/, '');
}

/** "host:port" of a ws:// URL (or the input itself when it does not parse), for messages. */
export function serverHost(url: string): string {
  try {
    return new URL(url).host || url;
  } catch {
    return url;
  }
}

/** Message shown when no connection could be made at all. */
export function unreachableMessage(url: string): string {
  return `Couldn't reach the server at ${serverHost(url)}: is it running and the port open?`;
}

/**
 * Turns a raw connection-end reason into something friendly for the disconnect screen. Reasons the
 * server sent on purpose (kicked, shutting down, version mismatch...) are kept as they are; low-level
 * socket ones are explained.
 */
export function friendlyDisconnectReason(reason: string, url: string): string {
  const host = serverHost(url);
  const r = reason.trim();
  if (!r || r === 'Connection lost' || r === 'Connection error' || r === 'Connection closed') {
    return `Lost the connection to ${host}. The server may have stopped, or the network dropped.`;
  }
  if (r === 'Handshake timed out' || r === 'The server did not answer the handshake.') {
    return `${host} accepted the connection but did not answer like a Blockwright server. Check the address and port.`;
  }
  if (r === 'Timed out') return `The server at ${host} stopped responding (timed out).`;
  return r;
}

/** A browser WebSocket as a shared `Connection` (binary frames only). */
export class WebSocketConnection implements Connection {
  private closeHandlers: ((reason: string) => void)[] = [];
  private closedReason: string | undefined;

  private constructor(
    private readonly ws: WebSocket,
    readonly remote: string,
  ) {
    ws.binaryType = 'arraybuffer';
    ws.addEventListener('close', (e) => this.finish(e.reason || (e.wasClean ? 'Connection closed' : 'Connection lost')));
    ws.addEventListener('error', () => this.finish('Connection error'));
  }

  /** Opens a socket; rejects if it cannot connect within `timeoutMs`. */
  static open(url: string, timeoutMs = 8000): Promise<WebSocketConnection> {
    return new Promise((resolve, reject) => {
      let ws: WebSocket;
      try {
        ws = new WebSocket(url);
      } catch (err) {
        reject(err instanceof Error ? err : new Error(String(err)));
        return;
      }
      const timer = window.setTimeout(() => {
        ws.close();
        reject(new Error(`${unreachableMessage(url)} (no answer after ${Math.round(timeoutMs / 1000)} s)`));
      }, timeoutMs);
      ws.addEventListener('open', () => {
        window.clearTimeout(timer);
        resolve(new WebSocketConnection(ws, url));
      }, { once: true });
      ws.addEventListener('error', () => {
        window.clearTimeout(timer);
        reject(new Error(unreachableMessage(url)));
      }, { once: true });
    });
  }

  get isOpen(): boolean {
    return this.closedReason === undefined && this.ws.readyState === WebSocket.OPEN;
  }

  send(data: Uint8Array): void {
    if (this.isOpen) this.ws.send(data);
  }

  onMessage(handler: (data: Uint8Array) => void): void {
    this.ws.onmessage = (e: MessageEvent) => {
      if (e.data instanceof ArrayBuffer) handler(new Uint8Array(e.data));
    };
  }

  onClose(handler: (reason: string) => void): void {
    if (this.closedReason !== undefined) handler(this.closedReason);
    else this.closeHandlers.push(handler);
  }

  close(reason = 'Disconnected'): void {
    if (this.ws.readyState === WebSocket.OPEN || this.ws.readyState === WebSocket.CONNECTING) this.ws.close(1000, reason.slice(0, 120));
    this.finish(reason);
  }

  private finish(reason: string): void {
    if (this.closedReason !== undefined) return;
    this.closedReason = reason;
    for (const h of this.closeHandlers) h(reason);
    this.closeHandlers = [];
  }
}

/**
 * The client end of the multiplayer protocol: handshake, typed sends and decoded receives over
 * any `Connection`. Messages that arrive before a handler is attached (chunks right after the
 * welcome, while the game is being built) are buffered and delivered in order.
 */
export class NetClient {
  private handler: ((m: ServerMessage) => void) | undefined;
  private backlog: ServerMessage[] = [];
  private closeHandler: ((reason: string) => void) | undefined;
  private seq = 0;
  /** Reason from the server's `disconnect` message (shown instead of the socket's). */
  private serverReason: string | undefined;
  closedReason: string | undefined;
  /** Round-trip time of the last ping, ms. */
  rtt = 0;
  readonly stats = { received: 0, sent: 0, bytesIn: 0, bytesOut: 0 };

  private constructor(readonly conn: Connection) {
    conn.onMessage((data) => this.onFrame(data));
    conn.onClose((reason) => {
      this.closedReason = this.serverReason ?? reason;
      this.closeHandler?.(this.closedReason);
    });
  }

  /** Connects, says hello and waits for the welcome (or a disconnect reason). */
  static async join(conn: Connection, name: string, viewDistance: number, timeoutMs = 10000): Promise<{ client: NetClient; welcome: WelcomeMsg }> {
    const client = new NetClient(conn);
    const welcome = await new Promise<WelcomeMsg>((resolve, reject) => {
      const timer = setTimeout(() => {
        conn.close('Handshake timed out');
        reject(new Error('The server did not answer the handshake.'));
      }, timeoutMs);
      client.handler = (m) => {
        if (m.type === 'welcome') {
          clearTimeout(timer);
          client.handler = undefined;
          resolve(m);
        } else {
          client.backlog.push(m);
        }
      };
      client.closeHandler = (reason) => {
        clearTimeout(timer);
        reject(new Error(reason));
      };
      client.send({ type: 'hello', version: PROTOCOL_VERSION, name, viewDistance });
    });
    client.closeHandler = undefined;
    return { client, welcome };
  }

  get isOpen(): boolean {
    return this.conn.isOpen;
  }

  /** Attaches the game's handlers; buffered messages are delivered right away. */
  attach(onMessage: (m: ServerMessage) => void, onClose: (reason: string) => void): void {
    this.handler = onMessage;
    this.closeHandler = onClose;
    const pending = this.backlog;
    this.backlog = [];
    for (const m of pending) onMessage(m);
    if (this.closedReason !== undefined) onClose(this.closedReason);
  }

  private onFrame(data: Uint8Array): void {
    this.stats.received++;
    this.stats.bytesIn += data.length;
    let m: ServerMessage;
    try {
      m = decodeServerMessage(data);
    } catch (err) {
      console.error('Bad message from server', err);
      this.disconnect(err instanceof ProtocolError ? `Bad data from server: ${err.message}` : 'Bad data from server');
      return;
    }
    if (m.type === 'disconnect') this.serverReason = m.reason;
    if (m.type === 'pong') this.rtt = performance.now() - m.time;
    if (this.handler) this.handler(m);
    else this.backlog.push(m);
  }

  send(m: ClientMessage): void {
    const data = encodeClientMessage(m);
    this.stats.sent++;
    this.stats.bytesOut += data.length;
    this.conn.send(data);
  }

  /** Sends a gameplay action; returns its sequence number. */
  action(action: ActionKind, x = 0, y = 0, z = 0, face = -1, arg = 0): number {
    const seq = ++this.seq;
    this.send({ type: 'action', seq, action, x, y, z, face, arg: arg >>> 0 });
    return seq;
  }

  invOp(op: InventoryOp): void {
    this.send({ type: 'invOp', seq: ++this.seq, op });
  }

  chat(text: string): void {
    this.send({ type: 'chat', text });
  }

  ping(): void {
    this.send({ type: 'ping', time: performance.now() });
  }

  disconnect(reason = 'Disconnected'): void {
    this.serverReason ??= reason;
    this.conn.close(reason);
  }
}
