/**
 * Byte compression for saved chunks via CompressionStream, when the browser has it. The codec name
 * is stored with each record so data written without compression (old browsers, or the
 * synchronous pagehide path) still loads.
 */

export type ByteCodec = 'none' | 'deflate-raw' | 'gzip';

function pickFormat(): CompressionFormat | undefined {
  if (typeof CompressionStream === 'undefined' || typeof DecompressionStream === 'undefined') return undefined;
  for (const f of ['deflate-raw', 'gzip'] as const) {
    try {
      new CompressionStream(f);
      return f;
    } catch {
      // unsupported format; try the next
    }
  }
  return undefined;
}

let format: CompressionFormat | undefined | null = null;

/** The compression format this browser supports, or undefined. */
export function compressionFormat(): CompressionFormat | undefined {
  if (format === null) format = pickFormat();
  return format;
}

async function pipe(data: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const out = new Blob([data as Uint8Array<ArrayBuffer>]).stream().pipeThrough(stream);
  return new Uint8Array(await new Response(out).arrayBuffer());
}

/** Compresses `data` if possible; returns the codec actually used. */
export async function compressBytes(data: Uint8Array): Promise<{ codec: ByteCodec; data: Uint8Array }> {
  const f = compressionFormat();
  if (!f) return { codec: 'none', data };
  try {
    return { codec: f as ByteCodec, data: await pipe(data, new CompressionStream(f)) };
  } catch (err) {
    console.warn('Compression failed; storing uncompressed', err);
    return { codec: 'none', data };
  }
}

export async function decompressBytes(codec: ByteCodec, data: Uint8Array): Promise<Uint8Array> {
  if (codec === 'none') return data;
  if (typeof DecompressionStream === 'undefined') throw new Error(`Cannot decompress ${codec}: DecompressionStream missing`);
  return pipe(data, new DecompressionStream(codec));
}
