import { chunkKey } from '@voxel/shared';

/**
 * Time-sliced light stitching (Milestone 9). Newly added chunks queue here instead of being
 * stitched inside `ChunkStreamer.update`; `process` stitches in arrival order until a per-frame
 * budget is used (always at least one chunk, so it never stalls). A chunk and its 4 neighbours are
 * not meshed while it waits (`isSettled`), so nothing is meshed with half-stitched border light.
 */
export class StitchQueue {
  /** Chunk key -> coordinates, in insertion order. */
  private readonly pending = new Map<number, [number, number]>();
  /** Chunks stitched in the last `process` call, and the time it took (ms). */
  lastCount = 0;
  lastMs = 0;

  constructor(
    private readonly stitch: (cx: number, cz: number) => void,
    private readonly now: () => number = () => performance.now(),
  ) {}

  get length(): number {
    return this.pending.size;
  }

  add(cx: number, cz: number): void {
    this.pending.set(chunkKey(cx, cz), [cx, cz]);
  }

  /** The chunk was unloaded before its turn. */
  remove(cx: number, cz: number): void {
    this.pending.delete(chunkKey(cx, cz));
  }

  has(cx: number, cz: number): boolean {
    return this.pending.has(chunkKey(cx, cz));
  }

  /** True when neither the chunk nor a horizontal neighbour waits for stitching. */
  isSettled(cx: number, cz: number): boolean {
    if (this.pending.size === 0) return true;
    return !this.has(cx, cz) && !this.has(cx + 1, cz) && !this.has(cx - 1, cz) && !this.has(cx, cz + 1) && !this.has(cx, cz - 1);
  }

  /** Stitches queued chunks until `budgetMs` has passed (at least one). Returns how many ran. */
  process(budgetMs: number): number {
    const t0 = this.now();
    let n = 0;
    for (const [key, [cx, cz]] of this.pending) {
      this.pending.delete(key);
      this.stitch(cx, cz);
      n++;
      if (this.now() - t0 >= budgetMs) break;
    }
    this.lastCount = n;
    this.lastMs = this.now() - t0;
    return n;
  }

  clear(): void {
    this.pending.clear();
  }
}
