import { CONCRETE_COLOURS, TEXTURE_LAYER_NAMES, mulberry32, type TextureLayerName } from '@voxel/shared';

/** Edge length of every block texture layer, in pixels. */
export const TEXTURE_SIZE = 16;
const S = TEXTURE_SIZE;

type RGB = readonly [number, number, number];
type Rand = () => number;

/** One RGBA8 16x16 image; row 0 is the top of the image. */
class Img {
  readonly data = new Uint8Array(S * S * 4);

  put(x: number, y: number, c: RGB, a = 255): void {
    const i = ((y & (S - 1)) * S + (x & (S - 1))) * 4;
    this.data[i] = c[0];
    this.data[i + 1] = c[1];
    this.data[i + 2] = c[2];
    this.data[i + 3] = a;
  }

  fill(palette: readonly RGB[], rand: Rand, a = 255): this {
    for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) this.put(x, y, pick(palette, rand), a);
    return this;
  }
}

function pick(palette: readonly RGB[], rand: Rand): RGB {
  return palette[Math.floor(rand() * palette.length) % palette.length]!;
}

const GRASS: readonly RGB[] = [[74, 132, 46], [86, 150, 52], [98, 166, 60], [66, 120, 42]];
const DIRT: readonly RGB[] = [[121, 85, 58], [134, 96, 66], [108, 76, 52], [146, 106, 74]];
const STONE: readonly RGB[] = [[118, 118, 122], [128, 128, 132], [138, 137, 140], [108, 108, 112]];
const SAND: readonly RGB[] = [[219, 205, 152], [227, 213, 160], [209, 194, 140], [233, 222, 172]];
const BARK: readonly RGB[] = [[92, 66, 40], [104, 75, 46], [80, 57, 35]];
const WOOD: readonly RGB[] = [[176, 138, 86], [188, 150, 96], [166, 128, 78]];
const PLANK: readonly RGB[] = [[170, 128, 76], [182, 139, 84], [160, 120, 70]];
const LEAF: readonly RGB[] = [[46, 112, 38], [56, 128, 44], [38, 98, 32], [64, 140, 52]];
const WATER: readonly RGB[] = [[46, 98, 196], [52, 108, 206], [42, 90, 184]];
const ASPHALT: readonly RGB[] = [[52, 52, 56], [58, 58, 62], [46, 46, 50], [62, 61, 64]];
const PATH: readonly RGB[] = [[150, 118, 74], [142, 110, 68], [158, 126, 80], [134, 104, 64]];

/** `c` scaled by `k` (clamped). */
function shade(c: RGB, k: number): RGB {
  return [Math.min(255, Math.round(c[0] * k)), Math.min(255, Math.round(c[1] * k)), Math.min(255, Math.round(c[2] * k))];
}

/** A small palette around one colour (for tinted blocks). */
function around(c: RGB, spread: number): RGB[] {
  return [shade(c, 1), shade(c, 1 - spread), shade(c, 1 + spread), shade(c, 1 - spread / 2)];
}

/** Road paint over asphalt, slightly worn: a few asphalt grains show through. */
function roadPaint(rand: Rand, paint: RGB): Img {
  const img = new Img().fill(around(paint, 0.03), rand);
  for (let n = 0; n < 7; n++) img.put(Math.floor(rand() * S), Math.floor(rand() * S), pick(ASPHALT, rand));
  return img;
}

/**
 * Running-bond courses: `course` px high rows, each block `len` px long, offset by half a block on
 * every other row. `face(rand)` colours one whole block; joints get `joint`.
 */
function courses(rand: Rand, course: number, len: number, face: (rand: Rand) => readonly RGB[], joint: RGB, jointBottomOnly = false): Img {
  const img = new Img();
  for (let row = 0; row < S / course; row++) {
    const off = row % 2 === 0 ? 0 : len / 2;
    for (let b = -1; b < S / len; b++) {
      const pal = face(rand);
      for (let y = row * course; y < (row + 1) * course; y++) {
        for (let x = b * len + off; x < (b + 1) * len + off; x++) {
          if (x < 0 || x >= S) continue;
          const isJoint = y === (row + 1) * course - 1 || (!jointBottomOnly && x === b * len + off);
          img.put(x, y, isJoint ? joint : pick(pal, rand));
        }
      }
    }
  }
  return img;
}

/** Concrete: nearly flat colour with faint aggregate speckles. */
function concrete(rand: Rand, c: RGB): Img {
  const img = new Img().fill(around(c, 0.025), rand);
  for (let n = 0; n < 10; n++) img.put(Math.floor(rand() * S), Math.floor(rand() * S), shade(c, rand() < 0.5 ? 0.9 : 1.08));
  return img;
}

const CONCRETE_GENERATORS = Object.fromEntries(
  CONCRETE_COLOURS.map((c) => [`concrete_${c.name}`, (rand: Rand) => concrete(rand, c.rgb)]),
) as Record<`concrete_${(typeof CONCRETE_COLOURS)[number]['name']}`, (rand: Rand) => Img>;

const GENERATORS: Record<TextureLayerName, (rand: Rand) => Img> = {
  stone(rand) {
    const img = new Img().fill(STONE, rand);
    // A few darker cracks.
    for (let n = 0; n < 4; n++) {
      let x = Math.floor(rand() * S);
      let y = Math.floor(rand() * S);
      for (let k = 0; k < 4; k++) {
        img.put(x, y, [92, 92, 96]);
        x += rand() < 0.5 ? 1 : 0;
        y += rand() < 0.5 ? 1 : 0;
      }
    }
    return img;
  },
  dirt: (rand) => new Img().fill(DIRT, rand),
  grass_top: (rand) => new Img().fill(GRASS, rand),
  grass_side(rand) {
    const img = new Img().fill(DIRT, rand);
    for (let x = 0; x < S; x++) {
      const depth = 2 + Math.floor(rand() * 4); // ragged fringe 2..5 px
      for (let y = 0; y < depth; y++) img.put(x, y, pick(GRASS, rand));
    }
    return img;
  },
  sand(rand) {
    const img = new Img().fill(SAND, rand);
    for (let n = 0; n < 6; n++) img.put(Math.floor(rand() * S), Math.floor(rand() * S), [196, 180, 126]);
    return img;
  },
  log_side(rand) {
    const img = new Img();
    for (let x = 0; x < S; x++) {
      // Vertical bark ridges: every 3rd-4th column darker.
      const dark = x % 4 === 0 || rand() < 0.15;
      for (let y = 0; y < S; y++) img.put(x, y, dark ? [66, 47, 29] : pick(BARK, rand));
    }
    return img;
  },
  log_top(rand) {
    const img = new Img();
    for (let y = 0; y < S; y++) {
      for (let x = 0; x < S; x++) {
        const d = Math.max(Math.abs(x - 7.5), Math.abs(y - 7.5));
        if (d > 6.5) img.put(x, y, pick(BARK, rand));
        else img.put(x, y, Math.floor(d) % 2 === 0 ? [150, 114, 68] : pick(WOOD, rand));
      }
    }
    return img;
  },
  leaves(rand) {
    const img = new Img();
    for (let y = 0; y < S; y++) {
      for (let x = 0; x < S; x++) {
        // ~20% holes give the cutout look.
        if (rand() < 0.2) img.put(x, y, [0, 0, 0], 0);
        else img.put(x, y, pick(LEAF, rand));
      }
    }
    return img;
  },
  planks(rand) {
    const img = new Img().fill(PLANK, rand);
    for (let row = 0; row < 4; row++) {
      const y = row * 4 + 3;
      for (let x = 0; x < S; x++) img.put(x, y, [120, 88, 50]); // board seams
      const joint = (row * 7 + 3) % S;
      for (let k = 0; k < 3; k++) img.put(joint, row * 4 + k, [128, 94, 54]);
    }
    return img;
  },
  glass(rand) {
    const img = new Img();
    for (let y = 0; y < S; y++) {
      for (let x = 0; x < S; x++) {
        const edge = x === 0 || y === 0 || x === S - 1 || y === S - 1;
        if (edge) img.put(x, y, [214, 232, 240], 255);
        else img.put(x, y, [200, 225, 240], 40 + Math.floor(rand() * 12));
      }
    }
    // Diagonal glints.
    for (let k = 0; k < 4; k++) {
      img.put(3 + k, 9 - k, [255, 255, 255], 170);
      img.put(9 + k, 12 - k, [255, 255, 255], 140);
    }
    return img;
  },
  water(rand) {
    const img = new Img().fill(WATER, rand, 175);
    for (let n = 0; n < 5; n++) {
      const x = Math.floor(rand() * S);
      const y = Math.floor(rand() * S);
      for (let k = 0; k < 3; k++) img.put(x + k, y, [110, 160, 230], 190); // ripple highlights
    }
    return img;
  },
  sandstone_top: (rand) => new Img().fill(SANDSTONE, rand),
  sandstone_side(rand) {
    const img = new Img().fill(SANDSTONE, rand);
    // Horizontal sediment bands.
    for (const y of [0, 5, 6, 11]) for (let x = 0; x < S; x++) img.put(x, y, rand() < 0.8 ? [190, 170, 116] : [202, 184, 128]);
    return img;
  },
  coal_ore: (rand) => oreTexture(rand, [[40, 40, 44], [22, 22, 25], [96, 96, 104]]),
  iron_ore: (rand) => oreTexture(rand, [[214, 160, 118], [168, 112, 80], [246, 210, 176]]),
  torch(rand) {
    // Transparent except a thin stick with a glowing head, centred so it reads on a cross mesh.
    const img = new Img();
    for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) img.put(x, y, [0, 0, 0], 0);
    for (let y = 6; y < S; y++) {
      img.put(7, y, y % 3 === 0 ? [92, 64, 36] : [118, 84, 48]);
      img.put(8, y, y % 4 === 1 ? [84, 58, 32] : [104, 74, 42]);
    }
    const FLAME: readonly RGB[] = [[255, 214, 92], [255, 186, 64], [255, 236, 150]];
    for (let y = 3; y < 6; y++) for (let x = 7; x < 9; x++) img.put(x, y, pick(FLAME, rand));
    img.put(7, 2, [255, 244, 190]);
    img.put(8, 2, [255, 160, 50]);
    img.put(6, 4, [255, 150, 40], 200);
    img.put(9, 4, [255, 150, 40], 200);
    return img;
  },
  lumen_block(rand) {
    // Warm glowing crystal: bright facets separated by darker amber seams.
    const img = new Img().fill([[255, 224, 128], [250, 208, 104], [255, 236, 160]], rand);
    for (let i = 0; i < S; i++) {
      img.put(i, (i * 5 + 3) % S, [196, 140, 60]);
      img.put((i * 7 + 11) % S, i, [208, 152, 66]);
    }
    for (let n = 0; n < 8; n++) img.put(Math.floor(rand() * S), Math.floor(rand() * S), [255, 252, 220]);
    return img;
  },
  bedrock(rand) {
    const img = new Img().fill([[62, 62, 64], [84, 84, 86], [44, 44, 46], [104, 104, 106]], rand);
    for (let n = 0; n < 10; n++) img.put(Math.floor(rand() * S), Math.floor(rand() * S), [24, 24, 26]);
    return img;
  },
  rubble(rand) {
    // Irregular rounded chunks with dark mortar gaps between them.
    const img = new Img().fill([[78, 78, 82], [70, 70, 74]], rand);
    const centres: [number, number][] = [];
    for (let n = 0; n < 9; n++) centres.push([rand() * S, rand() * S]);
    for (let y = 0; y < S; y++) {
      for (let x = 0; x < S; x++) {
        // Distance to nearest and second nearest centre (wrapping): small gap = mortar.
        let d1 = Infinity, d2 = Infinity;
        for (const [cx, cy] of centres) {
          const dx = Math.min(Math.abs(x - cx), S - Math.abs(x - cx));
          const dy = Math.min(Math.abs(y - cy), S - Math.abs(y - cy));
          const d = dx * dx + dy * dy;
          if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) d2 = d;
        }
        if (Math.sqrt(d2) - Math.sqrt(d1) < 0.9) img.put(x, y, [66, 66, 70]);
        else img.put(x, y, pick(STONE, rand));
      }
    }
    return img;
  },
  workbench_top(rand) {
    const img = new Img().fill(PLANK, rand);
    // Frame, and a 3x3 grid of inlaid squares.
    for (let i = 0; i < S; i++) {
      img.put(i, 0, [110, 78, 44]); img.put(i, S - 1, [110, 78, 44]);
      img.put(0, i, [110, 78, 44]); img.put(S - 1, i, [110, 78, 44]);
    }
    for (const g of [5, 10]) for (let i = 2; i < S - 2; i++) { img.put(g, i, [126, 90, 52]); img.put(i, g, [126, 90, 52]); }
    return img;
  },
  workbench_side(rand) {
    const img = new Img().fill(PLANK, rand);
    for (let x = 0; x < S; x++) { img.put(x, 0, [110, 78, 44]); img.put(x, 1, [196, 156, 98]); img.put(x, 4, [120, 88, 50]); }
    // Two hanging tools: a saw blade and a hammer, in plain shapes.
    for (let y = 6; y < 13; y++) img.put(4, y, [120, 84, 46]);
    for (let y = 6; y < 9; y++) { img.put(3, y, [170, 170, 176]); img.put(5, y, [170, 170, 176]); }
    for (let y = 6; y < 14; y++) img.put(11, y, [120, 84, 46]);
    for (let x = 9; x < 14; x++) img.put(x, 6, [150, 150, 156]);
    for (let x = 9; x < 14; x++) img.put(x, 7, [120, 120, 126]);
    return img;
  },
  stone_bricks(rand) {
    const img = new Img().fill([[134, 134, 138], [126, 126, 130], [142, 141, 144]], rand);
    for (let row = 0; row < 4; row++) {
      const y = row * 4 + 3;
      for (let x = 0; x < S; x++) img.put(x, y, [92, 92, 96]);
      const off = row % 2 === 0 ? 0 : 4;
      for (const jx of [off, off + 8]) for (let k = 0; k < 3; k++) img.put(jx, row * 4 + k, [92, 92, 96]);
    }
    return img;
  },
  wool(rand) {
    // Soft off-white with curly darker tufts.
    const img = new Img().fill([[232, 230, 222], [224, 222, 214], [238, 236, 230]], rand);
    for (let n = 0; n < 14; n++) {
      const x = Math.floor(rand() * S), y = Math.floor(rand() * S);
      img.put(x, y, [204, 200, 190]);
      img.put(x + 1, y, [212, 208, 198]);
    }
    return img;
  },
  // --- Map worlds, phase B ----------------------------------------------------------------------
  asphalt(rand) {
    const img = new Img().fill(ASPHALT, rand);
    for (let n = 0; n < 12; n++) img.put(Math.floor(rand() * S), Math.floor(rand() * S), rand() < 0.6 ? [84, 84, 88] : [36, 36, 40]);
    return img;
  },
  road_marking: (rand) => roadPaint(rand, [232, 232, 226]),
  road_marking_yellow: (rand) => roadPaint(rand, [226, 188, 60]),
  paving(rand) {
    // Four 8x8 slabs with grey joints, each slab a slightly different tone.
    const img = new Img();
    const base: RGB = [176, 170, 158];
    for (let sy = 0; sy < 2; sy++) {
      for (let sx = 0; sx < 2; sx++) {
        const pal = around(shade(base, 0.95 + rand() * 0.1), 0.03);
        for (let y = sy * 8; y < sy * 8 + 8; y++) {
          for (let x = sx * 8; x < sx * 8 + 8; x++) img.put(x, y, x % 8 === 7 || y % 8 === 7 ? [128, 124, 116] : pick(pal, rand));
        }
      }
    }
    return img;
  },
  brick: (rand) => {
    const tones: RGB[] = [[156, 72, 52], [146, 64, 46], [166, 82, 58], [136, 60, 44]];
    return courses(rand, 4, 8, (r) => around(pick(tones, r), 0.04), [190, 182, 166]);
  },
  plaster(rand) {
    const img = new Img().fill([[230, 222, 200], [225, 217, 195], [234, 227, 206]], rand);
    for (let n = 0; n < 6; n++) img.put(Math.floor(rand() * S), Math.floor(rand() * S), [214, 205, 182]);
    return img;
  },
  roof_tiles: (rand) => courses(rand, 4, 4, (r) => around(pick([[178, 76, 50], [166, 68, 44], [188, 86, 58]] as RGB[], r), 0.04), [116, 44, 30]),
  roof_slate: (rand) => courses(rand, 4, 8, (r) => around(pick([[66, 72, 82], [58, 64, 74], [72, 78, 88]] as RGB[], r), 0.04), [34, 38, 46]),
  gravel(rand) {
    const img = new Img().fill([[128, 124, 120], [104, 100, 98], [146, 142, 136], [92, 88, 86], [120, 110, 100]], rand);
    // Pebbles: a light pixel with a dark one below-right.
    for (let n = 0; n < 14; n++) {
      const x = Math.floor(rand() * S), y = Math.floor(rand() * S);
      img.put(x, y, [172, 168, 160]);
      img.put(x + 1, y + 1, [70, 66, 64]);
    }
    return img;
  },
  dirt_path_top(rand) {
    const img = new Img().fill(PATH, rand);
    for (let n = 0; n < 6; n++) img.put(Math.floor(rand() * S), Math.floor(rand() * S), [118, 92, 56]);
    return img;
  },
  dirt_path_side(rand) {
    const img = new Img().fill(DIRT, rand);
    for (let x = 0; x < S; x++) {
      const depth = 2 + (rand() < 0.3 ? 1 : 0);
      for (let y = 0; y < depth; y++) img.put(x, y, pick(PATH, rand));
    }
    return img;
  },
  ...CONCRETE_GENERATORS,
  // --- Map worlds, phase D (cut-out decals) -----------------------------------------------------
  rail(rand) {
    // Running north-south (along v): wooden ties every 4 rows under two steel rails.
    const img = clear();
    for (let y = 0; y < S; y++) {
      if (y % 4 === 1 || y % 4 === 2) for (let x = 1; x < S - 1; x++) img.put(x, y, pick(TIE, rand));
    }
    for (let y = 0; y < S; y++) {
      for (const x of [3, 12]) img.put(x, y, STEEL_DARK);
      for (const x of [4, 11]) img.put(x, y, STEEL);
    }
    return img;
  },
  rail_curve(rand) {
    // Quarter circle joining the south edge (v = 16) to the east edge (u = 16), around that corner.
    const img = clear();
    for (let y = 0; y < S; y++) {
      for (let x = 0; x < S; x++) {
        const r = Math.hypot(16 - (x + 0.5), 16 - (y + 0.5));
        const ang = Math.atan2(16 - (y + 0.5), 16 - (x + 0.5)); // 0..pi/2
        const tie = Math.floor((ang / (Math.PI / 2)) * 5 * 2) % 2 === 0;
        if (r >= 3 && r <= 14 && tie && r > 3.5 && r < 13.5) img.put(x, y, pick(TIE, rand));
        if ((r >= 4 && r < 5) || (r >= 11.5 && r < 12.5)) img.put(x, y, STEEL);
        else if ((r >= 3.3 && r < 4) || (r >= 12.5 && r < 13.2)) img.put(x, y, STEEL_DARK);
      }
    }
    return img;
  },
};

const TIE: readonly RGB[] = [[104, 76, 50], [96, 70, 46], [112, 82, 54]];
const STEEL: RGB = [196, 198, 204];
const STEEL_DARK: RGB = [92, 94, 100];

/** A fully transparent image. */
function clear(): Img {
  const img = new Img();
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) img.put(x, y, [0, 0, 0], 0);
  return img;
}

const SANDSTONE: readonly RGB[] = [[214, 196, 140], [208, 190, 134], [220, 204, 150]];

/**
 * Stone with small mineral clusters (Milestone 11: each grain is shaded like a little gem, a light
 * top-left pixel and a dark rim bottom-right, so ores read at a glance and from a distance).
 */
function oreTexture(rand: Rand, mineral: readonly RGB[]): Img {
  const img = GENERATORS.stone(rand);
  const light = mineral[2]!;
  const mid = mineral[0]!;
  const dark = mineral[1]!;
  const rim: RGB = [70, 70, 74];
  const taken = new Set<number>();
  let placed = 0;
  for (let tries = 0; tries < 40 && placed < 6; tries++) {
    const cx = 1 + Math.floor(rand() * (S - 3));
    const cy = 1 + Math.floor(rand() * (S - 3));
    if (taken.has(cy * S + cx)) continue;
    placed++;
    // A 2x2 grain (sometimes with a third lobe), mortar-dark shadow below / right.
    const cells: [number, number][] = [[0, 0], [1, 0], [0, 1], [1, 1]];
    if (rand() < 0.5) cells.push(rand() < 0.5 ? [2, 1] : [1, 2]);
    for (const [dx, dy] of cells) {
      for (let oy = -1; oy <= 1; oy++) for (let ox = -1; ox <= 1; ox++) taken.add(((cy + dy + oy) & 15) * S + ((cx + dx + ox) & 15));
    }
    for (const [dx, dy] of cells) {
      img.put(cx + dx + 1, cy + dy + 1, rim);
    }
    for (const [dx, dy] of cells) {
      const c = dx === 0 && dy === 0 ? light : dx + dy >= 2 ? dark : mid;
      img.put(cx + dx, cy + dy, c);
    }
  }
  return img;
}

// --- Finishing pass (Milestone 11) ------------------------------------------------------------------

/**
 * Per-layer finishing: `noise` = strength of a smooth value-noise brightness wobble (breaks up the
 * flat random-palette look), `bevel` = light top/left and dark bottom/right edge shading so blocks
 * read as blocks. Seamed / patterned textures (bricks, planks) and alpha textures get little or
 * none, otherwise tiling seams would show.
 */
const FINISH: Partial<Record<TextureLayerName, { noise: number; bevel: number }>> = {
  stone: { noise: 0.1, bevel: 0.07 },
  coal_ore: { noise: 0.08, bevel: 0.07 },
  iron_ore: { noise: 0.08, bevel: 0.07 },
  dirt: { noise: 0.12, bevel: 0.03 },
  grass_top: { noise: 0.12, bevel: 0.025 },
  grass_side: { noise: 0.08, bevel: 0.03 },
  sand: { noise: 0.07, bevel: 0.025 },
  sandstone_top: { noise: 0.06, bevel: 0.06 },
  sandstone_side: { noise: 0.05, bevel: 0.05 },
  log_side: { noise: 0.06, bevel: 0.04 },
  log_top: { noise: 0.05, bevel: 0.07 },
  planks: { noise: 0.06, bevel: 0.03 },
  bedrock: { noise: 0.12, bevel: 0.08 },
  rubble: { noise: 0.06, bevel: 0.05 },
  stone_bricks: { noise: 0.06, bevel: 0.04 },
  workbench_top: { noise: 0.04, bevel: 0 },
  workbench_side: { noise: 0.04, bevel: 0.03 },
  wool: { noise: 0.06, bevel: 0.05 },
  lumen_block: { noise: 0.05, bevel: 0.06 },
  leaves: { noise: 0.14, bevel: 0 },
  water: { noise: 0.06, bevel: 0 },
  // Ground blocks get almost no bevel so roads and pavements do not look gridded.
  asphalt: { noise: 0.08, bevel: 0.01 },
  road_marking: { noise: 0.04, bevel: 0.01 },
  road_marking_yellow: { noise: 0.04, bevel: 0.01 },
  paving: { noise: 0.05, bevel: 0 },
  brick: { noise: 0.05, bevel: 0.03 },
  plaster: { noise: 0.05, bevel: 0.035 },
  roof_tiles: { noise: 0.05, bevel: 0.02 },
  roof_slate: { noise: 0.05, bevel: 0.02 },
  gravel: { noise: 0.08, bevel: 0.03 },
  dirt_path_top: { noise: 0.08, bevel: 0.015 },
  dirt_path_side: { noise: 0.08, bevel: 0.03 },
  ...Object.fromEntries(CONCRETE_COLOURS.map((c) => [`concrete_${c.name}`, { noise: 0.04, bevel: 0.05 }])),
};

/** Tileable 16x16 value noise in -1..1 (bilinear over a coarse random lattice, wrapping). */
function valueNoise(rand: Rand, cell: number): Float32Array {
  const n = S / cell;
  const lattice = new Float32Array(n * n).map(() => rand() * 2 - 1);
  const out = new Float32Array(S * S);
  for (let y = 0; y < S; y++) {
    for (let x = 0; x < S; x++) {
      const fx = x / cell, fy = y / cell;
      const x0 = Math.floor(fx), y0 = Math.floor(fy);
      const tx = fx - x0, ty = fy - y0;
      const sx = tx * tx * (3 - 2 * tx), sy = ty * ty * (3 - 2 * ty);
      const at = (i: number, j: number): number => lattice[((j % n) + n) % n * n + (((i % n) + n) % n)]!;
      const a = at(x0, y0) + (at(x0 + 1, y0) - at(x0, y0)) * sx;
      const b = at(x0, y0 + 1) + (at(x0 + 1, y0 + 1) - at(x0, y0 + 1)) * sx;
      out[y * S + x] = a + (b - a) * sy;
    }
  }
  return out;
}

function finishTexture(img: Img, name: TextureLayerName, rand: Rand): Img {
  const f = FINISH[name];
  if (!f) return img;
  const coarse = valueNoise(rand, 8);
  const fine = valueNoise(rand, 4);
  const d = img.data;
  for (let y = 0; y < S; y++) {
    for (let x = 0; x < S; x++) {
      const i = (y * S + x) * 4;
      if (d[i + 3] === 0) continue;
      let k = 1 + f.noise * (coarse[y * S + x]! * 0.65 + fine[y * S + x]! * 0.35);
      if (f.bevel > 0) {
        if (x === 0 || y === 0) k += f.bevel;
        else if (x === S - 1 || y === S - 1) k -= f.bevel * 1.4;
        else if (x === 1 || y === 1) k += f.bevel * 0.35;
        else if (x === S - 2 || y === S - 2) k -= f.bevel * 0.5;
      }
      for (let c = 0; c < 3; c++) d[i + c] = Math.max(0, Math.min(255, Math.round(d[i + c]! * k)));
    }
  }
  return img;
}

let cached: Uint8Array[] | undefined;

/** Generates one image per entry of `TEXTURE_LAYER_NAMES`, in layer order. Deterministic and cached. */
export function generateBlockTextures(): Uint8Array[] {
  cached ??= TEXTURE_LAYER_NAMES.map((name, i) => {
    const rand = mulberry32(0x5eed + i * 7919);
    return finishTexture(GENERATORS[name](rand), name, mulberry32(0xf1e1d + i * 104729)).data;
  });
  return cached;
}

/** Number of break-progress crack stages. */
export const CRACK_STAGES = 10;

/**
 * Crack overlays for block breaking: stage 0 has two short cracks, later stages add more and
 * longer ones (each stage contains the previous). Black with alpha; transparent elsewhere.
 */
export function generateCrackTextures(): Uint8Array[] {
  const rand = mulberry32(0xc4ac);
  // Pre-generate crack paths; stage k draws the first k + 2 paths, each grown with the stage.
  const paths: [number, number][][] = [];
  for (let p = 0; p < CRACK_STAGES * 2; p++) {
    const path: [number, number][] = [];
    let x = 8 + Math.floor((rand() - 0.5) * 10);
    let y = 8 + Math.floor((rand() - 0.5) * 10);
    const dx = rand() < 0.5 ? -1 : 1;
    const dy = rand() < 0.5 ? -1 : 1;
    for (let k = 0; k < 9; k++) {
      path.push([x, y]);
      if (rand() < 0.6) x += dx; else y += dy;
      if (rand() < 0.25) y += dy;
    }
    paths.push(path);
  }
  const out: Uint8Array[] = [];
  for (let stage = 0; stage < CRACK_STAGES; stage++) {
    const img = new Img();
    for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) img.put(x, y, [0, 0, 0], 0);
    const len = 3 + Math.floor(stage * 0.6);
    for (let p = 0; p < stage + 2; p++) {
      for (const [x, y] of paths[p]!.slice(0, len)) img.put(x, y, [16, 12, 10], 170 + stage * 6);
    }
    out.push(img.data);
  }
  return out;
}
