/**
 * Uploads equally sized square RGBA8 layers into a single TEXTURE_2D_ARRAY with nearest filtering.
 * Each layer is `size * size * 4` bytes, row 0 = top of the image (sampled at v = 0).
 */
export function createTextureArray(gl: WebGL2RenderingContext, size: number, layers: Uint8Array[]): WebGLTexture {
  if (layers.length === 0) throw new Error('createTextureArray: need at least one layer');
  const tex = gl.createTexture();
  if (!tex) throw new Error('gl.createTexture failed');
  gl.bindTexture(gl.TEXTURE_2D_ARRAY, tex);
  gl.texStorage3D(gl.TEXTURE_2D_ARRAY, 1, gl.RGBA8, size, size, layers.length);
  gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
  layers.forEach((data, i) => {
    if (data.length !== size * size * 4) {
      throw new Error(`createTextureArray: layer ${i} has ${data.length} bytes, expected ${size * size * 4}`);
    }
    gl.texSubImage3D(gl.TEXTURE_2D_ARRAY, 0, 0, 0, i, size, size, 1, gl.RGBA, gl.UNSIGNED_BYTE, data);
  });
  gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
  gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_S, gl.REPEAT);
  gl.texParameteri(gl.TEXTURE_2D_ARRAY, gl.TEXTURE_WRAP_T, gl.REPEAT);
  gl.bindTexture(gl.TEXTURE_2D_ARRAY, null);
  return tex;
}
