/**
 * Dropped items (Milestone 7): small physics boxes that merge with identical neighbours, are
 * pulled toward and picked up by a nearby player, and despawn after ITEM_DESPAWN_SECONDS.
 */
import { stepBody, type BodyParams } from '../physics/body';
import type { BlockGetter } from '../physics/player';
import { getItemDef, stackFromSaved, stackToSaved, stacksMatch, type ItemStack, type SavedStack } from '../items/items';
import { EntityStore, allocateEntityId, type EntityBase } from './entities';

export const ITEM_SIZE = 0.25;
export const ITEM_DESPAWN_SECONDS = 300;
/** Pickup delay for block drops, and for items the player throws (Q, death). */
export const ITEM_PICKUP_DELAY = 0.5;
export const THROWN_PICKUP_DELAY = 1.5;
/** Within this distance (to the nearest point between the player's feet and head) items are pulled in... */
export const MAGNET_RADIUS = 2.5;
/** ...and within this one they are collected. */
export const PICKUP_RADIUS = 1.0;
export const MAGNET_SPEED = 8;
export const MERGE_RADIUS = 0.75;
export const MERGE_INTERVAL = 0.5;

export const ITEM_BODY: BodyParams = {
  halfWidth: ITEM_SIZE / 2,
  height: ITEM_SIZE,
  gravity: 20,
  terminal: 30,
  groundFriction: 8,
  airDrag: 0.5,
  waterDrag: 3,
  buoyancy: 2.5,
};

export interface ItemEntity extends EntityBase {
  readonly kind: 'item';
  stack: ItemStack;
  /** Seconds until it can be picked up. */
  pickupDelay: number;
  /** Random render phase so neighbouring items do not spin in sync. */
  phase: number;
}

/** Something that can pick items up (the player). Position is the feet. */
export interface ItemCollector {
  x: number;
  y: number;
  z: number;
  /** Height of the collector's body (its centre is at y + height / 2). */
  height: number;
  /** Takes as much of `stack` as it can; returns the count taken. */
  collect(stack: ItemStack): number;
}

export interface PickupEvent {
  item: number;
  count: number;
  /** Index of the collector (in the array passed to `tick`; 0 for a single collector). */
  collector: number;
}

export interface SavedItemEntity {
  stack: SavedStack;
  x: number;
  y: number;
  z: number;
  age: number;
}

export function createItemEntity(stack: ItemStack, x: number, y: number, z: number, vx = 0, vy = 0, vz = 0, pickupDelay = ITEM_PICKUP_DELAY, phase = 0): ItemEntity {
  return { id: allocateEntityId(), kind: 'item', stack, x, y, z, vx, vy, vz, onGround: false, inWater: false, age: 0, removed: false, pickupDelay, phase };
}

/** Owns every dropped item in the world and simulates them. */
export class ItemEntitySystem {
  readonly entities = new EntityStore<ItemEntity>();
  private mergeTimer = 0;
  /** Reused by `merge` (no per-pass array). */
  private readonly scratch: ItemEntity[] = [];

  constructor(private readonly rand: () => number = Math.random) {}

  get count(): number {
    return this.entities.size;
  }

  /**
   * Spawns a dropped stack. Without a velocity it pops out with a small random toss (block drops).
   * This is the item drop API (mob loot in Milestone 8 uses it too).
   */
  spawn(stack: ItemStack, x: number, y: number, z: number, velocity?: { x: number; y: number; z: number }, pickupDelay = ITEM_PICKUP_DELAY): ItemEntity {
    const r = this.rand;
    const v = velocity ?? { x: (r() - 0.5) * 2, y: 3 + r() * 1.5, z: (r() - 0.5) * 2 };
    return this.entities.add(createItemEntity({ ...stack }, x, y, z, v.x, v.y, v.z, pickupDelay, r() * Math.PI * 2));
  }

  clear(): void {
    this.entities.clear();
  }

  /**
   * One simulation step. Items in unloaded chunks (`isLoaded` false) are frozen. `collector` may be
   * undefined (dead / spectating) or a list (multiplayer: the nearest collector in range attracts
   * and picks up). Returns what was picked up this tick.
   */
  tick(dt: number, getBlock: BlockGetter, isLoaded: (x: number, z: number) => boolean, collectors: ItemCollector | readonly (ItemCollector | undefined)[] | undefined): PickupEvent[] {
    const events: PickupEvent[] = [];
    const list = collectors === undefined ? [] : Array.isArray(collectors) ? collectors : [collectors as ItemCollector];
    for (const e of this.entities) {
      if (e.removed || !isLoaded(e.x, e.z)) continue;
      e.age += dt;
      if (e.age >= ITEM_DESPAWN_SECONDS) {
        this.entities.remove(e);
        continue;
      }
      e.pickupDelay = Math.max(0, e.pickupDelay - dt);
      let attracted = false;
      let collector: ItemCollector | undefined;
      let ci = -1;
      let dx = 0, dy = 0, dz = 0, d = Infinity;
      if (e.pickupDelay === 0) {
        const iy = e.y + ITEM_SIZE / 2;
        for (let i = 0; i < list.length; i++) {
          const c = list[i];
          if (!c) continue;
          // Distance to the nearest point of the collector's vertical extent (feet to head).
          const cx = c.x - e.x;
          const cy = Math.max(c.y, Math.min(c.y + c.height, iy)) - iy;
          const cz = c.z - e.z;
          const cd = Math.hypot(cx, cy, cz);
          if (cd < d) { d = cd; dx = cx; dy = cy; dz = cz; collector = c; ci = i; }
        }
      }
      if (collector) {
        if (d < PICKUP_RADIUS) {
          const taken = collector.collect({ ...e.stack });
          if (taken > 0) {
            e.stack.count -= taken;
            events.push({ item: e.stack.item, count: taken, collector: ci });
            if (e.stack.count <= 0) {
              this.entities.remove(e);
              continue;
            }
          }
        }
        if (d < MAGNET_RADIUS && d > 1e-3) {
          // Pull toward the player; full speed close in, gentler at the edge.
          const s = MAGNET_SPEED * (1 - (d / MAGNET_RADIUS) * 0.5);
          e.vx = (dx / d) * s;
          e.vy = (dy / d) * s;
          e.vz = (dz / d) * s;
          attracted = true;
        }
      }
      // Attracted items fly straight in (gravity cancelled), still colliding with blocks.
      if (attracted && !e.inWater) e.vy += ITEM_BODY.gravity * dt;
      stepBody(e, ITEM_BODY, getBlock, dt);
    }
    this.mergeTimer += dt;
    if (this.mergeTimer >= MERGE_INTERVAL) {
      this.mergeTimer = 0;
      this.merge();
    }
    return events;
  }

  /** Merges identical stackable items that are close together (into the larger stack). */
  merge(): void {
    const list = this.entities.collect(this.scratch);
    for (let i = 0; i < list.length; i++) {
      const a = list[i]!;
      if (a.removed) continue;
      const max = getItemDef(a.stack.item).maxStack;
      if (max <= 1 || a.stack.count >= max) continue;
      for (let j = i + 1; j < list.length; j++) {
        const b = list[j]!;
        if (b.removed || !stacksMatch(a.stack, b.stack) || b.stack.count >= max) continue;
        if (Math.hypot(a.x - b.x, a.y - b.y, a.z - b.z) > MERGE_RADIUS) continue;
        const [big, small] = a.stack.count >= b.stack.count ? [a, b] : [b, a];
        const moved = Math.min(max - big.stack.count, small.stack.count);
        big.stack.count += moved;
        small.stack.count -= moved;
        big.age = Math.min(big.age, small.age);
        big.pickupDelay = Math.max(big.pickupDelay, small.pickupDelay);
        if (small.stack.count <= 0) this.entities.remove(small);
        if (a.removed || a.stack.count >= max) break;
      }
    }
  }

  toSaved(): SavedItemEntity[] {
    return [...this.entities].map((e) => ({ stack: stackToSaved(e.stack), x: e.x, y: e.y, z: e.z, age: e.age }));
  }

  restore(saved: readonly SavedItemEntity[] | undefined): void {
    if (!Array.isArray(saved)) return;
    for (const s of saved) {
      const stack = stackFromSaved(s?.stack);
      if (!stack || ![s.x, s.y, s.z].every(Number.isFinite)) continue;
      const e = this.spawn(stack, s.x, s.y, s.z, { x: 0, y: 0, z: 0 }, 0);
      e.age = Number.isFinite(s.age) ? s.age : 0;
    }
  }
}
