import './style.css';
import { DEFAULT_DAY_SECONDS, WorldTime, currentBlockPalette, randomSeed, seedFromText, type DemTile } from '@voxel/shared';
import { demTileList, ensureCurrentPackage, fetchDemTiles, fetchOsm, hasTerrain, prepareMapPackage } from '@voxel/mapgen';
import { loadMapcore } from '@voxel/mapgen/browser';
import { createGLContext } from './render/gl';
import { Renderer } from './render/renderer';
import { TitleBackground } from './render/titleBackground';
import { Game } from './game/game';
import { WORLD_FORMAT_VERSION, WorldStore, type GameMode, type GeneratorKind, type WorldMeta } from './storage/worldStore';
import { GAME_TITLE, Menus, type JoinServerInput, type MultiplayerDefaults } from './ui/menus';
import { NetClient, WebSocketConnection, friendlyDisconnectReason, normalizeServerUrl } from './net/netClient';
import { TouchModeDetector } from './input/controls';
import { AudioEngine } from './audio/audioEngine';
import { errorText, installGlobalErrorHandlers, toast } from './ui/toast';
import { registerServiceWorker } from './pwa';
import { mountVersionTag } from './ui/about';
import { browserDeviceInfo, browserStorage, defaultSettings, detectQuality, loadSettings, saveSettings, type Settings } from './settings/settings';

/*
 * URL parameters:
 *   ?seed=<int>   skip the menu and start a TEMPORARY world with that seed (dev; never saved)
 *   ?view=<n>     view distance in chunks for this page load (settings keep their own value)
 *   ?touch=1|0    force touch controls on / off for this page load (settings have the same override)
 *   ?quality=desktop|mobile|low  force the quality preset (worker counts, mob draw distance, defaults)
 *   ?day=<s>      length of a full day in seconds
 *   ?time=<hour>  start at this clock hour (overrides the saved time)
 *   ?mode=creative  with ?seed: the temporary world is creative (default survival)
 */

/** Reads an integer URL parameter, e.g. `?seed=123&view=10`. */
function intParam(params: URLSearchParams, name: string): number | undefined {
  const raw = params.get(name);
  if (raw === null || raw.trim() === '') return undefined;
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) ? n : undefined;
}

function showFatalError(message: string): void {
  const el = document.createElement('div');
  el.className = 'fatal-error';
  el.textContent = message;
  document.body.appendChild(el);
}

/** Last server address and player name (multiplayer menu). */
const MULTIPLAYER_KEY = 'blockwright.multiplayer';

/** How many recently joined server addresses the multiplayer screen offers. */
const MAX_RECENT_SERVERS = 5;

function loadMultiplayerDefaults(storage: ReturnType<typeof browserStorage>): MultiplayerDefaults {
  const fallback = { address: 'localhost:25580', name: `Player${Math.floor(Math.random() * 900 + 100)}`, recent: [] };
  try {
    const raw = storage?.getItem(MULTIPLAYER_KEY);
    if (!raw) return fallback;
    const v = JSON.parse(raw) as Partial<MultiplayerDefaults>;
    const recent = Array.isArray(v.recent) ? v.recent.filter((a): a is string => typeof a === 'string' && a.length > 0 && a.length < 200).slice(0, MAX_RECENT_SERVERS) : [];
    return {
      address: typeof v.address === 'string' && v.address.length < 200 ? v.address : fallback.address,
      name: typeof v.name === 'string' && /^[A-Za-z0-9_]{1,16}$/.test(v.name) ? v.name : fallback.name,
      recent,
    };
  } catch {
    return fallback;
  }
}

/** Remembers the address and name; `joined` also moves the address to the front of the recent list. */
function saveMultiplayerDefaults(storage: ReturnType<typeof browserStorage>, v: JoinServerInput, joined = false): void {
  try {
    const old = loadMultiplayerDefaults(storage);
    const recent = joined ? [v.address, ...old.recent.filter((a) => a !== v.address)].slice(0, MAX_RECENT_SERVERS) : old.recent;
    storage?.setItem(MULTIPLAYER_KEY, JSON.stringify({ address: v.address, name: v.name, recent }));
  } catch {
    // Storage blocked: nothing to remember.
  }
}

function newWorldId(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `w-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
  }
}

function newWorldMeta(name: string, seed: number, gameMode: GameMode, generator: GeneratorKind = 'terrain'): WorldMeta {
  const now = Date.now();
  return {
    id: newWorldId(),
    name,
    seed,
    generator,
    createdAt: now,
    lastPlayed: now,
    formatVersion: WORLD_FORMAT_VERSION,
    gameMode,
    palette: currentBlockPalette(),
    // New worlds start at 08:00 on day 0.
    timeTicks: new WorldTime(DEFAULT_DAY_SECONDS, 8).ticks,
  };
}

/** Full-screen "click to reload" notice after the GPU context was lost (driver reset, GPU switch...). */
function showContextLost(onClick: () => void): void {
  if (document.querySelector('.context-lost')) return;
  const el = document.createElement('div');
  el.className = 'context-lost';
  el.setAttribute('role', 'alertdialog');
  el.textContent = 'Graphics context lost: click to reload. (Your single-player world is saved first.)';
  el.addEventListener('click', onClick, { once: true });
  document.body.appendChild(el);
}

async function main(): Promise<void> {
  document.title = GAME_TITLE;
  installGlobalErrorHandlers();
  const canvas = document.getElementById('game');
  if (!(canvas instanceof HTMLCanvasElement)) throw new Error('#game canvas not found');
  // One GL context and renderer for the whole page; each Game frees its chunk meshes on exit.
  const gl = createGLContext(canvas);
  const renderer = new Renderer(gl, canvas);

  const params = new URLSearchParams(window.location.search);
  // Settings (localStorage) start from the device's quality preset; the touch detector needs to
  // exist first because a coarse pointer selects the mobile preset.
  const storage = browserStorage();
  const touchParam = params.get('touch');
  const touch = new TouchModeDetector('auto');
  const forcedQuality = params.get('quality');
  const quality = forcedQuality === 'desktop' || forcedQuality === 'mobile' || forcedQuality === 'low'
    ? detectQuality(forcedQuality === 'desktop' ? { coarsePointer: false, cores: 8, deviceMemory: 8 } : forcedQuality === 'mobile' ? { coarsePointer: true, cores: 8, deviceMemory: 8 } : { coarsePointer: true, cores: 2 })
    : detectQuality(browserDeviceInfo(touch.coarsePointer));
  let settings: Settings = loadSettings(storage, defaultSettings(quality));
  touch.setMode(touchParam === '1' ? 'on' : touchParam === '0' ? 'off' : settings.touchControls);
  renderer.maxDpr = settings.maxDpr;
  const viewParam = intParam(params, 'view');
  let viewDistance = Math.max(2, Math.min(32, viewParam ?? settings.viewDistance));
  const dayLength = intParam(params, 'day');
  const startHour = intParam(params, 'time');

  // Sound: the context starts on the first click / key press (browser autoplay rules).
  const audio = new AudioEngine();
  audio.installUnlock();
  const applyVolumes = (): void => audio.setVolumes({ master: settings.masterVolume, effects: settings.effectsVolume, ambient: settings.ambientVolume });
  applyVolumes();
  // UI click for every button, menu slot and select in the page.
  document.addEventListener('click', (e) => {
    const t = e.target instanceof Element ? e.target.closest('button, select, .slot, .hotbar-slot') : null;
    if (t) audio.play('click');
  }, { capture: true });

  const store = await WorldStore.open();
  let game: Game | undefined;
  // Slowly turning terrain behind the title menus; owns the renderer only while no game runs.
  const title = new TitleBackground(renderer, quality.name === 'desktop' ? 3 : 2);
  // Restoring every GPU resource after a context loss is not supported: save, then reload.
  canvas.addEventListener('webglcontextlost', (e) => {
    e.preventDefault();
    console.error('WebGL context lost');
    title.stop();
    showContextLost(() => {
      const g = game;
      game = undefined;
      const done = (): void => window.location.reload();
      if (g) g.saveAndQuit().then(done, done);
      else done();
    });
  });
  if (import.meta.env.DEV) Object.assign(window, { __title: title, __renderer: renderer, __audio: audio });
  const showBackdrop = (): void => {
    if (!game) title.start();
  };

  const pause = (): void => {
    if (!game || game.paused) return;
    game.setPaused(true);
    game.input.exitLock();
    if (game.mp) {
      const mp = game.mp;
      menus.showPause(game.meta.name, viewDistance, 'Multiplayer: the world keeps running while this menu is open. The server saves your progress.', true, () => mp.pingText());
      return;
    }
    const credit = game.meta.bbox ? ' Map data © OpenStreetMap contributors.' : '';
    const note = (game.temporary ? 'Temporary world: nothing is saved.' : store ? 'Progress also autosaves every 30 s.' : 'Saving is disabled.') + credit;
    menus.showPause(game.meta.name, viewDistance, note);
  };

  /**
   * A map world's MapPackage, rebuilt from its saved OSM data when it was made by another mapcore
   * format version (the gen workers then read the current one from IndexedDB).
   */
  const loadMapPackage = async (meta: WorldMeta): Promise<Uint8Array | undefined> => {
    if (meta.generator !== 'map' || meta.mapPackageId === undefined) return undefined;
    const rec = store && (await store.getMapPackage(meta.mapPackageId));
    if (!rec) throw new Error('This map world has lost its map data (map package missing).');
    const api = await loadMapcore();
    // An older package is rebuilt for this mapcore; one made before terrain gets its elevation tiles
    // downloaded now (stored with it from then on), or is rebuilt flat if that fails.
    const { stored, rebuilt, warning } = await ensureCurrentPackage(api, rec, { fetchDem: (tiles) => fetchDemTiles(tiles) });
    if (rebuilt) {
      console.info(`[map] rebuilt the map package of "${meta.name}" for mapcore format ${api.package_version()}${hasTerrain(stored) ? ' with terrain' : ' (flat)'}`);
      await store.putMapPackage(meta.mapPackageId, stored);
    }
    if (warning) toast(warning, 'warn', 10000);
    return stored.pkg;
  };

  const enter = async (meta: WorldMeta, temporary: boolean, freshPackage?: Uint8Array): Promise<void> => {
    const mapPackage = freshPackage ?? (await loadMapPackage(meta));
    if (game) await game.saveAndQuit();
    title.stop();
    game = await Game.create({
      canvas,
      renderer,
      store,
      meta,
      mapPackage,
      temporary,
      viewDistance,
      dayLength,
      startHour: temporary ? (startHour ?? 8) : startHour,
      onPauseRequest: pause,
      touch,
      quality,
      settings,
      audio,
    });
    menus.hide();
    game.start();
    // Called from the Play/Create click, so the browser allows pointer lock right away.
    void game.lockPointer();
  };

  /** Connects to a server and starts a multiplayer game (no local saving). */
  const join = async ({ address, name }: JoinServerInput): Promise<void> => {
    const url = normalizeServerUrl(address);
    saveMultiplayerDefaults(storage, { address, name });
    if (game) {
      const g = game;
      game = undefined;
      await g.saveAndQuit();
    }
    showBackdrop();
    menus.showStatus(`Connecting to ${url}...`);
    let conn: WebSocketConnection;
    let joined: Awaited<ReturnType<typeof NetClient.join>>;
    try {
      conn = await WebSocketConnection.open(url);
      joined = await NetClient.join(conn, name, viewDistance);
    } catch (err) {
      console.warn('Could not join', url, err);
      menus.showMultiplayer(friendlyDisconnectReason(err instanceof Error ? err.message : String(err), url));
      return;
    }
    const { client, welcome } = joined;
    saveMultiplayerDefaults(storage, { address, name }, true);
    const meta: WorldMeta = {
      id: `mp:${url}`,
      name: `${welcome.worldName} @ ${new URL(url).host}`,
      seed: welcome.seed,
      generator: welcome.generator,
      createdAt: Date.now(),
      lastPlayed: Date.now(),
      formatVersion: WORLD_FORMAT_VERSION,
      gameMode: welcome.gameMode,
      palette: currentBlockPalette(),
      timeTicks: welcome.timeTicks,
      player: { x: welcome.x, y: welcome.y, z: welcome.z, yaw: welcome.yaw, pitch: welcome.pitch, flying: welcome.flying },
    };
    title.stop();
    const g = await Game.create({
      canvas,
      renderer,
      store: undefined,
      meta,
      temporary: true,
      viewDistance,
      dayLength: welcome.dayTicks / welcome.tickRate,
      onPauseRequest: pause,
      touch,
      quality,
      settings,
      audio,
      net: {
        client,
        welcome,
        name,
        onDisconnect: (reason) => {
          if (game !== g) return;
          game = undefined;
          g.dispose();
          renderer.beginFrame();
          showBackdrop();
          menus.showDisconnected(friendlyDisconnectReason(reason, url), { address, name });
        },
      },
    });
    game = g;
    menus.hide();
    g.start();
    void g.lockPointer();
  };

  const menus: Menus = new Menus(
    {
      joinServer: join,
      multiplayerDefaults: () => loadMultiplayerDefaults(storage),
      listWorlds: async () => (store ? store.listWorlds() : []),
      play: async (meta) => {
        // Re-read so a stale list entry never overwrites newer saved state.
        const fresh = (store && (await store.getWorld(meta.id))) || meta;
        await enter(fresh, !store);
      },
      create: async ({ name, seedText, mode, generator }) => {
        const meta = newWorldMeta(name, seedFromText(seedText) ?? randomSeed(), mode, generator);
        if (store) await store.putWorld(meta);
        await enter(meta, !store);
      },
      createMap: async ({ name, mode, bbox, scale, signal, onProgress }) => {
        // A real place (phases E/F): download, prepare and store the MapPackage, then play.
        if (!store) throw new Error('Map worlds need saving (IndexedDB) to be available in this browser.');
        const meta = newWorldMeta(name, randomSeed(), mode, 'map');
        const t0 = performance.now();
        let host = '';
        const osm = await fetchOsm(bbox, {
          signal,
          onAttempt: (url) => {
            host = new URL(url).host;
            onProgress({ stage: 'download', host, bytes: 0 });
          },
          onProgress: (bytes) => onProgress({ stage: 'download', host, bytes }),
        });
        const t1 = performance.now();
        // Elevation (mapcore milestone 5): the Terrarium tiles mapcore asks for. Without them the
        // map is flat, which is still playable, so a failure only warns.
        const api = await loadMapcore();
        const tiles = demTileList(api, bbox, scale);
        onProgress({ stage: 'elevation', done: 0, total: tiles.length });
        let dem: DemTile[] | undefined;
        try {
          dem = await fetchDemTiles(tiles, { signal, onProgress: (done, total) => onProgress({ stage: 'elevation', done, total }) });
        } catch (err) {
          if (signal.aborted) throw err;
          toast(`Elevation data could not be downloaded (${errorText(err)}); this map will be flat.`, 'warn', 10000);
        }
        const t2 = performance.now();
        onProgress({ stage: 'prepare' });
        await new Promise((r) => setTimeout(r, 0)); // let the progress bar paint
        const stored = prepareMapPackage(api, osm, bbox, scale, dem);
        const t3 = performance.now();
        onProgress({ stage: 'save' });
        meta.mapPackageId = `map-${meta.id}`;
        meta.bbox = bbox;
        await store.putMapPackage(meta.mapPackageId, stored);
        await store.putWorld(meta);
        const timings = {
          downloadMs: Math.round(t1 - t0),
          elevationMs: Math.round(t2 - t1),
          tiles: dem?.length ?? 0,
          prepareMs: Math.round(t3 - t2),
          totalMs: Math.round(performance.now() - t0),
          osmKB: Math.round(osm.length / 1024),
          demKB: Math.round((dem ?? []).reduce((n, t) => n + t.png.length, 0) / 1024),
          packageKB: Math.round(stored.pkg.length / 1024),
        };
        console.info('[map] created', timings);
        if (import.meta.env.DEV) Object.assign(window, { __mapTimings: timings });
        onProgress({ stage: 'enter' });
        await enter(meta, false, stored.pkg);
      },
      rename: async (id, name) => {
        await store?.renameWorld(id, name);
      },
      remove: async (id) => {
        await store?.deleteWorld(id);
      },
      resume: () => {
        if (!game) return;
        menus.hide();
        game.setPaused(false);
        // If the lock is refused (Chrome's short cooldown after Esc), the "click to play" hint shows.
        void game.lockPointer();
      },
      saveAndQuit: async () => {
        const g = game;
        if (!g) return;
        menus.showStatus(g.mp ? 'Disconnecting...' : g.temporary || !store ? 'Leaving world...' : 'Saving world...');
        game = undefined;
        await g.saveAndQuit();
        renderer.beginFrame(); // clear the last frame behind the title screen
        showBackdrop();
        await menus.showTitle();
      },
      setViewDistance: (chunks) => {
        viewDistance = chunks;
        settings = { ...settings, viewDistance: chunks };
        saveSettings(storage, settings);
        game?.setViewDistance(chunks);
      },
      getSettings: () => ({ ...settings, viewDistance }),
      updateSettings: (patch) => {
        settings = { ...settings, ...patch };
        if (patch.viewDistance !== undefined) {
          viewDistance = patch.viewDistance;
          game?.setViewDistance(viewDistance);
        }
        if (patch.touchControls !== undefined && touchParam === null) touch.setMode(patch.touchControls);
        renderer.maxDpr = settings.maxDpr;
        applyVolumes();
        game?.applySettings(settings);
        return saveSettings(storage, settings);
      },
      qualityName: quality.name,
    },
    !!store,
  );

  const devSeed = intParam(params, 'seed');
  if (devSeed !== undefined) {
    // Dev shortcut: an unsaved world, straight into the game.
    const mode: GameMode = params.get('mode') === 'creative' ? 'creative' : 'survival';
    await enter(newWorldMeta(`Temporary (seed ${devSeed >>> 0})`, devSeed >>> 0, mode), true);
    document.getElementById('hint')?.classList.remove('hidden');
  } else {
    showBackdrop();
    await menus.showTitle();
  }
}

registerServiceWorker();
mountVersionTag();

main().catch((err: unknown) => {
  console.error(err);
  showFatalError(err instanceof Error ? err.message : String(err));
});
