/** Creative worlds without a saved inventory start with these in the hotbar (the old M4-M6 set). */
const CREATIVE_HOTBAR = ['stone', 'dirt', 'grass', 'sand', 'planks', 'log', 'glass', 'torch', 'lumen_block'];

/** Time speed-up while fast-forward (F6) is on: a 20 minute day passes in about 17 seconds. */
const FAST_FORWARD = 72;

/** Cardinal direction for a yaw (0 = facing -Z = north, positive yaw turns toward +X = east). */
function facingName(yaw: number): string {
  const names = ['north (-Z)', 'east (+X)', 'south (+Z)', 'west (-X)'];
  const quarter = Math.round(yaw / (Math.PI / 2));
  return names[((quarter % 4) + 4) % 4]!;
}

function ago(ms: number): string {
  if (ms === 0) return 'never';
  const s = Math.round((Date.now() - ms) / 1000);
  return s < 1 ? 'just now' : `${s}s ago`;
}

export interface GameOptions {
  canvas: HTMLCanvasElement;
  /** Shared across worlds (one GL context); the game frees its chunk meshes on dispose. */
  renderer: Renderer;
  /** Undefined: nothing is written (saving disabled or a temporary world). */
  store: WorldStore | undefined;
  meta: WorldMeta;
  /** A `?seed=` dev world that is never saved. */
  temporary: boolean;
  /** MapPackage bytes of a map world (`meta.mapPackageId`), already checked to be current. */
  mapPackage?: Uint8Array;
  viewDistance: number;
  /** Length of a full day in seconds (`?day=`). */
  dayLength?: number;
  /** Overrides the saved time of day (`?time=` hours). */
  startHour?: number;
  /** Pointer lock was lost (Esc) or Esc pressed while unlocked: show the pause menu. */
  onPauseRequest: () => void;
  /** Page-wide touch mode (shows the touch overlay; no pointer lock while active). */
  touch: TouchModeDetector;
  /** Device quality preset (worker counts, mob render distance, stitch budget). */
  quality: QualityPreset;
  /** Current settings (FOV, sensitivity, DPR cap); later changes go through `applySettings`. */
  settings: Settings;
  /** Page-wide sound engine (Milestone 11); undefined = silent (tests, no Web Audio). */
  audio?: AudioEngine;
  /**
   * Multiplayer (Milestone 10): play on a server instead of the in-process simulation. Nothing is
   * saved locally; the world keeps running while the pause menu is open.
   */
  net?: {
    client: NetClient;
    welcome: WelcomeMsg;
    name: string;
    /** The connection ended (kicked, server stopped, lost); the game should be torn down. */
    onDisconnect(reason: string): void;
  };
}

/**
 * One running world: owns the World, workers, session, input, HUD and save manager. Create with
 * `Game.create`, then `start()`. `saveAndQuit()` (or `dispose()` without saving) tears everything
 * down so another world can start without a page reload; only the shared Renderer survives.
 */
export class Game {
  readonly world = new World();
  readonly light: LightEngine;
  readonly time: WorldTime;
  readonly camera: Camera;
  readonly session: GameSession;
  readonly input: Input;
  /** Keyboard + mouse and touch, merged into one `PlayerIntent` per frame. */
  readonly controls: Controls;
  readonly touchControls: TouchControls;
  /** Newly added chunks waiting for main-thread light stitching (time-sliced). */
  readonly stitches: StitchQueue;
  /** Profiling: CPU ms per rendered frame, ms between frames, and ms per fixed tick. */
  readonly perf = { frameCpu: new TimingRing(240), frameInterval: new TimingRing(240), tick: new TimingRing(240) };
  readonly streamer: ChunkSource;
  /** Multiplayer state (undefined in single-player). */
  readonly mp: MultiplayerLink | undefined;
  readonly meshPool: MeshWorkerPool;
  readonly controller: PlayerController;
  readonly interaction: BlockInteraction;
  readonly hotbar: Hotbar;
  readonly hud: Hud;
  readonly screen: InventoryScreen;
  readonly debug: DebugOverlay;
  /**
   * Main-thread copy of the world's generator: spawn column and F3 lookups only (workers generate).
   * Undefined for a multiplayer map world (the client has no MapPackage; the server generates).
   */
  readonly generator: ChunkGenerator | undefined;
  /** Name labels of a map world (single-player; the client has no MapPackage in multiplayer). */
  readonly mapLabels: MapLabels | undefined;
  readonly loop: GameLoop;
  /** Turns game events into sounds (undefined without an AudioEngine). */
  readonly sound: SoundDirector | undefined;
  save!: SaveManager;
  paused = false;
  private disposed = false;
  private readonly abort = new AbortController();
  private readonly lookDir = vec3.create();
  private readonly rightDir = vec3.create();
  private wasLocked = false;
  /** Seconds since start, for item spin/bob. */
  private clock = 0;
  /** Mob type spawned by the debug key (F7 spawns, F8 cycles). */
  private debugMobIndex = 0;

  private constructor(private readonly opts: GameOptions) {
    const { meta, renderer, canvas } = opts;
    this.time = new WorldTime(Math.max(10, opts.dayLength ?? DEFAULT_DAY_SECONDS), 8);
    this.time.ticks = meta.timeTicks;
    if (opts.startHour !== undefined) this.time.hours = opts.startHour;
    const mpMap = !!opts.net && meta.generator === 'map';
    this.generator = mpMap ? undefined : createGenerator(meta, opts.mapPackage);
    const spawn = this.generator ? spawnColumn(this.generator) : { x: 0.5, z: 0.5 };
    // Street / park / building names of a real map world (phase F).
    if (this.generator instanceof MapGenerator) this.mapLabels = new MapLabels(this.generator.labels(), (x, y, z) => this.world.getBlock(x, y, z));
    this.light = new LightEngine(this.world);
    this.input = new Input(canvas);
    this.touchControls = new TouchControls({
      holdUsesSecondary: () => this.session.canEatHeld(),
      tapIsAttack: () => !!this.interaction.entityTarget,
      mouseOnLookArea: () => void this.input.requestLock(),
    });
    this.controls = new Controls(this.input, this.touchControls, () => opts.touch.active);
    this.stitches = new StitchQueue((cx, cz) => this.light.stitchChunk(cx, cz));

    // The camera waits above the spawn column (or the saved position) until its chunks load.
    const p = meta.player;
    this.camera = new Camera(p?.x ?? spawn.x, p ? p.y + PLAYER_EYE_HEIGHT : 100, p?.z ?? spawn.z);
    this.camera.yaw = p?.yaw ?? 0;
    this.camera.pitch = p?.pitch ?? -0.3;
    meta.gameMode = normalizeGameMode(meta.gameMode);
    const net = opts.net;
    const session = net
      ? new RemoteGameSession(this.world, this.light, meta.gameMode, net.client, net.welcome, net.name)
      : new GameSession(this.world, spawn.x, spawn.z, this.light, meta.gameMode);
    this.session = session;
    if (!net) {
      if (p) session.restore(p);
      else if (session.creative) session.player.flying = true;
      if (session.creative && !p?.inventory) CREATIVE_HOTBAR.forEach((name, i) => session.inventory.set(i, createStack(name, 64)));
      session.items.restore(meta.itemEntities);
      session.mobs.restore(meta.mobs);
    }

    const onUnload = (cx: number, cz: number, blocks: Uint16Array): void => {
      // Free GPU memory for every section, forget queued meshing, save it if it was edited.
      for (let sy = 0; sy < SECTION_COUNT; sy++) renderer.chunks.removeSection(sectionKey(cx, sy, cz));
      this.meshPool.forgetChunk(cx, cz);
      this.stitches.remove(cx, cz);
      if (!net) this.save.onChunkUnloaded(cx, cz, blocks);
    };
    const remoteChunks = net ? new RemoteChunkStreamer(this.world, (cx, cz, chunk) => onUnload(cx, cz, chunk.blocks), net.welcome.viewDistance, opts.quality.genWorkers ?? 2) : undefined;
    this.streamer =
      remoteChunks ??
      new ChunkStreamer(this.world, { generator: meta.generator, seed: meta.seed, mapPackageId: meta.mapPackageId }, (cx, cz, chunk) => onUnload(cx, cz, chunk.blocks), {
        viewDistance: opts.viewDistance,
        workerCount: opts.quality.genWorkers,
        saved: { has: (cx, cz) => this.save.has(cx, cz), load: (cx, cz) => this.save.load(cx, cz) },
      });
    // Each chunk arrives lit on its own (gen worker); light must flow across its borders before it
    // (or a neighbour) is meshed. Stitching is queued and time-sliced per frame (see frame()).
    // Neighbours whose light changes are marked dirty and re-mesh.
    this.streamer.onAdd = (chunk) => this.stitches.add(chunk.cx, chunk.cz);
    this.meshPool = new MeshWorkerPool(
      this.world,
      (key, mesh) => renderer.setSectionMesh(key, mesh),
      opts.quality.meshWorkers ?? defaultMeshWorkerCount(),
      (cx, cz) => this.streamer.canMesh(cx, cz) && this.stitches.isSettled(cx, cz),
    );
    renderer.setViewDistance(net ? Math.min(opts.viewDistance, net.welcome.viewDistance) : opts.viewDistance);

    this.controller = new PlayerController(session, this.camera, this.controls.intent);
    this.interaction = new BlockInteraction(session, this.controls.intent, { openWorkbench: (pos) => this.openScreen('workbench', pos) });
    this.hotbar = new Hotbar(session.inventory, document.body, (slot) => this.touchControls.selectHotbar(slot));
    if (p?.hotbar !== undefined) this.hotbar.select(p.hotbar);
    session.selectedSlot = this.hotbar.selected;
    this.hud = new Hud(() => this.respawn());
    this.screen = new InventoryScreen(session, {
      onClose: () => {
        this.controller.controlsEnabled = true;
        this.updateHint();
        void this.lockPointer();
      },
    });
    this.debug = new DebugOverlay();
    this.mp =
      net && remoteChunks && session instanceof RemoteGameSession
        ? new MultiplayerLink(net.client, session, remoteChunks, {
            camera: this.camera,
            controller: this.controller,
            interaction: this.interaction,
            time: this.time,
            onChatToggle: (open) => {
              this.touchControls.releaseAll();
              if (open) this.input.exitLock();
              else if (!this.paused && !this.screen.isOpen) void this.lockPointer();
              this.updateHint();
            },
            onDisconnect: (reason) => net.onDisconnect(reason),
          })
        : undefined;
    if (!net) session.onBlockChange((x, _y, z) => this.save.markEdited(x, z));
    this.sound = opts.audio ? new SoundDirector(opts.audio, session, this.world) : undefined;
    if (this.mp && this.sound) {
      const sound = this.sound;
      this.mp.remote.onItemRemoved = (x, y, z) => sound.itemRemoved(x, y, z);
    }
    session.onDamage((amount) => this.hud.flashDamage(amount));
    session.onDeath((cause) => {
      this.closeScreen(false);
      this.input.exitLock();
      this.touchControls.releaseAll();
      this.hud.showDeath(cause, session.deathAttacker);
      this.updateHint();
    });
    if (session.dead) this.hud.showDeath(session.deathCause);

    const signal = this.abort.signal;
    document.addEventListener('pointerlockchange', () => {
      const locked = this.input.isLocked;
      this.updateHint();
      // Losing the lock to a screen (inventory, death) is not a pause.
      if (this.wasLocked && !locked && !this.disposed && !this.screen.isOpen && !session.dead && !this.mp?.chatOpen) opts.onPauseRequest();
      this.wasLocked = locked;
    }, { signal });
    window.addEventListener('keydown', (e) => {
      // Multiplayer chat: T or Enter opens it (the chat input handles its own keys).
      if (this.mp && !this.disposed && !this.paused && !this.screen.isOpen && !this.mp.chatOpen && (e.code === 'KeyT' || e.code === 'Enter')) {
        if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
        e.preventDefault();
        this.mp.openChat();
        return;
      }
      if (e.code !== 'Escape' || this.disposed || this.paused) return;
      // Esc closes an open screen; while unlocked (lock refused or never taken) it opens the pause menu.
      if (this.screen.isOpen) {
        e.preventDefault();
        this.closeScreen(true);
      } else if (!session.dead && !this.input.isLocked) {
        opts.onPauseRequest();
      }
    }, { signal });
    // A hidden tab renders nothing: stop the loop (rAF would mostly stop anyway, but timers and
    // background frames still cost battery). SaveManager flushes on hide by itself; on touch
    // devices hiding also pauses, since there is no pointer lock loss to do it.
    document.addEventListener('visibilitychange', () => {
      if (this.disposed) return;
      if (document.visibilityState === 'hidden') {
        this.loop.stop();
        if (opts.touch.active && !this.paused && !session.dead) opts.onPauseRequest();
      } else {
        this.loop.start();
      }
    }, { signal });
    // Ctrl+W (sprint + forward on old muscle memory) closes the tab and cannot be blocked; while
    // actively playing, ask the browser to confirm leaving instead. Saving also runs on pagehide.
    window.addEventListener('beforeunload', (e) => {
      if (this.disposed || this.paused || !this.input.isLocked) return;
      e.preventDefault();
      e.returnValue = '';
    }, { signal });
    opts.touch.onChange(() => {
      this.touchControls.releaseAll();
      this.updateHint();
    });
    this.applySettings(opts.settings);

    let lastFrameStart = 0;
    this.loop = new GameLoop(TICK_RATE, {
      beginFrame: () => {
        const now = performance.now();
        if (lastFrameStart > 0) this.perf.frameInterval.push(now - lastFrameStart);
        lastFrameStart = now;
        // One intent per frame, read by the ticks below and by frame().
        this.controls.sample(now);
      },
      update: (dt) => {
        // Multiplayer never pauses the world: the menu / chat only take the controls away.
        if (this.paused && !this.mp) return;
        const t0 = performance.now();
        const enabled = this.controller.controlsEnabled;
        if (this.paused || this.mp?.chatOpen) this.controller.controlsEnabled = false;
        this.controller.tick(dt);
        this.controller.controlsEnabled = enabled;
        this.sound?.tick();
        const yaw = this.camera.yaw;
        const pickups = this.session.tick(dt, { daylight: daylightFactor(this.time.dayFraction), lookX: Math.sin(yaw), lookZ: -Math.cos(yaw) });
        if (pickups.length > 0) this.sound?.pickup();
        this.time.tick();
        this.perf.tick.push(performance.now() - t0);
      },
      render: (alpha, frameDt) => {
        const t0 = performance.now();
        this.frame(alpha, frameDt);
        this.perf.frameCpu.push(performance.now() - t0);
      },
    });
  }

  /** Applies FOV, look sensitivity and the DPR cap (view distance goes through setViewDistance). */
  applySettings(s: Settings): void {
    this.camera.fovY = (s.fov * Math.PI) / 180;
    this.controls.sensitivity = s.sensitivity;
    this.opts.renderer.maxDpr = s.maxDpr;
  }

  /** Builds a game for `meta` and loads its saved-chunk index. */
  static async create(opts: GameOptions): Promise<Game> {
    const game = new Game(opts);
    try {
      game.save = await SaveManager.open(opts.temporary ? undefined : opts.store, opts.meta.id, game.world, () => game.snapshotMeta());
    } catch (err) {
      game.dispose();
      throw err;
    }
    if (import.meta.env.DEV) Object.assign(window, { __voxel: game });
    return game;
  }

  get meta(): WorldMeta {
    return this.opts.meta;
  }

  get temporary(): boolean {
    return this.opts.temporary;
  }

  start(): void {
    this.loop.start();
    this.updateHint();
  }

  setPaused(paused: boolean): void {
    this.paused = paused;
    if (paused) this.touchControls.releaseAll();
    this.updateHint();
  }

  /** The "click to play" hint shows only when nothing else has the screen (never in touch mode). */
  private updateHint(): void {
    const hidden = this.input.isLocked || this.paused || this.screen.isOpen || this.session.dead || this.opts.touch.active || !!this.mp?.chatOpen;
    document.getElementById('hint')?.classList.toggle('hidden', hidden);
  }

  /** Opens the inventory (E) or workbench screen and releases the pointer. */
  openScreen(kind: ScreenKind, workbench?: { x: number; y: number; z: number }): void {
    if (this.session.dead || this.disposed) return;
    this.syncLook();
    this.screen.open(kind, workbench);
    this.touchControls.releaseAll();
    this.controller.controlsEnabled = false;
    this.input.exitLock();
    this.updateHint();
  }

  /** Closes the screen; `relock` re-requests pointer lock. */
  closeScreen(relock: boolean): void {
    if (!this.screen.isOpen) return;
    this.screen.close(relock);
    this.controller.controlsEnabled = true;
    this.updateHint();
  }

  /** Death screen "Respawn" button. */
  respawn(): void {
    this.session.respawnPlayer();
    this.controller.snapCamera();
    this.hud.hideDeath();
    this.updateHint();
    void this.lockPointer();
  }

  /** Requests pointer lock (call from a click handler). Touch mode plays without it. */
  lockPointer(): Promise<boolean> {
    if (this.opts.touch.active) return Promise.resolve(false);
    return this.input.requestLock();
  }

  setViewDistance(chunks: number): void {
    this.streamer.setViewDistance(chunks);
    this.opts.renderer.setViewDistance(chunks);
  }

  /** Current meta with the player (position, vitals, inventory), dropped items and time filled in. */
  snapshotMeta(): WorldMeta {
    const meta = this.opts.meta;
    const session = this.session;
    const p = session.player;
    meta.lastPlayed = Date.now();
    meta.timeTicks = this.time.ticks;
    meta.formatVersion = WORLD_FORMAT_VERSION;
    meta.gameMode = session.gameMode;
    meta.palette = currentBlockPalette();
    if (session.spawned) {
      const s = session.spawnPoint!;
      meta.player = {
        x: p.x,
        y: p.y,
        z: p.z,
        yaw: this.camera.yaw,
        pitch: this.camera.pitch,
        flying: p.flying,
        spawn: { x: s.x, y: s.y, z: s.z },
        hotbar: this.hotbar.selected,
        ...vitalsToSaved(session.vitals),
        // An open crafting grid and the cursor stack are folded in, so an autosave loses nothing.
        inventory: session.inventory.toSaved(session.craftGrid),
      };
      meta.itemEntities = session.items.toSaved();
      meta.mobs = session.mobs.toSaved();
    }
    return { ...meta, palette: [...meta.palette], player: meta.player ? { ...meta.player } : undefined };
  }

  /** Saves everything (best effort) and tears the world down. */
  async saveAndQuit(): Promise<void> {
    if (this.disposed) return;
    this.loop.stop();
    this.closeScreen(false);
    // Multiplayer: the server keeps the world (and our player); just leave.
    this.mp?.leave();
    try {
      await this.save.flush();
    } catch (err) {
      console.warn('Final save failed', err);
    }
    this.dispose();
  }

  /** Stops the loop and frees workers, GPU buffers, DOM and listeners. Does not save. */
  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.loop.stop();
    this.abort.abort();
    this.save?.dispose();
    this.sound?.dispose();
    this.mp?.dispose();
    this.mapLabels?.dispose();
    this.generator?.dispose?.();
    vec3.set(this.camera.offset, 0, 0, 0);
    this.streamer.dispose();
    this.meshPool.dispose();
    this.input.exitLock();
    this.input.dispose();
    this.touchControls.dispose();
    this.stitches.clear();
    this.hotbar.dispose();
    this.hud.dispose();
    this.screen.dispose();
    this.session.items.clear();
    this.session.mobs.clear();
    this.debug.dispose();
    this.opts.renderer.chunks.clear();
    this.opts.renderer.setUnderwater(false);
    document.body.classList.remove('underwater');
    for (const chunk of [...this.world]) this.world.removeChunk(chunk.cx, chunk.cz);
    if (import.meta.env.DEV && (window as { __voxel?: unknown }).__voxel === this) delete (window as { __voxel?: unknown }).__voxel;
  }

  /** Copies the camera look into the session (thrown items fly where the camera looks). */
  private syncLook(): void {
    this.session.yaw = this.camera.yaw;
    this.session.pitch = this.camera.pitch;
  }

  private frame(alpha: number, frameDt: number): void {
    const { input, controller, time, hotbar, camera, streamer, meshPool, interaction, debug, session, screen } = this;
    const intent = this.controls.intent;
    const renderer = this.opts.renderer;
    const touch = this.opts.touch.active;
    if (!this.paused) {
      this.clock += frameDt;
      // Debug keys stay on the raw keyboard (not gameplay intents).
      if (input.wasPressed('F3')) debug.toggle();
      // Time and debug spawning belong to the server in multiplayer.
      if (input.wasPressed('F6') && !this.mp) time.speed = time.speed === 1 ? FAST_FORWARD : 1;
      if (input.wasPressed('F8')) this.debugMobIndex = (this.debugMobIndex + 1) % MOB_TYPES.length;
      if (input.wasPressed('F7') && !this.mp) this.debugSpawnMob();
      if (screen.isOpen) {
        if (intent.openInventory) this.closeScreen(true);
      } else if (!session.dead) {
        if (intent.hotbarSlot >= 0) hotbar.select(intent.hotbarSlot);
        hotbar.scroll(intent.hotbarScroll);
        session.selectedSlot = hotbar.selected;
        if (intent.openInventory) this.openScreen('inventory');
        if (intent.drop) session.dropHeld(intent.dropStack, camera.forward(this.lookDir));
        if (intent.pause) this.opts.onPauseRequest();
      }
      controller.frame();
      session.selectedSlot = hotbar.selected;
      this.syncLook();
    }

    // Camera in water (last frame's eye is close enough): blue fog, no sky, a tint overlay.
    const ce = camera.renderPosition;
    const underwater = session.spawned && this.world.getBlock(Math.floor(ce[0]!), Math.floor(ce[1]!), Math.floor(ce[2]!)) === BlockId.Water;
    if (underwater !== renderer.isUnderwater) document.body.classList.toggle('underwater', underwater);
    renderer.setUnderwater(underwater);
    // Day/night only changes uniforms (sky, fog colour, sky-light multiplier): no re-meshing.
    renderer.setTimeOfDay(time.dayFraction);
    const aspect = renderer.beginFrame();
    camera.updateMatrices(aspect, alpha);
    renderer.drawSky(camera.forward(this.lookDir), camera.flatRight(this.rightDir), camera.fovY, aspect);
    const eye = camera.renderPosition;
    // Stream around the player's feet (same x/z as the eye).
    streamer.update(eye[0]!, eye[2]!);
    if (this.stitches.length > 0) this.stitches.process(this.opts.quality.stitchBudgetMs);
    meshPool.update(eye[0]!, eye[1]!, eye[2]!);

    // Target from the interpolated eye so the outline matches what is on screen. Touch mode acts
    // without pointer lock (aiming at the crosshair, i.e. the screen centre).
    const acting = (input.isLocked || touch) && !this.paused && !screen.isOpen && !this.mp?.chatOpen;
    interaction.update(frameDt, eye, camera.forward(this.lookDir), acting);
    this.mp?.frame(frameDt);
    this.sound?.frame(frameDt, eye, this.rightDir[0]!, this.rightDir[2]!, interaction, acting);

    renderer.drawWorld(camera.viewProj, eye);
    this.queueItemEntities(alpha);
    queueMobs(renderer.entities, session.mobs, alpha, this.world, renderer.sky, this.clock, eye[0]!, eye[2]!, this.opts.quality.mobRenderDistance, this.mp?.avatars);
    renderer.drawEntities(camera.viewProj, eye);
    const t = interaction.target;
    const b = interaction.breaking;
    // Shaped blocks (slabs, stairs, posts, rails) get an outline around just their boxes.
    const getBlock = this.world.getBlock.bind(this.world);
    if (b && !this.paused) renderer.drawBreakProgress(camera.viewProj, eye, b.x, b.y, b.z, interaction.breakProgress, blockBounds(getBlock, b.x, b.y, b.z, this.world.getBlock(b.x, b.y, b.z)));
    if (t && !this.paused) renderer.drawBlockOutline(camera.viewProj, eye, t.x, t.y, t.z, blockBounds(getBlock, t.x, t.y, t.z, t.blockId));

    hotbar.update();
    if (touch) {
      const food = interaction.eatSeconds > 0 && session.heldStack ? getItemDef(session.heldStack.item).food : undefined;
      const progress = interaction.breaking ? interaction.breakProgress : food ? interaction.eatSeconds / food.eatSeconds : 0;
      this.touchControls.update(session.creative, session.player.flying, this.paused ? 0 : progress);
    }
    screen.update();
    this.hud.update(session.vitals, !session.creative, this.paused ? 0 : frameDt);
    debug.tickFrame();
    if (debug.isVisible) {
      this.updateDebug();
      debug.drawGraph(this.perf.frameCpu, this.perf.frameInterval);
    }
    this.mp?.drawOverlays(camera.viewProj, eye, this.opts.canvas.clientWidth, this.opts.canvas.clientHeight);
    this.mapLabels?.update(camera.viewProj, eye, this.opts.canvas.clientWidth, this.opts.canvas.clientHeight);
    input.endFrame();
  }

  /**
   * Debug (F7): spawns the selected mob type (F8 cycles) on the ground about 3 blocks in front of
   * the player. Also callable from page JS as `__voxel.debugSpawnMob('sheep')` in dev builds.
   */
  debugSpawnMob(typeName?: string): boolean {
    const session = this.session;
    if (!session.spawned) return false;
    const type = typeName ? MOB_TYPES.find((t) => t.name === typeName) : MOB_TYPES[this.debugMobIndex];
    if (!type) return false;
    const p = session.player;
    const yaw = this.camera.yaw;
    const x = Math.floor(p.x + Math.sin(yaw) * 3);
    const z = Math.floor(p.z - Math.cos(yaw) * 3);
    const clearance = Math.ceil(type.height);
    const base = Math.floor(p.y);
    for (let d = 0; d <= 8; d++) {
      for (const y of d === 0 ? [base] : [base + d, base - d]) {
        if (isStandable(session.getBlock, x, y, z, clearance)) {
          session.mobs.spawn(type, x + 0.5, y, z + 0.5, yaw + Math.PI);
          return true;
        }
      }
    }
    return false;
  }

  /** Queues every dropped item as a spinning, bobbing cube (blocks) or sprite (other items). */
  private queueItemEntities(alpha: number): void {
    const renderer = this.opts.renderer;
    const ents = renderer.entities;
    ents.begin();
    const layerOf = itemIconAtlas().layerOf;
    const lighting = renderer.sky;
    const t = this.clock;
    for (const e of this.session.items.entities) {
      // Extrapolate from the last tick so moving items do not stutter at 20 Hz.
      const k = e.onGround ? 0 : alpha * TICK_SECONDS;
      const x = e.x + e.vx * k;
      const y = e.y + e.vy * k;
      const z = e.z + e.vz * k;
      const bx = Math.floor(x), by = Math.floor(y + 0.1), bz = Math.floor(z);
      const light = entityLight(this.world.getSkyLight(bx, by, bz), this.world.getBlockLight(bx, by, bz), lighting);
      const rot = e.phase + t * 1.6;
      const bob = 0.06 + Math.sin(e.phase + t * 2.4) * 0.06;
      const def = getItemDef(e.stack.item);
      const copies = e.stack.count >= 16 ? 3 : e.stack.count > 1 ? 2 : 1;
      for (let c = 0; c < copies; c++) {
        const ox = c * 0.07, oy = c * 0.05, oz = c * -0.06;
        if (def.block !== undefined) {
          const bd = getBlockDef(def.block);
          if (bd.shape === BlockShape.Cross) ents.addSprite('blocks', x + ox, y + bob + oy, z + oz, 0.45, 0.45, rot, bd.textures.side, light);
          else ents.addBox('blocks', x + ox, y + bob + oy, z + oz, ITEM_SIZE, ITEM_SIZE, ITEM_SIZE, rot, bd.textures, light);
        } else {
          ents.addSprite('items', x + ox, y + bob + oy, z + oz, 0.45, 0.45, rot, layerOf[def.id] ?? 0, light);
        }
      }
    }
  }

  private mobDebugLines(): string[] {
    const { session, interaction } = this;
    const mobs = session.mobs;
    const ms = mobs.stats;
    const counts = mobs.countsByType();
    const byType = MOB_TYPES.map((t) => `${t.name} ${counts[t.name] ?? 0}`).join(', ');
    const et = interaction.entityTarget;
    const m = et?.mob;
    return [
      `Mobs: ${mobs.count} (${byType})  projectiles ${mobs.projectiles.length}  killed ${ms.killed}, despawned ${ms.despawned}`,
      `Mob tick: ${ms.avgTickMs.toFixed(3)} ms avg / ${ms.lastTickMs.toFixed(3)} last  paths: ${ms.pathSearches} searches, last ${ms.lastPathNodes} nodes in ${ms.lastPathMs.toFixed(3)} ms`,
      m
        ? `Entity target: ${m.type.label} #${m.id} hp ${m.health.hp.toFixed(1)}/${m.health.max}  ${m.ai.state}${m.ai.path ? ` (path ${m.ai.pathIndex}/${m.ai.path.length})` : ''}${m.health.burning ? ' burning' : ''}  ${et!.distance.toFixed(2)} away`
        : 'Entity target: none',
      `Attack: charge ${(session.attackCharge * 100).toFixed(0)}%, ${session.stats.attacks} hits, ${session.stats.mobKills} kills  Debug spawn: F7 ${MOB_TYPES[this.debugMobIndex]!.label} (F8 cycles)`,
    ];
  }

  private updateDebug(): void {
    const { session, camera, interaction, world, light, time, streamer, meshPool, hotbar, debug, generator, controller } = this;
    const renderer = this.opts.renderer;
    const canvas = this.opts.canvas;
    const p = session.player;
    const v = session.vitals;
    const eye = camera.renderPosition;
    const stats = renderer.chunks.stats;
    const bx = Math.floor(p.x);
    const bz = Math.floor(p.z);
    const ccx = Math.floor(bx / CHUNK_SIZE);
    const ccz = Math.floor(bz / CHUNK_SIZE);
    const t = interaction.target;
    const mode = p.flying ? 'fly (noclip)' : 'walk';
    const fy = Math.floor(p.y);
    const lightAt = (x: number, y: number, z: number): string => `sky ${world.getSkyLight(x, y, z)} block ${world.getBlockLight(x, y, z)}`;
    const ls = light.stats;
    const ss = this.save.stats;
    const saveState = this.opts.temporary ? 'temporary (not saved)' : this.save.enabled ? 'on' : 'DISABLED';
    const fc = this.perf.frameCpu.summary();
    const fi = this.perf.frameInterval.summary();
    const tk = this.perf.tick.summary();
    const q = this.opts.quality;
    debug.setLines([
      ...(this.mp ? [this.mp.debugLine()] : []),
      `FPS: ${debug.fps.toFixed(0)}  frame interval p50 ${fi.p50.toFixed(1)} / p95 ${fi.p95.toFixed(1)} / p99 ${fi.p99.toFixed(1)} ms`,
      `Frame CPU: avg ${fc.avg.toFixed(2)}  p50 ${fc.p50.toFixed(2)}  p95 ${fc.p95.toFixed(2)}  p99 ${fc.p99.toFixed(2)}  max ${fc.max.toFixed(1)} ms   Tick: avg ${tk.avg.toFixed(2)}  p95 ${tk.p95.toFixed(2)} ms`,
      `Quality: ${q.name}  DPR cap ${renderer.maxDpr}  mob draw ${q.mobRenderDistance} blocks  entities ${renderer.entities.instances} boxes  input ${this.opts.touch.active ? 'touch' : 'keyboard/mouse'}`,
      `World: ${this.meta.name} (${this.meta.gameMode})  ${this.meta.generator !== 'map' ? `Seed: ${this.meta.seed}` : this.meta.bbox ? `Map: ${this.meta.bbox.map((v) => v.toFixed(4)).join(', ')} (mapcore)  © OpenStreetMap contributors` : this.mp ? 'Map (server)' : 'Map: test area (stub generator)'}`,
      `Saving: ${saveState}  modified chunks ${ss.modifiedChunks}, pending saves ${ss.unsavedChunks}${ss.writing ? ` (writing ${ss.writing})` : ''}, last save ${ago(ss.lastSaveTime)}${ss.lastSaveTime ? ` (${ss.lastSaveMs.toFixed(0)} ms)` : ''}${ss.failures ? `, ${ss.failures} failed: ${ss.lastError}` : ''}`,
      `Feet: ${p.x.toFixed(2)} / ${p.y.toFixed(2)} / ${p.z.toFixed(2)}`,
      `Eye: ${eye[0]!.toFixed(2)} / ${eye[1]!.toFixed(2)} / ${eye[2]!.toFixed(2)}`,
      `Velocity: ${p.vx.toFixed(2)} / ${p.vy.toFixed(2)} / ${p.vz.toFixed(2)} (${Math.hypot(p.vx, p.vz).toFixed(2)} b/s horizontal)`,
      `Mode: ${mode}  onGround: ${p.onGround}  inWater: ${p.inWater}${controller.waitingForChunks ? '  (waiting for chunks)' : ''}`,
      `Facing: ${facingName(camera.yaw)}  yaw/pitch ${((camera.yaw * 180) / Math.PI).toFixed(1)} / ${((camera.pitch * 180) / Math.PI).toFixed(1)}`,
      t
        ? `Target: ${getBlockDef(t.blockId).name} @ ${t.x} ${t.y} ${t.z} (face ${['+X', '-X', '+Y', '-Y', '+Z', '-Z'][t.face] ?? 'inside'}, ${t.distance.toFixed(2)} away)`
        : 'Target: none',
      `Time: ${time.clock} day ${time.day}${time.speed !== 1 ? ` (x${time.speed}, F6)` : ''}  daylight ${renderer.sky.daylight.toFixed(2)}`,
      `Light feet: ${lightAt(bx, fy, bz)}${t ? `  target: ${lightAt(t.x, t.y, t.z)}, face side: ${lightAt(t.placeX, t.placeY, t.placeZ)}` : ''}`,
      `Lighting: chunk pass ${streamer.avgLightMs.toFixed(2)} ms avg (worker), stitch ${ls.avgStitchMs.toFixed(2)} ms avg / ${ls.lastStitchMs.toFixed(2)} last (queue ${this.stitches.length}, last frame ${this.stitches.lastCount} in ${this.stitches.lastMs.toFixed(2)} ms), edit ${ls.lastEditMs.toFixed(2)} ms (${ls.lastChangedCells} cells)`,
      `Held: slot ${hotbar.selected + 1} ${Inventory.describe(session.heldStack)}  edits ${session.stats.edits}, rejected ${session.stats.rejected}${session.stats.lastRejection ? ` (last: ${session.stats.lastRejection})` : ''}`,
      `Break: ${interaction.breaking ? `${(interaction.breakProgress * 100).toFixed(0)}% of ${t ? session.breakSeconds(t).toFixed(2) : '?'} s` : 'idle'}${interaction.eatSeconds > 0 ? `  eating ${interaction.eatSeconds.toFixed(1)} s` : ''}`,
      `Vitals: ${session.creative ? 'creative (no damage)' : `health ${v.health.toFixed(0)}/20  hunger ${v.hunger}/20  saturation ${v.saturation.toFixed(1)}  exhaustion ${v.exhaustion.toFixed(2)}  air ${v.air.toFixed(1)} s  fall ${v.fallDistance.toFixed(1)}`}${session.dead ? '  DEAD' : ''}`,
      `Items: ${session.items.count} entities, ${session.stats.pickups} pickups, ${session.stats.toolsBroken} tools broken`,
      ...this.mobDebugLines(),
      `Chunk: ${ccx} ${ccz} (in chunk ${bx - ccx * CHUNK_SIZE} ${bz - ccz * CHUNK_SIZE})`,
      generator ? `${generator.biomeAt ? `Biome: ${generator.biomeAt(bx, bz)} ` : ''}(surface y ${generator.surfaceHeight(bx, bz)})` : 'Biome: n/a (server map)',
      `Canvas: ${canvas.width}x${canvas.height} @ ${window.devicePixelRatio.toFixed(2)}x`,
      `Chunks loaded: ${world.chunkCount} (view ${streamer.viewDistance}, ${streamer.unloaded} unloaded, ${streamer.loadedFromSave} from save)`,
      `Gen queue: ${streamer.queueLength} (${streamer.inFlight} in flight, ${streamer.workerCount} workers, ${streamer.avgGenMs.toFixed(2)} ms avg, ${streamer.staleDropped} stale dropped)`,
      `Sections visible: ${stats.visibleSections} / ${stats.sections} meshed`,
      `Mesh queue: ${meshPool.queueLength} (${meshPool.workerCount} workers, ${meshPool.avgMeshMs.toFixed(2)} ms avg, ${meshPool.staleDropped} stale dropped)`,
      `Triangles: ${stats.triangles.toLocaleString()}`,
    ]);
  }
}
