/**
 * Turns the "seed" text from the create-world form into a 32-bit unsigned seed.
 * - Empty or whitespace: undefined (the caller picks a random seed).
 * - An integer (e.g. "12345", "-7"): that number, as uint32.
 * - Any other text: a stable 32-bit FNV-1a hash of the trimmed text.
 */
export function seedFromText(text: string): number | undefined {
  const t = text.trim();
  if (t === '') return undefined;
  if (/^-?\d{1,15}$/.test(t)) return Number.parseInt(t, 10) >>> 0;
  let h = 0x811c9dc5;
  for (let i = 0; i < t.length; i++) {
    h ^= t.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** A random uint32 seed (not cryptographic). */
export function randomSeed(): number {
  return Math.floor(Math.random() * 0x100000000) >>> 0;
}
