import { BlockId } from '../world/blocks';
import { BLOCK_HAS_MODEL, pickBoxes } from '../world/models';
import { Face } from '../mesh/vertexFormat';
import type { BlockGetter } from './player';

/** Default reach for block interaction, in blocks. */
export const REACH_DISTANCE = 5;

export interface RaycastHit {
  /** The block that was hit. */
  x: number;
  y: number;
  z: number;
  blockId: number;
  /** Outward normal of the face that was hit (one component is +-1). All zero if the ray started inside the block. */
  nx: number;
  ny: number;
  nz: number;
  /** The face that was hit, or -1 if the ray started inside the block. */
  face: number;
  /** The cell next to the hit face, where a placed block would go. */
  placeX: number;
  placeY: number;
  placeZ: number;
  /** Distance along the (normalised) ray to the hit face. */
  distance: number;
  /** The point that was hit (on the face, or the ray start if it started inside). */
  px: number;
  py: number;
  pz: number;
}

/** Blocks the ray stops at: everything except air and water. */
export function isTargetable(id: number): boolean {
  return id !== BlockId.Air && id !== BlockId.Water;
}

function faceOf(nx: number, ny: number, nz: number): number {
  if (nx > 0) return Face.PosX;
  if (nx < 0) return Face.NegX;
  if (ny > 0) return Face.PosY;
  if (ny < 0) return Face.NegY;
  if (nz > 0) return Face.PosZ;
  if (nz < 0) return Face.NegZ;
  return -1;
}

/**
 * Nearest hit of a ray with the pick boxes of shaped block `id` in cell (x, y, z), at or after
 * `tMin` and within `tMax`: [t, nx, ny, nz] (normal all zero if the ray starts inside a box).
 */
function rayBoxes(
  getBlock: BlockGetter,
  id: number,
  x: number,
  y: number,
  z: number,
  ox: number,
  oy: number,
  oz: number,
  dx: number,
  dy: number,
  dz: number,
  tMin: number,
  tMax: number,
): [number, number, number, number] | null {
  let best: [number, number, number, number] | null = null;
  const o = [ox, oy, oz];
  const dir = [dx, dy, dz];
  for (const b of pickBoxes(getBlock, x, y, z, id)) {
    const lo = [x + b[0] / 16, y + b[1] / 16, z + b[2] / 16];
    const hi = [x + b[3] / 16, y + b[4] / 16, z + b[5] / 16];
    let tNear = -Infinity;
    let tFar = Infinity;
    let axis = -1;
    let sign = 0;
    let miss = false;
    for (let a = 0; a < 3; a++) {
      const d = dir[a]!;
      if (d === 0) {
        if (o[a]! < lo[a]! || o[a]! > hi[a]!) miss = true;
        continue;
      }
      let t1 = (lo[a]! - o[a]!) / d;
      let t2 = (hi[a]! - o[a]!) / d;
      let s = -1; // entering through the min face: normal points to -a
      if (t1 > t2) {
        [t1, t2] = [t2, t1];
        s = 1;
      }
      if (t1 > tNear) {
        tNear = t1;
        axis = a;
        sign = s;
      }
      tFar = Math.min(tFar, t2);
    }
    if (miss || tNear > tFar || tFar < 0) continue;
    const inside = tNear < 0;
    const t = inside ? 0 : tNear;
    if (t < tMin - 1e-9 || t > tMax) continue;
    if (!best || t < best[0]) {
      best = [t, inside || axis !== 0 ? 0 : sign, inside || axis !== 1 ? 0 : sign, inside || axis !== 2 ? 0 : sign];
    }
  }
  return best;
}

/**
 * Amanatides & Woo voxel traversal from (ox, oy, oz) along (dx, dy, dz) (need not be normalised).
 * Returns the first cell within `maxDist` whose block passes `stopAt`, or null.
 */
export function raycastBlocks(
  getBlock: BlockGetter,
  ox: number,
  oy: number,
  oz: number,
  dx: number,
  dy: number,
  dz: number,
  maxDist = REACH_DISTANCE,
  stopAt: (id: number) => boolean = isTargetable,
): RaycastHit | null {
  const len = Math.hypot(dx, dy, dz);
  if (len === 0) return null;
  dx /= len;
  dy /= len;
  dz /= len;

  let x = Math.floor(ox);
  let y = Math.floor(oy);
  let z = Math.floor(oz);
  const stepX = dx > 0 ? 1 : dx < 0 ? -1 : 0;
  const stepY = dy > 0 ? 1 : dy < 0 ? -1 : 0;
  const stepZ = dz > 0 ? 1 : dz < 0 ? -1 : 0;
  // Ray distance to cross one whole cell on each axis.
  const tDeltaX = stepX !== 0 ? Math.abs(1 / dx) : Infinity;
  const tDeltaY = stepY !== 0 ? Math.abs(1 / dy) : Infinity;
  const tDeltaZ = stepZ !== 0 ? Math.abs(1 / dz) : Infinity;
  // Ray distance to the first cell boundary on each axis.
  let tMaxX = stepX > 0 ? (x + 1 - ox) * tDeltaX : stepX < 0 ? (ox - x) * tDeltaX : Infinity;
  let tMaxY = stepY > 0 ? (y + 1 - oy) * tDeltaY : stepY < 0 ? (oy - y) * tDeltaY : Infinity;
  let tMaxZ = stepZ > 0 ? (z + 1 - oz) * tDeltaZ : stepZ < 0 ? (oz - z) * tDeltaZ : Infinity;

  let nx = 0, ny = 0, nz = 0;
  let t = 0;
  for (;;) {
    const id = getBlock(x, y, z);
    if (stopAt(id)) {
      if (!BLOCK_HAS_MODEL[id]) {
        return { x, y, z, blockId: id, nx, ny, nz, face: faceOf(nx, ny, nz), placeX: x + nx, placeY: y + ny, placeZ: z + nz, distance: t, px: ox + dx * t, py: oy + dy * t, pz: oz + dz * t };
      }
      // Shaped block (slab, stairs, post, rail): the ray must hit one of its boxes.
      const hit = rayBoxes(getBlock, id, x, y, z, ox, oy, oz, dx, dy, dz, t, maxDist);
      if (hit) {
        const [bt, bnx, bny, bnz] = hit;
        return { x, y, z, blockId: id, nx: bnx, ny: bny, nz: bnz, face: faceOf(bnx, bny, bnz), placeX: x + bnx, placeY: y + bny, placeZ: z + bnz, distance: bt, px: ox + dx * bt, py: oy + dy * bt, pz: oz + dz * bt };
      }
    }
    // Step into the next cell across the nearest boundary.
    if (tMaxX < tMaxY && tMaxX < tMaxZ) {
      t = tMaxX;
      x += stepX;
      tMaxX += tDeltaX;
      nx = -stepX; ny = 0; nz = 0;
    } else if (tMaxY < tMaxZ) {
      t = tMaxY;
      y += stepY;
      tMaxY += tDeltaY;
      nx = 0; ny = -stepY; nz = 0;
    } else {
      t = tMaxZ;
      z += stepZ;
      tMaxZ += tDeltaZ;
      nx = 0; ny = 0; nz = -stepZ;
    }
    if (t > maxDist) return null;
  }
}
