import { mat4, vec3, type Mat4, type Vec3 } from '@voxel/shared';

const MAX_PITCH = (89 * Math.PI) / 180;
const UP = vec3.create(0, 1, 0);

/**
 * First-person perspective camera. yaw = 0 looks toward -Z; positive yaw turns right.
 * Position is interpolated between ticks via `prevPosition`/`position`.
 */
export class Camera {
  readonly position: Vec3;
  readonly prevPosition: Vec3;
  /** Interpolated eye position used for the current frame. */
  readonly renderPosition = vec3.create();
  /** Added to the rendered eye (multiplayer: smoothing of small reconciliation corrections). */
  readonly offset = vec3.create();
  yaw = 0;
  pitch = 0;
  fovY = (70 * Math.PI) / 180;
  near = 0.05;
  far = 1000;

  readonly view: Mat4 = mat4.create();
  readonly projection: Mat4 = mat4.create();
  readonly viewProj: Mat4 = mat4.create();
  private readonly forwardTmp = vec3.create();
  private readonly targetTmp = vec3.create();

  constructor(x: number, y: number, z: number) {
    this.position = vec3.create(x, y, z);
    this.prevPosition = vec3.create(x, y, z);
  }

  addLook(dYaw: number, dPitch: number): void {
    this.yaw = (this.yaw + dYaw) % (Math.PI * 2);
    this.pitch = Math.max(-MAX_PITCH, Math.min(MAX_PITCH, this.pitch + dPitch));
  }

  /** Full 3D look direction. */
  forward(out: Vec3): Vec3 {
    const cp = Math.cos(this.pitch);
    return vec3.set(out, Math.sin(this.yaw) * cp, Math.sin(this.pitch), -Math.cos(this.yaw) * cp);
  }

  /** Horizontal forward (ignores pitch), unit length. */
  flatForward(out: Vec3): Vec3 {
    return vec3.set(out, Math.sin(this.yaw), 0, -Math.cos(this.yaw));
  }

  /** Horizontal right vector, unit length. */
  flatRight(out: Vec3): Vec3 {
    return vec3.set(out, Math.cos(this.yaw), 0, Math.sin(this.yaw));
  }

  /** Recomputes view/projection for rendering at interpolation factor `alpha`. */
  updateMatrices(aspect: number, alpha: number): void {
    vec3.lerp(this.renderPosition, this.prevPosition, this.position, alpha);
    vec3.add(this.renderPosition, this.renderPosition, this.offset);
    this.forward(this.forwardTmp);
    vec3.add(this.targetTmp, this.renderPosition, this.forwardTmp);
    mat4.lookAt(this.view, this.renderPosition, this.targetTmp, UP);
    mat4.perspective(this.projection, this.fovY, aspect, this.near, this.far);
    mat4.multiply(this.viewProj, this.projection, this.view);
  }
}
