/**
 * One player inside a `WorldSim` (Milestone 10, extracted from the client's GameSession): body,
 * vitals, inventory and crafting grid, game mode, break progress, damage and death, and the
 * block / combat / item rules. Pure TS: single-player runs it in the browser (the client's
 * GameSession extends it), the multiplayer server runs one per connected player.
 */
import { isPlaceableVariant } from '../world/models';
import { BlockId } from '../world/blocks';
import { MIN_Y } from '../world/chunk';
import { checkBreak, type EditCheck } from '../world/editRules';
import { findSafeSpawn, type SpawnPoint } from '../world/spawn';
import { Inventory, type SavedInventory } from '../items/inventory';
import { getItemDef, type ItemStack, type Slot } from '../items/items';
import { blockDrops, breakSeconds, toolWearForBreak, wearTool } from '../items/breaking';
import { PLAYER_EYE_HEIGHT, createPlayerState, stepPlayer, type PlayerInput, type PlayerState } from '../physics/player';
import { THROWN_PICKUP_DELAY } from '../entity/itemEntity';
import { attackDamage, toolWearForAttack } from '../mob/combat';
import type { HurtResult } from '../mob/mobSystem';
import type { Mob } from '../mob/mob';
import type { MobTypeDef } from '../mob/mobTypes';
import type { Vec3 } from '../math/vec3';
import {
  EXHAUSTION_BREAK_BLOCK,
  EXHAUSTION_JUMP,
  EXHAUSTION_SPRINT_JUMP,
  EXHAUSTION_SPRINT_PER_BLOCK,
  EXHAUSTION_SWIM_PER_BLOCK,
  MAX_AIR,
  MAX_HEALTH,
  MAX_HUNGER,
  addExhaustion,
  canSprint,
  createVitals,
  eat,
  resetVitals,
  tickVitals,
  updateFall,
  vitalsFromSaved,
  type DamageCause,
  type GameMode,
  type SavedVitals,
  type Vitals,
} from '../survival/vitals';
import { applyInventoryOp, closeCraftGrid, type InventoryOp, type InventoryOpResult } from './invOps';
import type { WorldSim } from './worldSim';

export interface BlockPos {
  x: number;
  y: number;
  z: number;
}

export type DamageListener = (amount: number, cause: DamageCause) => void;
export type DeathListener = (cause: DamageCause) => void;

/** Calls every listener; one that throws is logged and does not stop the others (or the game). */
export function emitAll<A extends unknown[]>(listeners: readonly ((...args: A) => void)[], ...args: A): void {
  for (const l of listeners) {
    try {
      l(...args);
    } catch (err) {
      console.error('Game event listener failed', err);
    }
  }
}

/**
 * Players below this y are respawned (creative) or killed (survival). Walking bodies can never get
 * here: `World.getBlock` reads solid stone below MIN_Y and the bedrock layer at MIN_Y is
 * unbreakable, so players, mobs and items all stop on the world floor. Only creative flight
 * (noclip) can go below it; this check is the safety net for that (Milestone 11).
 */
export const VOID_Y = MIN_Y - 64;
/** Speed of a thrown item (Q), blocks/s. */
export const THROW_SPEED = 6;
/** Horizontal knockback of a full-strength player hit on a mob, blocks/s. */
export const ATTACK_KNOCKBACK = 6;
/** Upward speed given to the player by a mob's knockback. */
export const PLAYER_KNOCKBACK_UP = 5;
export const EXHAUSTION_ATTACK = 0.1;

/** A saved player (single-player world meta and the server's per-player file share this shape). */
export type SavedPlayerState = {
  x: number;
  y: number;
  z: number;
  flying: boolean;
  spawn?: { x: number; y: number; z: number };
  inventory?: SavedInventory;
} & Partial<SavedVitals>;

/** Survival mining progress on one block (multiplayer server: validates break timing). */
export interface BreakProgress {
  x: number;
  y: number;
  z: number;
  /** 0..1 (and beyond while the button stays down). */
  progress: number;
}

export class PlayerSim {
  readonly player: PlayerState = createPlayerState();
  readonly inventory = new Inventory();
  readonly vitals: Vitals = createVitals();
  /** Look direction (multiplayer snapshots, mob spawning outside the view cone). */
  yaw = 0;
  pitch = 0;
  /** The mob whose hit killed the player (for the death screen). */
  deathAttacker: MobTypeDef | undefined;
  /** Crafting grid of the open inventory/workbench screen (empty array when closed). */
  craftGrid: Slot[] = [];
  /** Selected hotbar slot, 0-8. */
  selectedSlot = 0;
  dead = false;
  deathCause: DamageCause | undefined;
  /** Where the player (re)spawns; set by `trySpawn` / `restore`. */
  spawnPoint: SpawnPoint | undefined;
  /** Survival mining in progress (server-side validation of break timing). */
  breaking: BreakProgress | null = null;
  /** Accepted / rejected edit counters, for the debug overlay. */
  readonly stats = { edits: 0, rejected: 0, lastRejection: '', pickups: 0, toolsBroken: 0, attacks: 0, mobKills: 0 };
  /** Set when the simulation teleported the player (respawn, void); the server then forces a snap. */
  teleported = false;
  /** Mob type of the most recent 'mob' damage. */
  private lastAttacker: MobTypeDef | undefined;
  protected lastAttackTime = -Infinity;
  protected readonly damageListeners: DamageListener[] = [];
  protected readonly deathListeners: DeathListener[] = [];

  constructor(
    readonly sim: WorldSim,
    readonly id: number,
    readonly name: string,
    public gameMode: GameMode = 'survival',
    private readonly spawnX = 0,
    private readonly spawnZ = 0,
  ) {}

  get spawned(): boolean {
    return this.spawnPoint !== undefined;
  }

  get creative(): boolean {
    return this.gameMode === 'creative';
  }

  get heldStack(): Slot {
    return this.inventory.get(this.selectedSlot);
  }

  readonly getBlock = (x: number, y: number, z: number): number => this.sim.world.getBlock(x, y, z);

  onDamage(listener: DamageListener): void {
    this.damageListeners.push(listener);
  }

  onDeath(listener: DeathListener): void {
    this.deathListeners.push(listener);
  }

  /** Finds a safe spawn near the spawn column once its chunks have loaded. Returns true when spawned. */
  trySpawn(): boolean {
    if (this.spawnPoint) return true;
    if (!this.sim.isAreaLoaded(this.spawnX, this.spawnZ)) return false;
    const sx = Math.floor(this.spawnX);
    const sz = Math.floor(this.spawnZ);
    this.spawnPoint = findSafeSpawn(this.getBlock, this.sim.isLoadedAt, sx, sz, 16) ?? { x: sx + 0.5, y: 200, z: sz + 0.5, wet: false };
    this.respawn();
    return true;
  }

  /**
   * Restores a saved player (position, flight, spawn point, vitals, inventory). The controller
   * still holds the player still until the surrounding chunks have loaded.
   */
  restore(saved: SavedPlayerState): void {
    const p = this.player;
    p.x = saved.x;
    p.y = saved.y;
    p.z = saved.z;
    p.vx = p.vy = p.vz = 0;
    p.flying = saved.flying && this.creative;
    p.onGround = false;
    this.spawnPoint = saved.spawn ? { ...saved.spawn, wet: false } : { x: saved.x, y: saved.y, z: saved.z, wet: false };
    Object.assign(this.vitals, vitalsFromSaved(saved));
    const inv = Inventory.fromSaved(saved.inventory);
    for (let i = 0; i < inv.slots.length; i++) this.inventory.slots[i] = inv.slots[i] ?? null;
    this.inventory.touch();
    // Saved while dead (quit on the death screen): stay dead until Respawn.
    if (!this.creative && this.vitals.health <= 0) {
      this.dead = true;
      this.deathCause = 'other';
      this.deathAttacker = undefined;
    }
  }

  /** Teleports to the spawn point (does not touch vitals). */
  respawn(): void {
    const p = this.player;
    const s = this.spawnPoint;
    if (!s) return;
    p.x = s.x;
    p.y = s.y;
    p.z = s.z;
    p.vx = p.vy = p.vz = 0;
    p.onGround = false;
    this.vitals.fallDistance = 0;
    this.teleported = true;
  }

  /** Leaves the death screen: full vitals, back at the spawn point. */
  respawnPlayer(): void {
    if (!this.dead) return;
    this.dead = false;
    this.deathCause = undefined;
    this.deathAttacker = undefined;
    resetVitals(this.vitals);
    this.respawn();
  }

  // --- Movement & per-tick simulation ----------------------------------------------------------

  /** Eyes under water (drowning, slower mining). */
  headInWater(): boolean {
    const p = this.player;
    return this.getBlock(Math.floor(p.x), Math.floor(p.y + PLAYER_EYE_HEIGHT), Math.floor(p.z)) === BlockId.Water;
  }

  /** Whether sprinting is allowed (survival needs enough hunger). */
  canSprint(): boolean {
    return this.creative || canSprint(this.vitals);
  }

  /**
   * One physics tick for this player plus survival bookkeeping (fall damage, exhaustion).
   * Returns true if the player was teleported (void), so the camera should snap.
   */
  movePlayer(input: PlayerInput, dt: number): boolean {
    const p = this.player;
    if (this.dead) return false;
    if (!this.creative && p.flying) p.flying = false;
    if (input.sprint && !this.canSprint()) input.sprint = false;
    const sprinting = input.sprint && input.forward > 0 && !input.sneak;
    const wasOnGround = p.onGround;
    const px = p.x, py = p.y, pz = p.z;
    stepPlayer(p, input, this.getBlock, dt);

    if (!this.creative) {
      const v = this.vitals;
      const fall = updateFall(v, py, p.y, p.onGround, p.inWater, p.flying);
      if (fall > 0) this.damage(fall, 'fall');
      const dist = Math.hypot(p.x - px, p.z - pz);
      if (p.inWater) addExhaustion(v, EXHAUSTION_SWIM_PER_BLOCK * dist);
      else if (sprinting) addExhaustion(v, EXHAUSTION_SPRINT_PER_BLOCK * dist);
      if (wasOnGround && !p.onGround && p.vy > 0 && !p.inWater) addExhaustion(v, sprinting ? EXHAUSTION_SPRINT_JUMP : EXHAUSTION_JUMP);
    } else {
      this.vitals.fallDistance = 0;
    }

    if (p.y < VOID_Y) {
      if (this.creative) {
        this.respawn();
        return true;
      }
      this.kill('void');
    }
    return false;
  }

  /** Per-tick vitals (air, drowning, starvation, regeneration). Called by `WorldSim.tick`. */
  tickVitals(dt: number): void {
    const v = this.vitals;
    if (this.creative) {
      v.air = MAX_AIR;
    } else if (!this.dead) {
      const r = tickVitals(v, dt, this.headInWater());
      if (r.drown) this.damage(r.drown, 'drown');
      if (r.starve) this.damage(r.starve, 'starve');
    }
  }

  // --- Damage API ---------------------------------------------------------------------------------

  /**
   * Applies damage (ignored in creative or when dead). `attacker` names the mob for 'mob' damage.
   * Returns the damage dealt.
   */
  damage(amount: number, cause: DamageCause, attacker?: MobTypeDef): number {
    if (this.creative || this.dead || amount <= 0 || !this.spawned) return 0;
    this.lastAttacker = cause === 'mob' ? attacker : undefined;
    const v = this.vitals;
    const dealt = Math.min(v.health, amount);
    v.health -= dealt;
    emitAll(this.damageListeners, dealt, cause);
    if (v.health <= 0) this.die(cause);
    return dealt;
  }

  heal(amount: number): void {
    if (this.dead) return;
    this.vitals.health = Math.min(MAX_HEALTH, this.vitals.health + amount);
  }

  /** Kills the player outright (void). In creative it just respawns. */
  kill(cause: DamageCause): void {
    if (this.creative) {
      this.respawn();
      return;
    }
    if (this.dead) return;
    this.vitals.health = 0;
    emitAll(this.damageListeners, MAX_HEALTH, cause);
    this.die(cause);
  }

  /** Pushes the player (a mob hit): horizontal velocity plus a small hop. */
  knockback(kx: number, kz: number): void {
    const p = this.player;
    if (p.flying) return;
    p.vx += kx;
    p.vz += kz;
    p.vy = Math.max(p.vy, PLAYER_KNOCKBACK_UP);
    p.onGround = false;
  }

  private die(cause: DamageCause): void {
    this.dead = true;
    this.deathCause = cause;
    this.deathAttacker = cause === 'mob' ? this.lastAttacker : undefined;
    this.breaking = null;
    const p = this.player;
    const rand = this.sim.rand;
    // Everything the player carried (including a crafting grid in use) scatters as item entities.
    const stacks = [...this.inventory.takeAll(), ...this.takeCraftGrid()];
    if (p.y >= VOID_Y + 1) {
      for (const s of stacks) {
        const a = rand() * Math.PI * 2;
        const speed = 1 + rand() * 2.5;
        this.sim.items.spawn(s, p.x, p.y + 1, p.z, { x: Math.cos(a) * speed, y: 3 + rand() * 2, z: Math.sin(a) * speed }, THROWN_PICKUP_DELAY);
      }
    }
    p.vx = p.vy = p.vz = 0;
    emitAll(this.deathListeners, cause);
  }

  /** Empties the crafting grid and returns its stacks. */
  takeCraftGrid(): ItemStack[] {
    const out = this.craftGrid.filter((s): s is ItemStack => !!s);
    this.craftGrid.fill(null);
    return out;
  }

  // --- Blocks -------------------------------------------------------------------------------------

  /** Seconds to break the block at `pos` with the held item right now (0 in creative). */
  breakSeconds(pos: BlockPos): number {
    if (this.creative) return 0;
    const p = this.player;
    return breakSeconds(this.getBlock(pos.x, pos.y, pos.z), this.heldStack, { headInWater: this.headInWater(), onGround: p.onGround || p.inWater });
  }

  /** Starts (or restarts) survival mining progress on `pos` (multiplayer server). */
  startBreaking(pos: BlockPos): void {
    this.breaking = { x: pos.x, y: pos.y, z: pos.z, progress: 0 };
  }

  /** Advances mining progress by one tick with the current tool and conditions. */
  tickBreaking(dt: number): void {
    const b = this.breaking;
    if (!b || this.dead) return;
    const secs = this.breakSeconds(b);
    if (!Number.isFinite(secs)) return;
    b.progress += secs <= 0 ? 1 : dt / secs;
  }

  /**
   * Breaks a block (the caller has already waited `breakSeconds`). In survival this spawns the
   * drops and wears the held tool.
   */
  requestBreak(pos: BlockPos): EditCheck {
    if (this.dead) return this.reject({ ok: false, reason: 'not_loaded' });
    const check = this.loaded(pos) ?? checkBreak(this.getBlock, pos.x, pos.y, pos.z);
    if (!check.ok) return this.reject(check);
    const id = this.getBlock(pos.x, pos.y, pos.z);
    if (this.creative) {
      this.sim.applyBlockChange(pos.x, pos.y, pos.z, 0);
      return check;
    }
    const held = this.heldStack;
    const drops = blockDrops(id, held, this.sim.rand);
    const wear = toolWearForBreak(id, held);
    this.sim.applyBlockChange(pos.x, pos.y, pos.z, 0);
    for (const d of drops) this.sim.items.spawn(d, pos.x + 0.5, pos.y + 0.375, pos.z + 0.5);
    this.wearHeld(wear);
    addExhaustion(this.vitals, EXHAUSTION_BREAK_BLOCK);
    return check;
  }

  /**
   * Places the held block item; survival uses one up. `_against` is the clicked block and face
   * (used by the multiplayer client to tell the server what was targeted). `variant` is the
   * orientation of a slab / stairs / rail family to place (see `placementVariant`); it must belong
   * to the held item's block.
   */
  requestPlace(pos: BlockPos, _against?: BlockPos & { face: number }, variant?: number): EditCheck {
    const held = this.heldStack;
    const item = held ? getItemDef(held.item).block : undefined;
    if (this.dead || item === undefined) return this.reject({ ok: false, reason: 'invalid_block' });
    const block = variant ?? item;
    if (!isPlaceableVariant(item, block)) return this.reject({ ok: false, reason: 'invalid_block' });
    const check = this.loaded(pos) ?? this.sim.checkPlace(pos.x, pos.y, pos.z, block);
    if (!check.ok) return this.reject(check);
    this.sim.applyBlockChange(pos.x, pos.y, pos.z, block);
    if (!this.creative) this.inventory.removeFromSlot(this.selectedSlot, 1);
    return check;
  }

  private wearHeld(wear: number): void {
    const held = this.heldStack;
    if (!held || wear <= 0) return;
    if (wearTool(held, wear)) this.inventory.touch();
    else {
      this.inventory.set(this.selectedSlot, null);
      this.stats.toolsBroken++;
    }
  }

  // --- Combat -----------------------------------------------------------------------------------

  /** Seconds since the last attack, capped (for the cooldown indicator / damage scaling). */
  get attackCharge(): number {
    return Math.min(1, (this.sim.simTime - this.lastAttackTime) / 0.6);
  }

  /**
   * Hits a mob with the held item: damage scales with the attack cooldown (spamming hits weaker),
   * knocks it back, and wears the held tool (swords 1, other tools 2) in survival.
   */
  attackMob(mob: Mob): HurtResult {
    if (this.dead || !this.spawned) return 'ignored';
    const p = this.player;
    const held = this.heldStack;
    const since = this.sim.simTime - this.lastAttackTime;
    this.lastAttackTime = this.sim.simTime;
    const dmg = attackDamage(held, since);
    const strength = Math.min(1, since / 0.6);
    const result = this.sim.mobs.hurt(mob, dmg, { x: p.x, z: p.z }, ATTACK_KNOCKBACK * (0.4 + 0.6 * strength));
    if (result === 'ignored') return result;
    this.stats.attacks++;
    if (result === 'killed') this.stats.mobKills++;
    if (!this.creative) {
      addExhaustion(this.vitals, EXHAUSTION_ATTACK);
      this.wearHeld(toolWearForAttack(held));
    }
    return result;
  }

  // --- Items --------------------------------------------------------------------------------------

  /** Q: drops one held item (or the whole stack) in the look direction. */
  dropHeld(all: boolean, dir: Vec3): boolean {
    if (this.dead) return false;
    const s = this.inventory.removeFromSlot(this.selectedSlot, all ? Infinity : 1);
    if (!s) return false;
    this.throwStack(s, dir);
    return true;
  }

  /** Throws a stack from the player's eyes along `dir` (dropping from the inventory screen too). */
  throwStack(stack: ItemStack, dir: Vec3): void {
    const p = this.player;
    const eyeY = p.y + PLAYER_EYE_HEIGHT - 0.3;
    this.sim.items.spawn(
      stack,
      p.x + dir[0]! * 0.3,
      eyeY,
      p.z + dir[2]! * 0.3,
      { x: dir[0]! * THROW_SPEED, y: dir[1]! * THROW_SPEED + 1.5, z: dir[2]! * THROW_SPEED },
      THROWN_PICKUP_DELAY,
    );
  }

  /** Look direction from `yaw` / `pitch` (0 yaw faces -Z, positive pitch looks up). */
  lookDir(out: Vec3 = new Float32Array(3)): Vec3 {
    const cp = Math.cos(this.pitch);
    out[0] = Math.sin(this.yaw) * cp;
    out[1] = Math.sin(this.pitch);
    out[2] = -Math.cos(this.yaw) * cp;
    return out;
  }

  /** Whether the held item can be eaten now (survival, food, not full). */
  canEatHeld(): boolean {
    const held = this.heldStack;
    return !this.creative && !this.dead && !!held && !!getItemDef(held.item).food && this.vitals.hunger < MAX_HUNGER;
  }

  /** Eats one of the held food item. */
  eatHeld(): boolean {
    if (!this.canEatHeld()) return false;
    const food = getItemDef(this.heldStack!.item).food!;
    eat(this.vitals, food.hunger, food.saturation);
    this.inventory.removeFromSlot(this.selectedSlot, 1);
    return true;
  }

  // --- Inventory screen ---------------------------------------------------------------------------

  /** Opens a crafting grid (2 = inventory, 3 = workbench). Anything in an old grid goes back first. */
  openCraft(size: 2 | 3): void {
    if (this.craftGrid.length) this.closeCraft();
    this.craftGrid = new Array<Slot>(size * size).fill(null);
  }

  /** Closes the screen; returns stacks that did not fit back (thrown in the look direction). */
  closeCraft(): ItemStack[] {
    const left = closeCraftGrid(this);
    for (const s of left) this.throwStack(s, this.lookDir());
    return left;
  }

  /** Applies an inventory screen operation; a thrown cursor stack flies in the look direction. */
  inventoryOp(op: InventoryOp): InventoryOpResult {
    if (this.dead) return { ok: false };
    const r = applyInventoryOp(this, op);
    if (r.thrown) this.throwStack(r.thrown, this.lookDir());
    return r;
  }

  private loaded(pos: BlockPos): EditCheck | undefined {
    return this.sim.isLoadedAt(pos.x, pos.z) ? undefined : { ok: false, reason: 'not_loaded' };
  }

  protected reject(check: EditCheck): EditCheck {
    this.stats.rejected++;
    if (!check.ok) this.stats.lastRejection = check.reason;
    return check;
  }
}
