import { BLOCK_OPAQUE, raycastBlocks, type BlockGetter, type MapLabel, type Mat4 } from '@voxel/shared';

/** Labels further than this are not drawn (blocks); building names have a shorter range. */
export const LABEL_DISTANCE = 96;
const BUILDING_LABEL_DISTANCE = 64;
/** At most this many labels at once (the nearest). */
export const MAX_LABELS = 24;
/** Frames between line-of-sight checks (raycasts) of the shown labels. */
const SIGHT_INTERVAL = 8;

/** Label height above its anchor, so street names float over the road rather than on it. */
const LIFT = 1.5;

export interface LabelCandidate {
  label: MapLabel;
  index: number;
  distance: number;
}

/**
 * The labels worth drawing from `eye`: within range (shorter for buildings), nearest first, at most
 * `max`. Pure, so it is unit tested.
 */
export function nearbyLabels(labels: readonly MapLabel[], eye: ArrayLike<number>, max = MAX_LABELS): LabelCandidate[] {
  const out: LabelCandidate[] = [];
  const ex = eye[0]!, ey = eye[1]!, ez = eye[2]!;
  labels.forEach((label, index) => {
    const range = label.kind === 'building' ? BUILDING_LABEL_DISTANCE : LABEL_DISTANCE;
    const dx = label.x + 0.5 - ex, dz = label.z + 0.5 - ez;
    if (Math.abs(dx) > range || Math.abs(dz) > range) return;
    const distance = Math.hypot(dx, label.y + LIFT - ey, dz);
    if (distance <= range) out.push({ label, index, distance });
  });
  out.sort((a, b) => a.distance - b.distance);
  return out.slice(0, max);
}

/**
 * Map world name labels (phase F): streets, rivers, parks and buildings from mapcore, drawn as DOM
 * text projected each frame like player name tags. Only the nearest few within range are shown,
 * fading with distance, and labels hidden behind blocks (checked by raycast every few frames) are
 * left out.
 */
export class MapLabels {
  private readonly root: HTMLDivElement;
  private readonly els = new Map<number, HTMLDivElement>();
  private readonly blocked = new Set<number>();
  private frame = 0;

  constructor(
    private readonly labels: readonly MapLabel[],
    private readonly getBlock: BlockGetter,
    parent: HTMLElement = document.body,
  ) {
    this.root = document.createElement('div');
    this.root.className = 'map-labels';
    parent.append(this.root);
  }

  get count(): number {
    return this.labels.length;
  }

  /** Labels currently on screen (for tests / F3). */
  get shown(): number {
    let n = 0;
    for (const el of this.els.values()) if (!el.hidden) n++;
    return n;
  }

  update(viewProj: Mat4, eye: ArrayLike<number>, width: number, height: number): void {
    const near = nearbyLabels(this.labels, eye);
    const checkSight = this.frame++ % SIGHT_INTERVAL === 0;
    const live = new Set<number>();
    for (const { label, index, distance } of near) {
      live.add(index);
      let el = this.els.get(index);
      if (!el) {
        el = document.createElement('div');
        el.className = `map-label map-label-${label.kind}`;
        el.textContent = label.text;
        this.root.append(el);
        this.els.set(index, el);
      }
      const x = label.x + 0.5, y = label.y + LIFT, z = label.z + 0.5;
      if (checkSight) {
        const dx = x - eye[0]!, dy = y - eye[1]!, dz = z - eye[2]!;
        const hit = raycastBlocks(this.getBlock, eye[0]!, eye[1]!, eye[2]!, dx, dy, dz, distance - 0.75, (id) => BLOCK_OPAQUE[id] === 1);
        if (hit) this.blocked.add(index);
        else this.blocked.delete(index);
      }
      const m = viewProj;
      const cx = m[0]! * x + m[4]! * y + m[8]! * z + m[12]!;
      const cy = m[1]! * x + m[5]! * y + m[9]! * z + m[13]!;
      const cw = m[3]! * x + m[7]! * y + m[11]! * z + m[15]!;
      if (cw <= 0.05 || this.blocked.has(index)) {
        el.hidden = true;
        continue;
      }
      const sx = ((cx / cw) * 0.5 + 0.5) * width;
      const sy = (1 - ((cy / cw) * 0.5 + 0.5)) * height;
      el.hidden = sx < -200 || sx > width + 200 || sy < -50 || sy > height + 50;
      const range = label.kind === 'building' ? BUILDING_LABEL_DISTANCE : LABEL_DISTANCE;
      const near01 = 1 - distance / range;
      el.style.opacity = Math.min(1, 0.25 + near01 * 1.2).toFixed(2);
      el.style.transform = `translate(${sx.toFixed(1)}px, ${sy.toFixed(1)}px) translate(-50%, -100%) scale(${(0.75 + near01 * 0.35).toFixed(2)})`;
    }
    for (const [index, el] of this.els) {
      if (live.has(index)) continue;
      el.remove();
      this.els.delete(index);
      this.blocked.delete(index);
    }
  }

  dispose(): void {
    this.root.remove();
    this.els.clear();
  }
}
