/**
 * Non-blocking notifications (Milestone 11): a small stack at the top of the screen. Click one to
 * dismiss it. The same text shown again within a few seconds is not repeated, and at most a few
 * toasts are visible at once, so an error that fires every frame cannot flood the page.
 * Safe to call anywhere (does nothing without a DOM, e.g. in unit tests).
 */
export type ToastKind = 'error' | 'warn' | 'info';

const MAX_VISIBLE = 3;
const DEDUPE_MS = 8000;

let stack: HTMLDivElement | undefined;
const recent = new Map<string, number>();

export function toast(message: string, kind: ToastKind = 'warn', durationMs = 6000): void {
  if (typeof document === 'undefined' || !document.body) return;
  const text = message.length > 300 ? `${message.slice(0, 297)}...` : message;
  const now = Date.now();
  const last = recent.get(text);
  if (last !== undefined && now - last < DEDUPE_MS) return;
  recent.set(text, now);
  if (recent.size > 50) for (const [k, t] of recent) if (now - t > DEDUPE_MS) recent.delete(k);

  if (!stack || !stack.isConnected) {
    stack = document.createElement('div');
    stack.className = 'toast-stack';
    stack.setAttribute('role', 'status');
    stack.setAttribute('aria-live', 'polite');
    document.body.appendChild(stack);
  }
  while (stack.childElementCount >= MAX_VISIBLE) stack.firstElementChild?.remove();
  const el = document.createElement('div');
  el.className = `toast ${kind}`;
  el.textContent = text;
  const remove = (): void => {
    if (!el.isConnected) return;
    el.classList.add('leaving');
    setTimeout(() => el.remove(), 300);
  };
  el.addEventListener('click', remove);
  stack.appendChild(el);
  setTimeout(remove, durationMs);
}

/** Text for an unknown thrown value. */
export function errorText(err: unknown): string {
  if (err instanceof Error) return err.message || err.name;
  if (typeof err === 'string') return err;
  try {
    return JSON.stringify(err) ?? String(err);
  } catch {
    return String(err);
  }
}

/**
 * Logs uncaught errors and unhandled promise rejections and shows a toast for each, instead of
 * failing silently (or, worse, leaving a half-drawn frame). The game keeps running.
 */
export function installGlobalErrorHandlers(target: Window = window): void {
  target.addEventListener('error', (e: ErrorEvent) => {
    // Resource load errors (img/script) have no `error` and are reported by the browser already.
    if (!e.error && !e.message) return;
    console.error('Uncaught error:', e.error ?? e.message);
    toast(`Something went wrong: ${errorText(e.error ?? e.message)}. The game will try to keep running.`, 'error');
  });
  target.addEventListener('unhandledrejection', (e: PromiseRejectionEvent) => {
    console.error('Unhandled promise rejection:', e.reason);
    toast(`Something went wrong: ${errorText(e.reason)}`, 'error');
  });
}

/** Whether an IndexedDB / storage error means the browser's storage quota is used up. */
export function isQuotaError(err: unknown): boolean {
  if (!err || typeof err !== 'object') return false;
  const e = err as { name?: unknown; code?: unknown; message?: unknown; inner?: unknown };
  if (e.name === 'QuotaExceededError' || e.name === 'NS_ERROR_DOM_QUOTA_REACHED' || e.code === 22) return true;
  return typeof e.message === 'string' && /quota/i.test(e.message);
}
