import { CHUNK_SIZE, Chunk, chunkKey, type GeneratorKind, type World } from '@voxel/shared';
import type { GenRequest, GenResponse } from './genProtocol';
import { WorkerSet, type WorkerSlot } from '../workers/workerSet';

export interface ChunkStreamerOptions {
  /** Load radius in chunks (circular). Default 8. */
  viewDistance?: number;
  /** Extra chunks beyond the view distance before a chunk is unloaded. Default 2. */
  unloadMargin?: number;
  workerCount?: number;
  /** Generation requests kept in flight per worker. Default 2. */
  inFlightPerWorker?: number;
  /** Generated chunks added to the World per frame, to bound main-thread work. Default 4. */
  maxAddsPerFrame?: number;
  /** Saved (modified) chunks, loaded instead of generated. */
  saved?: SavedChunkSource;
}

/**
 * Where modified chunks come from. `has` must be synchronous and cheap (an in-memory key set), so
 * chunks that were never modified cost no storage round trip.
 */
export interface SavedChunkSource {
  has(cx: number, cz: number): boolean;
  /** The chunk's blocks (a fresh array the streamer may transfer), or undefined to generate it. */
  load(cx: number, cz: number): Promise<Uint16Array | undefined>;
}

/**
 * Called after a chunk is removed from the World (free its GPU sections and queued meshes, save it
 * if it was modified). The chunk is no longer referenced by the World.
 */
export type ChunkUnloadHandler = (cx: number, cz: number, chunk: Chunk) => void;
/**
 * Called right after a generated chunk is added to the World, in the same frame and before it can
 * be meshed (used to stitch light across its borders).
 */
export type ChunkAddHandler = (chunk: Chunk) => void;

/**
 * What the game needs from a chunk source: the generating `ChunkStreamer` (single-player) or the
 * server-fed `RemoteChunkStreamer` (multiplayer).
 */
export interface ChunkSource {
  readonly viewDistance: number;
  onAdd: ChunkAddHandler | undefined;
  update(camX: number, camZ: number): void;
  canMesh(cx: number, cz: number): boolean;
  setViewDistance(chunks: number): void;
  dispose(): void;
  readonly queueLength: number;
  readonly inFlight: number;
  readonly workerCount: number;
  readonly unloaded: number;
  readonly loadedFromSave: number;
  readonly staleDropped: number;
  readonly avgGenMs: number;
  readonly avgLightMs: number;
}

export function defaultGenWorkerCount(): number {
  const cores = typeof navigator !== 'undefined' ? navigator.hardwareConcurrency || 2 : 2;
  return Math.max(1, Math.min(3, Math.floor(cores / 2)));
}

/**
 * Keeps the World filled with generated chunks in a circle around the camera.
 *
 * - Missing chunks within `viewDistance` are generated on worker threads, nearest first. Chunks the
 *   `saved` source knows are read from storage instead and only lit on the worker.
 * - At most `maxAddsPerFrame` finished chunks are added to the World per frame.
 * - Chunks beyond `viewDistance + unloadMargin` are unloaded (hysteresis avoids thrashing).
 * - Results for chunks that are no longer wanted when they arrive are dropped.
 * - `canMesh` tells the mesher to wait until a chunk's 4 horizontal neighbours are loaded (or
 *   outside the view), so border faces aren't meshed against air and then rebuilt.
 */
export class ChunkStreamer implements ChunkSource {
  viewDistance: number;
  readonly unloadMargin: number;
  private readonly workers: WorkerSet<GenResponse, [number, number]>;
  private nextJob = 1;
  private readonly inFlightPerWorker: number;
  private readonly maxAddsPerFrame: number;
  /** Chunk keys with a generation request in flight. */
  private readonly requested = new Set<number>();
  /** Finished results waiting to be added to the World. */
  private readonly ready: GenResponse[] = [];
  /** Chunks to request, farthest first (popped from the end). Entries are [cx, cz]. */
  private queue: [number, number][] = [];
  private centerCx = Number.NaN;
  private centerCz = Number.NaN;
  /** Generated chunks dropped because they were no longer wanted on arrival. */
  staleDropped = 0;
  generated = 0;
  unloaded = 0;
  /** Exponential moving average of worker generation time, ms. */
  avgGenMs = 0;
  /** Exponential moving average of the worker's chunk-local light pass, ms. */
  avgLightMs = 0;
  /** Chunks read from the saved source (not generated). */
  loadedFromSave = 0;
  /** Called after each generated chunk is added to the World. */
  onAdd: ChunkAddHandler | undefined;
  private readonly saved: SavedChunkSource | undefined;
  private disposed = false;

  constructor(
    private readonly world: World,
    /** The world's generator (kind, seed, map package); sent with every generation request. */
    readonly spec: { generator: GeneratorKind; seed: number; mapPackageId?: string },
    private readonly onUnload: ChunkUnloadHandler,
    options: ChunkStreamerOptions = {},
  ) {
    this.viewDistance = options.viewDistance ?? 8;
    this.unloadMargin = options.unloadMargin ?? 2;
    this.inFlightPerWorker = options.inFlightPerWorker ?? 2;
    this.maxAddsPerFrame = options.maxAddsPerFrame ?? 4;
    this.saved = options.saved;
    const count = options.workerCount ?? defaultGenWorkerCount();
    this.workers = new WorkerSet<GenResponse, [number, number]>({
      create: () => new Worker(new URL('./genWorker.ts', import.meta.url), { type: 'module' }),
      count,
      label: 'Chunk generation',
      retryKey: ([cx, cz]) => chunkKey(cx, cz),
      onResult: (slot, res) => this.onResult(slot, res),
      // A crashed worker's chunks are requested again (nearest first, twice at most).
      onLost: (lost) => {
        for (const { job: [cx, cz], attempts } of lost) {
          this.requested.delete(chunkKey(cx, cz));
          if (attempts <= 2) this.queue.push([cx, cz]);
        }
        this.dispatch();
      },
    });
  }

  get workerCount(): number {
    return this.workers.size;
  }

  /** Workers replaced after crashing. */
  get restarts(): number {
    return this.workers.restarts;
  }

  /** Debug / tests: crash-and-restart a worker as if it had thrown. */
  simulateCrash(i = 0): void {
    this.workers.simulateCrash(i);
  }

  /** Chunks waiting to be requested, being generated, or generated but not yet added. */
  get queueLength(): number {
    return this.queue.length + this.requested.size + this.ready.length;
  }

  get inFlight(): number {
    return this.requested.size;
  }

  /** Whether chunk (cx, cz) is inside the load radius around the current camera chunk. */
  isWanted(cx: number, cz: number): boolean {
    const dx = cx - this.centerCx;
    const dz = cz - this.centerCz;
    return dx * dx + dz * dz <= this.viewDistance * this.viewDistance;
  }

  /**
   * Whether a loaded chunk may be meshed now: it is within the view, and each horizontal
   * neighbour is loaded or outside the view (and so won't arrive soon).
   */
  canMesh(cx: number, cz: number): boolean {
    if (!this.isWanted(cx, cz)) return false;
    const w = this.world;
    return (
      (!!w.getChunk(cx + 1, cz) || !this.isWanted(cx + 1, cz)) &&
      (!!w.getChunk(cx - 1, cz) || !this.isWanted(cx - 1, cz)) &&
      (!!w.getChunk(cx, cz + 1) || !this.isWanted(cx, cz + 1)) &&
      (!!w.getChunk(cx, cz - 1) || !this.isWanted(cx, cz - 1))
    );
  }

  /** Call once per frame with the camera position. */
  update(camX: number, camZ: number): void {
    const ccx = Math.floor(camX / CHUNK_SIZE);
    const ccz = Math.floor(camZ / CHUNK_SIZE);
    if (ccx !== this.centerCx || ccz !== this.centerCz) {
      this.centerCx = ccx;
      this.centerCz = ccz;
      this.unloadFar();
      this.rebuildQueue();
    }
    this.addReady();
    this.dispatch();
  }

  /** Changes the load radius; chunks are queued or unloaded on the next `update`. */
  setViewDistance(chunks: number): void {
    if (chunks === this.viewDistance) return;
    this.viewDistance = chunks;
    this.centerCx = this.centerCz = Number.NaN; // force unloadFar + rebuildQueue
  }

  dispose(): void {
    this.disposed = true;
    this.workers.dispose();
    this.queue.length = 0;
    this.requested.clear();
    this.ready.length = 0;
  }

  private rebuildQueue(): void {
    const r = this.viewDistance;
    const list: { cx: number; cz: number; d: number }[] = [];
    const waiting = new Set(this.ready.map((res) => chunkKey(res.cx, res.cz)));
    for (let dz = -r; dz <= r; dz++) {
      for (let dx = -r; dx <= r; dx++) {
        const d = dx * dx + dz * dz;
        if (d > r * r) continue;
        const cx = this.centerCx + dx;
        const cz = this.centerCz + dz;
        const key = chunkKey(cx, cz);
        if (this.world.getChunk(cx, cz) || this.requested.has(key) || waiting.has(key)) continue;
        list.push({ cx, cz, d });
      }
    }
    list.sort((a, b) => b.d - a.d); // farthest first; nearest is popped from the end
    this.queue = list.map((e) => [e.cx, e.cz]);
  }

  private unloadFar(): void {
    const limit = this.viewDistance + this.unloadMargin;
    const far: Chunk[] = [];
    for (const chunk of this.world) {
      const dx = chunk.cx - this.centerCx;
      const dz = chunk.cz - this.centerCz;
      if (dx * dx + dz * dz > limit * limit) far.push(chunk);
    }
    for (const chunk of far) {
      this.world.removeChunk(chunk.cx, chunk.cz);
      this.onUnload(chunk.cx, chunk.cz, chunk);
      this.unloaded++;
    }
  }

  private addReady(): void {
    let added = 0;
    while (this.ready.length > 0 && added < this.maxAddsPerFrame) {
      const res = this.ready.shift()!;
      if (!this.isWanted(res.cx, res.cz) || this.world.getChunk(res.cx, res.cz)) {
        this.staleDropped++;
        continue;
      }
      if (!res.fromSave && this.saved?.has(res.cx, res.cz)) {
        // Generated before we knew it was modified (or modified meanwhile): the save wins.
        this.staleDropped++;
        this.startLoad(res.cx, res.cz);
        continue;
      }
      if (res.fromSave) this.loadedFromSave++;
      const chunk = new Chunk(res.cx, res.cz, res.blocks, res.light);
      chunk.recount();
      this.world.addChunk(chunk);
      this.onAdd?.(chunk);
      added++;
    }
  }

  private dispatch(): void {
    for (const slot of this.workers.slots) {
      while (slot.inFlight < this.inFlightPerWorker) {
        const next = this.queue.pop();
        if (!next) return;
        const [cx, cz] = next;
        const key = chunkKey(cx, cz);
        if (!this.isWanted(cx, cz) || this.world.getChunk(cx, cz) || this.requested.has(key)) continue;
        if (this.saved?.has(cx, cz)) {
          this.startLoad(cx, cz);
          continue;
        }
        const job = this.nextJob++;
        const req: GenRequest = { ...this.genFields(), job, cx, cz };
        this.workers.post(slot, job, [cx, cz], req);
        this.requested.add(key);
      }
    }
  }

  /**
   * Reads a modified chunk from the saved source, then sends it to the least busy worker for
   * lighting (the result comes back like a generated chunk). Stays in `requested` throughout, so
   * it is never also generated. Falls back to generating if the save is missing.
   */
  private startLoad(cx: number, cz: number): void {
    const saved = this.saved;
    if (!saved) return;
    const key = chunkKey(cx, cz);
    this.requested.add(key);
    const finish = (blocks: Uint16Array | undefined): void => {
      if (this.disposed) return;
      if (!this.isWanted(cx, cz) || this.world.getChunk(cx, cz)) {
        // Became unwanted while loading; it is requeued normally if the player returns.
        this.requested.delete(key);
        this.staleDropped++;
        return;
      }
      const slot = this.workers.leastBusy();
      const job = this.nextJob++;
      const req: GenRequest = blocks ? { ...this.genFields(), job, cx, cz, blocks } : { ...this.genFields(), job, cx, cz };
      this.workers.post(slot, job, [cx, cz], req, blocks ? [blocks.buffer] : []);
    };
    saved.load(cx, cz).then(finish, (err: unknown) => {
      console.warn(`Loading saved chunk ${cx},${cz} failed; regenerating`, err);
      finish(undefined);
    });
  }

  get seed(): number {
    return this.spec.seed >>> 0;
  }

  /** The generator part of a `GenRequest`. */
  private genFields(): Pick<GenRequest, 'generator' | 'seed' | 'mapPackageId'> {
    const { generator, seed, mapPackageId } = this.spec;
    return mapPackageId === undefined ? { generator, seed } : { generator, seed, mapPackageId };
  }

  private onResult(slot: WorkerSlot<[number, number]>, res: GenResponse): void {
    this.workers.done(slot, res.job);
    this.requested.delete(chunkKey(res.cx, res.cz));
    if (!res.fromSave) {
      this.avgGenMs = this.generated === 0 ? res.ms : this.avgGenMs * 0.95 + res.ms * 0.05;
      this.avgLightMs = this.generated === 0 ? res.lightMs : this.avgLightMs * 0.95 + res.lightMs * 0.05;
      this.generated++;
    }
    if (res.seed !== this.seed || !this.isWanted(res.cx, res.cz)) {
      this.staleDropped++;
    } else {
      this.ready.push(res);
    }
    this.dispatch();
  }
}
