import { HOTBAR_SIZE, INVENTORY_SIZE, ITEMS, craftResult, type InvGroup, type InventoryOp, type Slot } from '@voxel/shared';
import type { GameSession } from '../game/session';
import { createSlotEl, setSlotContent, stackTooltip } from './slotView';

export type ScreenKind = 'inventory' | 'workbench';

type Group = InvGroup;

/** What a touch tap on a slot does (touch toolbar; desktop uses mouse buttons and shift). */
type TouchMode = 'move' | 'split' | 'quick';

/** A finger held this long on a slot acts like a right click (take half / put one). */
export const LONG_PRESS_MS = 450;
/** A finger moving farther than this (CSS px) is scrolling, not tapping. */
const TOUCH_SLOP_PX = 12;

export interface InventoryScreenHooks {
  /** After the screen closed (re-lock the pointer). */
  onClose(): void;
}

/**
 * DOM inventory screen: the 36 player slots plus either a crafting grid (2x2 from E, 3x3 at a
 * workbench) or, in creative, a palette of every item.
 *
 * Mouse: left click picks up / puts down / merges / swaps with the cursor stack; dragging a picked-up
 * stack onto another slot drops it there; right click takes half or puts one; shift-click moves a
 * stack between hotbar and main grid (or out of the crafting grid / takes all crafts). Clicking
 * outside the panel throws the cursor stack (right click: one item).
 *
 * Every click is a shared `InventoryOp` applied through the session (Milestone 10): locally in
 * single-player, optimistically plus sent to the server in multiplayer (the server's inventory
 * updates then drive what is shown).
 *
 * Touch (Milestone 9): tap = left click; long-press = right click (half / one); a toolbar (shown
 * only in touch mode) switches taps to "Split" (right click) or "Quick move" (shift-click) and has
 * a Close button. Slots are sized for fingers by style.css under `body.touch`.
 */
export class InventoryScreen {
  private readonly root: HTMLDivElement;
  private readonly panel: HTMLDivElement;
  private readonly cursorEl: HTMLDivElement;
  private readonly tooltip: HTMLDivElement;
  private readonly abort = new AbortController();
  private kind: ScreenKind = 'inventory';
  private size = 2;
  private invEls: HTMLDivElement[] = [];
  private gridEls: HTMLDivElement[] = [];
  private outEl: HTMLDivElement | undefined;
  private renderedVersion = -1;
  private hover: { group: Group; index: number } | null = null;
  private drag: { group: Group; index: number; pickedUp: boolean } | null = null;
  private mouseX = 0;
  private mouseY = 0;
  private touchMode: TouchMode = 'move';
  private readonly toolbar: HTMLDivElement;
  private touch: { id: number; x: number; y: number; target: EventTarget | null; timer: number; done: boolean } | null = null;

  constructor(
    private readonly session: GameSession,
    private readonly hooks: InventoryScreenHooks,
    parent: HTMLElement = document.body,
  ) {
    this.root = document.createElement('div');
    this.root.className = 'inv-root';
    this.root.hidden = true;
    this.panel = document.createElement('div');
    this.panel.className = 'inv-panel';
    this.cursorEl = createSlotEl('slot inv-cursor');
    this.tooltip = document.createElement('div');
    this.tooltip.className = 'inv-tooltip';
    this.tooltip.hidden = true;
    this.toolbar = this.buildToolbar();
    this.root.append(this.panel, this.cursorEl, this.tooltip);
    parent.appendChild(this.root);

    const signal = this.abort.signal;
    this.root.addEventListener('pointerdown', (e) => this.onTouchDown(e), { signal });
    this.root.addEventListener('pointermove', (e) => this.onTouchMove(e), { signal });
    this.root.addEventListener('pointerup', (e) => this.onTouchUp(e, false), { signal });
    this.root.addEventListener('pointercancel', (e) => this.onTouchUp(e, true), { signal });
    this.root.addEventListener('mousedown', (e) => this.onMouseDown(e), { signal });
    this.root.addEventListener('mouseup', (e) => this.onMouseUp(e), { signal });
    this.root.addEventListener('mousemove', (e) => this.onMouseMove(e), { signal });
    this.root.addEventListener('contextmenu', (e) => e.preventDefault(), { signal });
  }

  get isOpen(): boolean {
    return !this.root.hidden;
  }

  get openKind(): ScreenKind | undefined {
    return this.isOpen ? this.kind : undefined;
  }

  open(kind: ScreenKind, workbench?: { x: number; y: number; z: number }): void {
    if (this.isOpen) this.close(false);
    this.kind = kind;
    this.size = kind === 'workbench' ? 3 : 2;
    this.session.openScreen(this.size as 2 | 3, workbench);
    this.build();
    this.root.hidden = false;
    document.body.classList.add('in-inventory');
    this.renderedVersion = -1;
    this.render();
  }

  /** Closes the screen; the crafting grid and cursor go back to the inventory (or drop). */
  close(notify = true): void {
    if (!this.isOpen) return;
    this.session.closeScreen();
    this.root.hidden = true;
    this.tooltip.hidden = true;
    this.drag = null;
    this.cancelTouch();
    this.setTouchMode('move');
    document.body.classList.remove('in-inventory');
    if (notify) this.hooks.onClose();
  }

  /** Per frame: redraws when the inventory changed (pickups while open). */
  update(): void {
    if (this.isOpen && this.session.inventory.version !== this.renderedVersion) this.render();
  }

  dispose(): void {
    this.cancelTouch();
    this.abort.abort();
    this.root.remove();
    document.body.classList.remove('in-inventory');
  }

  // --- DOM --------------------------------------------------------------------------------------

  private slot(group: Group, index: number, extra = ''): HTMLDivElement {
    const el = createSlotEl(`slot${extra ? ` ${extra}` : ''}`);
    el.dataset['group'] = group;
    el.dataset['index'] = String(index);
    return el;
  }

  private section(title: string, cls: string, children: HTMLElement[]): HTMLDivElement {
    const wrap = document.createElement('div');
    wrap.className = `inv-section ${cls}`;
    const h = document.createElement('div');
    h.className = 'inv-title';
    h.textContent = title;
    const body = document.createElement('div');
    body.className = 'inv-body';
    body.append(...children);
    wrap.append(h, body);
    return wrap;
  }

  private build(): void {
    const creative = this.session.creative;
    const parts: HTMLElement[] = [];
    this.gridEls = [];
    this.outEl = undefined;
    if (creative && this.kind === 'inventory') {
      const pal = document.createElement('div');
      pal.className = 'inv-grid inv-palette';
      for (const def of ITEMS) {
        const el = this.slot('palette', def.id);
        setSlotContent(el, { item: def.id, count: 1, damage: 0 });
        pal.appendChild(el);
      }
      parts.push(this.section('All items (click: stack, right click: one, click with an item held: delete it)', 'inv-creative', [pal]));
    } else {
      const grid = document.createElement('div');
      grid.className = 'inv-grid';
      grid.style.gridTemplateColumns = `repeat(${this.size}, var(--slot))`;
      for (let i = 0; i < this.size * this.size; i++) {
        const el = this.slot('grid', i);
        grid.appendChild(el);
        this.gridEls.push(el);
      }
      const arrow = document.createElement('div');
      arrow.className = 'inv-arrow';
      arrow.textContent = '→';
      this.outEl = this.slot('out', 0, 'inv-output');
      const row = document.createElement('div');
      row.className = 'inv-craft';
      row.append(grid, arrow, this.outEl);
      parts.push(this.section(this.kind === 'workbench' ? 'Workbench' : 'Crafting', 'inv-crafting', [row]));
    }
    this.invEls = [];
    const main = document.createElement('div');
    main.className = 'inv-grid inv-main';
    for (let i = HOTBAR_SIZE; i < INVENTORY_SIZE; i++) main.appendChild(this.slot('inv', i));
    const hot = document.createElement('div');
    hot.className = 'inv-grid inv-hotbar';
    for (let i = 0; i < HOTBAR_SIZE; i++) hot.appendChild(this.slot('inv', i));
    parts.push(this.section('Inventory', 'inv-player', [main, hot]));
    this.panel.replaceChildren(this.toolbar, ...parts);
    this.invEls = [...this.panel.querySelectorAll<HTMLDivElement>('[data-group="inv"]')].sort(
      (a, b) => Number(a.dataset['index']) - Number(b.dataset['index']),
    );
  }

  private render(): void {
    const inv = this.session.inventory;
    this.renderedVersion = inv.version;
    for (let i = 0; i < INVENTORY_SIZE; i++) setSlotContent(this.invEls[i]!, inv.get(i));
    const grid = this.session.craftGrid;
    this.gridEls.forEach((el, i) => setSlotContent(el, grid[i] ?? null));
    if (this.outEl) setSlotContent(this.outEl, this.craftResult());
    setSlotContent(this.cursorEl, inv.cursor);
    this.cursorEl.hidden = !inv.cursor;
    this.placeCursor();
    this.updateTooltip();
  }

  private craftResult(): Slot {
    return craftResult(this.session);
  }

  private op(op: InventoryOp): void {
    this.session.inventoryOp(op);
  }

  // --- Touch ------------------------------------------------------------------------------------

  private buildToolbar(): HTMLDivElement {
    const bar = document.createElement('div');
    bar.className = 'inv-touchbar';
    const btn = (id: string, label: string, onClick: () => void): HTMLButtonElement => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'btn';
      b.id = id;
      b.textContent = label;
      b.addEventListener('click', onClick, { signal: this.abort.signal });
      return b;
    };
    const hint = document.createElement('span');
    hint.className = 'inv-touchhint';
    hint.textContent = 'Tap: pick up / place · hold: half / one';
    bar.append(
      btn('inv-split', 'Split', () => this.setTouchMode(this.touchMode === 'split' ? 'move' : 'split')),
      btn('inv-quick', 'Quick move', () => this.setTouchMode(this.touchMode === 'quick' ? 'move' : 'quick')),
      hint,
      btn('inv-close', 'Close', () => this.close()),
    );
    return bar;
  }

  private setTouchMode(mode: TouchMode): void {
    this.touchMode = mode;
    this.toolbar.querySelector('#inv-split')?.classList.toggle('primary', mode === 'split');
    this.toolbar.querySelector('#inv-quick')?.classList.toggle('primary', mode === 'quick');
  }

  private cancelTouch(): void {
    if (this.touch) window.clearTimeout(this.touch.timer);
    this.touch = null;
  }

  private onTouchDown(e: PointerEvent): void {
    if (e.pointerType === 'mouse' || !this.isOpen || this.touch) return;
    // Toolbar buttons keep their own click handling.
    if (e.target instanceof Element && e.target.closest('.inv-touchbar')) return;
    // Suppresses the compatibility mouse events, so the mouse handlers never see this finger.
    e.preventDefault();
    const hit = this.slotAt(e.target);
    const t = { id: e.pointerId, x: e.clientX, y: e.clientY, target: e.target, timer: 0, done: false };
    if (hit) {
      t.timer = window.setTimeout(() => {
        // Long-press: like a right click (take half / put one).
        t.done = true;
        this.mouseX = t.x;
        this.mouseY = t.y;
        this.rightClick(hit.group, hit.index);
        this.render();
      }, LONG_PRESS_MS);
    }
    this.touch = t;
  }

  private onTouchMove(e: PointerEvent): void {
    const t = this.touch;
    if (!t || e.pointerId !== t.id) return;
    if (Math.hypot(e.clientX - t.x, e.clientY - t.y) > TOUCH_SLOP_PX) this.cancelTouch(); // scrolling
  }

  private onTouchUp(e: PointerEvent, cancelled: boolean): void {
    const t = this.touch;
    if (!t || e.pointerId !== t.id) return;
    this.cancelTouch();
    if (cancelled || t.done || !this.isOpen) return;
    this.mouseX = e.clientX;
    this.mouseY = e.clientY;
    this.tapAt(t.target, e);
  }

  /** A touch tap: the action depends on the toolbar mode. */
  tapAt(target: EventTarget | null, e: MouseEvent | null = null): void {
    const inv = this.session.inventory;
    const hit = this.slotAt(target);
    if (!hit) {
      if (inv.cursor && !(target instanceof Node && this.panel.contains(target))) {
        this.op({ kind: 'throw', one: this.touchMode === 'split' });
        this.render();
      }
      return;
    }
    if (this.touchMode === 'quick') this.shiftClick(hit.group, hit.index);
    else if (this.touchMode === 'split') this.rightClick(hit.group, hit.index);
    else this.click(hit.group, hit.index, e);
    this.render();
  }

  // --- Input ------------------------------------------------------------------------------------

  private slotAt(target: EventTarget | null): { group: Group; index: number } | null {
    const el = target instanceof Element ? target.closest<HTMLElement>('[data-group]') : null;
    if (!el || el === this.cursorEl) return null;
    return { group: el.dataset['group'] as Group, index: Number(el.dataset['index']) };
  }

  private onMouseDown(e: MouseEvent): void {
    e.preventDefault();
    if (!this.isOpen) return;
    const inv = this.session.inventory;
    const hit = this.slotAt(e.target);
    if (!hit) {
      // Outside the panel: throw the held stack (right click: just one).
      if (inv.cursor && !this.panel.contains(e.target as Node)) {
        this.op({ kind: 'throw', one: e.button !== 0 });
        this.render();
      }
      return;
    }
    const hadCursor = !!inv.cursor;
    if (e.button === 0 && e.shiftKey) this.shiftClick(hit.group, hit.index);
    else if (e.button === 0) this.click(hit.group, hit.index, e);
    else if (e.button === 2) this.rightClick(hit.group, hit.index);
    this.drag = e.button === 0 && !e.shiftKey ? { ...hit, pickedUp: !hadCursor && !!inv.cursor } : null;
    this.render();
  }

  /** Drag and drop: releasing a just-picked-up stack over another slot puts it there. */
  private onMouseUp(e: MouseEvent): void {
    const d = this.drag;
    this.drag = null;
    if (!this.isOpen || !d || e.button !== 0 || !d.pickedUp || !this.session.inventory.cursor) return;
    const hit = this.slotAt(e.target);
    if (!hit || (hit.group === d.group && hit.index === d.index)) return;
    this.click(hit.group, hit.index, e);
    this.render();
  }

  private onMouseMove(e: MouseEvent): void {
    this.mouseX = e.clientX;
    this.mouseY = e.clientY;
    this.hover = this.slotAt(e.target);
    this.placeCursor();
    this.updateTooltip();
  }

  private placeCursor(): void {
    this.cursorEl.style.transform = `translate(${this.mouseX}px, ${this.mouseY}px)`;
  }

  private stackAt(group: Group, index: number): Slot {
    switch (group) {
      case 'inv':
        return this.session.inventory.get(index);
      case 'grid':
        return this.session.craftGrid[index] ?? null;
      case 'out':
        return this.craftResult();
      case 'palette':
        return { item: index, count: 1, damage: 0 };
    }
  }

  private updateTooltip(): void {
    const h = this.hover;
    const stack = h && !this.session.inventory.cursor ? this.stackAt(h.group, h.index) : null;
    if (!stack) {
      this.tooltip.hidden = true;
      return;
    }
    this.tooltip.textContent = stackTooltip(stack);
    this.tooltip.hidden = false;
    const x = Math.min(this.mouseX + 14, window.innerWidth - this.tooltip.offsetWidth - 4);
    this.tooltip.style.transform = `translate(${Math.max(4, x)}px, ${this.mouseY + 14}px)`;
  }

  private click(group: Group, index: number, e: MouseEvent | null): void {
    this.op({ kind: 'click', group, index, ctrl: !!e?.ctrlKey });
  }

  private rightClick(group: Group, index: number): void {
    this.op({ kind: 'right', group, index });
  }

  private shiftClick(group: Group, index: number): void {
    this.op({ kind: 'shift', group, index });
  }
}
