import { BlockShape, getBlockDef, getItemDef } from '@voxel/shared';
import { TEXTURE_SIZE, generateBlockTextures } from '../render/proceduralTextures';
import { itemIconPixels } from '../render/itemIcons';

/** Icon image size in device pixels (displayed smaller with CSS). */
const ICON_PX = 64;

/** Isometric face brightness: top, left (front-left), right (front-right). */
const SHADE_TOP = 1.0;
const SHADE_LEFT = 0.78;
const SHADE_RIGHT = 0.62;

/** A canvas of one 16x16 RGBA image with its RGB multiplied by `shade`. */
function pixelsCanvas(data: Uint8Array, shade: number): HTMLCanvasElement {
  const c = document.createElement('canvas');
  c.width = TEXTURE_SIZE;
  c.height = TEXTURE_SIZE;
  const ctx = c.getContext('2d');
  if (!ctx) return c;
  const img = ctx.createImageData(TEXTURE_SIZE, TEXTURE_SIZE);
  for (let i = 0; i < data.length; i += 4) {
    img.data[i] = data[i]! * shade;
    img.data[i + 1] = data[i + 1]! * shade;
    img.data[i + 2] = data[i + 2]! * shade;
    img.data[i + 3] = data[i + 3]!;
  }
  ctx.putImageData(img, 0, 0);
  return c;
}

/**
 * Draws an isometric cube for a block using the same procedural textures as the world, so icons
 * always match what gets placed. Cross-shaped blocks (torches) are drawn as a flat sprite.
 */
function drawBlockIcon(ctx: CanvasRenderingContext2D, s: number, blockId: number): void {
  const layers = generateBlockTextures();
  const def = getBlockDef(blockId);
  if (def.shape === BlockShape.Cross) {
    const sprite = layers[def.textures.side];
    if (sprite) ctx.drawImage(pixelsCanvas(sprite, 1), 0, 0, s, s);
    return;
  }
  const top = layers[def.textures.top];
  const side = layers[def.textures.side];
  if (!top || !side) return;
  const m = s * 0.08; // margin
  const w = s - 2 * m; // cube width
  const h = w / 2; // half height of the top diamond
  const k = w / 2 / TEXTURE_SIZE; // texel -> pixel along the diamond edges
  const Tx = s / 2, Ty = m;
  const Lx = m, Ly = m + h / 2;
  const Cx = s / 2, Cy = m + h;
  const sideH = w * 0.55; // vertical edge length
  // Top face: u -> toward R, v -> toward L.
  ctx.setTransform(k, k / 2, -k, k / 2, Tx, Ty);
  ctx.drawImage(pixelsCanvas(top, SHADE_TOP), 0, 0);
  // Left face: origin L, u -> toward C, v -> straight down.
  ctx.setTransform(k, k / 2, 0, sideH / TEXTURE_SIZE, Lx, Ly);
  ctx.drawImage(pixelsCanvas(side, SHADE_LEFT), 0, 0);
  // Right face: origin C, u -> toward R, v -> straight down.
  ctx.setTransform(k, -k / 2, 0, sideH / TEXTURE_SIZE, Cx, Cy);
  ctx.drawImage(pixelsCanvas(side, SHADE_RIGHT), 0, 0);
  ctx.setTransform(1, 0, 0, 1, 0, 0);
}

const urls = new Map<number, string>();

/** A data URL of an item's icon (cached). Block items are isometric cubes; others are pixel art. */
export function itemIconUrl(itemId: number): string {
  const cached = urls.get(itemId);
  if (cached) return cached;
  const def = getItemDef(itemId);
  const canvas = document.createElement('canvas');
  canvas.width = ICON_PX;
  canvas.height = ICON_PX;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.imageSmoothingEnabled = false;
    if (def.block !== undefined) drawBlockIcon(ctx, ICON_PX, def.block);
    else {
      const px = itemIconPixels(def);
      if (px) ctx.drawImage(pixelsCanvas(px, 1), 0, 0, ICON_PX, ICON_PX);
    }
  }
  const url = canvas.toDataURL();
  urls.set(itemId, url);
  return url;
}

/** A small pixel-art HUD icon from string rows, as a data URL. '.' is transparent. */
export function pixelArtUrl(rows: readonly string[], palette: Record<string, string>, scale = 4): string {
  const h = rows.length;
  const w = Math.max(...rows.map((r) => r.length));
  const canvas = document.createElement('canvas');
  canvas.width = w * scale;
  canvas.height = h * scale;
  const ctx = canvas.getContext('2d');
  if (ctx) {
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const c = palette[rows[y]![x] ?? '.'];
        if (!c) continue;
        ctx.fillStyle = c;
        ctx.fillRect(x * scale, y * scale, scale, scale);
      }
    }
  }
  return canvas.toDataURL();
}
