import { MAX_AIR, MAX_HEALTH, MAX_HUNGER, type DamageCause, type MobTypeDef, type Vitals } from '@voxel/shared';
import { pixelArtUrl } from './icons';

/* Original 9x9 HUD pips. x = outline, the rest are fill/shine colours. */
const HEART = [
  '.xx...xx.',
  'xffx.xffx',
  'xfwfxfffx',
  'xfffffffx',
  'xfffffffx',
  '.xfffffx.',
  '..xfffx..',
  '...xfx...',
  '....x....',
];
const LOAF = [
  '.........',
  '..xxxxx..',
  '.xffwffx.',
  'xfwfffffx',
  'xfffffffx',
  'xfffffffx',
  'xdddddddx',
  '.xxxxxxx.',
  '.........',
];
const BUBBLE = [
  '..xxxxx..',
  '.xfffffx.',
  'xfwwffffx',
  'xfwffffx.',
  'xfffffffx',
  'xfffffffx',
  '.xfffffx.',
  '..xxxxx..',
  '.........',
];

/** Builds full / half / empty variants: the half variant uses `fill` for the left 5 columns. */
function variants(rows: string[], fill: string, shine: string, dark: string, empty: string): [string, string, string] {
  const half = rows.map((r) => [...r].map((ch, x) => (x >= 5 && 'fwd'.includes(ch) ? 'e' : ch)).join(''));
  const pal = { x: '#151515', f: fill, w: shine, d: dark, e: empty };
  return [
    pixelArtUrl(rows, pal),
    pixelArtUrl(half, pal),
    pixelArtUrl(rows.map((r) => r.replace(/[fwd]/g, 'e')), pal),
  ];
}

const DEATH_MESSAGES: Record<DamageCause, string> = {
  fall: 'You hit the ground too hard.',
  drown: 'You ran out of air.',
  starve: 'You starved.',
  void: 'You fell out of the world.',
  mob: 'You were defeated.',
  other: 'You died.',
};

/** A row of 10 pips showing `value` of `max` (each pip is 2 points, half pips for odd values). */
class PipRow {
  readonly el: HTMLDivElement;
  private readonly imgs: HTMLImageElement[] = [];
  private shown = -1;

  constructor(className: string, private readonly urls: [string, string, string], private readonly max: number, rightToLeft = false) {
    this.el = document.createElement('div');
    this.el.className = `hud-row ${className}`;
    for (let i = 0; i < 10; i++) {
      const img = document.createElement('img');
      img.alt = '';
      img.draggable = false;
      this.imgs.push(img);
    }
    this.el.append(...(rightToLeft ? [...this.imgs].reverse() : this.imgs));
  }

  set(value: number): void {
    const v = Math.max(0, Math.min(20, Math.ceil(value * (20 / this.max) - 1e-9)));
    if (v === this.shown) return;
    this.shown = v;
    this.imgs.forEach((img, i) => {
      const left = v - i * 2;
      img.src = this.urls[left >= 2 ? 0 : left === 1 ? 1 : 2];
    });
  }
}

/**
 * Survival HUD over the hotbar: health, hunger and (under water) air, a red vignette when hurt,
 * and the "You died" screen.
 */
export class Hud {
  private readonly root: HTMLDivElement;
  private readonly health: PipRow;
  private readonly hunger: PipRow;
  private readonly air: PipRow;
  private readonly vignette: HTMLDivElement;
  private readonly death: HTMLDivElement;
  private readonly deathText: HTMLParagraphElement;
  private flashTimer = 0;

  constructor(onRespawn: () => void, parent: HTMLElement = document.body) {
    this.root = document.createElement('div');
    this.root.className = 'hud';
    this.health = new PipRow('hud-health', variants(HEART, '#d42a2a', '#ff9a8a', '#8a1010', '#3a2222'), MAX_HEALTH);
    this.hunger = new PipRow('hud-hunger', variants(LOAF, '#c98a3c', '#f2cf86', '#8a5520', '#3a2e22'), MAX_HUNGER, true);
    this.air = new PipRow('hud-air', variants(BUBBLE, '#4aa0f0', '#d8f0ff', '#2a6ab0', 'transparent'), MAX_AIR);
    const left = document.createElement('div');
    left.className = 'hud-col';
    left.append(this.health.el);
    const right = document.createElement('div');
    right.className = 'hud-col hud-right';
    right.append(this.air.el, this.hunger.el);
    this.root.append(left, right);

    this.vignette = document.createElement('div');
    this.vignette.className = 'damage-vignette';

    this.death = document.createElement('div');
    this.death.className = 'death-screen';
    this.death.hidden = true;
    const title = document.createElement('h1');
    title.textContent = 'You died';
    this.deathText = document.createElement('p');
    const btn = document.createElement('button');
    btn.className = 'btn primary';
    btn.id = 'respawn';
    btn.textContent = 'Respawn';
    btn.addEventListener('click', () => onRespawn());
    this.death.append(title, this.deathText, btn);
    parent.append(this.vignette, this.root, this.death);
  }

  /** Call every frame. `survival` false hides the bars (creative). */
  update(v: Vitals, survival: boolean, dt: number): void {
    this.root.hidden = !survival;
    if (survival) {
      this.health.set(v.health);
      this.hunger.set(v.hunger);
      this.air.el.style.visibility = v.air < MAX_AIR ? 'visible' : 'hidden';
      this.air.set(v.air);
      this.root.classList.toggle('low-health', v.health <= 4 && v.health > 0);
    }
    if (this.flashTimer > 0) {
      this.flashTimer = Math.max(0, this.flashTimer - dt);
      this.vignette.style.opacity = String(Math.min(1, this.flashTimer / 0.5));
    }
  }

  /** Red vignette pulse; stronger for bigger hits. */
  flashDamage(amount: number): void {
    this.flashTimer = Math.max(this.flashTimer, Math.min(1, 0.35 + amount * 0.08));
    this.vignette.style.opacity = '1';
  }

  get deathShown(): boolean {
    return !this.death.hidden;
  }

  /** `attacker`: the mob that dealt the killing blow ('mob' deaths), named in the message. */
  showDeath(cause: DamageCause | undefined, attacker?: MobTypeDef): void {
    this.deathText.textContent = cause === 'mob' && attacker ? `You were ${attacker.killVerb}.` : DEATH_MESSAGES[cause ?? 'other'];
    this.death.hidden = false;
    document.body.classList.add('is-dead');
    this.death.querySelector<HTMLButtonElement>('#respawn')?.focus();
  }

  hideDeath(): void {
    this.death.hidden = true;
    document.body.classList.remove('is-dead');
  }

  dispose(): void {
    this.root.remove();
    this.vignette.remove();
    this.death.remove();
    document.body.classList.remove('is-dead');
  }
}
