import { PLAYER_EYE_HEIGHT, vec3, type PlayerInput } from '@voxel/shared';
import type { PlayerIntent } from '../input/intent';
import type { Camera } from './camera';
import type { GameSession } from './session';

/**
 * Drives the session's local player from the device-independent `PlayerIntent` (Milestone 9;
 * keyboard + mouse and touch both fill it).
 * - `frame()` runs every rendered frame: look and the fly toggle (so nothing feels tick-limited
 *   and no press is missed between ticks).
 * - `tick()` runs every fixed tick: builds a `PlayerInput` and runs the shared physics step, then
 *   moves the camera eye so `Camera` can interpolate between the previous and current tick.
 */
export class PlayerController {
  private readonly input: PlayerInput = { forward: 0, strafe: 0, jump: false, sprint: false, sneak: false, yaw: 0 };
  /** Set when the physics was held back this tick because nearby chunks are not loaded. */
  waitingForChunks = true;
  /** False while a screen (inventory) is open: the player stands still, keys are ignored. */
  controlsEnabled = true;

  constructor(
    private readonly session: GameSession,
    private readonly camera: Camera,
    /** Refilled every animation frame by `Controls.sample` (read live, never copied). */
    private readonly intent: PlayerIntent,
  ) {}

  get flying(): boolean {
    return this.session.player.flying;
  }

  setFlying(on: boolean): void {
    const p = this.session.player;
    p.flying = on;
    p.vy = 0;
  }

  /** Per frame: look, and the fly toggle (F / double-tap Space / touch button; creative only). */
  frame(): void {
    const i = this.intent;
    if (!this.controlsEnabled || this.session.dead) return;
    if (i.lookYaw !== 0 || i.lookPitch !== 0) this.camera.addLook(i.lookYaw, i.lookPitch);
    if (this.session.creative && i.toggleFly) this.setFlying(!this.flying);
  }

  /** Per tick. */
  tick(dt: number): void {
    const { session, camera, intent, input } = this;
    const p = session.player;
    vec3.copy(camera.prevPosition, camera.position);

    const wasSpawned = session.spawned;
    if (!session.trySpawn()) {
      this.waitingForChunks = true;
      return;
    }
    if (!wasSpawned) {
      // First spawn: jump the camera there instead of interpolating from the waiting position.
      this.syncCamera();
      vec3.copy(camera.prevPosition, camera.position);
    }
    // Hold still until the chunks around the player exist, so we never fall through missing ground.
    this.waitingForChunks = !session.isAreaLoaded(p.x, p.z);
    if (!this.waitingForChunks) {
      const on = this.controlsEnabled;
      input.forward = on ? intent.moveZ : 0;
      input.strafe = on ? intent.moveX : 0;
      input.jump = on && intent.jump;
      input.sprint = on && intent.sprint;
      input.sneak = on && intent.sneak;
      input.yaw = camera.yaw;
      if (session.movePlayer(input, dt)) {
        this.snapCamera();
        return;
      }
    }
    this.syncCamera();
  }

  /** Moves the camera to the player without interpolation (after a teleport or respawn). */
  snapCamera(): void {
    this.syncCamera();
    vec3.copy(this.camera.prevPosition, this.camera.position);
  }

  /** Puts the camera eye at the player's eye; call after teleports too. */
  syncCamera(): void {
    const p = this.session.player;
    vec3.set(this.camera.position, p.x, p.y + PLAYER_EYE_HEIGHT, p.z);
  }
}
