/**
 * Mob simulation (Milestone 8): spawning, AI, steering, physics, combat, projectiles, saving.
 * Pure TS with no DOM; deterministic for a given RNG and inputs, so the Milestone 10 server can run
 * the same code. The world is reached through `MobWorld`, the player through `MobTickInput`, and
 * effects on the game (hurting the player, dropping loot) through `MobHooks`.
 *
 * Documented choices:
 * - Mobs in unloaded chunks are frozen (not simulated) and kept; every living mob is saved in the
 *   world meta whether its chunk is loaded or not. Far hostiles (> 128 blocks) are despawned.
 * - Hostiles burn in direct daylight (1 HP/s while sky-exposed by day); in caves they survive.
 *   By day they can only spawn in dark caves, at a reduced cap and rate, so they mostly appear at night.
 * - Path searches are budgeted (MAX_PATHS_PER_TICK, node budget per search) and throttled per mob
 *   (recomputed every 1-1.6 s, or sooner when the target moved more than 2 blocks).
 */
import { BLOCK_OPAQUE, BlockId } from '../world/blocks';
import { MAX_Y, MIN_Y } from '../world/chunk';
import { stepBody, type BodyParams } from '../physics/body';
import { GRAVITY, JUMP_VELOCITY, isSolidBlock, type BlockGetter } from '../physics/player';
import { raycastBlocks } from '../physics/raycast';
import type { ItemStack } from '../items/items';
import { EntityStore } from '../entity/entities';
import { MOB_TYPES, mobTypeByName, type MobTypeDef } from './mobTypes';
import { createMob, isAlive, mobAabb, type AiState, type Mob } from './mob';
import { nextAiState, stateDurationFor, type Perception } from './ai';
import { findPath, isStandable, type PathNode, type PathResult } from './pathfinding';
import { rayVsAabb, rollDrops } from './combat';
import { hostileSpawnAllowed, inViewCone, passiveSpawnAllowed } from './spawnRules';

export interface MobWorld {
  getBlock: BlockGetter;
  /** Whether the chunk holding column (x, z) is loaded. */
  isLoaded(x: number, z: number): boolean;
  getSkyLight(x: number, y: number, z: number): number;
  getBlockLight(x: number, y: number, z: number): number;
}

/** The player as mobs see it. Position is the feet. */
export interface MobTarget {
  /** Player id (multiplayer); passed back through `MobHooks.hurtPlayer`. */
  id?: number;
  x: number;
  y: number;
  z: number;
  halfWidth: number;
  height: number;
  eyeHeight: number;
  /** Alive and in survival: hostiles may attack. Creative / dead players are ignored. */
  targetable: boolean;
  /** Horizontal look direction (for "never spawn in view"). */
  lookX: number;
  lookZ: number;
}

export interface MobTickInput {
  /** Daylight factor 0.16..1 (`daylightFactor(time.dayFraction)`). */
  daylight: number;
  /** The single player (single-player); ignored when `players` is given. */
  player?: MobTarget | undefined;
  /**
   * Every player (multiplayer, Milestone 10). Each mob targets the nearest targetable player (or,
   * when none is targetable, simply the nearest one); spawning runs around each player.
   */
  players?: readonly MobTarget[];
  /** Natural spawning on/off (default on). */
  spawning?: boolean;
}

export interface MobHooks {
  /** A mob (or its projectile) hit the player. Knockback is a horizontal velocity. */
  hurtPlayer(amount: number, attacker: MobTypeDef, knockX: number, knockZ: number, target?: MobTarget): void;
  /** Loot from a dying mob. */
  dropItem(stack: ItemStack, x: number, y: number, z: number): void;
}

export interface Projectile {
  readonly id: number;
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  age: number;
  damage: number;
  knockback: number;
  source: MobTypeDef;
  /** Player the projectile was aimed at (informational). */
  targetId?: number;
}

export interface SavedMob {
  /** Mob type name. */
  type: string;
  x: number;
  y: number;
  z: number;
  health: number;
  yaw: number;
  age: number;
}

export type HurtResult = 'ignored' | 'hurt' | 'killed';

/** Seconds the death tip-over plays before the body is removed. */
export const DEATH_SECONDS = 1.0;
/** Length of the red hurt flash; the first INVULNERABLE_SECONDS of it ignore further hits. */
export const HURT_FLASH_SECONDS = 0.5;
export const INVULNERABLE_SECONDS = 0.25;
export const HOSTILE_CAP = 15;
/** By day (dark caves only) the hostile cap is this fraction of HOSTILE_CAP, with 1 attempt/s instead of 4. */
export const DAY_HOSTILE_CAP_FACTOR = 0.3;
/** Passive mobs within PASSIVE_AREA_RADIUS of the player, and in total. */
export const PASSIVE_AREA_CAP = 10;
export const PASSIVE_AREA_RADIUS = 64;
export const PASSIVE_CAP = 40;
export const DESPAWN_DISTANCE = 128;
export const MAX_PATHS_PER_TICK = 4;
export const CHASE_PATH_NODES = 600;
export const WANDER_PATH_NODES = 160;
const PROJECTILE_GRAVITY = 10;
const PROJECTILE_LIFETIME = 4;
const LOS_INTERVAL = 0.3;
const ATTACK_WINDUP = 0.5;
const TURN_RATE = 10;
const BURN_MIN_SKY = 14;
const BURN_MIN_DAYLIGHT = 0.6;

function approach(rate: number, dt: number): number {
  return 1 - Math.exp(-rate * dt);
}

function wrapAngle(a: number): number {
  a = (a + Math.PI) % (Math.PI * 2);
  if (a < 0) a += Math.PI * 2;
  return a - Math.PI;
}

/** Yaw that faces direction (dx, dz): 0 = -Z, positive toward +X. */
export function yawToward(dx: number, dz: number): number {
  return Math.atan2(dx, -dz);
}

const bodyParamsCache = new Map<MobTypeDef, BodyParams>();
function bodyParams(t: MobTypeDef): BodyParams {
  let p = bodyParamsCache.get(t);
  if (!p) {
    // Horizontal motion is driven by the steering code (which also decays knockback), so the body
    // itself has no ground friction or air drag.
    p = { halfWidth: t.halfWidth, height: t.height, gravity: GRAVITY, terminal: 60, groundFriction: 0, airDrag: 0, waterDrag: 2, buoyancy: 5 };
    bodyParamsCache.set(t, p);
  }
  return p;
}

let nextProjectileId = 1;
const NO_PLAYERS: readonly MobTarget[] = [];

export class MobSystem {
  readonly entities = new EntityStore<Mob>();
  readonly projectiles: Projectile[] = [];
  hooks: MobHooks = { hurtPlayer: () => {}, dropItem: () => {} };
  readonly stats = {
    pathSearches: 0,
    lastPathNodes: 0,
    lastPathMs: 0,
    pathsThisTick: 0,
    lastTickMs: 0,
    avgTickMs: 0,
    spawned: 0,
    killed: 0,
    despawned: 0,
  };
  /** Tunables (tests and the debug overlay may change them). */
  readonly config = {
    hostileCap: HOSTILE_CAP,
    passiveAreaCap: PASSIVE_AREA_CAP,
    passiveCap: PASSIVE_CAP,
    maxPathsPerTick: MAX_PATHS_PER_TICK,
  };
  private hostileTimer = 0;
  private passiveTimer = 0;
  /** Reused by `separate` (no per-tick array). */
  private readonly scratch: Mob[] = [];
  private pathBudget = 0;

  constructor(
    private readonly world: MobWorld,
    private readonly rand: () => number = Math.random,
    /** Clock in ms for stats only (performance.now on the client); never affects the simulation. */
    private readonly now: () => number = () => 0,
  ) {}

  get count(): number {
    return this.entities.size;
  }

  /** Living mobs by type name. */
  countsByType(): Record<string, number> {
    const out: Record<string, number> = {};
    for (const m of this.entities) if (isAlive(m)) out[m.type.name] = (out[m.type.name] ?? 0) + 1;
    return out;
  }

  clear(): void {
    this.entities.clear();
    this.projectiles.length = 0;
  }

  /** Adds a mob of `type` with its feet at (x, y, z). */
  spawn(type: MobTypeDef | string, x: number, y: number, z: number, yaw = this.rand() * Math.PI * 2): Mob {
    const def = typeof type === 'string' ? mobTypeByName(type) : type;
    if (!def) throw new Error(`Unknown mob type '${String(type)}'`);
    const m = createMob(def, x, y, z, wrapAngle(yaw));
    m.ai.stateDuration = stateDurationFor(m, 'idle', this.rand());
    this.stats.spawned++;
    return this.entities.add(m);
  }

  // --- Simulation ---------------------------------------------------------------------------------

  tick(dt: number, input: MobTickInput): void {
    const t0 = this.now();
    this.pathBudget = this.config.maxPathsPerTick;
    this.stats.pathsThisTick = 0;
    const players = input.players ?? (input.player ? [input.player] : NO_PLAYERS);
    if (input.spawning !== false && players.length > 0) this.spawnTick(dt, input.daylight, players);

    for (const m of this.entities) {
      if (m.removed) continue;
      m.prevX = m.x;
      m.prevY = m.y;
      m.prevZ = m.z;
      m.prevYaw = m.yaw;
      if (!this.areaLoaded(m.x, m.z)) continue; // frozen in unloaded chunks
      if (m.health.deathTime >= 0) {
        m.health.deathTime += dt;
        m.health.hurtTime = Math.max(0, m.health.hurtTime - dt);
        if (m.health.deathTime >= DEATH_SECONDS) this.entities.remove(m);
        else this.physics(m, 0, 0, false, dt);
        continue;
      }
      m.age += dt;
      if (m.type.hostile && players.length > 0 && players.every((p) => Math.hypot(m.x - p.x, m.z - p.z) > DESPAWN_DISTANCE)) {
        this.entities.remove(m);
        this.stats.despawned++;
        continue;
      }
      this.updateHealth(m, dt, input.daylight);
      if (m.health.deathTime >= 0) continue;
      this.think(m, dt, this.chooseTarget(m, players));
    }
    this.separate();
    this.tickProjectiles(dt, players);
    const ms = this.now() - t0;
    this.stats.lastTickMs = ms;
    this.stats.avgTickMs += (ms - this.stats.avgTickMs) * 0.05;
  }

  /**
   * The player a mob pays attention to: the nearest targetable one for hostiles (if any), otherwise
   * the nearest player. With one player this is always that player.
   */
  private chooseTarget(m: Mob, players: readonly MobTarget[]): MobTarget | undefined {
    if (players.length <= 1) return players[0];
    let best: MobTarget | undefined;
    let bestD = Infinity;
    let bestT: MobTarget | undefined;
    let bestTD = Infinity;
    for (const p of players) {
      const d = (p.x - m.x) ** 2 + (p.y - m.y) ** 2 + (p.z - m.z) ** 2;
      if (d < bestD) { bestD = d; best = p; }
      if (p.targetable && d < bestTD) { bestTD = d; bestT = p; }
    }
    return m.type.hostile && bestT ? bestT : best;
  }

  /** Whether the chunks around (x, z) are loaded (mobs near unloaded edges freeze). */
  private areaLoaded(x: number, z: number): boolean {
    const w = this.world;
    return w.isLoaded(x - 2, z - 2) && w.isLoaded(x + 2, z - 2) && w.isLoaded(x - 2, z + 2) && w.isLoaded(x + 2, z + 2);
  }

  private updateHealth(m: Mob, dt: number, daylight: number): void {
    const h = m.health;
    h.hurtTime = Math.max(0, h.hurtTime - dt);
    h.burning = false;
    if (m.type.behaviour.burnsInDaylight && daylight > BURN_MIN_DAYLIGHT && !m.inWater) {
      const sky = this.world.getSkyLight(Math.floor(m.x), Math.floor(m.y + m.type.eyeHeight), Math.floor(m.z));
      h.burning = sky >= BURN_MIN_SKY;
    }
    if (h.burning) {
      h.burnTimer += dt;
      if (h.burnTimer >= 1) {
        h.burnTimer -= 1;
        this.hurt(m, 1);
      }
    } else {
      h.burnTimer = 0;
    }
  }

  /** Perception for the AI this tick (also refreshes the line-of-sight cache). */
  perceive(m: Mob, dt: number, p: MobTarget | undefined): Perception {
    const ai = m.ai;
    const wasHit = ai.hurtFrom !== null;
    if (!p) return { targetable: false, targetDistance: Infinity, edgeDistance: Infinity, targetDy: 0, canSee: false, wasHit };
    const ex = m.x, ey = m.y + m.type.eyeHeight, ez = m.z;
    const dx = p.x - ex, dy = p.y + p.eyeHeight - ey, dz = p.z - ez;
    const dist = Math.hypot(dx, dy, dz);
    const horiz = Math.hypot(dx, dz);
    ai.losTimer -= dt;
    if (m.type.hostile && p.targetable && dist <= m.type.behaviour.sightRange * 1.5) {
      if (ai.losTimer <= 0) {
        ai.losTimer = LOS_INTERVAL;
        ai.canSee = raycastBlocks(this.world.getBlock, ex, ey, ez, dx, dy, dz, dist, (id) => BLOCK_OPAQUE[id] === 1) === null;
      }
    } else {
      ai.canSee = false;
    }
    return {
      targetable: p.targetable,
      targetDistance: dist,
      edgeDistance: Math.max(0, horiz - p.halfWidth - m.type.halfWidth),
      targetDy: p.y - m.y,
      canSee: ai.canSee,
      wasHit,
    };
  }

  private enterState(m: Mob, s: AiState): void {
    const ai = m.ai;
    ai.state = s;
    ai.stateTime = 0;
    ai.stateDuration = stateDurationFor(m, s, this.rand());
    ai.path = null;
    ai.pathIndex = 0;
    ai.goal = null;
    ai.repathTimer = 0;
    ai.stuckTime = 0;
    // A short wind-up before the first hit / shot.
    if (s === 'attack') ai.attackCooldown = Math.max(ai.attackCooldown, ATTACK_WINDUP);
    if (s === 'flee') ai.fleeFrom = ai.hurtFrom ?? { x: m.x + (this.rand() - 0.5), z: m.z + (this.rand() - 0.5) };
  }

  private think(m: Mob, dt: number, player: MobTarget | undefined): void {
    const ai = m.ai;
    const per = this.perceive(m, dt, player);
    ai.stateTime += dt;
    ai.attackCooldown = Math.max(0, ai.attackCooldown - dt);
    ai.knockbackTime = Math.max(0, ai.knockbackTime - dt);
    ai.swingTime = Math.max(0, ai.swingTime - dt);
    ai.repathTimer -= dt;
    const next = nextAiState(m, per);
    if (next !== ai.state || (next === 'flee' && per.wasHit)) this.enterState(m, next);
    ai.hurtFrom = null;

    const t = m.type;
    let speed = 0;
    let dirX = 0, dirZ = 0;
    let jump = false;
    let lookAt: { x: number; y: number; z: number } | undefined;
    const playerEye = player ? { x: player.x, y: player.y + player.eyeHeight, z: player.z } : undefined;

    const steer = (r: { dx: number; dz: number; jump: boolean } | null, s: number): boolean => {
      if (!r) return false;
      dirX = r.dx;
      dirZ = r.dz;
      jump = r.jump;
      speed = s;
      return true;
    };

    switch (ai.state) {
      case 'idle':
        if (playerEye && !t.hostile && Math.hypot(playerEye.x - m.x, playerEye.z - m.z) < 8) lookAt = playerEye;
        break;
      case 'wander': {
        if (!ai.goal && ai.repathTimer <= 0) {
          const goal = this.pickWanderGoal(m);
          if (goal) this.computePath(m, goal, WANDER_PATH_NODES, true, 0);
          else ai.stateTime = ai.stateDuration; // nowhere to go: back to idle
          ai.repathTimer = 1;
        }
        if (!steer(this.followPath(m, dt), t.speed) && ai.goal) ai.stateTime = ai.stateDuration;
        break;
      }
      case 'flee': {
        const from = ai.fleeFrom ?? { x: m.x, z: m.z };
        if (!ai.goal && ai.repathTimer <= 0) {
          ai.repathTimer = 1;
          const goal = this.pickFleeGoal(m, from);
          if (goal) this.computePath(m, goal, WANDER_PATH_NODES, true, 1);
        }
        const fs = t.speed * t.behaviour.fleeSpeedFactor;
        if (!steer(this.followPath(m, dt), fs)) {
          // No (more) path: run straight away from the attacker.
          const ax = m.x - from.x, az = m.z - from.z;
          const len = Math.hypot(ax, az) || 1;
          dirX = ax / len;
          dirZ = az / len;
          speed = fs;
          ai.goal = null;
        }
        break;
      }
      case 'chase':
      case 'attack': {
        if (!player || !playerEye) break;
        lookAt = playerEye;
        const cs = t.speed * t.behaviour.chaseSpeedFactor;
        const atk = t.behaviour.attack;
        const hx = player.x - m.x, hz = player.z - m.z;
        const hd = Math.hypot(hx, hz) || 1;
        const sameLevel = Math.abs(player.y - m.y) < 1.1;
        if (ai.state === 'attack' && atk?.kind === 'ranged') {
          // Hold position at the preferred distance and shoot.
          if (hd < atk.preferredDistance - 2) {
            dirX = -hx / hd;
            dirZ = -hz / hd;
            speed = t.speed;
          }
          if (ai.attackCooldown <= 0 && per.canSee) {
            this.shoot(m, player, atk.damage, atk.projectileSpeed, atk.knockback);
            ai.attackCooldown = atk.cooldown;
            ai.swingTime = 0.3;
          }
          break;
        }
        if (ai.state === 'attack' || (per.canSee && sameLevel && hd < 3)) {
          // Close and in sight: walk straight at the player.
          dirX = hx / hd;
          dirZ = hz / hd;
          speed = cs;
          ai.path = null;
          ai.goal = null;
          if (ai.state === 'attack' && atk?.kind === 'melee') {
            if (per.edgeDistance < 0.15) speed = 0; // already touching
            if (ai.attackCooldown <= 0 && per.edgeDistance <= atk.reach && Math.abs(per.targetDy) < 1.6) {
              const kx = (hx / hd) * atk.knockback;
              const kz = (hz / hd) * atk.knockback;
              this.hooks.hurtPlayer(atk.damage, t, kx, kz, player);
              ai.attackCooldown = atk.cooldown;
              ai.swingTime = 0.35;
            }
          }
        } else {
          const goal = this.groundCellBelow(player.x, player.y, player.z);
          const moved = ai.goal ? Math.max(Math.abs(ai.goal.x - goal.x), Math.abs(ai.goal.z - goal.z), Math.abs(ai.goal.y - goal.y)) : Infinity;
          if (ai.repathTimer <= 0 || (moved > 2 && ai.repathTimer < 0.75)) {
            if (this.computePath(m, goal, CHASE_PATH_NODES, true, 1)) ai.repathTimer = 1 + this.rand() * 0.6;
          }
          if (!steer(this.followPath(m, dt), cs) && per.canSee) {
            // Path finished or none (e.g. budget exhausted this tick): head straight for the player.
            dirX = hx / hd;
            dirZ = hz / hd;
            speed = cs;
          }
        }
        break;
      }
      default:
        break;
    }

    // Jump over a 1-block step we walked into.
    if (ai.blocked && m.onGround && speed > 0 && this.stepAhead(m, dirX, dirZ)) jump = true;
    this.physics(m, dirX * speed, dirZ * speed, jump, dt);

    // Turn the body toward where it is going (or, attacking, toward the target).
    let wantYaw: number | undefined;
    if (speed > 0.05) wantYaw = yawToward(dirX, dirZ);
    else if (lookAt && (ai.state === 'attack' || ai.state === 'chase')) wantYaw = yawToward(lookAt.x - m.x, lookAt.z - m.z);
    if (wantYaw !== undefined) {
      const d = wrapAngle(wantYaw - m.yaw);
      const maxTurn = TURN_RATE * dt;
      m.yaw = wrapAngle(m.yaw + Math.max(-maxTurn, Math.min(maxTurn, d)));
    }
    this.animate(m, dt, lookAt);
  }

  /** Steering + physics: approaches the wanted horizontal velocity, then steps the body. */
  private physics(m: Mob, wantVx: number, wantVz: number, jump: boolean, dt: number): void {
    const ai = m.ai;
    const rate = ai.knockbackTime > 0 ? 1.5 : m.inWater ? 6 : m.onGround ? 14 : 2;
    const k = approach(rate, dt);
    m.vx += (wantVx - m.vx) * k;
    m.vz += (wantVz - m.vz) * k;
    if (jump && m.onGround) m.vy = JUMP_VELOCITY;
    if (m.inWater && (jump || ai.blocked) && (wantVx !== 0 || wantVz !== 0)) m.vy = Math.max(m.vy, 5);
    const wantMove = Math.hypot(wantVx, wantVz) > 0.1;
    const bvx = m.vx, bvz = m.vz;
    stepBody(m, bodyParams(m.type), this.world.getBlock, dt);
    // stepBody zeroes a velocity component on collision: remember it to jump next tick.
    ai.blocked = wantMove && ((bvx !== 0 && m.vx === 0) || (bvz !== 0 && m.vz === 0));
  }

  /** Whether a 1-block step (solid at the feet, clear above) lies just ahead in direction (dx, dz). */
  private stepAhead(m: Mob, dx: number, dz: number): boolean {
    const g = this.world.getBlock;
    const reach = m.type.halfWidth + 0.3;
    const x = Math.floor(m.x + dx * reach), z = Math.floor(m.z + dz * reach);
    const y = Math.floor(m.y + 0.01);
    const h = Math.ceil(m.type.height);
    if (!isSolidBlock(g(x, y, z))) return false;
    for (let i = 1; i <= h; i++) if (isSolidBlock(g(x, y + i, z))) return false;
    // Head room above the mob itself for the jump.
    if (isSolidBlock(g(Math.floor(m.x), y + h, Math.floor(m.z)))) return false;
    return true;
  }

  private animate(m: Mob, dt: number, lookAt: { x: number; y: number; z: number } | undefined): void {
    const a = m.anim;
    let hy = 0, hp = 0;
    if (lookAt) {
      const dx = lookAt.x - m.x, dz = lookAt.z - m.z;
      const dy = lookAt.y - (m.y + m.type.eyeHeight);
      hy = Math.max(-1.2, Math.min(1.2, wrapAngle(yawToward(dx, dz) - m.yaw)));
      hp = Math.max(-0.8, Math.min(0.8, Math.atan2(dy, Math.hypot(dx, dz))));
    }
    const k = approach(10, dt);
    a.headYaw += (hy - a.headYaw) * k;
    a.headPitch += (hp - a.headPitch) * k;
    const hs = Math.hypot(m.x - m.prevX, m.z - m.prevZ) / Math.max(dt, 1e-6);
    if (m.onGround || m.inWater) a.walkPhase = (a.walkPhase + hs * dt * 5) % (Math.PI * 2);
    a.walkAmount += (Math.min(1, hs / Math.max(0.5, m.type.speed)) - a.walkAmount) * approach(8, dt);
  }

  // --- Paths --------------------------------------------------------------------------------------

  /** Feet cell of the ground below (x, y, z): drops through air up to 6 blocks (players mid-jump). */
  private groundCellBelow(x: number, y: number, z: number): PathNode {
    const bx = Math.floor(x), bz = Math.floor(z);
    let by = Math.floor(y + 0.01);
    for (let i = 0; i < 6 && by > MIN_Y + 1 && !isSolidBlock(this.world.getBlock(bx, by - 1, bz)) && this.world.getBlock(bx, by, bz) !== BlockId.Water; i++) by--;
    return { x: bx, y: by, z: bz };
  }

  /** Runs a budgeted A* search; stores the path on the mob. Returns false when out of budget. */
  computePath(m: Mob, goal: PathNode, maxNodes: number, allowPartial: boolean, tolerance: number): boolean {
    if (this.pathBudget <= 0) return false;
    this.pathBudget--;
    const start = { x: Math.floor(m.x), y: Math.floor(m.y + 0.01), z: Math.floor(m.z) };
    const t0 = this.now();
    const r: PathResult = findPath(this.world.getBlock, start, goal, { maxNodes, allowPartial, goalTolerance: tolerance, clearance: Math.max(1, Math.ceil(m.type.height)) });
    this.stats.lastPathMs = this.now() - t0;
    this.stats.lastPathNodes = r.nodes;
    this.stats.pathSearches++;
    this.stats.pathsThisTick++;
    m.ai.path = r.path;
    m.ai.pathIndex = 0;
    m.ai.goal = goal;
    m.ai.stuckTime = 0;
    return true;
  }

  /** Direction toward the next waypoint (and whether to jump), or null when there is no path left. */
  private followPath(m: Mob, dt: number): { dx: number; dz: number; jump: boolean } | null {
    const ai = m.ai;
    const path = ai.path;
    if (!path) return null;
    while (ai.pathIndex < path.length) {
      const n = path[ai.pathIndex]!;
      const d = Math.hypot(n.x + 0.5 - m.x, n.z + 0.5 - m.z);
      if (d < 0.35 && Math.abs(n.y - m.y) < 1.2) {
        ai.pathIndex++;
        ai.stuckTime = 0;
        continue;
      }
      break;
    }
    if (ai.pathIndex >= path.length) {
      ai.path = null;
      return null;
    }
    const n = path[ai.pathIndex]!;
    const dx = n.x + 0.5 - m.x, dz = n.z + 0.5 - m.z;
    const d = Math.hypot(dx, dz) || 1;
    // Stuck detection: barely moving while trying to.
    const moved = Math.hypot(m.x - m.prevX, m.z - m.prevZ);
    ai.stuckTime = moved < 0.01 && m.ai.knockbackTime <= 0 ? ai.stuckTime + dt : 0;
    if (ai.stuckTime > 1.5) {
      ai.path = null;
      ai.goal = null;
      ai.repathTimer = 0;
      ai.stuckTime = 0;
      return null;
    }
    const jump = n.y > m.y + 0.5 && d < 1.6;
    return { dx: dx / d, dz: dz / d, jump };
  }

  /** A standable cell 3-10 blocks away, at about the same height. */
  private pickWanderGoal(m: Mob): PathNode | undefined {
    const clearance = Math.max(1, Math.ceil(m.type.height));
    for (let attempt = 0; attempt < 6; attempt++) {
      const a = this.rand() * Math.PI * 2;
      const r = 3 + this.rand() * 7;
      const cell = this.standableNear(Math.floor(m.x + Math.cos(a) * r), Math.floor(m.y), Math.floor(m.z + Math.sin(a) * r), clearance, 3);
      if (cell && this.world.getBlock(cell.x, cell.y, cell.z) !== BlockId.Water) return cell;
    }
    return undefined;
  }

  private pickFleeGoal(m: Mob, from: { x: number; z: number }): PathNode | undefined {
    const clearance = Math.max(1, Math.ceil(m.type.height));
    const base = Math.atan2(m.z - from.z, m.x - from.x);
    for (let attempt = 0; attempt < 5; attempt++) {
      const a = base + (this.rand() - 0.5) * 1.6;
      const r = 8 + this.rand() * 4;
      const cell = this.standableNear(Math.floor(m.x + Math.cos(a) * r), Math.floor(m.y), Math.floor(m.z + Math.sin(a) * r), clearance, 4);
      if (cell) return cell;
    }
    return undefined;
  }

  /** The standable cell in column (x, z) closest to y within +-range. */
  private standableNear(x: number, y: number, z: number, clearance: number, range: number): PathNode | undefined {
    if (!this.world.isLoaded(x, z)) return undefined;
    for (let d = 0; d <= range; d++) {
      for (const yy of d === 0 ? [y] : [y + d, y - d]) {
        if (yy > MIN_Y && yy < MAX_Y - 1 && isStandable(this.world.getBlock, x, yy, z, clearance)) return { x, y: yy, z };
      }
    }
    return undefined;
  }

  // --- Combat -------------------------------------------------------------------------------------

  /**
   * Damages a mob. `from` (the attacker's position) and `knockback` (blocks/s) push it away.
   * Ignored while dead or within the invulnerability window after the previous hit.
   */
  hurt(m: Mob, amount: number, from?: { x: number; z: number }, knockback = 0): HurtResult {
    const h = m.health;
    if (!isAlive(m) || amount <= 0) return 'ignored';
    if (h.hurtTime > HURT_FLASH_SECONDS - INVULNERABLE_SECONDS) return 'ignored';
    h.hp -= amount;
    h.hurtTime = HURT_FLASH_SECONDS;
    m.ai.hurtFrom = from ? { x: from.x, z: from.z } : { x: m.x - Math.sin(m.yaw), z: m.z + Math.cos(m.yaw) };
    if (from && knockback > 0) {
      let dx = m.x - from.x, dz = m.z - from.z;
      const len = Math.hypot(dx, dz);
      if (len < 1e-6) { dx = 0; dz = 1; } else { dx /= len; dz /= len; }
      m.vx = dx * knockback;
      m.vz = dz * knockback;
      m.vy = Math.max(m.vy, 4.5);
      m.ai.knockbackTime = 0.4;
    }
    if (h.hp <= 0) {
      this.kill(m);
      return 'killed';
    }
    return 'hurt';
  }

  /** Starts the death animation and drops loot. */
  private kill(m: Mob): void {
    const h = m.health;
    h.hp = 0;
    h.deathTime = 0;
    h.burning = false;
    m.ai.state = 'dead';
    m.ai.path = null;
    this.stats.killed++;
    for (const s of rollDrops(m.type.drops, this.rand)) this.hooks.dropItem(s, m.x, m.y + 0.5, m.z);
  }

  /** Nearest living mob hit by a ray within `maxDist`, with the distance. */
  raycast(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, maxDist: number): { mob: Mob; distance: number } | null {
    let best: { mob: Mob; distance: number } | null = null;
    for (const m of this.entities) {
      if (!isAlive(m)) continue;
      const t = rayVsAabb(ox, oy, oz, dx, dy, dz, mobAabb(m), best ? best.distance : maxDist);
      if (t !== null && (!best || t < best.distance)) best = { mob: m, distance: t };
    }
    return best;
  }

  private shoot(m: Mob, p: MobTarget, damage: number, speed: number, knockback: number): void {
    const ox = m.x - Math.sin(m.yaw) * (m.type.halfWidth + 0.1);
    const oz = m.z + Math.cos(m.yaw) * (m.type.halfWidth + 0.1);
    const oy = m.y + m.type.eyeHeight;
    const tx = p.x, ty = p.y + p.height * 0.6, tz = p.z;
    const dx = tx - ox, dy = ty - oy, dz = tz - oz;
    const dist = Math.hypot(dx, dy, dz) || 1;
    const time = dist / speed;
    this.projectiles.push({
      id: nextProjectileId++,
      x: ox, y: oy, z: oz,
      vx: dx / time,
      vy: dy / time + 0.5 * PROJECTILE_GRAVITY * time, // lead for the drop
      vz: dz / time,
      age: 0,
      damage,
      knockback,
      source: m.type,
      targetId: p.id,
    });
  }

  private tickProjectiles(dt: number, players: readonly MobTarget[]): void {
    const list = this.projectiles;
    for (let i = list.length - 1; i >= 0; i--) {
      const s = list[i]!;
      s.age += dt;
      let dead = s.age > PROJECTILE_LIFETIME || !this.world.isLoaded(s.x, s.z);
      if (!dead) {
        s.vy -= PROJECTILE_GRAVITY * dt;
        const len = Math.hypot(s.vx, s.vy, s.vz) * dt;
        for (const p of players) {
          const box = { minX: p.x - p.halfWidth - 0.1, minY: p.y - 0.1, minZ: p.z - p.halfWidth - 0.1, maxX: p.x + p.halfWidth + 0.1, maxY: p.y + p.height + 0.1, maxZ: p.z + p.halfWidth + 0.1 };
          if (rayVsAabb(s.x, s.y, s.z, s.vx, s.vy, s.vz, box, len) !== null) {
            const h = Math.hypot(s.vx, s.vz) || 1;
            this.hooks.hurtPlayer(s.damage, s.source, (s.vx / h) * s.knockback, (s.vz / h) * s.knockback, p);
            dead = true;
            break;
          }
        }
        if (!dead) {
          const hit = raycastBlocks(this.world.getBlock, s.x, s.y, s.z, s.vx, s.vy, s.vz, len, isSolidBlock);
          if (hit) dead = true;
          else {
            s.x += s.vx * dt;
            s.y += s.vy * dt;
            s.z += s.vz * dt;
          }
        }
      }
      if (dead) list.splice(i, 1);
    }
  }

  /** Pushes overlapping living mobs apart (soft, velocity based). */
  private separate(): void {
    const list = this.entities.collect(this.scratch);
    for (let i = 0; i < list.length; i++) {
      const a = list[i]!;
      if (!isAlive(a)) continue;
      for (let j = i + 1; j < list.length; j++) {
        const b = list[j]!;
        if (!isAlive(b)) continue;
        const min = a.type.halfWidth + b.type.halfWidth;
        const dx = b.x - a.x, dz = b.z - a.z;
        if (Math.abs(dx) >= min || Math.abs(dz) >= min || Math.abs(b.y - a.y) > 1.5) continue;
        const d = Math.hypot(dx, dz);
        if (d >= min) continue;
        const nx = d > 1e-4 ? dx / d : 1, nz = d > 1e-4 ? dz / d : 0;
        const push = (min - d) * 2;
        a.vx -= nx * push; a.vz -= nz * push;
        b.vx += nx * push; b.vz += nz * push;
      }
    }
  }

  // --- Spawning -----------------------------------------------------------------------------------

  /** Spawning around each player (hostile cap is per player in multiplayer, passive caps per area). */
  private spawnTick(dt: number, daylight: number, players: readonly MobTarget[]): void {
    this.hostileTimer -= dt;
    if (this.hostileTimer <= 0) {
      this.hostileTimer = 1;
      let hostiles = 0;
      for (const m of this.entities) if (m.type.hostile && isAlive(m)) hostiles++;
      // By day only dark caves qualify; keep that trickle small so hostiles mostly appear at night.
      const day = daylight > 0.5;
      const cap = (day ? Math.ceil(this.config.hostileCap * DAY_HOSTILE_CAP_FACTOR) : this.config.hostileCap) * players.length;
      const attempts = day ? 1 : 4;
      for (const p of players) {
        for (let i = 0; i < attempts && hostiles < cap; i++) hostiles += this.trySpawnHostile(p, daylight, cap - hostiles);
      }
    }
    this.passiveTimer -= dt;
    if (this.passiveTimer <= 0) {
      let total = 0;
      for (const m of this.entities) if (!m.type.hostile && isAlive(m)) total++;
      let timer = 6;
      for (const p of players) {
        let near = 0;
        for (const m of this.entities) {
          if (m.type.hostile || !isAlive(m)) continue;
          if (Math.hypot(m.x - p.x, m.z - p.z) < PASSIVE_AREA_RADIUS) near++;
        }
        // Fill an empty area quickly (fresh world / new region), then trickle.
        if (near < this.config.passiveAreaCap / 2) timer = 1;
        const cap = this.config.passiveCap * players.length;
        if (near < this.config.passiveAreaCap && total < cap) total += this.trySpawnPassive(p, Math.min(this.config.passiveAreaCap - near, cap - total));
      }
      this.passiveTimer = timer;
    }
  }

  private pickType(category: 'passive' | 'hostile'): MobTypeDef {
    const list = MOB_TYPES.filter((t) => t.spawn.category === category);
    let total = 0;
    for (const t of list) total += t.spawn.weight;
    let r = this.rand() * total;
    for (const t of list) {
      r -= t.spawn.weight;
      if (r < 0) return t;
    }
    return list[list.length - 1]!;
  }

  /** One hostile spawn attempt around the player. Returns how many spawned. */
  trySpawnHostile(p: MobTarget, daylight: number, room: number): number {
    const a = this.rand() * Math.PI * 2;
    const r = 24 + this.rand() * 40;
    const x = Math.floor(p.x + Math.cos(a) * r);
    const z = Math.floor(p.z + Math.sin(a) * r);
    if (!this.areaLoaded(x + 0.5, z + 0.5)) return 0;
    const type = this.pickType('hostile');
    const clearance = Math.ceil(type.height);
    const g = this.world.getBlock;
    // Candidate floors in this column within 32 blocks of the player's height (caves included).
    const cands: number[] = [];
    const top = Math.min(MAX_Y - 2, Math.floor(p.y) + 32);
    const bottom = Math.max(MIN_Y + 1, Math.floor(p.y) - 32);
    for (let y = top; y >= bottom && cands.length < 8; y--) {
      if (isStandable(g, x, y, z, clearance) && g(x, y, z) !== BlockId.Water && g(x, y - 1, z) !== BlockId.Leaves) cands.push(y);
    }
    if (cands.length === 0) return 0;
    const y = cands[Math.floor(this.rand() * cands.length)]!;
    const site = (sx: number, sy: number, sz: number): boolean =>
      hostileSpawnAllowed({
        skyLight: this.world.getSkyLight(sx, sy, sz),
        blockLight: this.world.getBlockLight(sx, sy, sz),
        daylight,
        distance: Math.hypot(sx + 0.5 - p.x, sy - p.y, sz + 0.5 - p.z),
        inView: inViewCone(sx + 0.5 - p.x, sz + 0.5 - p.z, p.lookX, p.lookZ),
      });
    if (!site(x, y, z)) return 0;
    return this.spawnGroup(type, x, y, z, room, (cx, cy, cz) => site(cx, cy, cz) && g(cx, cy, cz) !== BlockId.Water);
  }

  /** One passive group spawn attempt on grass around the player. Returns how many spawned. */
  trySpawnPassive(p: MobTarget, room: number): number {
    const a = this.rand() * Math.PI * 2;
    const r = 16 + this.rand() * 32;
    const x = Math.floor(p.x + Math.cos(a) * r);
    const z = Math.floor(p.z + Math.sin(a) * r);
    if (!this.areaLoaded(x + 0.5, z + 0.5)) return 0;
    const type = this.pickType('passive');
    const clearance = Math.ceil(type.height);
    const site = (sx: number, _sy: number, sz: number): number | undefined => {
      const g = this.world.getBlock;
      let y = MAX_Y - 1;
      while (y > MIN_Y + 1 && !isSolidBlock(g(sx, y - 1, sz)) && g(sx, y - 1, sz) !== BlockId.Water) y--;
      if (!isStandable(g, sx, y, sz, clearance)) return undefined;
      const ok = passiveSpawnAllowed({
        skyLight: this.world.getSkyLight(sx, y, sz),
        blockLight: this.world.getBlockLight(sx, y, sz),
        daylight: 1,
        distance: Math.hypot(sx + 0.5 - p.x, sz + 0.5 - p.z),
        ground: g(sx, y - 1, sz),
      });
      return ok ? y : undefined;
    };
    const y = site(x, 0, z);
    if (y === undefined) return 0;
    return this.spawnGroup(type, x, y, z, room, (cx, cy, cz) => site(cx, cy, cz) !== undefined, (cx, cz) => site(cx, 0, cz));
  }

  /**
   * Spawns a group of `type` around cell (x, y, z): the first at the cell, the rest at nearby cells
   * that pass `ok`. `yAt` finds the floor of a nearby column (default: the same y).
   */
  private spawnGroup(type: MobTypeDef, x: number, y: number, z: number, room: number, ok: (x: number, y: number, z: number) => boolean, yAt?: (x: number, z: number) => number | undefined): number {
    const n = Math.min(room, type.spawn.groupMin + Math.floor(this.rand() * (type.spawn.groupMax - type.spawn.groupMin + 1)));
    if (n <= 0) return 0;
    this.spawn(type, x + 0.5, y, z + 0.5);
    let spawned = 1;
    const clearance = Math.ceil(type.height);
    for (let tries = 0; tries < n * 4 && spawned < n; tries++) {
      const cx = x + Math.floor(this.rand() * 7) - 3;
      const cz = z + Math.floor(this.rand() * 7) - 3;
      const cy = yAt ? yAt(cx, cz) : y;
      if (cy === undefined || !this.world.isLoaded(cx, cz) || !isStandable(this.world.getBlock, cx, cy, cz, clearance) || !ok(cx, cy, cz)) continue;
      this.spawn(type, cx + 0.5, cy, cz + 0.5);
      spawned++;
    }
    return spawned;
  }

  // --- Saving -------------------------------------------------------------------------------------

  /** Living mobs, by type name (dying ones and projectiles are not saved). */
  toSaved(): SavedMob[] {
    const out: SavedMob[] = [];
    for (const m of this.entities) {
      if (!isAlive(m)) continue;
      out.push({ type: m.type.name, x: m.x, y: m.y, z: m.z, health: m.health.hp, yaw: m.yaw, age: m.age });
    }
    return out;
  }

  /** Adds saved mobs; unknown types and broken records are skipped. */
  restore(saved: readonly SavedMob[] | undefined): void {
    if (!Array.isArray(saved)) return;
    for (const s of saved) {
      const type = typeof s?.type === 'string' ? mobTypeByName(s.type) : undefined;
      if (!type || ![s.x, s.y, s.z].every(Number.isFinite)) continue;
      const m = this.spawn(type, s.x, s.y, s.z, Number.isFinite(s.yaw) ? s.yaw : 0);
      this.stats.spawned--;
      m.health.hp = Number.isFinite(s.health) ? Math.max(1, Math.min(type.maxHealth, s.health)) : type.maxHealth;
      m.age = Number.isFinite(s.age) ? s.age : 0;
    }
  }
}
