import type { DemTile, GeoBBox, MapcoreApi } from '@voxel/shared';

/**
 * Elevation (mapcore milestone 5): Terrarium-encoded PNG tiles from the public AWS terrain bucket
 * (CORS enabled), the same source mapcore's CLI uses. mapcore says which tiles an area needs
 * (`dem_tiles`); a 0.4 km² area needs 1-4 tiles at zoom 14.
 */
export const DEM_TILE_URL = 'https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png';

export interface DemTileId {
  z: number;
  x: number;
  y: number;
}

/** The tiles mapcore needs for `bbox` at `scale`. */
export function demTileList(api: MapcoreApi, bbox: GeoBBox, scale: number): DemTileId[] {
  const flat = api.dem_tiles(new Float64Array(bbox), scale);
  const out: DemTileId[] = [];
  for (let i = 0; i + 2 < flat.length; i += 3) out.push({ z: flat[i]!, x: flat[i + 1]!, y: flat[i + 2]! });
  return out;
}

export function demTileUrl(t: DemTileId, template = DEM_TILE_URL): string {
  return template.replace('{z}', String(t.z)).replace('{x}', String(t.x)).replace('{y}', String(t.y));
}

export interface FetchDemOptions {
  fetch?: typeof fetch;
  signal?: AbortSignal;
  /** Sent where allowed (Node). */
  userAgent?: string;
  /** Tries per tile (default 3), with a growing pause between them. */
  attempts?: number;
  /** Base pause before a retry, ms (doubles each time; default 400). */
  retryDelayMs?: number;
  /** Tiles downloaded at the same time (default 4). */
  concurrency?: number;
  urlTemplate?: string;
  /** Called after each finished tile. */
  onProgress?: (done: number, total: number) => void;
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const t = setTimeout(resolve, ms);
    signal?.addEventListener('abort', () => {
      clearTimeout(t);
      reject(signal.reason ?? new Error('aborted'));
    }, { once: true });
  });
}

/** Downloads one tile, retrying network errors and 5xx / 429 responses. */
async function fetchTile(t: DemTileId, o: FetchDemOptions): Promise<DemTile> {
  const doFetch = o.fetch ?? globalThis.fetch;
  const url = demTileUrl(t, o.urlTemplate);
  const attempts = Math.max(1, o.attempts ?? 3);
  let last = '';
  for (let a = 0; a < attempts; a++) {
    if (a > 0) await sleep((o.retryDelayMs ?? 400) * 2 ** (a - 1), o.signal);
    try {
      const res = await doFetch(url, { signal: o.signal, headers: o.userAgent ? { 'User-Agent': o.userAgent } : undefined });
      if (res.ok) return { ...t, png: new Uint8Array(await res.arrayBuffer()) };
      last = `HTTP ${res.status}`;
      if (res.status < 500 && res.status !== 429) break; // 404 etc.: retrying will not help
    } catch (err) {
      if (o.signal?.aborted) throw err;
      last = err instanceof Error ? err.message : String(err);
    }
  }
  throw new Error(`missing elevation tile ${t.z}/${t.x}/${t.y} (${last})`);
}

/** Downloads every tile (a few at a time). Throws if any tile still fails after its retries. */
export async function fetchDemTiles(tiles: readonly DemTileId[], o: FetchDemOptions = {}): Promise<DemTile[]> {
  const out: DemTile[] = new Array(tiles.length);
  let next = 0;
  let done = 0;
  o.onProgress?.(0, tiles.length);
  const worker = async (): Promise<void> => {
    while (next < tiles.length) {
      const i = next++;
      out[i] = await fetchTile(tiles[i]!, o);
      o.onProgress?.(++done, tiles.length);
    }
  };
  await Promise.all(Array.from({ length: Math.min(tiles.length, Math.max(1, o.concurrency ?? 4)) }, worker));
  return out;
}
