import { LightEngine, TerrainGenerator, World, computeChunkLight, meshSection, sectionKey, sectionOf, vec3, SECTION_COUNT } from '@voxel/shared';
import { Camera } from '../game/camera';
import type { Renderer } from './renderer';

/** Fixed seed of the title panorama (a pleasant spot; any seed works). */
const TITLE_SEED = 20241102;
/** Radians per second the panorama turns. */
const TURN_SPEED = 0.035;
/** Time of day of the panorama (early morning light). */
const TITLE_TIME = 0.1;

/**
 * Title screen backdrop (Milestone 11): a small patch of real terrain generated and meshed on the
 * main thread a little at a time (one chunk or a few sections per frame, so the menu stays
 * responsive), drawn with the normal renderer from a slowly turning camera. It owns the renderer
 * only while no game runs: `stop()` frees its chunk meshes before a world starts.
 */
export class TitleBackground {
  private readonly world = new World();
  private readonly light = new LightEngine(this.world);
  private readonly generator = new TerrainGenerator(TITLE_SEED);
  private readonly camera: Camera;
  private readonly lookDir = vec3.create();
  private readonly rightDir = vec3.create();
  /** Chunks still to generate, then sections still to mesh. */
  private genQueue: [number, number][] = [];
  private meshQueue: [number, number, number][] = [];
  private raf = 0;
  private running = false;
  private last = 0;
  private built = false;

  constructor(
    private readonly renderer: Renderer,
    /** Chunks meshed around the centre (2 = 5x5); one extra ring is generated for lighting. */
    private readonly radius = 2,
  ) {
    const y = this.generator.surfaceHeight(8, 8);
    // Low enough that the ground is well inside the fog distance when looking slightly down.
    this.camera = new Camera(8, Math.max(y, 62) + 12, 8);
    this.camera.pitch = -0.26;
    this.camera.yaw = 0.6;
  }

  get isRunning(): boolean {
    return this.running;
  }

  start(): void {
    if (this.running) return;
    this.running = true;
    this.renderer.setViewDistance(this.radius + 2);
    this.renderer.setUnderwater(false);
    if (!this.built && this.genQueue.length === 0) this.queueBuild();
    this.queueMeshes();
    this.last = performance.now();
    const frame = (now: number): void => {
      if (!this.running) return;
      this.raf = requestAnimationFrame(frame);
      try {
        this.frame(now);
      } catch (err) {
        // A broken backdrop must never take the menu down.
        console.warn('Title background stopped', err);
        this.stop();
      }
    };
    this.raf = requestAnimationFrame(frame);
  }

  /** Stops drawing and frees the meshes (the generated chunks stay cached for the next start). */
  stop(): void {
    if (!this.running) return;
    this.running = false;
    cancelAnimationFrame(this.raf);
    this.meshQueue = [];
    this.renderer.chunks.clear();
  }

  private queueBuild(): void {
    const r = this.radius + 1;
    for (let cz = -r; cz <= r; cz++) for (let cx = -r; cx <= r; cx++) this.genQueue.push([cx, cz]);
    // Nearest first so the centre appears first.
    this.genQueue.sort((a, b) => Math.hypot(a[0], a[1]) - Math.hypot(b[0], b[1]));
  }

  private queueMeshes(): void {
    const r = this.radius;
    this.meshQueue = [];
    for (let cz = -r; cz <= r; cz++) {
      for (let cx = -r; cx <= r; cx++) {
        let high = 0;
        for (const [ox, oz] of [[8, 8], [1, 1], [14, 1], [1, 14], [14, 14]] as const) high = Math.max(high, this.generator.surfaceHeight(cx * 16 + ox, cz * 16 + oz));
        const top = Math.min(SECTION_COUNT - 1, sectionOf(high + 12));
        for (let sy = Math.max(0, top - 3); sy <= top; sy++) this.meshQueue.push([cx, sy, cz]);
      }
    }
    this.meshQueue.sort((a, b) => Math.hypot(a[0], a[2]) - Math.hypot(b[0], b[2]) || b[1] - a[1]);
  }

  /** A section can be meshed once its chunk and all 8 neighbours exist (borders and light settled). */
  private canMesh(cx: number, cz: number): boolean {
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) if (!this.world.getChunk(cx + dx, cz + dz)) return false;
    return true;
  }

  private frame(now: number): void {
    const dt = Math.min(0.1, (now - this.last) / 1000);
    this.last = now;
    // Build a little per frame within a small time budget: mesh what is ready, else generate.
    const t0 = performance.now();
    while (performance.now() - t0 < 6) {
      const next = this.meshQueue[0];
      if (next && this.canMesh(next[0], next[2])) {
        this.meshQueue.shift();
        const [cx, sy, cz] = next;
        const mesh = meshSection(this.world.copySectionPadded(cx, sy, cz), this.world.copySectionPaddedLight(cx, sy, cz));
        this.renderer.setSectionMesh(sectionKey(cx, sy, cz), mesh);
      } else if (this.genQueue.length > 0) {
        const [cx, cz] = this.genQueue.shift()!;
        const chunk = this.generator.generateChunk(cx, cz);
        computeChunkLight(chunk);
        this.world.addChunk(chunk);
        this.light.stitchChunk(cx, cz);
        if (this.genQueue.length === 0) this.built = true;
      } else break;
    }

    const { renderer, camera } = this;
    camera.yaw = (camera.yaw + TURN_SPEED * dt) % (Math.PI * 2);
    renderer.setTimeOfDay(TITLE_TIME);
    const aspect = renderer.beginFrame();
    vec3.copy(camera.prevPosition, camera.position);
    camera.updateMatrices(aspect, 1);
    renderer.drawSky(camera.forward(this.lookDir), camera.flatRight(this.rightDir), camera.fovY, aspect);
    renderer.drawWorld(camera.viewProj, camera.renderPosition);
  }
}
