import type { World } from '@voxel/shared';
import type { GameSession } from '../game/session';
import type { BlockInteraction } from '../game/interaction';
import type { AudioEngine, MobVoice } from './audioEngine';
import { ambientMix, blockMaterial } from './spatial';

/** Blocks walked per footstep sound (walking; sprinting covers it faster, so steps come quicker). */
const STRIDE = 2.1;
/** Seconds between mining "hit" ticks while holding the button on a block. */
const MINING_TICK = 0.26;
/** Seconds between chews while eating. */
const CHEW_INTERVAL = 0.22;
/** Mobs farther than this never make idle calls. */
const VOICE_DISTANCE = 20;

interface MobEar {
  hurt: number;
  dying: boolean;
  swing: number;
  /** Seconds until the next idle call. */
  voiceTimer: number;
  seen: number;
}

const VOICES: Record<string, MobVoice> = {
  sheep: 'sheep',
  pig: 'pig',
  chicken: 'chicken',
  gloomwalker: 'gloomwalker',
  bilespitter: 'bilespitter',
};

/**
 * Turns game state into sounds (Milestone 11). It mostly *observes* instead of being called from
 * the simulation, so the same code works single-player and in multiplayer (where the world state
 * is mirrored from the server):
 * - block edits (local, optimistic, and other players' changes from the server) through the
 *   session's block-change listener: break / place by material at the block;
 * - the local body each tick: footsteps by the block underfoot, jump, landing, splash;
 * - damage / death listeners: hurt and death;
 * - mobs and projectiles each frame: rising edges of hurt / swing / dying, new and vanished
 *   projectiles (Bilespitter globs), random idle calls nearby;
 * - the camera position: ambient wind vs cave mix, muffling under water.
 */
export class SoundDirector {
  private stepDistance = 0;
  private wasOnGround = true;
  private wasInWater = false;
  private lastVy = 0;
  private lastX = NaN;
  private lastZ = NaN;
  private miningTimer = 0;
  private chewTimer = 0;
  private frameNo = 0;
  private disposed = false;
  private readonly ears = new Map<number, MobEar>();
  private projectiles = new Map<number, { x: number; y: number; z: number }>();

  constructor(
    private readonly audio: AudioEngine,
    private readonly session: GameSession,
    private readonly world: World,
  ) {
    session.onBlockChange((x, y, z, oldId, newId) => {
      if (this.disposed || oldId === newId) return;
      if (newId === 0) {
        const m = blockMaterial(oldId);
        if (m) audio.play(`break_${m}`, { x: x + 0.5, y: y + 0.5, z: z + 0.5 });
      } else {
        const m = blockMaterial(newId);
        if (m) audio.play(`place_${m}`, { x: x + 0.5, y: y + 0.5, z: z + 0.5 });
      }
    });
    session.onDamage(() => {
      if (!this.disposed && !session.dead) audio.play('hurt');
    });
    session.onDeath(() => {
      if (!this.disposed) audio.play('death');
    });
  }

  /** Items picked up this tick (single-player pickup events / a vanished nearby item in multiplayer). */
  pickup(): void {
    this.audio.play('pickup', { volume: 0.8, pitch: 0.9 + Math.random() * 0.4 });
  }

  /** Multiplayer: an item entity disappeared; if it was right next to us, we picked it up. */
  itemRemoved(x: number, y: number, z: number): void {
    const p = this.session.player;
    if (Math.hypot(x - p.x, y - (p.y + 0.8), z - p.z) < 2.2) this.pickup();
  }

  /** After each fixed physics tick of the local player. */
  tick(): void {
    const s = this.session;
    const p = s.player;
    if (!s.spawned || s.dead) {
      this.lastX = NaN;
      return;
    }
    const moved = Number.isNaN(this.lastX) ? 0 : Math.hypot(p.x - this.lastX, p.z - this.lastZ);
    this.lastX = p.x;
    this.lastZ = p.z;
    if (moved > 3) {
      // Teleport / respawn / correction: no sounds for the jump.
      this.stepDistance = 0;
      this.wasOnGround = p.onGround;
      this.wasInWater = p.inWater;
      this.lastVy = p.vy;
      return;
    }
    const under = (): number => this.world.getBlock(Math.floor(p.x), Math.floor(p.y - 0.05), Math.floor(p.z));
    if (!p.flying) {
      if (p.onGround && !p.inWater) {
        this.stepDistance += moved;
        if (this.stepDistance >= STRIDE) {
          this.stepDistance = 0;
          const m = blockMaterial(under());
          if (m) this.audio.play(`step_${m}`, { volume: 0.7 });
        }
      } else if (p.inWater) {
        this.stepDistance += moved * 0.6;
        if (this.stepDistance >= STRIDE) {
          this.stepDistance = 0;
          this.audio.play('splash', { volume: 0.18, pitch: 1.3 });
        }
      }
      if (this.wasOnGround && !p.onGround && p.vy > 0 && !p.inWater) this.audio.play('jump');
      if (!this.wasOnGround && p.onGround && this.lastVy < -6) {
        const m = blockMaterial(under());
        this.audio.play('land', { volume: Math.min(1, (-this.lastVy - 4) / 10) });
        if (m) this.audio.play(`step_${m}`, { volume: 0.8 });
        this.stepDistance = 0;
      }
      if (!this.wasInWater && p.inWater && this.lastVy < -3) this.audio.play('splash', { volume: Math.min(1, -this.lastVy / 12) });
    }
    this.wasOnGround = p.onGround;
    this.wasInWater = p.inWater;
    this.lastVy = p.vy;
  }

  /** Once per rendered frame. `rightX/Z` is the camera's horizontal right vector. */
  frame(dt: number, eye: ArrayLike<number>, rightX: number, rightZ: number, interaction: BlockInteraction, active: boolean): void {
    const audio = this.audio;
    if (!audio.unlocked) return;
    this.frameNo++;
    const ex = eye[0]!, ey = eye[1]!, ez = eye[2]!;
    audio.setListener(ex, ey, ez, rightX, rightZ);
    const s = this.session;

    // Mining ticks and chewing.
    const b = interaction.breaking;
    if (active && b && interaction.breakProgress > 0) {
      this.miningTimer -= dt;
      if (this.miningTimer <= 0) {
        this.miningTimer = MINING_TICK;
        const m = blockMaterial(this.world.getBlock(b.x, b.y, b.z));
        if (m) audio.play(`hit_${m}`, { x: b.x + 0.5, y: b.y + 0.5, z: b.z + 0.5 });
      }
    } else this.miningTimer = 0;
    if (active && interaction.eatSeconds > 0) {
      this.chewTimer -= dt;
      if (this.chewTimer <= 0) {
        this.chewTimer = CHEW_INTERVAL;
        audio.play('eat');
      }
    } else this.chewTimer = 0;

    this.mobs(dt, ex, ey, ez);
    this.globs();

    // Ambience and underwater muffling.
    const bx = Math.floor(ex), by = Math.floor(ey), bz = Math.floor(ez);
    const amb = ambientMix(this.world.getSkyLight(bx, by, bz), ey);
    audio.setAmbient(s.spawned ? amb.wind : 0, s.spawned ? amb.cave : 0, dt);
    audio.setMuffled(s.spawned && s.headInWater());
  }

  private mobs(dt: number, ex: number, ey: number, ez: number): void {
    const audio = this.audio;
    const frame = this.frameNo;
    for (const m of this.session.mobs.entities) {
      let ear = this.ears.get(m.id);
      const h = m.health;
      if (!ear) {
        ear = { hurt: h.hurtTime, dying: h.deathTime >= 0, swing: m.ai.swingTime, voiceTimer: 2 + Math.random() * 10, seen: frame };
        this.ears.set(m.id, ear);
        continue;
      }
      ear.seen = frame;
      const pos = { x: m.x, y: m.y + m.type.height * 0.7, z: m.z };
      const pitch = Math.max(0.6, Math.min(1.6, 0.9 / Math.max(0.4, m.type.height)));
      const dying = h.deathTime >= 0;
      if (dying && !ear.dying) audio.play('mob_death', { ...pos, pitch });
      else if (!dying && h.hurtTime > ear.hurt + 0.05) audio.play('mob_hurt', { ...pos, pitch });
      if (m.ai.swingTime > ear.swing + 0.05 && m.type.hostile && m.type.name === 'gloomwalker') audio.play('mob_attack', pos);
      ear.hurt = h.hurtTime;
      ear.dying = dying;
      ear.swing = m.ai.swingTime;
      if (!dying) {
        ear.voiceTimer -= dt;
        if (ear.voiceTimer <= 0) {
          const near = Math.hypot(m.x - ex, m.y - ey, m.z - ez) < VOICE_DISTANCE;
          ear.voiceTimer = (m.type.hostile ? 5 : 7) + Math.random() * 10;
          const voice = VOICES[m.type.name];
          if (near && voice) audio.play(`voice_${voice}`, { ...pos, volume: 0.8 });
        }
      }
    }
    // Forget mobs that are gone.
    if (frame % 30 === 0) for (const [id, ear] of this.ears) if (ear.seen !== frame) this.ears.delete(id);
  }

  private globs(): void {
    const next = new Map<number, { x: number; y: number; z: number }>();
    for (const p of this.session.mobs.projectiles) {
      next.set(p.id, { x: p.x, y: p.y, z: p.z });
      if (!this.projectiles.has(p.id)) this.audio.play('glob', { x: p.x, y: p.y, z: p.z });
    }
    for (const [id, pos] of this.projectiles) if (!next.has(id)) this.audio.play('splat', pos);
    this.projectiles = next;
  }

  dispose(): void {
    this.disposed = true;
    this.ears.clear();
    this.projectiles.clear();
    this.audio.stopAmbient();
    this.audio.setMuffled(false);
  }
}
