import { mapPackageVersion, type DemTile, type GeoBBox, type MapcoreApi, type StoredMapPackage } from '@voxel/shared';
import { demTileList, type DemTileId } from './dem';

export type { StoredMapPackage };

/** Default blocks per metre. */
export const DEFAULT_MAP_SCALE = 1;

/**
 * Runs mapcore's one-time preparation. With elevation tiles (`dem`, every tile `dem_tiles` lists)
 * the package has terrain; without, it is flat.
 */
export function prepareMapPackage(api: MapcoreApi, osm: string, bbox: GeoBBox, scale = DEFAULT_MAP_SCALE, dem?: readonly DemTile[]): StoredMapPackage {
  if (!dem || dem.length === 0) return { pkg: api.prepare(osm, new Float64Array(bbox), scale), osm, bbox, scale };
  const prep = new api.MapPrepare(osm, new Float64Array(bbox), scale);
  try {
    for (const t of dem) prep.add_dem_tile(t.z, t.x, t.y, t.png);
    return { pkg: prep.finish(), osm, bbox, scale, dem: [...dem] };
  } finally {
    prep.free();
  }
}

/** Whether a stored package was prepared with terrain. */
export function hasTerrain(stored: StoredMapPackage): boolean {
  return !!stored.dem && stored.dem.length > 0;
}

export interface EnsureOptions {
  /**
   * Downloads elevation tiles for a package that has none stored (an older, flat package being
   * upgraded). Omit to rebuild offline (flat unless tiles are stored).
   */
  fetchDem?: (tiles: DemTileId[]) => Promise<DemTile[]>;
}

export interface EnsureResult {
  stored: StoredMapPackage;
  /** The package was rebuilt (save it). */
  rebuilt: boolean;
  /** Set when terrain was wanted but the tiles could not be had, so the rebuild is flat. */
  warning?: string;
}

/**
 * The stored package, or a fresh one prepared from its saved data when it was written by another
 * mapcore format version. Stored elevation tiles are reused; a package without any (made before
 * terrain existed) gets them downloaded with `fetchDem`, and is rebuilt flat (with a warning) if
 * that fails.
 */
export async function ensureCurrentPackage(api: MapcoreApi, stored: StoredMapPackage, options: EnsureOptions = {}): Promise<EnsureResult> {
  if (mapPackageVersion(stored.pkg) === api.package_version()) return { stored, rebuilt: false };
  let dem = stored.dem;
  let warning: string | undefined;
  if (!dem?.length && options.fetchDem) {
    try {
      dem = await options.fetchDem(demTileList(api, stored.bbox, stored.scale));
    } catch (err) {
      dem = undefined;
      warning = `Elevation data could not be downloaded (${err instanceof Error ? err.message : String(err)}); the map was rebuilt flat.`;
    }
  }
  return { stored: prepareMapPackage(api, stored.osm, stored.bbox, stored.scale, dem), rebuilt: true, ...(warning ? { warning } : {}) };
}
