import { getItemDef, type Slot } from '@voxel/shared';
import { itemIconUrl } from './icons';

/** A slot element: icon, count and durability bar. Used by the hotbar and inventory screens. */
export function createSlotEl(className = 'slot'): HTMLDivElement {
  const el = document.createElement('div');
  el.className = className;
  const img = document.createElement('img');
  img.className = 'slot-icon';
  img.alt = '';
  img.draggable = false;
  img.hidden = true;
  const count = document.createElement('span');
  count.className = 'slot-count';
  const dur = document.createElement('div');
  dur.className = 'slot-dur';
  dur.hidden = true;
  dur.appendChild(document.createElement('div'));
  el.append(img, count, dur);
  return el;
}

/** Shows `stack` in a slot element; only touches the DOM when the content changed. */
export function setSlotContent(el: HTMLElement, stack: Slot): void {
  const key = stack ? `${stack.item}:${stack.count}:${stack.damage}` : '';
  if (el.dataset['content'] === key) return;
  el.dataset['content'] = key;
  const img = el.querySelector<HTMLImageElement>('.slot-icon')!;
  const count = el.querySelector<HTMLElement>('.slot-count')!;
  const dur = el.querySelector<HTMLElement>('.slot-dur')!;
  if (!stack) {
    img.hidden = true;
    img.removeAttribute('src');
    count.textContent = '';
    dur.hidden = true;
    return;
  }
  const def = getItemDef(stack.item);
  img.src = itemIconUrl(stack.item);
  img.hidden = false;
  count.textContent = stack.count > 1 ? String(stack.count) : '';
  const tool = def.tool;
  if (tool && stack.damage > 0) {
    const frac = Math.max(0, (tool.durability - stack.damage) / tool.durability);
    const bar = dur.firstElementChild as HTMLElement;
    bar.style.width = `${Math.round(frac * 100)}%`;
    bar.style.background = `hsl(${Math.round(frac * 120)}, 85%, 50%)`;
    dur.hidden = false;
  } else {
    dur.hidden = true;
  }
}

/** Tooltip text: name, and durability for tools. */
export function stackTooltip(stack: Slot): string {
  if (!stack) return '';
  const def = getItemDef(stack.item);
  const lines = [def.label];
  if (def.tool) lines.push(`Durability ${def.tool.durability - stack.damage} / ${def.tool.durability}`);
  if (def.food) lines.push(`Restores ${def.food.hunger} hunger (hold right click)`);
  return lines.join('\n');
}
