export class WebGL2UnavailableError extends Error {
  constructor() {
    super(
      'WebGL 2 is not available. Please use a recent version of Chrome, Edge, Firefox or Safari, ' +
        'and make sure hardware acceleration is enabled.',
    );
    this.name = 'WebGL2UnavailableError';
  }
}

export function createGLContext(canvas: HTMLCanvasElement): WebGL2RenderingContext {
  const gl = canvas.getContext('webgl2', { antialias: false, alpha: false, powerPreference: 'high-performance' });
  if (!gl) throw new WebGL2UnavailableError();
  return gl;
}

/**
 * Sizes the canvas backing store to its CSS size times devicePixelRatio (capped).
 * Cheap enough to call every frame; returns true when the size changed.
 */
export function resizeCanvasToDisplaySize(canvas: HTMLCanvasElement, maxDpr = 2): boolean {
  const dpr = Math.min(window.devicePixelRatio || 1, maxDpr);
  const width = Math.max(1, Math.round(canvas.clientWidth * dpr));
  const height = Math.max(1, Math.round(canvas.clientHeight * dpr));
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
    return true;
  }
  return false;
}
