/**
 * Block breaking rules (Milestone 7): break time from hardness and the held tool, harvest checks,
 * drops and tool wear. Pure; `rand` is injected for drop chances.
 *
 * Break time (seconds) = hardness * (canHarvest ? 1.5 : 5) / speed
 *   speed = TIER_SPEED[tier] with the block's preferred tool family, else 1 (hand speed)
 *   x5 with the head under water, x5 while not standing on the ground.
 */
import { BlockId, blockHardness, getBlockDef } from '../world/blocks';
import { TIER_SPEED, getItemDef, itemForBlock, itemId, type ItemStack, type Slot } from './items';

export const HARVEST_FACTOR = 1.5;
export const NO_HARVEST_FACTOR = 5;
export const UNDERWATER_FACTOR = 5;
export const AIRBORNE_FACTOR = 5;
/** Chance per leaves block of dropping an apple. */
export const APPLE_CHANCE = 0.05;

export interface BreakEnv {
  /** Eyes under water. */
  headInWater: boolean;
  onGround: boolean;
}

const GROUNDED: BreakEnv = { headInWater: false, onGround: true };

/** The tool info of a held stack, if it is a tool. */
function toolOf(held: Slot): { kind: string; tier: number } | undefined {
  return held ? getItemDef(held.item).tool : undefined;
}

/** Whether breaking `blockId` with `held` yields drops (tier requirement met). */
export function canHarvest(blockId: number, held: Slot): boolean {
  const def = getBlockDef(blockId);
  if (def.requiredTier === undefined || def.requiredTier <= 0) return true;
  const tool = toolOf(held);
  return !!tool && tool.kind === def.tool && tool.tier >= def.requiredTier;
}

/** Mining speed multiplier of `held` against `blockId` (1 = bare hand / wrong tool). */
export function miningSpeed(blockId: number, held: Slot): number {
  const tool = toolOf(held);
  const def = getBlockDef(blockId);
  if (!tool || !def.tool || tool.kind !== def.tool) return 1;
  return TIER_SPEED[tool.tier] ?? 1;
}

/** Seconds needed to break `blockId`; 0 = instant, Infinity = unbreakable. */
export function breakSeconds(blockId: number, held: Slot, env: BreakEnv = GROUNDED): number {
  const hardness = blockHardness(blockId);
  if (hardness < 0) return Infinity;
  if (hardness === 0) return 0;
  let t = (hardness * (canHarvest(blockId, held) ? HARVEST_FACTOR : NO_HARVEST_FACTOR)) / miningSpeed(blockId, held);
  if (env.headInWater) t *= UNDERWATER_FACTOR;
  if (!env.onGround) t *= AIRBORNE_FACTOR;
  return t;
}

/** What a block drops when broken by `held` in survival. Empty when the tier is too low. */
export function blockDrops(blockId: number, held: Slot, rand: () => number = Math.random): ItemStack[] {
  if (!canHarvest(blockId, held)) return [];
  const one = (name: string, count = 1): ItemStack[] => [{ item: itemId(name), count, damage: 0 }];
  switch (blockId) {
    case BlockId.Air:
    case BlockId.Water:
    case BlockId.Bedrock:
      return [];
    case BlockId.Stone:
      return one('rubble');
    case BlockId.Grass:
      return one('dirt');
    case BlockId.CoalOre:
      return one('coal');
    case BlockId.Leaves:
      return rand() < APPLE_CHANCE ? one('apple') : [];
    default: {
      const item = itemForBlock(blockId);
      return item ? [{ item: item.id, count: 1, damage: 0 }] : [];
    }
  }
}

/** Durability used by breaking `blockId` with `held`: 0 for instant blocks and non-tools, 2 for swords. */
export function toolWearForBreak(blockId: number, held: Slot): number {
  const tool = toolOf(held);
  if (!tool || blockHardness(blockId) <= 0) return 0;
  return tool.kind === 'sword' ? 2 : 1;
}

/**
 * Adds `amount` wear to a tool stack (in place). Returns the stack, or null when it broke.
 * Non-tools are returned unchanged.
 */
export function wearTool(stack: ItemStack, amount = 1): ItemStack | null {
  const tool = getItemDef(stack.item).tool;
  if (!tool || amount <= 0) return stack;
  stack.damage += amount;
  return stack.damage >= tool.durability ? null : stack;
}
