import type { TimingRing } from '../perf/frameStats';

const GRAPH_W = 240;
const GRAPH_H = 60;
/** Graph full scale, ms (bars taller than this are clipped and drawn red). */
const GRAPH_MAX_MS = 33.3;

/** Minimal F3 debug overlay. Callers push key/value lines each frame via `setLines`. */
export class DebugOverlay {
  private readonly el: HTMLDivElement;
  private readonly text: HTMLDivElement;
  private readonly graph: HTMLCanvasElement;
  private readonly g2d: CanvasRenderingContext2D | null;
  private visible = false;
  private frames = 0;
  private fpsWindowStart = performance.now();
  fps = 0;

  constructor(parent: HTMLElement = document.body) {
    this.el = document.createElement('div');
    this.el.className = 'debug-overlay';
    this.el.hidden = true;
    this.text = document.createElement('div');
    this.graph = document.createElement('canvas');
    this.graph.className = 'debug-graph';
    this.graph.width = GRAPH_W;
    this.graph.height = GRAPH_H;
    this.g2d = this.graph.getContext('2d');
    this.el.append(this.text, this.graph);
    parent.appendChild(this.el);
  }

  get isVisible(): boolean {
    return this.visible;
  }

  toggle(): void {
    this.visible = !this.visible;
    this.el.hidden = !this.visible;
  }

  /** Call once per rendered frame. */
  tickFrame(now = performance.now()): void {
    this.frames++;
    const elapsed = now - this.fpsWindowStart;
    if (elapsed >= 500) {
      this.fps = (this.frames * 1000) / elapsed;
      this.frames = 0;
      this.fpsWindowStart = now;
    }
  }

  dispose(): void {
    this.el.remove();
  }

  setLines(lines: readonly string[]): void {
    if (this.visible) this.text.textContent = lines.join('\n');
  }

  /**
   * Frame-time graph: one bar per frame for `interval` (time between frames, grey) with the frame's
   * CPU time on top (green / yellow / red), plus 16.7 ms and 33.3 ms guide lines.
   */
  drawGraph(cpu: TimingRing, interval: TimingRing): void {
    const g = this.g2d;
    if (!this.visible || !g) return;
    g.clearRect(0, 0, GRAPH_W, GRAPH_H);
    g.fillStyle = 'rgba(0, 0, 0, 0.35)';
    g.fillRect(0, 0, GRAPH_W, GRAPH_H);
    const scale = GRAPH_H / GRAPH_MAX_MS;
    const n = Math.min(cpu.count, GRAPH_W);
    const offCpu = cpu.count - n;
    const offInt = interval.count - Math.min(interval.count, GRAPH_W);
    for (let i = 0; i < n; i++) {
      const x = GRAPH_W - n + i;
      const iv = i + offInt < interval.count ? interval.at(i + offInt) : 0;
      g.fillStyle = 'rgba(200, 200, 200, 0.35)';
      g.fillRect(x, GRAPH_H - Math.min(GRAPH_H, iv * scale), 1, Math.min(GRAPH_H, iv * scale));
      const c = cpu.at(i + offCpu);
      g.fillStyle = c > 16.7 ? '#ff5050' : c > 8 ? '#ffd040' : '#50e070';
      g.fillRect(x, GRAPH_H - Math.min(GRAPH_H, c * scale), 1, Math.min(GRAPH_H, c * scale));
    }
    g.fillStyle = 'rgba(255, 255, 255, 0.6)';
    g.fillRect(0, Math.round(GRAPH_H - 16.7 * scale), GRAPH_W, 1);
    g.fillRect(0, 0, GRAPH_W, 1);
  }
}
