/**
 * Keyboard + mouse state with pointer lock. Keys are tracked by `KeyboardEvent.code`
 * (layout independent, e.g. 'KeyW', 'Space', 'ShiftLeft').
 */
export class Input {
  private readonly down = new Set<string>();
  private readonly pressedThisFrame = new Set<string>();
  private mouseDX = 0;
  private mouseDY = 0;
  private wheel = 0;
  private readonly buttonsDown = new Set<number>();
  private readonly buttonsPressed = new Set<number>();
  private readonly abort = new AbortController();

  constructor(private readonly canvas: HTMLCanvasElement) {
    const opts = { signal: this.abort.signal };
    window.addEventListener('keydown', (e) => this.onKeyDown(e), opts);
    window.addEventListener('keyup', (e) => this.down.delete(e.code), opts);
    window.addEventListener('blur', () => this.releaseAll(), opts);
    canvas.addEventListener('click', () => void this.requestLock(), opts);
    document.addEventListener('mousemove', (e) => this.onMouseMove(e), opts);
    document.addEventListener('pointerlockchange', () => {
      if (!this.isLocked) this.releaseAll();
    }, opts);
    document.addEventListener('mousedown', (e) => {
      if (!this.isLocked) return;
      e.preventDefault();
      if (!this.buttonsDown.has(e.button)) this.buttonsPressed.add(e.button);
      this.buttonsDown.add(e.button);
    }, opts);
    document.addEventListener('mouseup', (e) => this.buttonsDown.delete(e.button), opts);
    canvas.addEventListener('contextmenu', (e) => e.preventDefault(), opts);
    window.addEventListener('wheel', (e) => {
      if (!this.isLocked) return;
      e.preventDefault();
      this.wheel += Math.sign(e.deltaY);
    }, { signal: this.abort.signal, passive: false });
  }

  get isLocked(): boolean {
    return document.pointerLockElement === this.canvas;
  }

  isDown(code: string): boolean {
    return this.down.has(code);
  }

  /** True if the key went down since the last `endFrame()`. */
  wasPressed(code: string): boolean {
    return this.pressedThisFrame.has(code);
  }

  /** Mouse button held (0 = left, 2 = right). Only tracked while the pointer is locked. */
  isMouseDown(button: number): boolean {
    return this.buttonsDown.has(button);
  }

  /** True if the mouse button went down since the last `endFrame()`. */
  wasMousePressed(button: number): boolean {
    return this.buttonsPressed.has(button);
  }

  /** Returns and resets accumulated wheel notches (positive = scrolled down / toward the user). */
  consumeWheel(): number {
    const w = this.wheel;
    this.wheel = 0;
    return w;
  }

  /** Returns and resets accumulated mouse movement (in CSS pixels) since the last call. */
  consumeMouseDelta(): { dx: number; dy: number } {
    const d = { dx: this.mouseDX, dy: this.mouseDY };
    this.mouseDX = 0;
    this.mouseDY = 0;
    return d;
  }

  endFrame(): void {
    this.pressedThisFrame.clear();
    this.buttonsPressed.clear();
  }

  private releaseAll(): void {
    this.down.clear();
    this.buttonsDown.clear();
  }

  dispose(): void {
    this.abort.abort();
  }

  /** Asks for pointer lock (needs a user gesture). Resolves true if the pointer ended up locked. */
  requestLock(): Promise<boolean> {
    if (this.isLocked) return Promise.resolve(true);
    // requestPointerLock returns a Promise in modern browsers; ignore rejections (e.g. user gesture
    // timing, or Chrome's ~1 s cooldown after Esc).
    try {
      const result = this.canvas.requestPointerLock() as unknown;
      if (result instanceof Promise) return result.then(() => this.isLocked, () => false);
    } catch {
      return Promise.resolve(false);
    }
    return Promise.resolve(this.isLocked);
  }

  /** Releases pointer lock if held. */
  exitLock(): void {
    if (this.isLocked) document.exitPointerLock();
  }

  private onKeyDown(e: KeyboardEvent): void {
    // Typing in a text field (chat, menus) is not game input.
    if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
    if (e.code === 'F3' || e.code === 'F6' || e.code === 'F7' || e.code === 'F8' || (this.isLocked && (e.code === 'Space' || e.code === 'KeyF' || e.code.startsWith('Arrow') || e.ctrlKey))) {
      e.preventDefault();
    }
    if (!e.repeat) this.pressedThisFrame.add(e.code);
    this.down.add(e.code);
  }

  private onMouseMove(e: MouseEvent): void {
    if (!this.isLocked) return;
    this.mouseDX += e.movementX;
    this.mouseDY += e.movementY;
  }
}
