/**
 * Pure touch-control math (Milestone 9), kept DOM-free so it is unit tested: the virtual joystick
 * vector and the tap / hold / drag classification of a finger on the look area.
 */

/** Joystick radius in CSS pixels: the knob's travel from the base centre. */
export const JOYSTICK_RADIUS = 56;
/** Fraction of the radius ignored around the centre. */
export const JOYSTICK_DEAD_ZONE = 0.12;
/** Pushing the stick at least this far (after the dead zone)... */
export const SPRINT_EDGE = 0.92;
/** ...and mostly forward (this much of the vector) sprints. */
export const SPRINT_FORWARD = 0.75;

export interface StickVector {
  /** Strafe -1..1 (right +). */
  x: number;
  /** Forward -1..1 (screen up = forward +). */
  z: number;
  /** Length 0..1 after the dead zone. */
  magnitude: number;
}

/**
 * Maps a finger offset from the joystick base (CSS px, screen y down) to a move vector. The length
 * is remapped so the dead zone edge is 0 and the rim is 1, so walking speed scales smoothly.
 */
export function joystickVector(dx: number, dy: number, radius = JOYSTICK_RADIUS, deadZone = JOYSTICK_DEAD_ZONE): StickVector {
  const len = Math.hypot(dx, dy);
  if (len === 0 || radius <= 0) return { x: 0, z: 0, magnitude: 0 };
  const raw = Math.min(1, len / radius);
  const m = raw <= deadZone ? 0 : (raw - deadZone) / (1 - deadZone);
  if (m === 0) return { x: 0, z: 0, magnitude: 0 };
  return { x: (dx / len) * m, z: (-dy / len) * m, magnitude: m };
}

/** True when the stick is pushed to the rim, mostly forward. */
export function stickSprints(v: StickVector): boolean {
  return v.magnitude >= SPRINT_EDGE && v.z >= SPRINT_FORWARD * v.magnitude;
}

/** Knob offset clamped to the rim (for drawing). */
export function clampToRadius(dx: number, dy: number, radius = JOYSTICK_RADIUS): { x: number; y: number } {
  const len = Math.hypot(dx, dy);
  if (len <= radius || len === 0) return { x: dx, y: dy };
  return { x: (dx / len) * radius, y: (dy / len) * radius };
}

// --- Look-area gestures ----------------------------------------------------------------------------

/** A finger that stays within this many CSS px of where it landed is not a drag. */
export const TAP_SLOP_PX = 10;
/** A finger held still this long (ms) becomes a hold (mine / eat). Releasing sooner is a tap. */
export const HOLD_MS = 280;

/**
 * - `pending`: just landed, still undecided.
 * - `drag`: moved past the slop before the hold time: look only; release does nothing.
 * - `hold`: held still past HOLD_MS: mine (or eat) while down; moving afterwards also looks.
 */
export type GesturePhase = 'pending' | 'drag' | 'hold';

export interface Gesture {
  startTime: number;
  startX: number;
  startY: number;
  lastX: number;
  lastY: number;
  phase: GesturePhase;
}

export function startGesture(x: number, y: number, now: number): Gesture {
  return { startTime: now, startX: x, startY: y, lastX: x, lastY: y, phase: 'pending' };
}

/**
 * Advances a gesture to time `now` with the finger at (x, y). Returns the look delta (CSS px) to
 * apply: nothing while pending (taps stay precise), the full motion once dragging or holding.
 */
export function updateGesture(g: Gesture, x: number, y: number, now: number): { dx: number; dy: number } {
  let dx = 0, dy = 0;
  if (g.phase === 'pending') {
    if (Math.hypot(x - g.startX, y - g.startY) > TAP_SLOP_PX) g.phase = 'drag';
    else if (now - g.startTime >= HOLD_MS) g.phase = 'hold';
  } else {
    dx = x - g.lastX;
    dy = y - g.lastY;
  }
  g.lastX = x;
  g.lastY = y;
  return { dx, dy };
}

/** Classifies the release: a short, still touch is a tap; anything else ends with no action. */
export function endGesture(g: Gesture, x: number, y: number, now: number): 'tap' | 'none' {
  updateGesture(g, x, y, now);
  return g.phase === 'pending' ? 'tap' : 'none';
}
