/**
 * Client-side prediction and server reconciliation (Milestone 10).
 *
 * The client runs the shared `stepPlayer` on its own inputs right away (no input lag) and keeps
 * every input it sent, by client tick. Each authoritative `playerState` from the server carries
 * the last input tick it simulated; `reconcile` snaps the local body to that state and replays
 * the inputs the server has not seen yet. Because client and server run the exact same physics
 * on the same inputs, the replayed position equals what the server will compute, unless the
 * world differed (an edit not seen yet) or the server corrected us (knockback, anti-cheat).
 *
 * The visual result is smoothed by `CorrectionSmoother`: the camera keeps showing where the
 * player was and the offset decays to zero over ~100 ms, unless the error is large (teleport).
 */
import { stepPlayer, type BlockGetter, type PlayerInput, type PlayerState } from '../physics/player';

export interface PredictedInput {
  tick: number;
  input: PlayerInput;
  /** Flight state requested with this input (creative). */
  flying: boolean;
}

/** Inputs sent but not yet acknowledged, oldest first. */
export class InputHistory {
  private list: PredictedInput[] = [];

  constructor(private readonly max = 256) {}

  get length(): number {
    return this.list.length;
  }

  push(tick: number, input: PlayerInput, flying: boolean): void {
    this.list.push({ tick, input: { ...input }, flying });
    if (this.list.length > this.max) this.list.shift();
  }

  /** Drops every input up to and including `tick`. */
  ack(tick: number): void {
    let i = 0;
    while (i < this.list.length && this.list[i]!.tick <= tick) i++;
    if (i > 0) this.list.splice(0, i);
  }

  pending(): readonly PredictedInput[] {
    return this.list;
  }

  clear(): void {
    this.list.length = 0;
  }
}

/** The authoritative body the server sends. */
export interface AuthoritativeBody {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  onGround: boolean;
  inWater: boolean;
  flying: boolean;
}

/** One predicted step, exactly as the server applies an input to its PlayerSim body. */
export function applyPredictedInput(state: PlayerState, entry: PredictedInput, getBlock: BlockGetter, dt: number, creative: boolean): void {
  state.flying = creative && entry.flying;
  stepPlayer(state, entry.input, getBlock, dt);
}

/**
 * Snaps `state` to the server's body at `ackTick`, then replays every input after it. Returns the
 * distance between the position before and after (how far the prediction was off).
 */
export function reconcile(
  state: PlayerState,
  server: AuthoritativeBody,
  ackTick: number,
  history: InputHistory,
  getBlock: BlockGetter,
  dt: number,
  creative: boolean,
): number {
  const bx = state.x, by = state.y, bz = state.z;
  history.ack(ackTick);
  state.x = server.x;
  state.y = server.y;
  state.z = server.z;
  state.vx = server.vx;
  state.vy = server.vy;
  state.vz = server.vz;
  state.onGround = server.onGround;
  state.inWater = server.inWater;
  state.flying = server.flying;
  for (const e of history.pending()) applyPredictedInput(state, e, getBlock, dt, creative);
  return Math.hypot(state.x - bx, state.y - by, state.z - bz);
}

/**
 * Hides small reconciliation corrections: `x/y/z` is added to the rendered position and decays
 * exponentially. Errors larger than `snapDistance` are not smoothed (snap).
 */
export class CorrectionSmoother {
  x = 0;
  y = 0;
  z = 0;

  constructor(
    /** Decay rate (1/s). */
    private readonly rate = 15,
    readonly snapDistance = 2,
  ) {}

  /** The body moved from `b` (before) to `a` (after) because of a correction. */
  correct(bx: number, by: number, bz: number, ax: number, ay: number, az: number): void {
    const dx = bx - ax, dy = by - ay, dz = bz - az;
    if (Math.hypot(dx + this.x, dy + this.y, dz + this.z) > this.snapDistance) {
      this.reset();
      return;
    }
    this.x += dx;
    this.y += dy;
    this.z += dz;
  }

  update(dt: number): void {
    const k = Math.exp(-this.rate * dt);
    this.x *= k;
    this.y *= k;
    this.z *= k;
    if (Math.abs(this.x) + Math.abs(this.y) + Math.abs(this.z) < 1e-4) this.reset();
  }

  reset(): void {
    this.x = this.y = this.z = 0;
  }
}
