import { BlockId, REACH_DISTANCE, getItemDef, placementVariant, raycastBlocks, type Mob, type RaycastHit, type Vec3 } from '@voxel/shared';
import type { PlayerIntent } from '../input/intent';
import type { GameSession } from './session';

/** Seconds between repeated breaks (creative) / places while a mouse button is held. */
export const REPEAT_SECONDS = 0.25;
/** Pause after a survival break before the next block starts. */
const BREAK_COOLDOWN = 0.2;
/** Mobs can be hit up to this far away (blocks are reachable to REACH_DISTANCE). */
export const ATTACK_REACH = 4;

type Button = 'primary' | 'secondary';

export interface InteractionHooks {
  /** Right click on a workbench (not sneaking). */
  openWorkbench(pos: { x: number; y: number; z: number }): void;
}

/**
 * Per-frame block and mob targeting and intent-driven actions; all changes go through the session.
 * The block ray and the mob ray (ray vs each mob's box) are both cast from the crosshair (screen
 * centre, also for touch); the nearer hit wins.
 * - Primary (left click / touch tap on a mob / touch hold) on a mob: attack (one hit per press;
 *   damage scales with the attack cooldown).
 * - Primary: survival accumulates break progress on the targeted block (reset when the target
 *   changes or the button is released); creative breaks instantly, repeating every REPEAT_SECONDS.
 * - Secondary (right click / touch tap / touch hold with food): opens a workbench, eats held food
 *   (hold), or places the held block.
 */
export class BlockInteraction {
  /** The block under the crosshair this frame, or null. */
  target: RaycastHit | null = null;
  /** The mob under the crosshair (nearer than any block), or null. */
  entityTarget: { mob: Mob; distance: number } | null = null;
  /** Survival break progress 0..1 on `breaking`. */
  breakProgress = 0;
  breaking: { x: number; y: number; z: number } | null = null;
  /** Seconds spent eating so far. */
  eatSeconds = 0;
  private breakTimer = 0;
  private placeTimer = 0;
  private breakCooldown = 0;

  constructor(
    private readonly session: GameSession,
    /** Refilled every animation frame by `Controls.sample`. */
    private readonly intent: PlayerIntent,
    private readonly hooks: InteractionHooks,
  ) {}

  /** `eye` and `dir` are the interpolated camera eye and look direction. */
  update(frameDt: number, eye: Vec3, dir: Vec3, enabled: boolean): void {
    const s = this.session;
    this.target = s.spawned && !s.dead
      ? raycastBlocks(s.getBlock, eye[0]!, eye[1]!, eye[2]!, dir[0]!, dir[1]!, dir[2]!, REACH_DISTANCE)
      : null;
    const mobHit = s.spawned && !s.dead ? s.mobs.raycast(eye[0]!, eye[1]!, eye[2]!, dir[0]!, dir[1]!, dir[2]!, ATTACK_REACH) : null;
    // Nearest wins: a mob in front of the block hides the block target (no outline, no breaking).
    this.entityTarget = mobHit && (!this.target || mobHit.distance < this.target.distance) ? mobHit : null;
    if (this.entityTarget) this.target = null;
    if (!enabled || s.dead) {
      this.breakTimer = this.placeTimer = 0;
      this.resetBreak();
      this.eatSeconds = 0;
      return;
    }
    if (this.entityTarget && this.intent.primaryPressed) {
      s.attackMob(this.entityTarget.mob);
      this.breakTimer = REPEAT_SECONDS;
    }
    if (s.creative) {
      this.resetBreak();
      if (this.repeat('primary', frameDt, 'break')) this.breakTarget();
    } else {
      this.survivalBreak(frameDt);
    }
    this.rightButton(frameDt);
  }

  breakTarget(): boolean {
    const t = this.target;
    return !!t && this.session.requestBreak({ x: t.x, y: t.y, z: t.z }).ok;
  }

  placeAtTarget(): boolean {
    const t = this.target;
    if (!t || t.face < 0) return false;
    // Slabs, stairs and rails: the orientation comes from where the block was clicked and the look direction.
    const held = this.session.heldStack;
    const item = held ? getItemDef(held.item).block : undefined;
    const variant = item === undefined ? undefined : placementVariant(item, t.face, t.py - t.placeY, this.session.yaw);
    return this.session.requestPlace({ x: t.placeX, y: t.placeY, z: t.placeZ }, { x: t.x, y: t.y, z: t.z, face: t.face }, variant).ok;
  }

  private resetBreak(): void {
    this.breakProgress = 0;
    this.breaking = null;
  }

  private survivalBreak(dt: number): void {
    this.breakCooldown = Math.max(0, this.breakCooldown - dt);
    const t = this.target;
    if (!t || !this.intent.primary) {
      this.resetBreak();
      return;
    }
    const b = this.breaking;
    if (!b || b.x !== t.x || b.y !== t.y || b.z !== t.z) {
      // Looked at another block: start over.
      this.breaking = { x: t.x, y: t.y, z: t.z };
      this.breakProgress = 0;
    }
    if (this.breakCooldown > 0) return;
    const secs = this.session.breakSeconds(t);
    if (!Number.isFinite(secs)) return;
    this.breakProgress += secs <= 0 ? 1 : dt / secs;
    if (this.breakProgress >= 1) {
      this.session.requestBreak({ x: t.x, y: t.y, z: t.z });
      this.resetBreak();
      this.breakCooldown = BREAK_COOLDOWN;
    }
  }

  private rightButton(dt: number): void {
    const s = this.session;
    if (!this.intent.secondary) {
      this.eatSeconds = 0;
      this.placeTimer = 0;
      return;
    }
    const t = this.target;
    const sneaking = this.intent.sneak;
    if (this.intent.secondaryPressed && t && t.blockId === BlockId.Workbench && !sneaking) {
      this.placeTimer = REPEAT_SECONDS;
      this.hooks.openWorkbench({ x: t.x, y: t.y, z: t.z });
      return;
    }
    if (s.canEatHeld()) {
      this.eatSeconds += dt;
      const food = getItemDef(s.heldStack!.item).food!;
      if (this.eatSeconds >= food.eatSeconds) {
        s.eatHeld();
        this.eatSeconds = 0;
      }
      return;
    }
    this.eatSeconds = 0;
    if (this.repeat('secondary', dt, 'place')) this.placeAtTarget();
  }

  /** True on the press frame, then every REPEAT_SECONDS while held. */
  private repeat(button: Button, dt: number, which: 'break' | 'place'): boolean {
    const key = which === 'break' ? 'breakTimer' : 'placeTimer';
    const pressed = button === 'primary' ? this.intent.primaryPressed : this.intent.secondaryPressed;
    const down = button === 'primary' ? this.intent.primary : this.intent.secondary;
    if (pressed) {
      this[key] = REPEAT_SECONDS;
      return true;
    }
    if (!down) {
      this[key] = 0;
      return false;
    }
    this[key] -= dt;
    if (this[key] > 0) return false;
    this[key] += REPEAT_SECONDS;
    if (this[key] <= 0) this[key] = REPEAT_SECONDS; // long frame: don't fire a burst
    return true;
  }
}
