/**
 * The mob AI state machine (Milestone 8), as a pure transition function of the mob and what it
 * perceives this tick, so it can be tested with synthetic inputs.
 *
 * Passive (sheep, pig, chicken):  idle <-> wander;  hit -> flee (fleeSeconds) -> idle.
 * Hostile (Gloomwalker, Bilespitter):
 *   idle <-> wander;  sees a targetable player within sightRange -> chase;
 *   chase -> attack when in attack range; attack -> chase when out of range;
 *   chase/attack -> idle when the target is lost (out of 1.5 x sightRange, or not targetable —
 *   creative, dead); being hit by a targetable player -> chase.
 * Any state -> dead when health reaches 0 (handled by the system, never left).
 */
import type { AiState, Mob } from './mob';

export interface Perception {
  /** A player that may be attacked exists (alive, survival). */
  targetable: boolean;
  /** Distance between the mob's and the player's centres (eyes), blocks. */
  targetDistance: number;
  /** Horizontal gap between the two bodies (0 = touching), for melee reach. */
  edgeDistance: number;
  /** Vertical offset target feet - mob feet. */
  targetDy: number;
  /** Line of sight from the mob's eyes to the player's eyes. */
  canSee: boolean;
  /** Hit since the last update (by anything). */
  wasHit: boolean;
}

/** Idle/wander durations, seconds. */
export const IDLE_MIN = 2;
export const IDLE_MAX = 7;
export const WANDER_MAX = 8;
/** Hysteresis: leave melee attack only when this much further than the reach. */
const ATTACK_EXIT_MARGIN = 0.6;

/** Whether the target is within the mob's attack range. `leaving` adds hysteresis. */
export function inAttackRange(mob: Mob, p: Perception, leaving = false): boolean {
  const atk = mob.type.behaviour.attack;
  if (!atk) return false;
  if (atk.kind === 'melee') return p.edgeDistance <= atk.reach + (leaving ? ATTACK_EXIT_MARGIN : 0) && Math.abs(p.targetDy) < 1.6;
  return p.canSee && p.targetDistance <= atk.range + (leaving ? 2 : 0);
}

/**
 * Returns the state the mob should be in now. Does not mutate; the system applies the change
 * (`enterState`) and its side effects (paths, timers).
 */
export function nextAiState(mob: Mob, p: Perception): AiState {
  const ai = mob.ai;
  const b = mob.type.behaviour;
  if (mob.health.deathTime >= 0) return 'dead';
  if (!mob.type.hostile) {
    if (p.wasHit && b.fleeSeconds > 0) return 'flee';
    if (ai.state === 'flee') return ai.stateTime >= ai.stateDuration ? 'idle' : 'flee';
    return idleOrWander(mob);
  }

  // Hostile.
  const engaged = ai.state === 'chase' || ai.state === 'attack';
  if (!p.targetable) return engaged ? 'idle' : idleOrWander(mob);
  if (engaged) {
    if (p.targetDistance > b.sightRange * 1.5) return 'idle';
    if (ai.state === 'attack') return inAttackRange(mob, p, true) ? 'attack' : 'chase';
    return inAttackRange(mob, p) ? 'attack' : 'chase';
  }
  if (p.wasHit || (p.canSee && p.targetDistance <= b.sightRange)) return inAttackRange(mob, p) ? 'attack' : 'chase';
  return idleOrWander(mob);
}

/** Idle until its time is up, then wander until that is up (or the system ends it), and repeat. */
function idleOrWander(mob: Mob): AiState {
  const ai = mob.ai;
  const done = ai.stateTime >= ai.stateDuration;
  if (ai.state === 'idle') return done ? 'wander' : 'idle';
  if (ai.state === 'wander') return done ? 'idle' : 'wander';
  return 'idle';
}

/** How long a newly entered state lasts before it is reconsidered. */
export function stateDurationFor(mob: Mob, state: AiState, roll: number): number {
  switch (state) {
    case 'idle':
      return IDLE_MIN + roll * (IDLE_MAX - IDLE_MIN);
    case 'wander':
      return WANDER_MAX;
    case 'flee':
      return mob.type.behaviour.fleeSeconds;
    default:
      return Infinity;
  }
}
