import {
  ENTITY_FLAG,
  ENTITY_KIND,
  ITEM_COUNT,
  InterpolationBuffer,
  MOB_TYPES,
  PLAYER_AVATAR,
  ServerClock,
  TICK_RATE,
  createItemEntity,
  createMob,
  type EntitiesMsg,
  type EntityPose,
  type EntitySnapshot,
  type ItemEntity,
  type Mob,
  type MobSystem,
  type ItemEntitySystem,
  type Projectile,
} from '@voxel/shared';

/** A remote entity mirrored from snapshots. */
interface Remote {
  id: number;
  kind: EntitySnapshot['kind'];
  buffer: InterpolationBuffer;
  flags: number;
  /** Mob / avatar object (players and mobs), or item entity, or projectile. */
  mob?: Mob;
  item?: ItemEntity;
  projectile?: Projectile;
  /** Last snapshot time it appeared in (server ms). */
  seen: number;
}

export interface RemotePlayerView {
  id: number;
  name: string;
  avatar: Mob;
  /** Rendered eye-level position for the name tag. */
  x: number;
  y: number;
  z: number;
}

const pose: EntityPose = { x: 0, y: 0, z: 0, yaw: 0, pitch: 0, headYaw: 0 };
const MS_PER_TICK = 1000 / TICK_RATE;

/**
 * Mirrors the server's entities on the client (Milestone 10). Each snapshot entry goes into a
 * per-entity `InterpolationBuffer` keyed by server time; every frame `update` samples them
 * ~100 ms in the past and writes the pose into the objects the existing renderers draw: mobs
 * live in the session's `MobSystem` store (so targeting and attacking work unchanged), items in
 * its `ItemEntitySystem`, projectiles in `mobs.projectiles`, and other players are `Mob` objects
 * using the `PLAYER_AVATAR` box model.
 */
export class RemoteEntities {
  readonly clock = new ServerClock();
  private readonly remotes = new Map<number, Remote>();
  private readonly names = new Map<number, string>();
  readonly players: RemotePlayerView[] = [];
  /** Snapshots received / entities in the last one (debug). */
  snapshots = 0;
  lastCount = 0;
  /** An item entity was removed by the server (picked up, merged or despawned); for sounds. */
  onItemRemoved: ((x: number, y: number, z: number) => void) | undefined;

  constructor(
    private readonly mobs: MobSystem,
    private readonly items: ItemEntitySystem,
    private readonly selfId: number,
  ) {}

  setName(id: number, name: string): void {
    this.names.set(id, name);
  }

  forgetName(id: number): void {
    this.names.delete(id);
  }

  nameOf(id: number): string | undefined {
    return this.names.get(id);
  }

  get count(): number {
    return this.remotes.size;
  }

  onSnapshot(m: EntitiesMsg, localMs: number): void {
    const serverMs = m.serverTick * MS_PER_TICK;
    this.clock.observe(serverMs, localMs);
    this.snapshots++;
    this.lastCount = m.entities.length;
    for (const e of m.entities) {
      if (e.id === this.selfId) continue;
      let r = this.remotes.get(e.id);
      if (!r || r.kind !== e.kind) {
        if (r) this.remove(r);
        const created = this.create(e);
        if (!created) continue;
        r = created;
        this.remotes.set(e.id, r);
      }
      r.flags = e.flags;
      r.seen = serverMs;
      if (r.item) r.item.stack.count = Math.max(1, e.count);
      r.buffer.push({ time: serverMs, x: e.x, y: e.y, z: e.z, yaw: e.yaw, pitch: e.pitch, headYaw: e.headYaw });
    }
    for (const id of m.removed) {
      const r = this.remotes.get(id);
      if (!r) continue;
      if (r.item) this.onItemRemoved?.(r.item.x, r.item.y, r.item.z);
      this.remove(r);
    }
  }

  private create(e: EntitySnapshot): Remote | undefined {
    const base = { id: e.id, kind: e.kind, buffer: new InterpolationBuffer(), flags: e.flags, seen: 0 };
    switch (e.kind) {
      case ENTITY_KIND.player:
        return { ...base, mob: { ...createMob(PLAYER_AVATAR, e.x, e.y, e.z, e.yaw), id: e.id } };
      case ENTITY_KIND.mob: {
        const type = MOB_TYPES[e.type];
        if (!type) return undefined;
        const mob: Mob = { ...createMob(type, e.x, e.y, e.z, e.yaw), id: e.id };
        this.mobs.entities.add(mob);
        return { ...base, mob };
      }
      case ENTITY_KIND.item: {
        if (e.type >= ITEM_COUNT) return undefined;
        const item: ItemEntity = { ...createItemEntity({ item: e.type, count: Math.max(1, e.count), damage: 0 }, e.x, e.y, e.z, 0, 0, 0, 0, e.yaw), id: e.id };
        item.onGround = true;
        this.items.entities.add(item);
        return { ...base, item };
      }
      case ENTITY_KIND.projectile:
        return {
          ...base,
          projectile: { id: e.id, x: e.x, y: e.y, z: e.z, vx: 0, vy: 0, vz: 0, age: 0, damage: 0, knockback: 0, source: MOB_TYPES[0]! },
        };
      default:
        return undefined;
    }
  }

  private remove(r: Remote): void {
    this.remotes.delete(r.id);
    if (r.mob && r.kind === ENTITY_KIND.mob) this.mobs.entities.remove(r.mob);
    if (r.item) this.items.entities.remove(r.item);
  }

  /** Samples every entity at the interpolation time and updates the render objects. */
  update(localMs: number, dt: number): void {
    const t = this.clock.renderTime(localMs);
    this.players.length = 0;
    const projectiles = this.mobs.projectiles;
    projectiles.length = 0;
    for (const r of this.remotes.values()) {
      if (!r.buffer.sample(t, pose)) continue;
      if (r.mob) {
        this.poseMob(r.mob, r.flags, dt, r.kind === ENTITY_KIND.player);
        if (r.kind === ENTITY_KIND.player) {
          const m = r.mob;
          this.players.push({ id: r.id, name: this.names.get(r.id) ?? 'player', avatar: m, x: m.x, y: m.y + 2.05, z: m.z });
        }
      } else if (r.item) {
        const e = r.item;
        e.x = pose.x;
        e.y = pose.y;
        e.z = pose.z;
      } else if (r.projectile) {
        const p = r.projectile;
        p.x = pose.x;
        p.y = pose.y;
        p.z = pose.z;
        p.age += dt;
        projectiles.push(p);
      }
    }
  }

  private poseMob(m: Mob, flags: number, dt: number, isPlayer: boolean): void {
    const moved = Math.hypot(pose.x - m.x, pose.z - m.z);
    m.x = m.prevX = pose.x;
    m.y = m.prevY = pose.y;
    m.z = m.prevZ = pose.z;
    m.yaw = m.prevYaw = pose.yaw;
    const a = m.anim;
    if (isPlayer) {
      a.headYaw = 0;
      a.headPitch = pose.pitch;
    } else {
      a.headYaw = pose.headYaw;
      a.headPitch = pose.pitch;
    }
    // Walk cycle from the interpolated speed (the server's anim state is not sent).
    const speed = dt > 0 ? moved / dt : 0;
    if ((flags & ENTITY_FLAG.onGround) !== 0 || isPlayer) a.walkPhase = (a.walkPhase + Math.min(speed, 8) * dt * 5) % (Math.PI * 2);
    const want = Math.min(1, speed / Math.max(0.5, m.type.speed));
    a.walkAmount += (want - a.walkAmount) * (1 - Math.exp(-8 * dt));
    const h = m.health;
    h.hurtTime = (flags & ENTITY_FLAG.hurt) !== 0 ? 0.3 : 0;
    h.burning = (flags & ENTITY_FLAG.burning) !== 0;
    if ((flags & ENTITY_FLAG.dying) !== 0) h.deathTime = h.deathTime < 0 ? 0 : h.deathTime + dt;
    else h.deathTime = -1;
    m.ai.swingTime = (flags & ENTITY_FLAG.swinging) !== 0 ? 0.3 : 0;
  }

  clear(): void {
    for (const r of [...this.remotes.values()]) this.remove(r);
    this.players.length = 0;
    this.mobs.projectiles.length = 0;
  }
}
