import { CHUNK_SIZE, Chunk, chunkKey, decodeChunkBlocks, type BlockChange, type ChunkMsg, type World } from '@voxel/shared';
import type { GenRequest, GenResponse } from './genProtocol';
import type { ChunkAddHandler, ChunkSource, ChunkUnloadHandler } from './chunkStreamer';
import { WorkerSet, type WorkerSlot } from '../workers/workerSet';

/** Mesh a chunk anyway after this long, even if a neighbour inside the view never arrived. */
const NEIGHBOUR_WAIT_MS = 2000;

/**
 * Multiplayer chunk source (Milestone 10): the server pushes chunks (codec-compressed blocks)
 * and tells us when to drop them. Blocks are decoded on the main thread (cheap RLE) and lit on
 * the same gen workers single-player uses (`GenRequest.blocks`), then added to the World and
 * stitched exactly like generated chunks, so the meshing pipeline is unchanged.
 *
 * Block changes for a chunk that is still being lit are queued and applied when it is added.
 */
export class RemoteChunkStreamer implements ChunkSource {
  viewDistance: number;
  private readonly workers: WorkerSet<GenResponse, ChunkMsg>;
  private nextJob = 1;
  /** Chunks the server says we have (received and not unloaded). */
  private readonly known = new Set<number>();
  /** Chunks sent to a worker and not back yet. */
  private readonly lighting = new Set<number>();
  private readonly ready: GenResponse[] = [];
  private readonly queuedEdits = new Map<number, BlockChange[]>();
  private readonly addedAt = new Map<number, number>();
  private centerCx = 0;
  private centerCz = 0;
  onAdd: ChunkAddHandler | undefined;
  /** Edits that arrived while their chunk was being lit; applied right after it is added. */
  onQueuedEdits: ((changes: BlockChange[]) => void) | undefined;
  // Stats in the same shape as ChunkStreamer (debug overlay).
  unloaded = 0;
  loadedFromSave = 0;
  staleDropped = 0;
  avgGenMs = 0;
  avgLightMs = 0;
  received = 0;
  private disposed = false;

  constructor(
    private readonly world: World,
    private readonly onUnload: ChunkUnloadHandler,
    viewDistance: number,
    workerCount: number,
    private readonly maxAddsPerFrame = 6,
  ) {
    this.viewDistance = viewDistance;
    this.workers = new WorkerSet<GenResponse, ChunkMsg>({
      create: () => new Worker(new URL('./genWorker.ts', import.meta.url), { type: 'module' }),
      count: workerCount,
      label: 'Chunk lighting',
      retryKey: (m) => chunkKey(m.cx, m.cz),
      onResult: (slot, res) => this.onResult(slot, res),
      // The server's chunk message is kept until lit, so a crashed worker's chunks are re-sent.
      onLost: (lost) => {
        for (const { job: m, attempts } of lost) {
          this.lighting.delete(chunkKey(m.cx, m.cz));
          if (attempts <= 2 && this.known.has(chunkKey(m.cx, m.cz))) this.receive(m);
        }
      },
    });
  }

  get workerCount(): number {
    return this.workers.size;
  }

  /** Workers replaced after crashing. */
  get restarts(): number {
    return this.workers.restarts;
  }

  get queueLength(): number {
    return this.lighting.size + this.ready.length;
  }

  get inFlight(): number {
    return this.lighting.size;
  }

  /** A chunk from the server: decode and light it on a worker. */
  receive(m: ChunkMsg): void {
    if (this.disposed) return;
    const key = chunkKey(m.cx, m.cz);
    let blocks: Uint16Array;
    try {
      blocks = decodeChunkBlocks({ palette: m.palette, rle: m.rle }).blocks;
    } catch (err) {
      console.error(`Bad chunk ${m.cx},${m.cz} from server`, err);
      return;
    }
    this.received++;
    this.known.add(key);
    if (this.world.getChunk(m.cx, m.cz)) this.removeLoaded(m.cx, m.cz); // resent: replace
    this.lighting.add(key);
    const slot = this.workers.leastBusy();
    const job = this.nextJob++;
    // Light only (blocks given): the generator fields are not used.
    const req: GenRequest = { job, generator: 'terrain', seed: 0, cx: m.cx, cz: m.cz, blocks };
    this.workers.post(slot, job, m, req, [blocks.buffer]);
  }

  /** The server dropped this chunk from our view. */
  unload(cx: number, cz: number): void {
    const key = chunkKey(cx, cz);
    this.known.delete(key);
    this.queuedEdits.delete(key);
    this.removeLoaded(cx, cz);
  }

  /** Queues a change for a chunk still being lit. Returns false if the caller should apply it now. */
  queueEdit(c: BlockChange): boolean {
    const key = chunkKey(c.x >> 4, c.z >> 4);
    if (this.world.getChunk(c.x >> 4, c.z >> 4) || !this.known.has(key)) return false;
    let list = this.queuedEdits.get(key);
    if (!list) this.queuedEdits.set(key, (list = []));
    list.push(c);
    return true;
  }

  private removeLoaded(cx: number, cz: number): void {
    const chunk = this.world.removeChunk(cx, cz);
    this.addedAt.delete(chunkKey(cx, cz));
    if (chunk) {
      this.onUnload(cx, cz, chunk);
      this.unloaded++;
    }
  }

  private onResult(slot: WorkerSlot<ChunkMsg>, res: GenResponse): void {
    this.workers.done(slot, res.job);
    const key = chunkKey(res.cx, res.cz);
    this.lighting.delete(key);
    this.avgLightMs = this.avgLightMs === 0 ? res.lightMs : this.avgLightMs * 0.95 + res.lightMs * 0.05;
    if (!this.known.has(key)) {
      this.staleDropped++;
      return;
    }
    this.ready.push(res);
  }

  isWanted(cx: number, cz: number): boolean {
    return this.known.has(chunkKey(cx, cz));
  }

  private inView(cx: number, cz: number): boolean {
    const dx = cx - this.centerCx, dz = cz - this.centerCz;
    return dx * dx + dz * dz <= this.viewDistance * this.viewDistance;
  }

  canMesh(cx: number, cz: number): boolean {
    if (!this.known.has(chunkKey(cx, cz))) return false;
    const added = this.addedAt.get(chunkKey(cx, cz));
    if (added !== undefined && performance.now() - added > NEIGHBOUR_WAIT_MS) return true;
    const ok = (nx: number, nz: number): boolean => !!this.world.getChunk(nx, nz) || (!this.known.has(chunkKey(nx, nz)) && !this.inView(nx, nz));
    return ok(cx + 1, cz) && ok(cx - 1, cz) && ok(cx, cz + 1) && ok(cx, cz - 1);
  }

  update(camX: number, camZ: number): void {
    this.centerCx = Math.floor(camX / CHUNK_SIZE);
    this.centerCz = Math.floor(camZ / CHUNK_SIZE);
    let added = 0;
    while (this.ready.length > 0 && added < this.maxAddsPerFrame) {
      const res = this.ready.shift()!;
      const key = chunkKey(res.cx, res.cz);
      if (!this.known.has(key) || this.world.getChunk(res.cx, res.cz) || this.lighting.has(key)) {
        this.staleDropped++;
        continue;
      }
      const chunk = new Chunk(res.cx, res.cz, res.blocks, res.light);
      chunk.recount();
      this.world.addChunk(chunk);
      this.addedAt.set(key, performance.now());
      this.onAdd?.(chunk);
      const edits = this.queuedEdits.get(key);
      if (edits) {
        this.queuedEdits.delete(key);
        this.onQueuedEdits?.(edits);
      }
      added++;
    }
  }

  setViewDistance(chunks: number): void {
    // The server decides what we receive; this only affects the meshing neighbour rule.
    this.viewDistance = chunks;
  }

  dispose(): void {
    this.disposed = true;
    this.workers.dispose();
    this.ready.length = 0;
    this.known.clear();
    this.lighting.clear();
  }
}
