/**
 * Sound (Milestone 11). Every sound is synthesized in code with the Web Audio API: filtered noise
 * bursts and short oscillator envelopes. There are no audio files and nothing is sampled from
 * other games.
 *
 * Graph: one-shot sounds -> [pan + distance gain] -> effects bus -> underwater low-pass -> master
 * -> destination; ambient loops (wind, cave) -> ambient bus -> master.
 *
 * Browsers only let audio start after a user gesture, so the AudioContext is created (or resumed)
 * on the first pointerdown / keydown / touchend (`installUnlock`). Until then `play` does nothing.
 * The context is suspended while the tab is hidden.
 */
import { MAX_SOUND_DISTANCE, spatialize, type Listener, type Material } from './spatial';

export interface Volumes {
  master: number;
  effects: number;
  ambient: number;
}

export type MobVoice = 'sheep' | 'pig' | 'chicken' | 'gloomwalker' | 'bilespitter';

export type SoundName =
  | `break_${Material}`
  | `place_${Material}`
  | `step_${Material}`
  | `hit_${Material}`
  | 'jump'
  | 'land'
  | 'splash'
  | 'hurt'
  | 'death'
  | 'eat'
  | 'pickup'
  | 'click'
  | 'mob_attack'
  | 'mob_hurt'
  | 'mob_death'
  | 'glob'
  | 'splat'
  | 'swing'
  | `voice_${MobVoice}`;

export interface PlayOptions {
  /** World position; omitted = played "in your head" (UI, own body). */
  x?: number;
  y?: number;
  z?: number;
  /** Extra volume factor (default 1). */
  volume?: number;
  /** Playback pitch factor (default 1, small random variation is added anyway). */
  pitch?: number;
}

type Ctx = AudioContext;

/** A tiny deterministic-enough RNG for per-sound variation. */
const rnd = (a: number, b: number): number => a + Math.random() * (b - a);

interface MaterialVoice {
  /** Noise filter type / centre frequency / Q. */
  filter: BiquadFilterType;
  freq: number;
  q: number;
  /** Seconds of the main burst. */
  dur: number;
  /** Optional tonal body (knock) frequency. */
  tone?: number;
  gain: number;
  /** Number of grains (crunchy materials use several tiny bursts). */
  grains: number;
}

const MATERIAL_VOICES: Record<Material, MaterialVoice> = {
  stone: { filter: 'bandpass', freq: 1700, q: 1.2, dur: 0.12, tone: 140, gain: 0.55, grains: 2 },
  wood: { filter: 'bandpass', freq: 700, q: 3, dur: 0.1, tone: 230, gain: 0.6, grains: 1 },
  dirt: { filter: 'lowpass', freq: 900, q: 0.7, dur: 0.16, gain: 0.55, grains: 3 },
  grass: { filter: 'bandpass', freq: 2400, q: 0.8, dur: 0.14, gain: 0.35, grains: 4 },
  sand: { filter: 'highpass', freq: 2800, q: 0.6, dur: 0.22, gain: 0.3, grains: 5 },
  glass: { filter: 'highpass', freq: 3500, q: 1, dur: 0.08, gain: 0.35, grains: 1 },
  wool: { filter: 'lowpass', freq: 450, q: 0.5, dur: 0.18, gain: 0.5, grains: 1 },
  leaves: { filter: 'bandpass', freq: 3200, q: 0.6, dur: 0.16, gain: 0.3, grains: 4 },
};

export class AudioEngine {
  ctx: Ctx | undefined;
  private master!: GainNode;
  private effects!: GainNode;
  private ambient!: GainNode;
  private muffle!: BiquadFilterNode;
  private noise!: AudioBuffer;
  private brown!: AudioBuffer;
  private wind: { gain: GainNode; filter: BiquadFilterNode } | undefined;
  private cave: { gain: GainNode } | undefined;
  private dripTimer = 3;
  private volumes: Volumes = { master: 0.8, effects: 1, ambient: 0.6 };
  private listener: Listener = { x: 0, y: 0, z: 0, rightX: 1, rightZ: 0 };
  private unlockInstalled = false;
  private hidden = typeof document !== 'undefined' && document.visibilityState === 'hidden';
  /** Counters for tests / the debug overlay. */
  readonly stats = { played: 0, culled: 0, lastSound: '' as string, errors: 0 };

  get unlocked(): boolean {
    return !!this.ctx;
  }

  get state(): string {
    return this.ctx?.state ?? 'locked';
  }

  /** Creates / resumes the context on the first user gesture; suspends while the tab is hidden. */
  installUnlock(target: Window = window): void {
    if (this.unlockInstalled) return;
    this.unlockInstalled = true;
    const unlock = (): void => {
      this.ensureContext();
      if (this.ctx && this.ctx.state === 'suspended' && !this.hidden) void this.ctx.resume().catch(() => {});
    };
    for (const ev of ['pointerdown', 'keydown', 'touchend'] as const) target.addEventListener(ev, unlock, { capture: true, passive: true });
    document.addEventListener('visibilitychange', () => {
      this.hidden = document.visibilityState === 'hidden';
      if (!this.ctx) return;
      if (this.hidden) void this.ctx.suspend().catch(() => {});
      else void this.ctx.resume().catch(() => {});
    });
  }

  private ensureContext(): void {
    if (this.ctx) return;
    const AC = (window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext) as typeof AudioContext | undefined;
    if (!AC) return;
    try {
      const ctx = new AC();
      this.ctx = ctx;
      this.master = ctx.createGain();
      this.master.connect(ctx.destination);
      this.muffle = ctx.createBiquadFilter();
      this.muffle.type = 'lowpass';
      this.muffle.frequency.value = 20000;
      this.muffle.connect(this.master);
      this.effects = ctx.createGain();
      this.effects.connect(this.muffle);
      this.ambient = ctx.createGain();
      this.ambient.connect(this.master);
      this.noise = this.makeNoise(ctx, false);
      this.brown = this.makeNoise(ctx, true);
      this.applyVolumes();
      this.startAmbient();
    } catch (err) {
      console.warn('Audio unavailable', err);
      this.ctx = undefined;
    }
  }

  private makeNoise(ctx: Ctx, brown: boolean): AudioBuffer {
    const len = Math.floor(ctx.sampleRate * 2);
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      if (brown) {
        last = (last + 0.02 * w) / 1.02;
        d[i] = last * 3.5;
      } else d[i] = w;
    }
    return buf;
  }

  setVolumes(v: Volumes): void {
    this.volumes = { ...v };
    this.applyVolumes();
  }

  private applyVolumes(): void {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const v = this.volumes;
    this.master.gain.setTargetAtTime(v.master, t, 0.03);
    this.effects.gain.setTargetAtTime(v.effects, t, 0.03);
    this.ambient.gain.setTargetAtTime(v.ambient, t, 0.03);
  }

  /** Camera eye and horizontal right vector, once per frame. */
  setListener(x: number, y: number, z: number, rightX: number, rightZ: number): void {
    const l = this.listener;
    l.x = x;
    l.y = y;
    l.z = z;
    l.rightX = rightX;
    l.rightZ = rightZ;
  }

  /** Low-passes world sounds (head under water). */
  setMuffled(on: boolean): void {
    if (!this.ctx) return;
    this.muffle.frequency.setTargetAtTime(on ? 650 : 20000, this.ctx.currentTime, 0.08);
  }

  /** Ambient loop levels 0..1 (smoothed); `dt` drives the occasional cave drip. */
  setAmbient(wind: number, cave: number, dt: number): void {
    const ctx = this.ctx;
    if (!ctx || !this.wind || !this.cave) return;
    const t = ctx.currentTime;
    this.wind.gain.gain.setTargetAtTime(wind * 0.16, t, 1.2);
    this.cave.gain.gain.setTargetAtTime(cave * 0.22, t, 1.2);
    if (cave > 0.3) {
      this.dripTimer -= dt;
      if (this.dripTimer <= 0) {
        this.dripTimer = rnd(4, 11);
        this.drip(cave);
      }
    }
  }

  /** Silences the ambient loops (title screen, between worlds). */
  stopAmbient(): void {
    this.setAmbient(0, 0, 0);
  }

  private startAmbient(): void {
    const ctx = this.ctx!;
    // Wind: looping white noise through a slowly wandering band-pass.
    const wsrc = ctx.createBufferSource();
    wsrc.buffer = this.noise;
    wsrc.loop = true;
    const wf = ctx.createBiquadFilter();
    wf.type = 'bandpass';
    wf.frequency.value = 420;
    wf.Q.value = 0.9;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 220;
    lfo.connect(lfoGain).connect(wf.frequency);
    const wg = ctx.createGain();
    wg.gain.value = 0;
    wsrc.connect(wf).connect(wg).connect(this.ambient);
    wsrc.start();
    lfo.start();
    this.wind = { gain: wg, filter: wf };
    // Cave: deep brown-noise rumble plus a faint low hum.
    const csrc = ctx.createBufferSource();
    csrc.buffer = this.brown;
    csrc.loop = true;
    const cf = ctx.createBiquadFilter();
    cf.type = 'lowpass';
    cf.frequency.value = 160;
    const hum = ctx.createOscillator();
    hum.type = 'sine';
    hum.frequency.value = 55;
    const humGain = ctx.createGain();
    humGain.gain.value = 0.12;
    const cg = ctx.createGain();
    cg.gain.value = 0;
    csrc.connect(cf).connect(cg);
    hum.connect(humGain).connect(cg);
    cg.connect(this.ambient);
    csrc.start();
    hum.start();
    this.cave = { gain: cg };
  }

  private drip(level: number): void {
    const ctx = this.ctx!;
    const t = ctx.currentTime;
    const out = ctx.createGain();
    out.gain.value = 0.25 * level;
    out.connect(this.ambient);
    const f = rnd(900, 1700);
    this.tone(out, t, { type: 'sine', freq: f, freqEnd: f * 1.6, dur: 0.09, gain: 0.5, attack: 0.002 });
    this.tone(out, t + 0.11, { type: 'sine', freq: f * 0.7, freqEnd: f * 0.9, dur: 0.18, gain: 0.12, attack: 0.002 });
    this.release(out, t + 0.5);
  }

  // --- One-shot sounds ------------------------------------------------------------------------------

  /** Plays a sound; positional when `x/y/z` are given. Never throws. */
  play(name: SoundName, opts: PlayOptions = {}): void {
    const ctx = this.ctx;
    if (!ctx || ctx.state !== 'running') return;
    try {
      let gain = opts.volume ?? 1;
      let pan = 0;
      if (opts.x !== undefined && opts.y !== undefined && opts.z !== undefined) {
        const s = spatialize(this.listener, opts.x, opts.y, opts.z, MAX_SOUND_DISTANCE);
        if (s.gain < 0.01) {
          this.stats.culled++;
          return;
        }
        gain *= s.gain;
        pan = s.pan;
      }
      const t = ctx.currentTime + 0.005;
      const out = ctx.createGain();
      out.gain.value = gain;
      if (pan !== 0 && typeof ctx.createStereoPanner === 'function') {
        const p = ctx.createStereoPanner();
        p.pan.value = pan;
        out.connect(p).connect(this.effects);
      } else {
        out.connect(this.effects);
      }
      const pitch = (opts.pitch ?? 1) * rnd(0.92, 1.08);
      const end = this.synth(name, out, t, pitch);
      this.release(out, t + end + 0.1);
      this.stats.played++;
      this.stats.lastSound = name;
    } catch (err) {
      this.stats.errors++;
      if (this.stats.errors < 5) console.warn('Sound failed', name, err);
    }
  }

  /** Disconnects a per-sound output node after it finished. */
  private release(node: AudioNode, at: number): void {
    const ms = Math.max(0, (at - (this.ctx?.currentTime ?? 0)) * 1000) + 50;
    setTimeout(() => {
      try {
        node.disconnect();
      } catch {
        // already gone
      }
    }, ms);
  }

  /** Builds the nodes of one sound into `out`; returns its duration in seconds. */
  private synth(name: SoundName, out: GainNode, t: number, pitch: number): number {
    const [kind, arg] = name.split('_') as [string, string | undefined];
    switch (kind) {
      case 'break':
        return this.materialSound(out, t, arg as Material, pitch, 1.25, true);
      case 'place':
        return this.materialSound(out, t, arg as Material, pitch * 1.1, 0.9, false);
      case 'step':
        return this.materialSound(out, t, arg as Material, pitch * 1.15, 0.35, false);
      case 'hit':
        return this.materialSound(out, t, arg as Material, pitch * 1.3, 0.3, false);
      case 'voice':
        return this.voice(out, t, arg as MobVoice, pitch);
    }
    switch (name) {
      case 'jump':
        this.noiseBurst(out, t, { filter: 'bandpass', freq: 900 * pitch, q: 0.8, dur: 0.08, gain: 0.12 });
        return 0.1;
      case 'land':
        this.tone(out, t, { type: 'sine', freq: 90 * pitch, freqEnd: 45, dur: 0.14, gain: 0.5 });
        this.noiseBurst(out, t, { filter: 'lowpass', freq: 600, q: 0.7, dur: 0.1, gain: 0.35 });
        return 0.16;
      case 'splash':
        this.noiseBurst(out, t, { filter: 'bandpass', freq: 1200 * pitch, freqEnd: 500, q: 0.7, dur: 0.35, gain: 0.4, attack: 0.01 });
        for (let i = 0; i < 4; i++) this.tone(out, t + rnd(0.02, 0.25), { type: 'sine', freq: rnd(500, 900), freqEnd: rnd(1000, 1600), dur: 0.05, gain: 0.08 });
        return 0.4;
      case 'hurt':
        // A short low "oof": a falling, slightly growly tone plus a muffled thump.
        this.tone(out, t, { type: 'triangle', freq: 260 * pitch, freqEnd: 150 * pitch, dur: 0.18, gain: 0.45, attack: 0.01 });
        this.noiseBurst(out, t, { filter: 'lowpass', freq: 500, q: 0.7, dur: 0.09, gain: 0.4 });
        return 0.2;
      case 'death':
        this.tone(out, t, { type: 'triangle', freq: 240 * pitch, freqEnd: 70 * pitch, dur: 0.7, gain: 0.45, attack: 0.01 });
        this.noiseBurst(out, t, { filter: 'lowpass', freq: 400, q: 0.7, dur: 0.25, gain: 0.4 });
        return 0.75;
      case 'eat':
        // Two crunchy grains: munch.
        this.noiseBurst(out, t, { filter: 'bandpass', freq: 1600 * pitch, q: 1.5, dur: 0.05, gain: 0.35 });
        this.noiseBurst(out, t + 0.06, { filter: 'bandpass', freq: 1100 * pitch, q: 1.5, dur: 0.06, gain: 0.3 });
        return 0.14;
      case 'pickup':
        // A soft rising "pop".
        this.tone(out, t, { type: 'sine', freq: 520 * pitch, freqEnd: 1250 * pitch, dur: 0.09, gain: 0.25, attack: 0.004 });
        return 0.1;
      case 'click':
        this.tone(out, t, { type: 'square', freq: 1800, freqEnd: 1200, dur: 0.025, gain: 0.06, attack: 0.001 });
        return 0.03;
      case 'swing':
        this.noiseBurst(out, t, { filter: 'bandpass', freq: 500 * pitch, freqEnd: 1800 * pitch, q: 1.4, dur: 0.16, gain: 0.18, attack: 0.03 });
        return 0.18;
      case 'mob_attack':
        // Heavy whoosh and a dull impact.
        this.noiseBurst(out, t, { filter: 'bandpass', freq: 350 * pitch, freqEnd: 1300 * pitch, q: 1.2, dur: 0.22, gain: 0.4, attack: 0.04 });
        this.tone(out, t + 0.16, { type: 'sine', freq: 110 * pitch, freqEnd: 55, dur: 0.15, gain: 0.5 });
        return 0.32;
      case 'mob_hurt':
        this.noiseBurst(out, t, { filter: 'lowpass', freq: 700 * pitch, q: 0.7, dur: 0.08, gain: 0.45 });
        this.tone(out, t, { type: 'triangle', freq: 330 * pitch, freqEnd: 200 * pitch, dur: 0.12, gain: 0.25 });
        return 0.14;
      case 'mob_death':
        this.tone(out, t, { type: 'triangle', freq: 300 * pitch, freqEnd: 90 * pitch, dur: 0.45, gain: 0.3 });
        this.noiseBurst(out, t + 0.3, { filter: 'lowpass', freq: 500, q: 0.7, dur: 0.15, gain: 0.35 });
        return 0.5;
      case 'glob':
        // Wet launch: a falling "bloop" with a slurp of filtered noise.
        this.tone(out, t, { type: 'sine', freq: 640 * pitch, freqEnd: 160 * pitch, dur: 0.16, gain: 0.45, attack: 0.005 });
        this.noiseBurst(out, t, { filter: 'lowpass', freq: 900, freqEnd: 300, q: 2, dur: 0.18, gain: 0.25 });
        return 0.2;
      case 'splat':
        this.noiseBurst(out, t, { filter: 'lowpass', freq: 1400 * pitch, freqEnd: 250, q: 1.5, dur: 0.22, gain: 0.45 });
        this.tone(out, t, { type: 'sine', freq: 180 * pitch, freqEnd: 90, dur: 0.1, gain: 0.3 });
        return 0.25;
    }
    return 0;
  }

  private materialSound(out: GainNode, t: number, m: Material, pitch: number, level: number, breaking: boolean): number {
    const v = MATERIAL_VOICES[m] ?? MATERIAL_VOICES.stone;
    let end = 0;
    const grains = breaking ? v.grains + 2 : v.grains;
    for (let i = 0; i < grains; i++) {
      const at = t + (i === 0 ? 0 : rnd(0.01, v.dur * (breaking ? 1.6 : 1)));
      const dur = v.dur * (i === 0 ? 1 : rnd(0.3, 0.6)) * (breaking ? 1.3 : 1);
      this.noiseBurst(out, at, { filter: v.filter, freq: v.freq * pitch * rnd(0.85, 1.15), q: v.q, dur, gain: v.gain * level * (i === 0 ? 1 : 0.6) });
      end = Math.max(end, at - t + dur);
    }
    if (v.tone) {
      this.tone(out, t, { type: 'triangle', freq: v.tone * pitch, freqEnd: v.tone * pitch * 0.7, dur: breaking ? 0.12 : 0.08, gain: 0.35 * level });
    }
    if (m === 'glass' && breaking) {
      // Shatter: a scatter of short high pings.
      for (let i = 0; i < 6; i++) {
        const f = rnd(2200, 5200);
        const at = t + rnd(0, 0.18);
        this.tone(out, at, { type: 'sine', freq: f, freqEnd: f * 0.97, dur: rnd(0.08, 0.2), gain: 0.07 * level, attack: 0.001 });
      }
      end = Math.max(end, 0.4);
    } else if (m === 'glass') {
      const f = rnd(2600, 3400) * pitch;
      this.tone(out, t, { type: 'sine', freq: f, freqEnd: f, dur: 0.15, gain: 0.06 * level, attack: 0.001 });
    }
    return end;
  }

  /** Short original creature calls; deliberately abstract (filtered tones and noise). */
  private voice(out: GainNode, t: number, mob: MobVoice, pitch: number): number {
    switch (mob) {
      case 'sheep': {
        // Soft breathy warble: a triangle with fast tremolo under a band of noise.
        const d = 0.5;
        const osc = this.tone(out, t, { type: 'triangle', freq: 320 * pitch, freqEnd: 290 * pitch, dur: d, gain: 0.12, attack: 0.06 });
        this.tremolo(osc.gain, t, d, 9, 0.6);
        this.noiseBurst(out, t, { filter: 'bandpass', freq: 900 * pitch, q: 3, dur: d, gain: 0.06, attack: 0.08 });
        return d;
      }
      case 'pig': {
        // Two low nasal snorts.
        for (let i = 0; i < 2; i++) {
          const at = t + i * 0.17;
          this.tone(out, at, { type: 'sawtooth', freq: 120 * pitch, freqEnd: 95 * pitch, dur: 0.11, gain: 0.12, attack: 0.01, lowpass: 600 });
          this.noiseBurst(out, at, { filter: 'bandpass', freq: 400 * pitch, q: 2, dur: 0.1, gain: 0.12 });
        }
        return 0.3;
      }
      case 'chicken': {
        // Quick little chirps.
        const n = 2 + Math.floor(Math.random() * 2);
        for (let i = 0; i < n; i++) {
          const at = t + i * 0.09;
          const f = rnd(1500, 1900) * pitch;
          this.tone(out, at, { type: 'sine', freq: f, freqEnd: f * 1.25, dur: 0.05, gain: 0.08, attack: 0.003 });
        }
        return 0.1 * n;
      }
      case 'gloomwalker': {
        // A slow, hollow low moan: two detuned sines swelling in and out with a breath of noise.
        const d = 1.3;
        this.tone(out, t, { type: 'sine', freq: 82 * pitch, freqEnd: 70 * pitch, dur: d, gain: 0.3, attack: 0.45 });
        this.tone(out, t, { type: 'sine', freq: 85.5 * pitch, freqEnd: 73 * pitch, dur: d, gain: 0.22, attack: 0.5 });
        this.noiseBurst(out, t, { filter: 'bandpass', freq: 260 * pitch, q: 4, dur: d, gain: 0.08, attack: 0.5 });
        return d;
      }
      case 'bilespitter': {
        // Wet gurgle: a low tone wobbled by a fast square LFO through a low-pass.
        const d = 0.6;
        const osc = this.tone(out, t, { type: 'sine', freq: 190 * pitch, freqEnd: 150 * pitch, dur: d, gain: 0.25, attack: 0.04 });
        const ctx = this.ctx!;
        const lfo = ctx.createOscillator();
        lfo.type = 'square';
        lfo.frequency.value = rnd(14, 22);
        const depth = ctx.createGain();
        depth.gain.value = 60 * pitch;
        lfo.connect(depth).connect(osc.osc.frequency);
        lfo.start(t);
        lfo.stop(t + d);
        this.noiseBurst(out, t + 0.1, { filter: 'lowpass', freq: 500, q: 3, dur: 0.35, gain: 0.08 });
        return d;
      }
    }
    return 0;
  }

  // --- Building blocks ------------------------------------------------------------------------------

  private noiseBurst(
    out: AudioNode,
    t: number,
    o: { filter: BiquadFilterType; freq: number; freqEnd?: number; q: number; dur: number; gain: number; attack?: number },
  ): void {
    const ctx = this.ctx!;
    const src = ctx.createBufferSource();
    src.buffer = this.noise;
    const f = ctx.createBiquadFilter();
    f.type = o.filter;
    f.frequency.setValueAtTime(Math.min(20000, Math.max(20, o.freq)), t);
    if (o.freqEnd) f.frequency.exponentialRampToValueAtTime(Math.min(20000, Math.max(20, o.freqEnd)), t + o.dur);
    f.Q.value = o.q;
    const g = ctx.createGain();
    const attack = o.attack ?? 0.004;
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(o.gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0008, t + Math.max(attack + 0.01, o.dur));
    src.connect(f).connect(g).connect(out);
    const offset = Math.random() * (this.noise.duration - o.dur - 0.05);
    src.start(t, Math.max(0, offset), o.dur + 0.05);
  }

  private tone(
    out: AudioNode,
    t: number,
    o: { type: OscillatorType; freq: number; freqEnd?: number; dur: number; gain: number; attack?: number; lowpass?: number },
  ): { osc: OscillatorNode; gain: GainNode } {
    const ctx = this.ctx!;
    const osc = ctx.createOscillator();
    osc.type = o.type;
    osc.frequency.setValueAtTime(o.freq, t);
    if (o.freqEnd && o.freqEnd !== o.freq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, o.freqEnd), t + o.dur);
    const g = ctx.createGain();
    const attack = o.attack ?? 0.005;
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(o.gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0008, t + Math.max(attack + 0.01, o.dur));
    if (o.lowpass) {
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = o.lowpass;
      osc.connect(f).connect(g);
    } else osc.connect(g);
    g.connect(out);
    osc.start(t);
    osc.stop(t + o.dur + 0.02);
    return { osc, gain: g };
  }

  /** Amplitude wobble on an existing gain envelope. */
  private tremolo(gain: GainNode, t: number, dur: number, rate: number, depth: number): void {
    const ctx = this.ctx!;
    const lfo = ctx.createOscillator();
    lfo.frequency.value = rate;
    const d = ctx.createGain();
    d.gain.value = depth * 0.1;
    lfo.connect(d).connect(gain.gain);
    lfo.start(t);
    lfo.stop(t + dur);
  }
}
