import { HOTBAR_SIZE, getItemDef, type Inventory } from '@voxel/shared';
import { createSlotEl, setSlotContent } from './slotView';

export const HOTBAR_SLOTS = HOTBAR_SIZE;

/** DOM hotbar showing inventory slots 0-8; number keys 1-9 and the mouse wheel select. */
export class Hotbar {
  private readonly el: HTMLDivElement;
  private readonly slotEls: HTMLDivElement[] = [];
  private readonly label: HTMLDivElement;
  private selectedIndex = 0;
  private labelTimer = 0;
  private shownVersion = -1;
  private labelItem = -2;

  constructor(
    private readonly inventory: Inventory,
    parent: HTMLElement = document.body,
    /** A slot was tapped (touch mode makes the hotbar tappable; see style.css `body.touch`). */
    onTap?: (slot: number) => void,
  ) {
    this.el = document.createElement('div');
    this.el.className = 'hotbar';
    if (onTap) {
      this.el.addEventListener('pointerdown', (e) => {
        const slot = (e.target instanceof Element ? e.target.closest<HTMLElement>('[data-slot]') : null)?.dataset['slot'];
        if (slot === undefined) return;
        e.preventDefault();
        onTap(Number(slot));
      });
    }
    this.label = document.createElement('div');
    this.label.className = 'hotbar-label';
    for (let i = 0; i < HOTBAR_SLOTS; i++) {
      const slot = createSlotEl('hotbar-slot');
      slot.dataset['slot'] = String(i);
      const key = document.createElement('span');
      key.className = 'hotbar-key';
      key.textContent = String(i + 1);
      slot.append(key);
      this.el.appendChild(slot);
      this.slotEls.push(slot);
    }
    parent.append(this.label, this.el);
    this.select(0);
  }

  get selected(): number {
    return this.selectedIndex;
  }

  select(index: number): void {
    const i = ((index % HOTBAR_SLOTS) + HOTBAR_SLOTS) % HOTBAR_SLOTS;
    this.slotEls[this.selectedIndex]?.classList.remove('selected');
    this.selectedIndex = i;
    this.slotEls[i]?.classList.add('selected');
    this.labelItem = -2; // re-show the label
    this.update();
  }

  /** Moves the selection by `delta` slots (wheel notches), wrapping around. */
  scroll(delta: number): void {
    if (delta !== 0) this.select(this.selectedIndex + delta);
  }

  /** Redraws slots when the inventory changed; shows the held item's name when it changes. */
  update(): void {
    const inv = this.inventory;
    if (inv.version !== this.shownVersion) {
      this.shownVersion = inv.version;
      for (let i = 0; i < HOTBAR_SLOTS; i++) setSlotContent(this.slotEls[i]!, inv.get(i));
    }
    const held = inv.get(this.selectedIndex);
    const id = held ? held.item : -1;
    if (id !== this.labelItem) {
      this.labelItem = id;
      this.label.textContent = held ? getItemDef(held.item).label : '';
      this.label.classList.toggle('visible', !!held);
      window.clearTimeout(this.labelTimer);
      this.labelTimer = window.setTimeout(() => this.label.classList.remove('visible'), 1500);
    }
  }

  /** Removes the hotbar's DOM and timer. */
  dispose(): void {
    window.clearTimeout(this.labelTimer);
    this.el.remove();
    this.label.remove();
  }
}
