import { SECTION_COUNT, SECTION_SIZE, PADDED_VOLUME, decodeSectionKey, sectionBaseY, sectionKey, type SectionMesh, type World } from '@voxel/shared';
import type { MeshRequest, MeshResponse } from './meshProtocol';
import { WorkerSet, type WorkerSlot } from '../workers/workerSet';

/** Requests kept in flight per worker, to hide message latency. */
const IN_FLIGHT_PER_WORKER = 2;

export function defaultMeshWorkerCount(): number {
  const cores = typeof navigator !== 'undefined' ? navigator.hardwareConcurrency || 2 : 2;
  return Math.max(1, Math.min(4, cores - 1));
}

/**
 * Called when a section's mesh is ready. `mesh` is null when the section became empty and its GPU
 * buffers should simply be deleted.
 */
export type MeshReadyHandler = (key: number, mesh: SectionMesh | null) => void;

/** Returns false to hold off meshing a chunk for now (its dirty flags are kept for later). */
export type CanMeshPredicate = (cx: number, cz: number) => boolean;

/**
 * Pulls dirty sections out of the World, meshes them on a pool of workers (nearest to the camera
 * first) and hands fresh meshes to `onMesh`. Results whose section version changed while the job
 * was in flight are dropped; the section will already have been re-queued as dirty.
 */
export class MeshWorkerPool {
  private readonly workers: WorkerSet<MeshResponse, number>;
  private nextJob = 1;
  /** Section keys waiting for a worker. */
  private readonly pending = new Set<number>();
  private sortedPending: number[] = [];
  private pendingChanged = false;
  private readonly spare: Uint16Array[] = [];
  private readonly spareLight: Uint8Array[] = [];
  private camX = 0;
  private camY = 0;
  private camZ = 0;
  /** Results discarded because the section changed while it was being meshed. */
  staleDropped = 0;
  /** Total sections meshed. */
  meshed = 0;
  /** Average worker meshing time in ms (exponential moving average). */
  avgMeshMs = 0;

  constructor(
    private readonly world: World,
    private readonly onMesh: MeshReadyHandler,
    workerCount = defaultMeshWorkerCount(),
    private readonly canMesh: CanMeshPredicate = () => true,
  ) {
    this.workers = new WorkerSet<MeshResponse, number>({
      create: () => new Worker(new URL('./meshWorker.ts', import.meta.url), { type: 'module' }),
      count: workerCount,
      label: 'Mesh',
      retryKey: (sectionKey) => sectionKey,
      onResult: (slot, res) => this.onResult(slot, res),
      // A crashed worker's sections are meshed again (twice at most; then they are skipped).
      onLost: (lost) => {
        for (const { job: key, attempts } of lost) if (attempts <= 2 && this.world.getChunk(decodeSectionKey(key).cx, decodeSectionKey(key).cz)) this.pending.add(key);
        this.pendingChanged = true;
        this.dispatch();
      },
    });
  }

  get workerCount(): number {
    return this.workers.size;
  }

  /** Workers replaced after crashing. */
  get restarts(): number {
    return this.workers.restarts;
  }

  /** Debug / tests: crash-and-restart a worker as if it had thrown. */
  simulateCrash(i = 0): void {
    this.workers.simulateCrash(i);
  }

  private get inFlight(): number {
    let n = 0;
    for (const s of this.workers.slots) n += s.inFlight;
    return n;
  }

  /** Sections waiting for a worker plus sections being meshed. */
  get queueLength(): number {
    return this.pending.size + this.inFlight;
  }

  /** Call once per frame: collects newly dirty sections and dispatches work. */
  update(camX: number, camY: number, camZ: number): void {
    this.camX = camX;
    this.camY = camY;
    this.camZ = camZ;
    this.collectDirty();
    // Re-prioritise every frame: the camera moves and new work arrives.
    this.pendingChanged = true;
    this.dispatch();
  }

  dispose(): void {
    this.workers.dispose();
    this.pending.clear();
  }

  /** Forgets queued work for an unloaded chunk (in-flight results are dropped as stale on arrival). */
  forgetChunk(cx: number, cz: number): void {
    for (let sy = 0; sy < SECTION_COUNT; sy++) this.pending.delete(sectionKey(cx, sy, cz));
  }

  private collectDirty(): void {
    for (const chunk of this.world) {
      if (!chunk.hasDirtySections) continue;
      if (!this.canMesh(chunk.cx, chunk.cz)) continue;
      for (let sy = 0; sy < SECTION_COUNT; sy++) {
        if (!chunk.sectionDirty[sy]) continue;
        chunk.clearSectionDirty(sy);
        const key = sectionKey(chunk.cx, sy, chunk.cz);
        if (chunk.isSectionEmpty(sy)) {
          // Nothing to mesh. Any in-flight job for it is now stale (its version was bumped).
          this.pending.delete(key);
          this.onMesh(key, null);
        } else {
          this.pending.add(key);
        }
      }
    }
  }

  private sortPending(): void {
    const { camX, camY, camZ } = this;
    const dist = new Map<number, number>();
    for (const key of this.pending) {
      const { cx, sy, cz } = decodeSectionKey(key);
      const h = SECTION_SIZE / 2;
      const dx = cx * SECTION_SIZE + h - camX;
      const dy = sectionBaseY(sy) + h - camY;
      const dz = cz * SECTION_SIZE + h - camZ;
      dist.set(key, dx * dx + dy * dy + dz * dz);
    }
    // Farthest first, so the nearest is popped from the end.
    this.sortedPending = [...this.pending].sort((a, b) => dist.get(b)! - dist.get(a)!);
    this.pendingChanged = false;
  }

  private dispatch(): void {
    if (this.pending.size === 0) return;
    if (this.pendingChanged) this.sortPending();
    for (const slot of this.workers.slots) {
      while (slot.inFlight < IN_FLIGHT_PER_WORKER) {
        const key = this.popNearest();
        if (key === undefined) return;
        const { cx, sy, cz } = decodeSectionKey(key);
        const chunk = this.world.getChunk(cx, cz);
        if (!chunk) continue; // unloaded while queued
        const padded = this.spare.pop() ?? new Uint16Array(PADDED_VOLUME);
        const light = this.spareLight.pop() ?? new Uint8Array(PADDED_VOLUME);
        this.world.copySectionPadded(cx, sy, cz, padded);
        this.world.copySectionPaddedLight(cx, sy, cz, light);
        const job = this.nextJob++;
        const req: MeshRequest = { job, key, version: chunk.sectionVersion[sy]!, padded, light };
        this.workers.post(slot, job, key, req, [padded.buffer, light.buffer]);
      }
    }
  }

  private popNearest(): number | undefined {
    while (this.sortedPending.length > 0) {
      const key = this.sortedPending.pop()!;
      if (this.pending.delete(key)) return key;
    }
    return undefined;
  }

  private onResult(slot: WorkerSlot<number>, res: MeshResponse): void {
    this.workers.done(slot, res.job);
    if (this.spare.length < 16) this.spare.push(res.padded);
    if (this.spareLight.length < 16) this.spareLight.push(res.light);
    this.avgMeshMs = this.meshed === 0 ? res.ms : this.avgMeshMs * 0.95 + res.ms * 0.05;
    this.meshed++;

    const { cx, sy, cz } = decodeSectionKey(res.key);
    const chunk = this.world.getChunk(cx, cz);
    if (!chunk || chunk.sectionVersion[sy] !== res.version) {
      this.staleDropped++;
    } else {
      this.onMesh(res.key, res.mesh);
    }
    this.dispatch();
  }
}
