/** Ring buffer of timings (ms) with percentiles, for the F3 frame graph and profiling. */
export class TimingRing {
  readonly samples: Float32Array;
  private next = 0;
  private filled = 0;
  private readonly sorted: Float32Array;

  constructor(readonly capacity = 240) {
    this.samples = new Float32Array(capacity);
    this.sorted = new Float32Array(capacity);
  }

  get count(): number {
    return this.filled;
  }

  push(ms: number): void {
    this.samples[this.next] = ms;
    this.next = (this.next + 1) % this.capacity;
    if (this.filled < this.capacity) this.filled++;
  }

  clear(): void {
    this.next = 0;
    this.filled = 0;
  }

  /** The i-th oldest sample still kept (0 = oldest). */
  at(i: number): number {
    const start = this.filled < this.capacity ? 0 : this.next;
    return this.samples[(start + i) % this.capacity]!;
  }

  /** avg, p50, p95, p99 and max of the kept samples (all 0 when empty). */
  summary(): { avg: number; p50: number; p95: number; p99: number; max: number } {
    const n = this.filled;
    if (n === 0) return { avg: 0, p50: 0, p95: 0, p99: 0, max: 0 };
    const s = this.sorted.subarray(0, n);
    s.set(this.samples.subarray(0, n));
    s.sort();
    let sum = 0;
    for (let i = 0; i < n; i++) sum += s[i]!;
    const q = (p: number): number => s[Math.min(n - 1, Math.floor(p * n))]!;
    return { avg: sum / n, p50: q(0.5), p95: q(0.95), p99: q(0.99), max: s[n - 1]! };
  }
}
