import type { Mat4, Vec3 } from '@voxel/shared';
import { createProgram, type ShaderProgram } from './shader';

/** A block's box inside its cell: [x0, y0, z0, x1, y1, z1] in blocks. */
export type Bounds = readonly [number, number, number, number, number, number];
const FULL_CELL: Bounds = [0, 0, 0, 1, 1, 1];

const VS = `#version 300 es
layout(location = 0) in vec3 a_pos;
uniform mat4 u_viewProj;
uniform vec3 u_origin;
// Part of the cell the block occupies (slabs, stairs, posts): min corner and size, in blocks.
uniform vec3 u_boxMin;
uniform vec3 u_boxSize;
uniform vec3 u_camPos;
void main() {
  vec3 world = u_origin + u_boxMin + a_pos * u_boxSize;
  // Pull each vertex a little toward the eye so edges shared with neighbouring solid blocks are not
  // hidden behind their faces (a view-dependent depth bias).
  vec3 toEye = u_camPos - world;
  world += toEye * min(0.02 / max(length(toEye), 1e-3), 0.5);
  gl_Position = u_viewProj * vec4(world, 1.0);
}
`;

const FS = `#version 300 es
precision mediump float;
uniform vec4 u_color;
out vec4 outColor;
void main() {
  outColor = u_color;
}
`;

/** How far the box is grown past the block on every side, so the lines are not z-fighting the faces. */
const GROW = 0.002;

/** Draws a thin wireframe box (GL_LINES, 12 edges) around one block. */
export class OutlineRenderer {
  private readonly shader: ShaderProgram;
  private readonly vao: WebGLVertexArrayObject;
  private readonly vbo: WebGLBuffer;
  color: readonly [number, number, number, number] = [0.05, 0.05, 0.05, 0.7];

  constructor(private readonly gl: WebGL2RenderingContext) {
    this.shader = createProgram(gl, VS, FS);
    const lo = -GROW;
    const hi = 1 + GROW;
    const c = (i: number): number => (i ? hi : lo);
    const verts: number[] = [];
    // Each edge joins two corners that differ in exactly one coordinate bit.
    for (let a = 0; a < 8; a++) {
      for (const bit of [1, 2, 4]) {
        const b = a | bit;
        if (b === a) continue;
        verts.push(c(a & 1), c(a & 2), c(a & 4), c(b & 1), c(b & 2), c(b & 4));
      }
    }
    const vao = gl.createVertexArray();
    const vbo = gl.createBuffer();
    if (!vao || !vbo) throw new Error('Failed to allocate GL buffers for the block outline');
    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(verts), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 12, 0);
    gl.bindVertexArray(null);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
    this.vao = vao;
    this.vbo = vbo;
  }

  /** Draws the outline of block (x, y, z), depth-tested against the world. */
  /** `bounds`: the block's box inside its cell, [x0, y0, z0, x1, y1, z1] in blocks (default the whole cell). */
  draw(viewProj: Mat4, camPos: Vec3, x: number, y: number, z: number, bounds: Bounds = FULL_CELL): void {
    const { gl, shader } = this;
    gl.useProgram(shader.program);
    const u = shader.uniforms;
    if (u['u_viewProj']) gl.uniformMatrix4fv(u['u_viewProj'], false, viewProj);
    if (u['u_origin']) gl.uniform3f(u['u_origin'], x, y, z);
    if (u['u_boxMin']) gl.uniform3f(u['u_boxMin'], bounds[0], bounds[1], bounds[2]);
    if (u['u_boxSize']) gl.uniform3f(u['u_boxSize'], bounds[3] - bounds[0], bounds[4] - bounds[1], bounds[5] - bounds[2]);
    if (u['u_camPos']) gl.uniform3f(u['u_camPos'], camPos[0]!, camPos[1]!, camPos[2]!);
    if (u['u_color']) gl.uniform4f(u['u_color'], this.color[0], this.color[1], this.color[2], this.color[3]);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    gl.depthMask(false);
    gl.bindVertexArray(this.vao);
    gl.drawArrays(gl.LINES, 0, 24);
    gl.bindVertexArray(null);
    gl.depthMask(true);
    gl.disable(gl.BLEND);
  }

  dispose(): void {
    this.gl.deleteVertexArray(this.vao);
    this.gl.deleteBuffer(this.vbo);
    this.gl.deleteProgram(this.shader.program);
  }
}
