import { TICK_RATE } from '../constants';

/** Default length of a full day/night cycle in real seconds (20 minutes). */
export const DEFAULT_DAY_SECONDS = 20 * 60;

/**
 * World clock, advanced once per simulation tick. `ticks` is the total since world creation (what
 * a save file should store). The time of day is a fraction of the cycle where 0 is sunrise, 0.25
 * noon, 0.5 sunset and 0.75 midnight; `hours` maps that onto a 24 h clock (sunrise = 06:00).
 */
export class WorldTime {
  /** Simulation ticks elapsed since the world began (fractional while fast-forwarding). */
  ticks = 0;
  /** Ticks per full day. */
  readonly dayTicks: number;
  /** Multiplier on how many ticks pass per simulation tick (debug fast-forward). */
  speed = 1;

  constructor(dayLengthSeconds = DEFAULT_DAY_SECONDS, startHours = 8) {
    this.dayTicks = Math.max(1, Math.round(dayLengthSeconds * TICK_RATE));
    this.hours = startHours;
  }

  /** Advances the clock by one simulation tick (times `speed`). */
  tick(): void {
    this.ticks += this.speed;
  }

  /** Days completed since the world began. */
  get day(): number {
    return Math.floor(this.ticks / this.dayTicks);
  }

  /** Time of day in [0, 1): 0 sunrise, 0.25 noon, 0.5 sunset, 0.75 midnight. */
  get dayFraction(): number {
    const f = (this.ticks % this.dayTicks) / this.dayTicks;
    return f < 0 ? f + 1 : f;
  }

  /** Clock time in hours [0, 24), sunrise at 06:00. */
  get hours(): number {
    return (this.dayFraction * 24 + 6) % 24;
  }

  /** Sets the time of day (hours on the 24 h clock) without changing the day count. */
  set hours(h: number) {
    const frac = ((((h - 6) / 24) % 1) + 1) % 1;
    this.ticks = this.day * this.dayTicks + frac * this.dayTicks;
  }

  /** "HH:MM". */
  get clock(): string {
    // Small epsilon so float error in hours * 60 doesn't show 07:59 for 08:00.
    const minutes = Math.floor(this.hours * 60 + 1e-6) % (24 * 60);
    const hh = Math.floor(minutes / 60);
    const mm = minutes % 60;
    return `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
  }
}

/** Sine of the sun's elevation for a time of day: 0 at sunrise/sunset, 1 at noon, -1 at midnight. */
export function sunHeight(dayFraction: number): number {
  return Math.sin(dayFraction * Math.PI * 2);
}

/**
 * How strongly sky light lights the world, 0..1. Full by day, a dim moonlit floor at night, with a
 * smooth ramp through dawn and dusk.
 */
export function daylightFactor(dayFraction: number): number {
  const s = sunHeight(dayFraction);
  const t = Math.min(1, Math.max(0, (s + 0.2) / 0.5));
  const smooth = t * t * (3 - 2 * t);
  return 0.16 + (1 - 0.16) * smooth;
}
