/**
 * Player settings and the device quality preset (Milestone 9). Pure apart from the optional
 * `localStorage` lookup in `browserStorage`, so load/save is unit tested with a fake storage.
 *
 * Stored as JSON under `blockwright.settings`. Every read and write is wrapped in try/catch:
 * private mode, blocked storage, quota errors or a corrupt value fall back to the defaults.
 */

export type TouchMode = 'auto' | 'on' | 'off';

export interface Settings {
  /** Chunks. */
  viewDistance: number;
  /** Cap on devicePixelRatio for the canvas (render scale). */
  maxDpr: number;
  /** Vertical field of view, degrees. */
  fov: number;
  /** Look sensitivity multiplier (mouse and touch). */
  sensitivity: number;
  /** Show touch controls: auto-detect, always or never. */
  touchControls: TouchMode;
  /** Sound volumes 0..1 (Milestone 11): everything, world/UI effects, wind/cave ambience. */
  masterVolume: number;
  effectsVolume: number;
  ambientVolume: number;
}

export const SETTINGS_KEY = 'blockwright.settings';
/** Milestone 6-8 stored only the view distance, under this key; read once as a fallback. */
export const LEGACY_VIEW_KEY = 'blockwright.viewDistance';

export const LIMITS = {
  viewDistance: { min: 2, max: 16, step: 1 },
  maxDpr: { min: 0.5, max: 3, step: 0.25 },
  fov: { min: 50, max: 110, step: 1 },
  sensitivity: { min: 0.2, max: 3, step: 0.1 },
  volume: { min: 0, max: 1, step: 0.05 },
} as const;

const TOUCH_MODES: readonly TouchMode[] = ['auto', 'on', 'off'];

// --- Quality preset ------------------------------------------------------------------------------

export interface DeviceInfo {
  /** `matchMedia('(pointer: coarse)')`. */
  coarsePointer: boolean;
  /** `navigator.deviceMemory` (GB, Chromium only), if known. */
  deviceMemory?: number;
  /** `navigator.hardwareConcurrency`, if known. */
  cores?: number;
}

export type QualityName = 'desktop' | 'mobile' | 'low';

export interface QualityPreset {
  name: QualityName;
  viewDistance: number;
  maxDpr: number;
  /** Worker counts; undefined = the pools' own defaults (desktop). */
  genWorkers: number | undefined;
  meshWorkers: number | undefined;
  /** Mobs farther than this (blocks, horizontal) are not drawn. */
  mobRenderDistance: number;
  /** Main-thread light stitching budget per frame, ms (at least one chunk always runs). */
  stitchBudgetMs: number;
}

/**
 * - `low`: little memory (<= 2 GB) or few cores (<= 2), or a coarse pointer with <= 4 cores / <= 3 GB.
 * - `mobile`: any other coarse-pointer device (phones, tablets).
 * - `desktop`: everything else (the Milestone 8 behaviour).
 */
export function detectQuality(d: DeviceInfo): QualityPreset {
  const mem = d.deviceMemory;
  const cores = d.cores;
  const weak = (mem !== undefined && mem <= 2) || (cores !== undefined && cores <= 2);
  const weakMobile = d.coarsePointer && ((mem !== undefined && mem <= 3) || (cores !== undefined && cores <= 4));
  if (weak || weakMobile) {
    return { name: 'low', viewDistance: 4, maxDpr: 1.25, genWorkers: 1, meshWorkers: 1, mobRenderDistance: 32, stitchBudgetMs: 2 };
  }
  if (d.coarsePointer) {
    return { name: 'mobile', viewDistance: 5, maxDpr: 1.5, genWorkers: 1, meshWorkers: 2, mobRenderDistance: 40, stitchBudgetMs: 3 };
  }
  return { name: 'desktop', viewDistance: 8, maxDpr: 2, genWorkers: undefined, meshWorkers: undefined, mobRenderDistance: 96, stitchBudgetMs: 4 };
}

/** Reads the device info from the browser (all fields optional / guarded). */
export function browserDeviceInfo(coarsePointer: boolean): DeviceInfo {
  const nav = typeof navigator !== 'undefined' ? (navigator as Navigator & { deviceMemory?: number }) : undefined;
  return {
    coarsePointer,
    deviceMemory: typeof nav?.deviceMemory === 'number' ? nav.deviceMemory : undefined,
    cores: typeof nav?.hardwareConcurrency === 'number' && nav.hardwareConcurrency > 0 ? nav.hardwareConcurrency : undefined,
  };
}

// --- Settings ------------------------------------------------------------------------------------

export const DEFAULT_VOLUMES = { masterVolume: 0.8, effectsVolume: 1, ambientVolume: 0.6 } as const;

export function defaultSettings(preset: QualityPreset): Settings {
  return { viewDistance: preset.viewDistance, maxDpr: preset.maxDpr, fov: 70, sensitivity: 1, touchControls: 'auto', ...DEFAULT_VOLUMES };
}

function num(v: unknown, lim: { min: number; max: number }, fallback: number): number {
  const n = typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : Number.NaN;
  return Number.isFinite(n) ? Math.max(lim.min, Math.min(lim.max, n)) : fallback;
}

/** Validates anything (parsed JSON) into Settings; bad or missing fields take the defaults. */
export function sanitizeSettings(raw: unknown, defaults: Settings): Settings {
  const r = raw !== null && typeof raw === 'object' ? (raw as Record<string, unknown>) : {};
  return {
    viewDistance: Math.round(num(r['viewDistance'], LIMITS.viewDistance, defaults.viewDistance)),
    maxDpr: num(r['maxDpr'], LIMITS.maxDpr, defaults.maxDpr),
    fov: num(r['fov'], LIMITS.fov, defaults.fov),
    sensitivity: num(r['sensitivity'], LIMITS.sensitivity, defaults.sensitivity),
    touchControls: TOUCH_MODES.includes(r['touchControls'] as TouchMode) ? (r['touchControls'] as TouchMode) : defaults.touchControls,
    masterVolume: num(r['masterVolume'], LIMITS.volume, defaults.masterVolume),
    effectsVolume: num(r['effectsVolume'], LIMITS.volume, defaults.effectsVolume),
    ambientVolume: num(r['ambientVolume'], LIMITS.volume, defaults.ambientVolume),
  };
}

/** The bit of the Web Storage API we use. */
export interface StorageLike {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

/** `window.localStorage`, or undefined when it is missing or access throws (blocked / sandboxed). */
export function browserStorage(): StorageLike | undefined {
  try {
    return typeof localStorage !== 'undefined' ? localStorage : undefined;
  } catch {
    return undefined;
  }
}

/** Loads settings; never throws. Falls back to the legacy view-distance key, then the defaults. */
export function loadSettings(storage: StorageLike | undefined, defaults: Settings): Settings {
  if (!storage) return { ...defaults };
  let raw: string | null = null;
  try {
    raw = storage.getItem(SETTINGS_KEY);
  } catch {
    return { ...defaults };
  }
  if (raw !== null) {
    try {
      return sanitizeSettings(JSON.parse(raw), defaults);
    } catch {
      return { ...defaults }; // corrupt JSON
    }
  }
  try {
    const legacy = storage.getItem(LEGACY_VIEW_KEY);
    if (legacy !== null) return sanitizeSettings({ viewDistance: legacy }, defaults);
  } catch {
    // ignore
  }
  return { ...defaults };
}

/** Saves settings; returns false if storage is unavailable or the write failed. */
export function saveSettings(storage: StorageLike | undefined, s: Settings): boolean {
  if (!storage) return false;
  try {
    storage.setItem(SETTINGS_KEY, JSON.stringify(s));
    return true;
  } catch {
    return false;
  }
}
