import type { Mat4, SectionMesh, Vec3 } from '@voxel/shared';
import { resizeCanvasToDisplaySize } from './gl';
import { createTextureArray } from './textureArray';
import { generateBlockTextures, TEXTURE_SIZE } from './proceduralTextures';
import { ChunkRenderer, type FogSettings } from './chunkRenderer';
import { OutlineRenderer, type Bounds } from './outlineRenderer';
import { SkyRenderer, computeSky, type SkyState } from './sky';
import { EntityRenderer } from './entityRenderer';
import { BreakRenderer } from './breakRenderer';
import { ITEM_ICON_SIZE, itemIconAtlas } from './itemIcons';
import { mobTextureAtlas } from './mobTextures';

/** Owns GL state for the frame and the chunk-section meshes. */
export class Renderer {
  readonly blockTextures: WebGLTexture;
  readonly chunks: ChunkRenderer;
  readonly outline: OutlineRenderer;
  readonly skyRenderer: SkyRenderer;
  /** Non-block item icons (one layer per item, see itemIcons.ts) for item sprites. */
  readonly itemTextures: WebGLTexture;
  /** Procedural mob skins (see mobTextures.ts). */
  readonly mobTextures: WebGLTexture;
  /** Per-frame entity geometry (item drops and mobs). */
  readonly entities: EntityRenderer;
  readonly breakOverlay: BreakRenderer;
  /** Current time-of-day sky; set with `setTimeOfDay`. */
  sky: SkyState = computeSky(0.1);
  /** Distance fog; blends to the sky's horizon colour. Call `setViewDistance` to fit it to the view. */
  readonly fog: FogSettings = { color: this.sky.horizon, start: 64, end: 100 };
  /** Cap on devicePixelRatio for the drawing buffer (settings "render scale"; mobile preset 1.5). */
  maxDpr = 2;
  /** Camera eye is in water: short blue fog, no sky (Milestone 11). */
  private underwater = false;
  /** Fog distances for the current view distance (restored when leaving the water). */
  private viewFog = { start: 64, end: 100 };

  constructor(
    readonly gl: WebGL2RenderingContext,
    readonly canvas: HTMLCanvasElement,
  ) {
    this.blockTextures = createTextureArray(gl, TEXTURE_SIZE, generateBlockTextures());
    this.chunks = new ChunkRenderer(gl);
    this.outline = new OutlineRenderer(gl);
    this.skyRenderer = new SkyRenderer(gl);
    if (ITEM_ICON_SIZE !== TEXTURE_SIZE) throw new Error('Item icons must match the block texture size');
    this.itemTextures = createTextureArray(gl, ITEM_ICON_SIZE, itemIconAtlas().layers);
    this.mobTextures = createTextureArray(gl, TEXTURE_SIZE, mobTextureAtlas().layers);
    this.entities = new EntityRenderer(gl);
    this.breakOverlay = new BreakRenderer(gl);
    gl.enable(gl.DEPTH_TEST);
    gl.enable(gl.CULL_FACE);
    gl.cullFace(gl.BACK);
    gl.frontFace(gl.CCW);
  }

  /** Uploads (or with null, deletes) a section mesh. Hook this up as the MeshWorkerPool handler. */
  setSectionMesh(key: number, mesh: SectionMesh | null): void {
    this.chunks.setSectionMesh(key, mesh);
  }

  /**
   * Fits the fog to a circular load radius of `chunks` chunks. A chunk-aligned circle is only
   * guaranteed to be fully loaded out to about (chunks - 1.5) * 16 blocks from the camera, so fog
   * ends there and the ragged edge of loaded terrain is never visible.
   */
  setViewDistance(chunks: number): void {
    this.viewFog.end = Math.max(16, (chunks - 1.5) * 16);
    this.viewFog.start = this.viewFog.end * 0.6;
    this.applyFog();
  }

  /** Underwater view: dense blue-green fog that follows the daylight, and the sky is hidden. */
  setUnderwater(on: boolean): void {
    if (on === this.underwater) return;
    this.underwater = on;
    this.applyFog();
  }

  get isUnderwater(): boolean {
    return this.underwater;
  }

  private applyFog(): void {
    const f = this.fog;
    if (this.underwater) {
      const d = 0.25 + 0.75 * this.sky.daylight;
      f.color = [0.07 * d, 0.24 * d, 0.42 * d];
      f.start = 0;
      f.end = Math.min(this.viewFog.end, 22);
    } else {
      f.color = this.sky.horizon;
      f.start = this.viewFog.start;
      f.end = this.viewFog.end;
    }
  }

  /**
   * Updates the sky, fog colour and sky-light uniforms for a time of day (0 sunrise, 0.25 noon,
   * 0.5 sunset, 0.75 midnight). Only uniforms change, so no chunk is re-meshed.
   */
  setTimeOfDay(dayFraction: number): void {
    this.sky = computeSky(dayFraction);
    this.applyFog();
  }

  /** Resizes the drawing buffer if needed; returns the current aspect ratio. */
  beginFrame(): number {
    const { gl, canvas } = this;
    resizeCanvasToDisplaySize(canvas, this.maxDpr);
    gl.viewport(0, 0, canvas.width, canvas.height);
    const h = this.fog.color;
    gl.clearColor(h[0], h[1], h[2], 1);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    return canvas.width / canvas.height;
  }

  /** Fullscreen sky gradient with sun, moon and stars. Call first in the frame. */
  drawSky(forward: Vec3, right: Vec3, fovY: number, aspect: number): void {
    if (this.underwater) return; // the clear colour is the water fog
    this.skyRenderer.draw(this.sky, forward, right, fovY, aspect);
  }

  drawWorld(viewProj: Mat4, cameraPos: Vec3): void {
    this.chunks.draw(viewProj, this.blockTextures, cameraPos[0]!, cameraPos[1]!, cameraPos[2]!, this.fog, this.sky);
  }

  /** Draws what was queued on `entities` this frame. Call after `drawWorld`. */
  drawEntities(viewProj: Mat4, cameraPos: Vec3): void {
    this.entities.draw(viewProj, cameraPos[0]!, cameraPos[1]!, cameraPos[2]!, this.fog, { blocks: this.blockTextures, items: this.itemTextures, mobs: this.mobTextures });
  }

  /** Crack overlay on the block being broken; `progress` 0..1. */
  drawBreakProgress(viewProj: Mat4, cameraPos: Vec3, x: number, y: number, z: number, progress: number, bounds?: Bounds): void {
    this.breakOverlay.draw(viewProj, cameraPos, x, y, z, progress, bounds);
  }

  /** Wireframe around the targeted block. Call after `drawWorld`. */
  drawBlockOutline(viewProj: Mat4, cameraPos: Vec3, x: number, y: number, z: number, bounds?: Bounds): void {
    this.outline.draw(viewProj, cameraPos, x, y, z, bounds);
  }
}
