/**
 * A fixed-size set of identical workers that replaces any worker that crashes (Milestone 11).
 *
 * Each slot remembers the jobs it has in flight (by a numeric key). When a worker reports an
 * uncaught error (or a message that cannot be deserialized), it is terminated and replaced with a
 * fresh one, and its unfinished jobs are handed back to the owner through `onLost` together with
 * how many times each job has already been lost, so the owner can retry it once or twice but not
 * forever (a job that crashes the worker deterministically would otherwise loop).
 */
export interface WorkerSlot<J> {
  worker: Worker;
  /** Jobs posted and not answered yet. */
  readonly jobs: Map<number, J>;
  readonly inFlight: number;
}

class Slot<J> implements WorkerSlot<J> {
  readonly jobs = new Map<number, J>();
  constructor(public worker: Worker) {}
  get inFlight(): number {
    return this.jobs.size;
  }
}

export interface WorkerSetOptions<R, J> {
  /** Creates one worker (e.g. `() => new Worker(new URL('./x.ts', import.meta.url), { type: 'module' })`). */
  create: () => Worker;
  count: number;
  /** Name for log messages. */
  label: string;
  onResult: (slot: WorkerSlot<J>, result: R) => void;
  /** Jobs that were in flight on a crashed worker; `attempts` = times this job was lost so far. */
  onLost: (lost: { key: number; job: J; attempts: number }[]) => void;
  /** Identifies "the same job" across retries (e.g. the section or chunk key); default: the post key. */
  retryKey?: (job: J, key: number) => number;
}

export class WorkerSet<R, J> {
  private readonly slotList: Slot<J>[] = [];
  private readonly lostCounts = new Map<number, number>();
  /** Workers replaced after a crash (debug overlay). */
  restarts = 0;
  private disposed = false;

  constructor(private readonly opts: WorkerSetOptions<R, J>) {
    for (let i = 0; i < Math.max(1, opts.count); i++) {
      const slot = new Slot<J>(undefined as unknown as Worker);
      this.attach(slot);
      this.slotList.push(slot);
    }
  }

  get slots(): readonly WorkerSlot<J>[] {
    return this.slotList;
  }

  get size(): number {
    return this.slotList.length;
  }

  /** The slot with the fewest jobs in flight. */
  leastBusy(): WorkerSlot<J> {
    return this.slotList.reduce((a, b) => (b.inFlight < a.inFlight ? b : a));
  }

  /** Posts a job and remembers it until `done(slot, key)`. */
  post(slot: WorkerSlot<J>, key: number, job: J, message: unknown, transfer: Transferable[] = []): void {
    (slot as Slot<J>).jobs.set(key, job);
    slot.worker.postMessage(message, transfer);
  }

  /** Marks a job answered (call from `onResult`). */
  done(slot: WorkerSlot<J>, key: number): void {
    const job = slot.jobs.get(key);
    (slot as Slot<J>).jobs.delete(key);
    if (job !== undefined && this.lostCounts.size > 0) this.lostCounts.delete(this.retryKey(job, key));
  }

  private retryKey(job: J, key: number): number {
    return this.opts.retryKey ? this.opts.retryKey(job, key) : key;
  }

  dispose(): void {
    this.disposed = true;
    for (const s of this.slotList) s.worker.terminate();
    this.slotList.length = 0;
  }

  /** Test / debug hook: behaves exactly like a crash of slot `i`. */
  simulateCrash(i = 0): void {
    const s = this.slotList[i];
    if (s) this.crash(s, 'simulated crash');
  }

  private attach(slot: Slot<J>): void {
    const w = this.opts.create();
    slot.worker = w;
    w.onmessage = (e: MessageEvent<R>) => {
      if (slot.worker === w) this.opts.onResult(slot, e.data);
    };
    w.onerror = (e: ErrorEvent) => {
      e.preventDefault();
      if (slot.worker === w) this.crash(slot, e.message || 'worker error');
    };
    w.onmessageerror = () => {
      if (slot.worker === w) this.crash(slot, 'message could not be deserialized');
    };
  }

  private crash(slot: Slot<J>, reason: string): void {
    if (this.disposed) return;
    console.error(`${this.opts.label} worker crashed (${reason}); restarting it with ${slot.jobs.size} job(s) to retry`);
    slot.worker.terminate();
    const lost = [...slot.jobs].map(([key, job]) => {
      const rk = this.retryKey(job, key);
      const attempts = (this.lostCounts.get(rk) ?? 0) + 1;
      this.lostCounts.set(rk, attempts);
      return { key, job, attempts };
    });
    slot.jobs.clear();
    this.restarts++;
    this.attach(slot);
    if (lost.length > 0) this.opts.onLost(lost);
  }
}
