import type { Mob, MobSystem, ModelPart, World } from '@voxel/shared';
import { TICK_SECONDS } from '@voxel/shared';
import {
  affineMul,
  affineRotX,
  affineRotZ,
  affineTranslate,
  affineYaw,
  entityLight,
  type BoxFaceLayers,
  type EntityRenderer,
  type RGB,
} from './entityRenderer';
import type { WorldLighting } from './chunkRenderer';
import { mobTextureAtlas } from './mobTextures';

/*
 * Poses and queues every mob as box-model parts (Milestone 8): body, a head that turns toward the
 * mob's look target, legs swinging with the walk cycle (arms lift while attacking), a red tint
 * while hurt, an orange flicker while burning, and a sideways tip-over while dying.
 */

const faceCache = new Map<ModelPart, BoxFaceLayers>();

function facesOf(part: ModelPart): BoxFaceLayers {
  let f = faceCache.get(part);
  if (!f) {
    const layerOf = mobTextureAtlas().layerOf;
    const L = (name: string | undefined): number => layerOf.get(name ?? part.faces.side) ?? 0;
    f = { side: L(part.faces.side), top: L(part.faces.top), bottom: L(part.faces.bottom), front: L(part.faces.front), back: L(part.faces.back) };
    faceCache.set(part, f);
  }
  return f;
}

function lerpAngle(a: number, b: number, t: number): number {
  let d = (b - a) % (Math.PI * 2);
  if (d > Math.PI) d -= Math.PI * 2;
  if (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
}

// Scratch matrices.
const mRoot = new Float64Array(12);
const mTmp = new Float64Array(12);
const mTmp2 = new Float64Array(12);
const mPart = new Float64Array(12);
const mA = new Float64Array(12);
const mB = new Float64Array(12);

/**
 * Queues every mob and mob projectile. `alpha` interpolates between the last two ticks. Mobs
 * farther than `maxDistance` blocks (horizontal) from (camX, camZ) are skipped (mobile preset).
 */
export function queueMobs(ents: EntityRenderer, mobs: MobSystem, alpha: number, world: World, lighting: WorldLighting, clock: number, camX = 0, camZ = 0, maxDistance = Infinity, extra: readonly Mob[] = []): void {
  const max2 = maxDistance * maxDistance;
  for (const list of [mobs.entities, extra]) {
    for (const m of list) {
      const x = m.prevX + (m.x - m.prevX) * alpha;
      const z = m.prevZ + (m.z - m.prevZ) * alpha;
      if ((x - camX) * (x - camX) + (z - camZ) * (z - camZ) > max2) continue;
      queueMob(ents, m, alpha, world, lighting, clock);
    }
  }
  queueProjectiles(ents, mobs, alpha, world, lighting, clock);
}

/** Poses and queues one box-model mob (also used for remote player avatars in multiplayer). */
export function queueMob(ents: EntityRenderer, m: Mob, alpha: number, world: World, lighting: WorldLighting, clock: number): void {
  {
    const t = m.type;
    const x = m.prevX + (m.x - m.prevX) * alpha;
    const z = m.prevZ + (m.z - m.prevZ) * alpha;
    const y = m.prevY + (m.y - m.prevY) * alpha;
    const yaw = lerpAngle(m.prevYaw, m.yaw, alpha);
    const bx = Math.floor(x), by = Math.floor(y + t.height * 0.5), bz = Math.floor(z);
    let light: RGB = entityLight(world.getSkyLight(bx, by, bz), world.getBlockLight(bx, by, bz), lighting);
    const h = m.health;
    if (h.hurtTime > 0 || h.deathTime >= 0) {
      light = [Math.max(light[0], 0.55) * 1.1, light[1] * 0.35, light[2] * 0.35];
    } else if (h.burning && Math.sin(clock * 30 + m.id) > -0.3) {
      light = [Math.min(1.4, light[0] + 0.45), light[1] * 0.8 + 0.15, light[2] * 0.45];
    }

    // Root: position, body yaw, then the death tip-over around the right-hand foot edge.
    affineTranslate(x, y, z, mA);
    affineYaw(yaw, mB);
    affineMul(mA, mB, mRoot);
    if (h.deathTime >= 0) {
      const ang = Math.min(1, h.deathTime / 0.6) * (Math.PI / 2);
      affineTranslate(t.halfWidth, 0, 0, mA);
      affineRotZ(-ang, mB);
      affineMul(mA, mB, mTmp);
      affineTranslate(-t.halfWidth, 0, 0, mA);
      affineMul(mTmp, mA, mTmp2);
      affineMul(mRoot, mTmp2, mTmp);
      mRoot.set(mTmp);
    }

    const a = m.anim;
    const swing = Math.sin(a.walkPhase) * 0.75 * a.walkAmount;
    const attackLift = m.ai.swingTime > 0 ? 1.3 * Math.min(1, m.ai.swingTime / 0.2) : 0;
    for (const part of t.model) {
      affineTranslate(part.pivot[0], part.pivot[1], part.pivot[2], mA);
      if (part.role === 'head') {
        affineYaw(a.headYaw, mB);
        affineMul(mA, mB, mTmp);
        affineRotX(a.headPitch, mB);
        affineMul(mTmp, mB, mTmp2);
        affineMul(mRoot, mTmp2, mPart);
      } else if (part.role === 'leg') {
        const isArm = part.pivot[1] > t.height * 0.6;
        const rot = swing * (part.phase ?? 1) * (isArm ? 0.6 : 1) + (isArm ? attackLift : 0);
        affineRotX(rot, mB);
        affineMul(mA, mB, mTmp);
        affineMul(mRoot, mTmp, mPart);
      } else {
        affineMul(mRoot, mA, mPart);
      }
      const [ox, oy, oz] = part.offset;
      const [sx, sy, sz] = part.size;
      ents.addTransformedBox('mobs', mPart, ox, oy, oz, ox + sx, oy + sy, oz + sz, facesOf(part), light);
    }
  }
}

function queueProjectiles(ents: EntityRenderer, mobs: MobSystem, alpha: number, world: World, lighting: WorldLighting, clock: number): void {
  // Projectiles: small spinning globs, extrapolated along their velocity.
  const layer = mobTextureAtlas().layerOf.get('projectile') ?? 0;
  const faces: BoxFaceLayers = { side: layer, top: layer, bottom: layer, front: layer, back: layer };
  for (const p of mobs.projectiles) {
    const k = alpha * TICK_SECONDS;
    const px = p.x + p.vx * k, py = p.y + p.vy * k, pz = p.z + p.vz * k;
    const light = entityLight(world.getSkyLight(Math.floor(px), Math.floor(py), Math.floor(pz)), world.getBlockLight(Math.floor(px), Math.floor(py), Math.floor(pz)), lighting);
    const glow: RGB = [Math.max(light[0], 0.5), Math.max(light[1], 0.6), Math.max(light[2], 0.3)];
    affineTranslate(px, py, pz, mA);
    affineYaw(clock * 8 + p.id, mB);
    affineMul(mA, mB, mTmp);
    affineRotX(clock * 6, mB);
    affineMul(mTmp, mB, mPart);
    ents.addTransformedBox('mobs', mPart, -0.12, -0.12, -0.12, 0.12, 0.12, 0.12, faces, glow);
  }
}
