import { vec3, type Mat4, type Mob, type ServerMessage, type Vec3 } from '@voxel/shared';
import type { Camera } from '../game/camera';
import type { PlayerController } from '../game/playerController';
import type { BlockInteraction } from '../game/interaction';
import type { WorldTime } from '@voxel/shared';
import { ChatBox } from '../ui/chat';
import { NameTags } from '../ui/nameTags';
import type { RemoteChunkStreamer } from '../world/remoteChunks';
import type { NetClient } from './netClient';
import { RemoteEntities } from './remoteEntities';
import type { RemoteGameSession } from './remoteSession';

/** Seconds between pings (round-trip time for F3, and app-level keep-alive). */
const PING_SECONDS = 2;

export interface MultiplayerHooks {
  camera: Camera;
  controller: PlayerController;
  interaction: BlockInteraction;
  time: WorldTime;
  /** Chat opened / closed (release / retake the pointer). */
  onChatToggle(open: boolean): void;
  /** The connection ended for a reason other than leaving. */
  onDisconnect(reason: string): void;
}

/**
 * Everything multiplayer-specific in a running game (Milestone 10): routes server messages into
 * the session (reconciliation, inventory, vitals), the chunk streamer, the remote entity mirror,
 * the clock and the chat; sends the per-frame state changes the server needs (hotbar slot,
 * mining start / stop, eating start); draws name tags.
 */
export class MultiplayerLink {
  readonly remote: RemoteEntities;
  readonly chat: ChatBox;
  readonly tags = new NameTags();
  private readonly pingTimer: number;
  /** Small always-on latency pill (top right), outside the F3 overlay. */
  private readonly pingEl: HTMLDivElement;
  private pingShown = '';
  private lastSlot = -1;
  private lastBreak = '';
  private wasEating = false;
  private leaving = false;
  /** Rejected actions (debug). */
  rejected = 0;
  lastRejection = '';

  constructor(
    readonly client: NetClient,
    readonly session: RemoteGameSession,
    private readonly streamer: RemoteChunkStreamer,
    private readonly hooks: MultiplayerHooks,
  ) {
    this.remote = new RemoteEntities(session.mobs, session.items, session.id);
    this.chat = new ChatBox((text) => client.chat(text), (open) => hooks.onChatToggle(open));
    streamer.onQueuedEdits = (changes) => {
      for (const c of changes) session.applyBlockChange(c.x, c.y, c.z, c.id);
    };
    this.pingTimer = window.setInterval(() => client.ping(), PING_SECONDS * 1000);
    client.ping();
    this.pingEl = document.createElement('div');
    this.pingEl.className = 'net-ping';
    this.pingEl.title = 'Round-trip time to the server';
    document.body.appendChild(this.pingEl);
    client.attach(
      (m) => this.onMessage(m),
      (reason) => {
        if (!this.leaving) hooks.onDisconnect(reason);
      },
    );
  }

  get chatOpen(): boolean {
    return this.chat.isOpen;
  }

  /** Remote player avatars to draw with the mobs. */
  get avatars(): Mob[] {
    return this.remote.players.map((p) => p.avatar);
  }

  private onMessage(m: ServerMessage): void {
    const s = this.session;
    switch (m.type) {
      case 'chunk':
        this.streamer.receive(m);
        break;
      case 'unloadChunk':
        this.streamer.unload(m.cx, m.cz);
        break;
      case 'blockChanges':
        // Authoritative: always applied (this also rolls back a rejected optimistic edit).
        for (const c of m.changes) if (!this.streamer.queueEdit(c)) s.applyBlockChange(c.x, c.y, c.z, c.id);
        break;
      case 'entities':
        this.remote.onSnapshot(m, performance.now());
        break;
      case 'playerState':
        if (s.applyServerState(m)) this.hooks.controller.snapCamera();
        else this.hooks.controller.syncCamera();
        break;
      case 'inventory':
        s.applyInventory(m);
        break;
      case 'chat':
        this.chat.add(m);
        break;
      case 'time':
        this.hooks.time.ticks = m.timeTicks;
        break;
      case 'playerList':
        if (m.joined) this.remote.setName(m.id, m.name);
        else this.remote.forgetName(m.id);
        break;
      case 'actionAck':
        if (!m.ok) {
          this.rejected++;
          this.lastRejection = m.reason;
          s.stats.rejected++;
          s.stats.lastRejection = m.reason;
        }
        break;
      case 'welcome':
      case 'pong':
      case 'disconnect':
        break;
    }
  }

  openChat(): void {
    this.chat.open();
  }

  /** Per frame, after input handling: interpolation, smoothing and the state the server needs. */
  frame(frameDt: number): void {
    const s = this.session;
    const now = performance.now();
    this.remote.update(now, frameDt);
    if (this.client.rtt > 0) s.rttMs = this.client.rtt;
    s.flushInventory(now);
    const label = this.client.rtt > 0 ? `${Math.round(this.client.rtt)} ms` : '... ms';
    if (label !== this.pingShown) {
      this.pingShown = label;
      this.pingEl.textContent = label;
      const rtt = this.client.rtt;
      this.pingEl.dataset['quality'] = rtt <= 0 ? 'unknown' : rtt < 80 ? 'good' : rtt < 200 ? 'ok' : 'bad';
    }
    s.smoother.update(frameDt);
    vec3.set(this.hooks.camera.offset, s.smoother.x, s.smoother.y, s.smoother.z);
    if (s.selectedSlot !== this.lastSlot) {
      this.lastSlot = s.selectedSlot;
      s.sendSelectedSlot(s.selectedSlot);
    }
    const b = this.hooks.interaction.breaking;
    const key = b ? `${b.x},${b.y},${b.z}` : '';
    if (key !== this.lastBreak) {
      this.lastBreak = key;
      s.sendBreakProgress(b);
    }
    const eating = this.hooks.interaction.eatSeconds > 0;
    if (eating && !this.wasEating) s.sendEatStart();
    this.wasEating = eating;
  }

  /** After the 3D frame: name tags over remote players. */
  drawOverlays(viewProj: Mat4, eye: Vec3, width: number, height: number): void {
    this.tags.update(this.remote.players, viewProj, eye, width, height);
  }

  /** "Ping 23 ms (localhost:25580)" for the pause menu. */
  pingText(): string {
    const rtt = this.client.rtt;
    const where = this.client.conn.remote ? ` · ${this.client.conn.remote.replace(/^wss?:\/\//, '')}` : '';
    return rtt > 0 ? `Ping ${Math.round(rtt)} ms${where}` : `Ping: measuring...${where}`;
  }

  debugLine(): string {
    const c = this.client;
    const s = this.session;
    return `Net: ping ${c.rtt.toFixed(0)} ms  in ${(c.stats.bytesIn / 1024).toFixed(0)} KB / out ${(c.stats.bytesOut / 1024).toFixed(0)} KB  inputs pending ${s.history.length} (ack ${s.ackTick})  last error ${s.lastError.toFixed(3)}  corrections ${s.corrections}  entities ${this.remote.count}  chunks recv ${this.streamer.received}  rejected ${this.rejected}${this.lastRejection ? ` (${this.lastRejection})` : ''}`;
  }

  /** Leaves on purpose (no disconnect screen). */
  leave(): void {
    this.leaving = true;
    this.client.disconnect('Left the game');
  }

  dispose(): void {
    window.clearInterval(this.pingTimer);
    this.pingEl.remove();
    if (this.client.isOpen) this.leave();
    this.chat.dispose();
    this.tags.dispose();
    this.remote.clear();
  }
}
