import { BlockId } from './blocks';
import { MAX_Y, MIN_Y } from './chunk';
import { isSolidBlock, type BlockGetter } from '../physics/player';

export interface SpawnPoint {
  /** Feet position: centre of the block column, on top of the ground block. */
  x: number;
  y: number;
  z: number;
  /** True if the spot is under or in water (used only when no dry spot was found). */
  wet: boolean;
}

/**
 * Feet y for column (x, z): one above the top solid non-leaf block, if the two cells above it are
 * not solid. Returns undefined if that spot is blocked (e.g. a trunk under a canopy).
 */
export function columnSpawnY(getBlock: BlockGetter, x: number, z: number): { y: number; wet: boolean } | undefined {
  for (let y = MAX_Y; y >= MIN_Y; y--) {
    const id = getBlock(x, y, z);
    if (!isSolidBlock(id) || id === BlockId.Leaves) continue;
    const a = getBlock(x, y + 1, z);
    const b = getBlock(x, y + 2, z);
    if (isSolidBlock(a) || isSolidBlock(b)) return undefined;
    return { y: y + 1, wet: a === BlockId.Water || b === BlockId.Water };
  }
  return undefined;
}

/**
 * Searches columns in growing squares around (cx, cz) out to `radius` for a dry spawn spot, falling
 * back to the nearest wet one. `isLoaded(x, z)` must say whether a column's chunk is available.
 */
export function findSafeSpawn(
  getBlock: BlockGetter,
  isLoaded: (x: number, z: number) => boolean,
  cx: number,
  cz: number,
  radius = 16,
): SpawnPoint | undefined {
  let wet: SpawnPoint | undefined;
  for (let r = 0; r <= radius; r++) {
    for (let dz = -r; dz <= r; dz++) {
      for (let dx = -r; dx <= r; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dz)) !== r) continue; // ring only
        const x = cx + dx;
        const z = cz + dz;
        if (!isLoaded(x, z)) continue;
        const s = columnSpawnY(getBlock, x, z);
        if (!s) continue;
        const p = { x: x + 0.5, y: s.y, z: z + 0.5, wet: s.wet };
        if (!s.wet) return p;
        wet ??= p;
      }
    }
  }
  return wet;
}
