/**
 * Combat helpers (Milestone 8): ray vs box picking, melee damage from the held item with an
 * attack cooldown, and drop-table rolls. Pure.
 */
import type { Aabb } from '../physics/player';
import { createStack, getItemDef, type ItemStack, type Slot } from '../items/items';
import type { DropEntry } from './mobTypes';

/**
 * Distance along a ray (origin o, direction d — need not be normalised; the result is in units of
 * |d|) to where it enters `box`, or null if it misses or the hit is beyond `maxDist`. A ray that
 * starts inside the box hits at 0. Slab method.
 */
export function rayVsAabb(ox: number, oy: number, oz: number, dx: number, dy: number, dz: number, box: Aabb, maxDist = Infinity): number | null {
  const len = Math.hypot(dx, dy, dz);
  if (len === 0) return null;
  dx /= len;
  dy /= len;
  dz /= len;
  let tMin = 0;
  let tMax = maxDist;
  const o = [ox, oy, oz];
  const d = [dx, dy, dz];
  const lo = [box.minX, box.minY, box.minZ];
  const hi = [box.maxX, box.maxY, box.maxZ];
  for (let a = 0; a < 3; a++) {
    const oa = o[a]!, da = d[a]!;
    if (Math.abs(da) < 1e-12) {
      if (oa < lo[a]! || oa > hi[a]!) return null;
      continue;
    }
    let t1 = (lo[a]! - oa) / da;
    let t2 = (hi[a]! - oa) / da;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tMin) tMin = t1;
    if (t2 < tMax) tMax = t2;
    if (tMin > tMax) return null;
  }
  return tMin;
}

/** Seconds for a player attack to recharge to full strength. */
export const ATTACK_COOLDOWN = 0.6;
/** Damage of a bare hand (or a non-tool item). */
export const HAND_DAMAGE = 1;

/**
 * Damage of a player hit with `held`, `sinceLast` seconds after the previous attack. Spamming
 * deals less: strength = 0.2 + 0.8 * charge^2 where charge = sinceLast / ATTACK_COOLDOWN (<= 1).
 */
export function attackDamage(held: Slot, sinceLast: number): number {
  const base = (held && getItemDef(held.item).tool?.attackDamage) || HAND_DAMAGE;
  const charge = Math.max(0, Math.min(1, sinceLast / ATTACK_COOLDOWN));
  return base * (0.2 + 0.8 * charge * charge);
}

/** Durability a held tool loses for hitting a mob: swords 1, other tools 2, non-tools 0. */
export function toolWearForAttack(held: Slot): number {
  const tool = held ? getItemDef(held.item).tool : undefined;
  if (!tool) return 0;
  return tool.kind === 'sword' ? 1 : 2;
}

/** Rolls a drop table. `rand` yields [0, 1). */
export function rollDrops(table: readonly DropEntry[], rand: () => number): ItemStack[] {
  const out: ItemStack[] = [];
  for (const d of table) {
    if (d.chance !== undefined && rand() >= d.chance) continue;
    const n = d.min + Math.floor(rand() * (d.max - d.min + 1));
    if (n > 0) out.push(createStack(d.item, n));
  }
  return out;
}
