import type { Mat4 } from '@voxel/shared';

/** Name tags are hidden beyond this distance (blocks). */
const MAX_TAG_DISTANCE = 64;

export interface TaggedPosition {
  id: number;
  name: string;
  x: number;
  y: number;
  z: number;
}

/**
 * DOM name tags over remote players (Milestone 10): each frame the tag's world position is
 * projected with the camera's view-projection matrix and the label is moved there. Names are
 * set with `textContent`.
 */
export class NameTags {
  private readonly root: HTMLDivElement;
  private readonly tags = new Map<number, HTMLDivElement>();

  constructor(parent: HTMLElement = document.body) {
    this.root = document.createElement('div');
    this.root.className = 'name-tags';
    parent.append(this.root);
  }

  update(list: readonly TaggedPosition[], viewProj: Mat4, eye: ArrayLike<number>, width: number, height: number): void {
    const live = new Set<number>();
    for (const p of list) {
      live.add(p.id);
      let el = this.tags.get(p.id);
      if (!el) {
        el = document.createElement('div');
        el.className = 'name-tag';
        this.root.append(el);
        this.tags.set(p.id, el);
      }
      if (el.textContent !== p.name) el.textContent = p.name;
      const m = viewProj;
      const cx = m[0]! * p.x + m[4]! * p.y + m[8]! * p.z + m[12]!;
      const cy = m[1]! * p.x + m[5]! * p.y + m[9]! * p.z + m[13]!;
      const cw = m[3]! * p.x + m[7]! * p.y + m[11]! * p.z + m[15]!;
      const dist = Math.hypot(p.x - eye[0]!, p.y - eye[1]!, p.z - eye[2]!);
      if (cw <= 0.05 || dist > MAX_TAG_DISTANCE) {
        el.hidden = true;
        continue;
      }
      const sx = (cx / cw * 0.5 + 0.5) * width;
      const sy = (1 - (cy / cw * 0.5 + 0.5)) * height;
      el.hidden = sx < -100 || sx > width + 100 || sy < -50 || sy > height + 50;
      el.style.transform = `translate(${sx.toFixed(1)}px, ${sy.toFixed(1)}px) translate(-50%, -100%)`;
    }
    for (const [id, el] of this.tags) {
      if (live.has(id)) continue;
      el.remove();
      this.tags.delete(id);
    }
  }

  dispose(): void {
    this.root.remove();
    this.tags.clear();
  }
}
