import {
  CHUNK_FORMAT_VERSION,
  CHUNK_SIZE,
  ChunkSaveTracker,
  decodeChunkBlocks,
  encodeChunkBlocks,
  type PendingChunkSave,
  type World,
} from '@voxel/shared';
import { compressBytes, decompressBytes, type ByteCodec } from './compression';
import type { ChunkRecord, WorldMeta, WorldStore } from './worldStore';
import type { SavedChunkSource } from '../world/chunkStreamer';
import { isQuotaError, toast } from '../ui/toast';

/** Seconds between autosaves. */
export const AUTOSAVE_SECONDS = 30;
/** Delay before saving chunks that were just unloaded (coalesces a burst of unloads). */
const UNLOAD_FLUSH_DELAY_MS = 1500;

export interface SaveStats {
  /** Chunks that differ from generation (stored, pending or edited). */
  modifiedChunks: number;
  /** Chunks with edits not yet confirmed on disk. */
  unsavedChunks: number;
  /** Chunks in the transaction currently being written. */
  writing: number;
  /** `Date.now()` of the last successful save, or 0. */
  lastSaveTime: number;
  lastSaveMs: number;
  failures: number;
  lastError: string;
}

/**
 * Per-world persistence: tracks modified chunks (via `ChunkSaveTracker`), loads them for the
 * streamer, and writes them plus the world meta on unload, every AUTOSAVE_SECONDS, when the tab is
 * hidden and on pagehide.
 *
 * With no store (IndexedDB unavailable, or a temporary `?seed=` world) nothing is written, but
 * edits to unloaded chunks are still kept in memory for the session.
 */
export class SaveManager implements SavedChunkSource {
  readonly tracker: ChunkSaveTracker;
  readonly stats: SaveStats = {
    modifiedChunks: 0,
    unsavedChunks: 0,
    writing: 0,
    lastSaveTime: 0,
    lastSaveMs: 0,
    failures: 0,
    lastError: '',
  };
  private chain: Promise<void> = Promise.resolve();
  private queued: Promise<void> | null = null;
  private unloadTimer = 0;
  private autosaveTimer = 0;
  private readonly abort = new AbortController();
  private disposed = false;

  private constructor(
    private readonly store: WorldStore | undefined,
    private readonly worldId: string,
    private readonly world: World,
    /** Builds the current meta (player, time) for each save. */
    private readonly getMeta: () => WorldMeta,
    savedCoords: [number, number][],
  ) {
    this.tracker = new ChunkSaveTracker(savedCoords);
    this.refreshStats();
  }

  /** Loads the set of stored chunk keys for the world (one key-only query), then starts autosave. */
  static async open(store: WorldStore | undefined, worldId: string, world: World, getMeta: () => WorldMeta): Promise<SaveManager> {
    let coords: [number, number][] = [];
    if (store) {
      try {
        coords = await store.listChunkCoords(worldId);
      } catch (err) {
        console.warn('Could not list saved chunks', err);
      }
    }
    const m = new SaveManager(store, worldId, world, getMeta, coords);
    m.startTriggers();
    return m;
  }

  get enabled(): boolean {
    return !!this.store;
  }

  private startTriggers(): void {
    if (!this.store) return;
    this.autosaveTimer = window.setInterval(() => void this.flush(), AUTOSAVE_SECONDS * 1000);
    const opts = { signal: this.abort.signal };
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') this.flushNow();
    }, opts);
    window.addEventListener('pagehide', () => this.flushNow(), opts);
  }

  /** Stops timers and listeners. Does not save; call `flush()` first. */
  dispose(): void {
    this.disposed = true;
    window.clearInterval(this.autosaveTimer);
    window.clearTimeout(this.unloadTimer);
    this.abort.abort();
  }

  /** Call after every applied block edit. */
  markEdited(x: number, z: number): void {
    this.tracker.markDirty(Math.floor(x / CHUNK_SIZE), Math.floor(z / CHUNK_SIZE));
    this.refreshStats();
  }

  /** Streamer unload hook: snapshot edited chunks and save them shortly. */
  onChunkUnloaded(cx: number, cz: number, blocks: Uint16Array): void {
    if (!this.tracker.onUnload(cx, cz, blocks)) return;
    this.refreshStats();
    if (this.store && !this.unloadTimer) {
      this.unloadTimer = window.setTimeout(() => {
        this.unloadTimer = 0;
        void this.flush();
      }, UNLOAD_FLUSH_DELAY_MS);
    }
  }

  // --- SavedChunkSource ---------------------------------------------------------------------

  has(cx: number, cz: number): boolean {
    return this.tracker.hasSaved(cx, cz);
  }

  async load(cx: number, cz: number): Promise<Uint16Array | undefined> {
    // A snapshot not yet on disk (or being written) is newer than whatever storage holds.
    const pending = this.tracker.pendingBlocks(cx, cz);
    if (pending) return pending.slice();
    if (!this.store) return undefined;
    const rec = await this.store.getChunk(this.worldId, cx, cz);
    const pendingNow = this.tracker.pendingBlocks(cx, cz);
    if (pendingNow) return pendingNow.slice();
    if (!rec) return undefined;
    if (rec.format > CHUNK_FORMAT_VERSION) throw new Error(`chunk ${cx},${cz} has newer format ${rec.format}`);
    const rle = await decompressBytes(rec.codec, new Uint8Array(rec.data));
    const { blocks, unknown } = decodeChunkBlocks({ palette: rec.palette, rle });
    if (unknown.length > 0) console.warn(`Chunk ${cx},${cz}: unknown blocks ${unknown.join(', ')} loaded as air`);
    return blocks;
  }

  // --- Saving ---------------------------------------------------------------------------------

  /**
   * Saves all edited chunks and the meta (compressed, one transaction). Calls are serialized; a
   * call made while another is waiting to start joins it.
   */
  flush(): Promise<void> {
    if (!this.store) return Promise.resolve();
    if (!this.queued) {
      const run = this.chain.then(() => {
        this.queued = null;
        return this.doFlush();
      });
      this.queued = run;
      this.chain = run.catch(() => undefined);
    }
    return this.queued;
  }

  /**
   * Synchronous best-effort save for pagehide / tab hidden: RLE only (no async compression), so
   * the transaction is queued before the handler returns.
   */
  flushNow(): void {
    const store = this.store;
    if (!store || this.disposed) return;
    try {
      const batch = this.tracker.beginFlush((cx, cz) => this.world.getChunk(cx, cz)?.blocks);
      const records = batch.map((e) => {
        const enc = encodeChunkBlocks(e.blocks);
        return this.record(e, 'none', enc.palette, enc.rle);
      });
      const t0 = performance.now();
      store.saveBatch(this.getMeta(), records).then(
        () => this.saved(batch, t0),
        (err: unknown) => this.failed(err),
      );
    } catch (err) {
      this.failed(err);
    }
  }

  private async doFlush(): Promise<void> {
    const store = this.store;
    if (!store) return;
    const t0 = performance.now();
    try {
      const batch = this.tracker.beginFlush((cx, cz) => this.world.getChunk(cx, cz)?.blocks);
      const encoded = await Promise.all(
        batch.map(async (e) => {
          const enc = encodeChunkBlocks(e.blocks);
          const c = await compressBytes(enc.rle);
          return { e, palette: enc.palette, codec: c.codec, data: c.data };
        }),
      );
      // Skip snapshots superseded while compressing (a newer one is written by a later flush).
      const current = encoded.filter((x) => this.tracker.isCurrent(x.e));
      this.stats.writing = current.length;
      await store.saveBatch(
        this.getMeta(),
        current.map((x) => this.record(x.e, x.codec, x.palette, x.data)),
      );
      this.saved(current.map((x) => x.e), t0);
    } catch (err) {
      this.failed(err);
      throw err;
    } finally {
      this.stats.writing = 0;
    }
  }

  private record(e: PendingChunkSave, codec: ByteCodec, palette: string[], data: Uint8Array): ChunkRecord {
    const buf = data.byteOffset === 0 && data.byteLength === data.buffer.byteLength ? data.buffer : data.slice().buffer;
    return {
      worldId: this.worldId,
      cx: e.cx,
      cz: e.cz,
      format: CHUNK_FORMAT_VERSION,
      codec,
      palette,
      data: buf as ArrayBuffer,
      savedAt: Date.now(),
    };
  }

  private saved(entries: readonly PendingChunkSave[], t0: number): void {
    this.tracker.endFlush(entries);
    this.stats.lastSaveTime = Date.now();
    this.stats.lastSaveMs = performance.now() - t0;
    this.refreshStats();
  }

  private failed(err: unknown): void {
    this.stats.failures++;
    this.stats.lastError = err instanceof Error ? err.message : String(err);
    console.warn('Save failed', err);
    if (isQuotaError(err)) {
      toast('Storage is full: your world could not be saved. Free some space (delete old worlds or clear site data for other pages), then try Save & quit.', 'error', 15000);
    } else if (this.stats.failures === 1 || this.stats.failures % 10 === 0) {
      toast(`Saving failed: ${this.stats.lastError}. The game keeps trying.`, 'error');
    }
    this.refreshStats();
  }

  private refreshStats(): void {
    this.stats.modifiedChunks = this.tracker.modifiedCount;
    this.stats.unsavedChunks = this.tracker.unsavedCount;
  }
}
