import type { Mat4 } from '@voxel/shared';

/**
 * View frustum as 6 planes (a, b, c, d) with inward-facing normals, extracted from a
 * column-major view-projection matrix (Gribb/Hartmann). A point p is inside a plane when
 * a*px + b*py + c*pz + d >= 0.
 */
export class Frustum {
  /** 6 planes x 4 coefficients: left, right, bottom, top, near, far. */
  readonly planes = new Float32Array(24);

  setFromViewProj(m: Mat4): this {
    const p = this.planes;
    // Row r of the matrix is (m[r], m[4 + r], m[8 + r], m[12 + r]).
    for (let i = 0; i < 6; i++) {
      const row = i >> 1; // 0: x, 1: y, 2: z
      const sign = i & 1 ? -1 : 1;
      let a = m[3]! + sign * m[row]!;
      let b = m[7]! + sign * m[4 + row]!;
      let c = m[11]! + sign * m[8 + row]!;
      let d = m[15]! + sign * m[12 + row]!;
      const len = Math.hypot(a, b, c) || 1;
      a /= len;
      b /= len;
      c /= len;
      d /= len;
      p[i * 4] = a;
      p[i * 4 + 1] = b;
      p[i * 4 + 2] = c;
      p[i * 4 + 3] = d;
    }
    return this;
  }

  /** Conservative AABB test: false only when the box is fully outside some plane. */
  intersectsBox(minX: number, minY: number, minZ: number, maxX: number, maxY: number, maxZ: number): boolean {
    const p = this.planes;
    for (let i = 0; i < 24; i += 4) {
      const a = p[i]!, b = p[i + 1]!, c = p[i + 2]!, d = p[i + 3]!;
      // The box corner furthest along the plane normal.
      const x = a >= 0 ? maxX : minX;
      const y = b >= 0 ? maxY : minY;
      const z = c >= 0 ? maxZ : minZ;
      if (a * x + b * y + c * z + d < 0) return false;
    }
    return true;
  }
}
