/**
 * Player intent (Milestone 9): what the player wants to do this frame, independent of the device.
 * Keyboard + mouse and touch both fill one `PlayerIntent`; `PlayerController`, `BlockInteraction`
 * and `Game` read only this. It is plain data (numbers and booleans), so it is also the natural
 * shape for the Milestone 10 network input message.
 *
 * Held fields (`jump`, `primary`, ...) are the state right now; `*Pressed` and the one-shot actions
 * (`openInventory`, `drop`, ...) are edges since the previous sample. Sampled once per animation
 * frame, before the fixed ticks of that frame run.
 */
export interface PlayerIntent {
  /** Strafe, -1 (left) .. 1 (right). Analog for touch; keyboard gives -1, 0 or 1. */
  moveX: number;
  /** Forward, -1 (back) .. 1 (forward). The length of (moveX, moveZ) scales walking speed. */
  moveZ: number;
  /** Yaw to add this frame, radians (positive turns right). Sensitivity already applied. */
  lookYaw: number;
  /** Pitch to add this frame, radians (positive looks up). */
  lookPitch: number;
  jump: boolean;
  sneak: boolean;
  sprint: boolean;
  /** Attack / break: held, and went down this frame. */
  primary: boolean;
  primaryPressed: boolean;
  /** Place / use / eat: held, and went down this frame. */
  secondary: boolean;
  secondaryPressed: boolean;
  /** Hotbar slot 0-8 chosen this frame, or -1. */
  hotbarSlot: number;
  /** Hotbar wheel notches this frame (positive = next slot). */
  hotbarScroll: number;
  /** Toggle the inventory screen (open, or close when open). */
  openInventory: boolean;
  /** Drop the held item; with `dropStack` the whole stack. */
  drop: boolean;
  dropStack: boolean;
  /** Open the pause menu (touch has no Esc; desktop pauses through pointer lock / Esc events). */
  pause: boolean;
  /** Toggle flying (creative only; the controller ignores it in survival). */
  toggleFly: boolean;
}

export function createIntent(): PlayerIntent {
  return {
    moveX: 0,
    moveZ: 0,
    lookYaw: 0,
    lookPitch: 0,
    jump: false,
    sneak: false,
    sprint: false,
    primary: false,
    primaryPressed: false,
    secondary: false,
    secondaryPressed: false,
    hotbarSlot: -1,
    hotbarScroll: 0,
    openInventory: false,
    drop: false,
    dropStack: false,
    pause: false,
    toggleFly: false,
  };
}

/** Clears an intent in place (no allocation per frame). */
export function resetIntent(i: PlayerIntent): PlayerIntent {
  i.moveX = i.moveZ = i.lookYaw = i.lookPitch = i.hotbarScroll = 0;
  i.jump = i.sneak = i.sprint = false;
  i.primary = i.primaryPressed = i.secondary = i.secondaryPressed = false;
  i.hotbarSlot = -1;
  i.openInventory = i.drop = i.dropStack = i.pause = i.toggleFly = false;
  return i;
}

/** Clamps a move vector to length 1 (diagonals and summed sources never exceed full speed). */
export function clampMove(i: PlayerIntent): void {
  const len = Math.hypot(i.moveX, i.moveZ);
  if (len > 1) {
    i.moveX /= len;
    i.moveZ /= len;
  }
}

// --- Keyboard + mouse ------------------------------------------------------------------------------

/** Radians per CSS pixel of mouse movement at sensitivity 1 (the pre-M9 constant). */
export const MOUSE_SENSITIVITY = 0.0025;
/** Two presses within this many seconds count as a double tap (Space: fly, W: sprint). */
export const DOUBLE_TAP_SECONDS = 0.3;

/** What the keyboard source reads; `Input` implements it, tests use a fake. */
export interface KeyState {
  isDown(code: string): boolean;
  wasPressed(code: string): boolean;
  isMouseDown(button: number): boolean;
  wasMousePressed(button: number): boolean;
  consumeMouseDelta(): { dx: number; dy: number };
  consumeWheel(): number;
}

/**
 * Desktop bindings: WASD move, mouse look, Space jump (double tap: fly in creative, or F), Shift
 * sneak, sprint = double-tap W (held until W is released) or hold Ctrl, left/right mouse buttons,
 * 1-9 / wheel hotbar, E inventory, Q drop (Ctrl+Q the stack).
 *
 * Sprint note: Ctrl+W closes the browser tab and pages cannot block it, so double-tap W is the
 * recommended sprint; Ctrl still works for players who press it before W or use arrow-free layouts.
 */
export class KeyboardMouseSource {
  private lastSpace = -Infinity;
  private lastW = -Infinity;
  /** Sprint latched by a W double tap; ends when W is released. */
  sprintLatched = false;

  /** `now` in seconds; `sensitivity` multiplies MOUSE_SENSITIVITY. */
  fill(out: PlayerIntent, keys: KeyState, now: number, sensitivity = 1): void {
    const fwd = (keys.isDown('KeyW') ? 1 : 0) - (keys.isDown('KeyS') ? 1 : 0);
    const str = (keys.isDown('KeyD') ? 1 : 0) - (keys.isDown('KeyA') ? 1 : 0);
    out.moveZ += fwd;
    out.moveX += str;
    const { dx, dy } = keys.consumeMouseDelta();
    out.lookYaw += dx * MOUSE_SENSITIVITY * sensitivity;
    out.lookPitch -= dy * MOUSE_SENSITIVITY * sensitivity;

    if (keys.wasPressed('KeyW')) {
      if (now - this.lastW < DOUBLE_TAP_SECONDS) {
        this.sprintLatched = true;
        this.lastW = -Infinity;
      } else {
        this.lastW = now;
      }
    }
    if (!keys.isDown('KeyW')) this.sprintLatched = false;
    const ctrl = keys.isDown('ControlLeft') || keys.isDown('ControlRight');
    out.sprint ||= ctrl || this.sprintLatched;
    out.jump ||= keys.isDown('Space');
    out.sneak ||= keys.isDown('ShiftLeft') || keys.isDown('ShiftRight');

    if (keys.wasPressed('KeyF')) out.toggleFly = !out.toggleFly;
    if (keys.wasPressed('Space')) {
      if (now - this.lastSpace < DOUBLE_TAP_SECONDS) {
        out.toggleFly = !out.toggleFly;
        this.lastSpace = -Infinity;
      } else {
        this.lastSpace = now;
      }
    }

    out.primary ||= keys.isMouseDown(0);
    out.primaryPressed ||= keys.wasMousePressed(0);
    out.secondary ||= keys.isMouseDown(2);
    out.secondaryPressed ||= keys.wasMousePressed(2);

    for (let i = 0; i < 9; i++) if (keys.wasPressed(`Digit${i + 1}`)) out.hotbarSlot = i;
    out.hotbarScroll += keys.consumeWheel();
    if (keys.wasPressed('KeyE')) out.openInventory = true;
    if (keys.wasPressed('KeyQ')) {
      out.drop = true;
      out.dropStack ||= ctrl;
    }
  }
}
