import { SECTION_SIZE, VERTEX_BYTES, decodeSectionKey, sectionBaseY, type Mat4, type MeshBuffers, type SectionMesh } from '@voxel/shared';
import { createProgram, type ShaderProgram } from './shader';
import { Frustum } from './frustum';

// Must match packages/shared/src/mesh/vertexFormat.ts.
const VS = `#version 300 es
layout(location = 0) in uvec2 a_data;

uniform mat4 u_viewProj;
uniform vec3 u_origin;
uniform vec3 u_camPos;

out vec3 v_uvl;
/** Smoothed sky and block light, 0..15. */
out vec2 v_light;
/** AO and directional face shading combined. */
out float v_shade;
/** Horizontal distance from the camera, for fog. */
out float v_dist;

// Gentle directional shading so block edges stay readable: +X, -X, +Y, -Y, +Z, -Z, cross.
const float FACE_SHADE[7] = float[7](0.86, 0.86, 1.0, 0.7, 0.93, 0.93, 1.0);
// Brightness for AO 0..3 (0 = corner fully enclosed).
const float AO_SHADE[4] = float[4](0.5, 0.67, 0.83, 1.0);

void main() {
  uint w0 = a_data.x;
  uint w1 = a_data.y;
  // Layout: shared mesh/vertexFormat.ts (positions and uv in sixteenths).
  vec3 pos = vec3(float(w0 & 511u), float((w0 >> 9u) & 511u), float((w0 >> 18u) & 511u)) * 0.0625;
  uint face = (w0 >> 27u) & 7u;
  uint ao = (w0 >> 30u) & 3u;
  // Light fields are stored in quarter steps (0..60).
  v_light = vec2(float(w1 & 63u), float((w1 >> 6u) & 63u)) * 0.25;
  float layer = float((w1 >> 12u) & 1023u);
  vec2 uv = vec2(float((w1 >> 22u) & 31u), float((w1 >> 27u) & 31u)) * 0.0625;

  v_uvl = vec3(uv, layer);
  v_shade = FACE_SHADE[min(face, 6u)] * AO_SHADE[ao];
  vec3 world = u_origin + pos;
  v_dist = length(world.xz - u_camPos.xz);
  gl_Position = u_viewProj * vec4(world, 1.0);
}
`;

const FS = `#version 300 es
precision highp float;
precision highp sampler2DArray;

uniform sampler2DArray u_blocks;
uniform vec3 u_fogColor;
/** Fog start and end distance (horizontal, in blocks). */
uniform vec2 u_fog;
/** How strongly sky light lights the world right now (day/night), 0..1. */
uniform float u_daylight;
/** Colour of sky light right now (neutral by day, warm at dusk, blue at night). */
uniform vec3 u_skyTint;

in vec3 v_uvl;
in vec2 v_light;
in float v_shade;
in float v_dist;
out vec4 outColor;

// Warm torch colour for block light.
const vec3 TORCH_TINT = vec3(1.0, 0.8, 0.55);
// Floor so unlit caves are dark but their shapes stay readable (Milestone 11: was 0.035).
const float MIN_AMBIENT = 0.13;

/**
 * Light level 0..15 to brightness 0..1, a falloff curve that reads like a gamma ramp. Milestone 11
 * flattened it a little (was b / (3 - 2b)) so dim light a few blocks from a torch or a cave mouth
 * reads better; full light is unchanged.
 */
float curve(float level) {
  float b = clamp(level / 15.0, 0.0, 1.0);
  return b / (2.4 - 1.4 * b);
}

void main() {
  vec4 c = texture(u_blocks, v_uvl);
  if (c.a < 0.02) discard; // leaf holes (cutout) and fully clear texels
  vec3 sky = curve(v_light.x) * u_daylight * u_skyTint;
  vec3 torch = curve(v_light.y) * TORCH_TINT;
  vec3 light = max(max(sky, torch), vec3(MIN_AMBIENT)) * v_shade;
  vec3 rgb = c.rgb * light;
  float f = smoothstep(u_fog.x, u_fog.y, v_dist);
  // Fully fogged geometry becomes opaque sky colour, so transparent water hides the edge too.
  outColor = vec4(mix(rgb, u_fogColor, f), mix(c.a, 1.0, f));
}
`;

interface GpuMesh {
  vao: WebGLVertexArrayObject;
  vbo: WebGLBuffer;
  ibo: WebGLBuffer;
  indexCount: number;
}

interface GpuSection {
  key: number;
  /** World-space origin (min corner). */
  x: number;
  y: number;
  z: number;
  opaque: GpuMesh | null;
  transparent: GpuMesh | null;
  /** Squared distance from the camera to the section centre, set while drawing (sort key). */
  d: number;
}

/** Per-frame lighting uniforms for day/night (no re-meshing needed when these change). */
export interface WorldLighting {
  /** Sky light multiplier 0..1. */
  daylight: number;
  /** Sky light colour. */
  skyTint: readonly [number, number, number];
}

/** Distance fog parameters. Geometry beyond `end` is not drawn at all. */
export interface FogSettings {
  /** Should match the sky's horizon colour. */
  color: readonly [number, number, number];
  /** Horizontal distance in blocks where fog begins. */
  start: number;
  /** Horizontal distance in blocks where fog is total. */
  end: number;
}

export interface ChunkRenderStats {
  /** Sections with any GPU geometry. */
  sections: number;
  /** Sections drawn this frame (inside the view frustum and fog distance). */
  visibleSections: number;
  /** Triangles drawn this frame. */
  triangles: number;
}

const byDistanceAscending = (a: GpuSection, b: GpuSection): number => a.d - b.d;
const byDistanceDescending = (a: GpuSection, b: GpuSection): number => b.d - a.d;

/** Owns one VAO/VBO/IBO per non-empty section and pass, and draws them in two passes. */
export class ChunkRenderer {
  private readonly shader: ShaderProgram;
  private readonly sections = new Map<number, GpuSection>();
  /** Reused per frame: visible opaque sections (sorted near to far) and transparent ones (far to near). */
  private readonly opaqueList: GpuSection[] = [];
  private readonly transparentList: GpuSection[] = [];
  private readonly frustum = new Frustum();
  readonly stats: ChunkRenderStats = { sections: 0, visibleSections: 0, triangles: 0 };

  constructor(private readonly gl: WebGL2RenderingContext) {
    this.shader = createProgram(gl, VS, FS);
  }

  get sectionCount(): number {
    return this.sections.size;
  }

  /** Replaces (or removes, when `mesh` is null or empty) the GPU buffers for a section. */
  setSectionMesh(key: number, mesh: SectionMesh | null): void {
    this.removeSection(key);
    if (!mesh || (mesh.opaque.indices.length === 0 && mesh.transparent.indices.length === 0)) return;
    const { cx, sy, cz } = decodeSectionKey(key);
    this.sections.set(key, {
      key,
      x: cx * SECTION_SIZE,
      y: sectionBaseY(sy),
      z: cz * SECTION_SIZE,
      opaque: this.upload(mesh.opaque),
      transparent: this.upload(mesh.transparent),
      d: 0,
    });
  }

  removeSection(key: number): void {
    const s = this.sections.get(key);
    if (!s) return;
    this.deleteMesh(s.opaque);
    this.deleteMesh(s.transparent);
    this.sections.delete(key);
  }

  /** Deletes every section's GPU buffers (when leaving a world); the shader stays. */
  clear(): void {
    for (const key of [...this.sections.keys()]) this.removeSection(key);
    this.stats.sections = this.stats.visibleSections = this.stats.triangles = 0;
  }

  dispose(): void {
    this.clear();
    this.gl.deleteProgram(this.shader.program);
  }

  draw(
    viewProj: Mat4,
    blockTextures: WebGLTexture,
    camX: number,
    camY: number,
    camZ: number,
    fog: FogSettings,
    lighting: WorldLighting,
  ): void {
    const { gl, shader, stats } = this;
    stats.sections = this.sections.size;
    stats.visibleSections = 0;
    stats.triangles = 0;

    gl.useProgram(shader.program);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D_ARRAY, blockTextures);
    const uBlocks = shader.uniforms['u_blocks'];
    const uViewProj = shader.uniforms['u_viewProj'];
    const uOrigin = shader.uniforms['u_origin'] ?? null;
    if (uBlocks) gl.uniform1i(uBlocks, 0);
    if (uViewProj) gl.uniformMatrix4fv(uViewProj, false, viewProj);
    const uCamPos = shader.uniforms['u_camPos'];
    const uFogColor = shader.uniforms['u_fogColor'];
    const uFog = shader.uniforms['u_fog'];
    if (uCamPos) gl.uniform3f(uCamPos, camX, camY, camZ);
    if (uFogColor) gl.uniform3f(uFogColor, fog.color[0], fog.color[1], fog.color[2]);
    if (uFog) gl.uniform2f(uFog, fog.start, fog.end);
    const uDaylight = shader.uniforms['u_daylight'];
    const uSkyTint = shader.uniforms['u_skyTint'];
    if (uDaylight) gl.uniform1f(uDaylight, lighting.daylight);
    if (uSkyTint) gl.uniform3f(uSkyTint, lighting.skyTint[0], lighting.skyTint[1], lighting.skyTint[2]);
    const frustum = this.frustum.setFromViewProj(viewProj);
    const maxDist2 = fog.end * fog.end;

    // Cull, and collect the visible sections with their distance.
    const opaque = this.opaqueList;
    const list = this.transparentList;
    opaque.length = 0;
    list.length = 0;
    const h = SECTION_SIZE / 2;
    const S = SECTION_SIZE;
    for (const s of this.sections.values()) {
      // Fully fogged (horizontal distance to the nearest point of the section beyond fog end)?
      const nx = Math.max(s.x - camX, 0, camX - (s.x + S));
      const nz = Math.max(s.z - camZ, 0, camZ - (s.z + S));
      if (nx * nx + nz * nz > maxDist2) continue;
      if (!frustum.intersectsBox(s.x, s.y, s.z, s.x + S, s.y + S, s.z + S)) continue;
      stats.visibleSections++;
      const dx = s.x + h - camX;
      const dy = s.y + h - camY;
      const dz = s.z + h - camZ;
      s.d = dx * dx + dy * dy + dz * dz;
      if (s.opaque) opaque.push(s);
      if (s.transparent) list.push(s);
    }

    // Pass 1: opaque + cutout, near to far so early depth testing rejects hidden fragments.
    opaque.sort(byDistanceAscending);
    for (const s of opaque) {
      gl.uniform3f(uOrigin, s.x, s.y, s.z);
      this.drawMesh(s.opaque!);
    }

    // Pass 2: transparent, sections back to front, blended, no depth writes.
    if (list.length > 0) {
      list.sort(byDistanceDescending);
      gl.enable(gl.BLEND);
      gl.blendFuncSeparate(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.depthMask(false);
      // Both sides: a water surface must be visible from below (looking up while swimming).
      gl.disable(gl.CULL_FACE);
      for (const s of list) {
        gl.uniform3f(uOrigin, s.x, s.y, s.z);
        this.drawMesh(s.transparent!);
      }
      gl.enable(gl.CULL_FACE);
      gl.depthMask(true);
      gl.disable(gl.BLEND);
    }
    gl.bindVertexArray(null);
  }

  private drawMesh(m: GpuMesh): void {
    const { gl } = this;
    gl.bindVertexArray(m.vao);
    gl.drawElements(gl.TRIANGLES, m.indexCount, gl.UNSIGNED_SHORT, 0);
    this.stats.triangles += m.indexCount / 3;
  }

  private upload(buffers: MeshBuffers): GpuMesh | null {
    if (buffers.indices.length === 0) return null;
    const { gl } = this;
    const vao = gl.createVertexArray();
    const vbo = gl.createBuffer();
    const ibo = gl.createBuffer();
    if (!vao || !vbo || !ibo) throw new Error('Failed to allocate GL buffers for a chunk section');
    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
    gl.bufferData(gl.ARRAY_BUFFER, buffers.vertices, gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribIPointer(0, 2, gl.UNSIGNED_INT, VERTEX_BYTES, 0);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibo);
    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, buffers.indices, gl.STATIC_DRAW);
    gl.bindVertexArray(null);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
    return { vao, vbo, ibo, indexCount: buffers.indices.length };
  }

  private deleteMesh(m: GpuMesh | null): void {
    if (!m) return;
    const { gl } = this;
    gl.deleteVertexArray(m.vao);
    gl.deleteBuffer(m.vbo);
    gl.deleteBuffer(m.ibo);
  }
}
