/** Lines stay fully visible this long, then fade out (all lines show while the chat is open). */
const VISIBLE_MS = 10_000;
const MAX_LINES = 100;

export interface ChatLine {
  /** 0 = player message, 1 = system (join / leave / deaths). */
  kind: number;
  from: string;
  text: string;
}

/**
 * Multiplayer chat (Milestone 10): a log at the bottom left whose lines fade after a few
 * seconds, and an input opened with T or Enter (or the touch "Chat" button). Enter sends, Esc
 * closes. Text is always inserted with `textContent` (never parsed as HTML).
 */
export class ChatBox {
  private readonly root: HTMLDivElement;
  private readonly log: HTMLDivElement;
  private readonly input: HTMLInputElement;
  private readonly touchBtn: HTMLButtonElement;
  private readonly abort = new AbortController();
  private openState = false;

  constructor(
    private readonly onSend: (text: string) => void,
    private readonly onOpenChange: (open: boolean) => void,
    parent: HTMLElement = document.body,
  ) {
    this.root = document.createElement('div');
    this.root.className = 'chat';
    this.log = document.createElement('div');
    this.log.className = 'chat-log';
    this.log.setAttribute('role', 'log');
    this.log.setAttribute('aria-live', 'polite');
    this.input = document.createElement('input');
    this.input.className = 'chat-input';
    this.input.type = 'text';
    this.input.maxLength = 256;
    this.input.placeholder = 'Say something (Enter to send, Esc to close)';
    this.input.hidden = true;
    this.input.setAttribute('aria-label', 'Chat message');
    this.root.append(this.log, this.input);
    this.touchBtn = document.createElement('button');
    this.touchBtn.type = 'button';
    this.touchBtn.className = 'btn chat-touch-btn';
    this.touchBtn.textContent = 'Chat';
    parent.append(this.root, this.touchBtn);

    const signal = this.abort.signal;
    this.input.addEventListener('keydown', (e) => {
      e.stopPropagation(); // typing never reaches the game
      if (e.key === 'Enter') {
        e.preventDefault();
        const text = this.input.value.trim();
        if (text) this.onSend(text);
        this.close();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        this.close();
      }
    }, { signal });
    this.touchBtn.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (this.openState) this.close();
      else this.open();
    }, { signal });
  }

  get isOpen(): boolean {
    return this.openState;
  }

  open(): void {
    if (this.openState) return;
    this.openState = true;
    this.root.classList.add('open');
    this.input.hidden = false;
    this.input.value = '';
    // Focus after the key event that opened it, so the 'T' is not typed into the box.
    setTimeout(() => this.input.focus(), 0);
    this.log.scrollTop = this.log.scrollHeight;
    this.onOpenChange(true);
  }

  close(): void {
    if (!this.openState) return;
    this.openState = false;
    this.root.classList.remove('open');
    this.input.blur();
    this.input.hidden = true;
    this.onOpenChange(false);
  }

  add(line: ChatLine): void {
    const el = document.createElement('div');
    el.className = line.kind === 1 ? 'chat-line system' : 'chat-line';
    if (line.kind === 0 && line.from) {
      const who = document.createElement('span');
      who.className = 'chat-from';
      who.textContent = `<${line.from}> `;
      el.append(who);
    }
    el.append(document.createTextNode(line.text));
    this.log.append(el);
    while (this.log.childElementCount > MAX_LINES) this.log.firstElementChild?.remove();
    this.log.scrollTop = this.log.scrollHeight;
    setTimeout(() => el.classList.add('faded'), VISIBLE_MS);
  }

  /** Text of every line (tests / debugging). */
  lines(): string[] {
    return [...this.log.children].map((c) => c.textContent ?? '');
  }

  dispose(): void {
    this.abort.abort();
    this.root.remove();
    this.touchBtn.remove();
  }
}
