/**
 * Validation for block edits. Pure, so the client checks requests before sending them and the
 * server (Milestone 10) re-checks them with the same rules.
 */
import { MAX_Y, MIN_Y } from './chunk';
import { BLOCK_COUNT, BlockId } from './blocks';
import { isSolidBlock, playerIntersectsBlock, type BlockGetter } from '../physics/player';

export type EditRejection =
  | 'out_of_world'
  | 'unbreakable'
  | 'nothing_there'
  | 'occupied'
  | 'intersects_player'
  | 'invalid_block'
  | 'not_loaded';

export type EditCheck = { ok: true } | { ok: false; reason: EditRejection };

const OK: EditCheck = { ok: true };
const no = (reason: EditRejection): EditCheck => ({ ok: false, reason });

/** Blocks a placed block may replace. */
export function isReplaceable(id: number): boolean {
  return id === BlockId.Air || id === BlockId.Water;
}

/** Blocks the player may place. */
export function isPlaceable(id: number): boolean {
  return Number.isInteger(id) && id > BlockId.Air && id < BLOCK_COUNT && id !== BlockId.Bedrock && id !== BlockId.Water;
}

export function inWorldHeight(y: number): boolean {
  return y >= MIN_Y && y <= MAX_Y;
}

export function checkBreak(getBlock: BlockGetter, x: number, y: number, z: number): EditCheck {
  if (!inWorldHeight(y)) return no('out_of_world');
  const id = getBlock(x, y, z);
  if (id === BlockId.Bedrock) return no('unbreakable');
  if (id === BlockId.Air || id === BlockId.Water) return no('nothing_there');
  return OK;
}

/** A player position (feet) that a placed block must not overlap. */
export interface PlayerFeet {
  x: number;
  y: number;
  z: number;
}

export function checkPlace(
  getBlock: BlockGetter,
  x: number,
  y: number,
  z: number,
  id: number,
  players: readonly PlayerFeet[],
): EditCheck {
  if (!inWorldHeight(y)) return no('out_of_world');
  if (!isPlaceable(id)) return no('invalid_block');
  if (!isReplaceable(getBlock(x, y, z))) return no('occupied');
  if (isSolidBlock(id)) {
    for (const p of players) if (playerIntersectsBlock(p.x, p.y, p.z, x, y, z)) return no('intersects_player');
  }
  return OK;
}
