import type { GeoBBox } from '@voxel/shared';

/**
 * OpenStreetMap download from Overpass (MAP_WORLDS.md phase E). Same query and mirrors as mapcore's
 * CLI (map-to-minecraft `crates/mapcore-cli/src/fetch.rs`), so the browser, the server and the CLI
 * prepare packages from the same data.
 */
export const OVERPASS_ENDPOINTS: readonly string[] = [
  'https://overpass-api.de/api/interpreter',
  'https://overpass.kumi.systems/api/interpreter',
  'https://maps.mail.ru/osm/tools/overpass/api/interpreter',
];

/** Identifies Blockwright to Overpass (Node only: browsers do not let pages set User-Agent). */
export const OVERPASS_USER_AGENT = 'Blockwright/1.0 (OpenStreetMap to voxel world; mapcore)';

const KEYS = ['building', 'building:part', 'highway', 'railway', 'landuse', 'natural', 'leisure', 'amenity', 'waterway', 'water', 'barrier'];

/** Overpass QL for every feature mapcore uses inside `bbox` ([south, west, north, east]). */
export function overpassQuery(bbox: GeoBBox): string {
  const bb = bbox.join(',');
  return `[out:json][timeout:300];\n(\n${KEYS.map((k) => `  nwr["${k}"](${bb});\n`).join('')});\n(._;>;);\nout body;\n`;
}

/** Parses "south,west,north,east" (degrees); throws on anything else. */
export function parseBBox(text: string): GeoBBox {
  const v = text.split(',').map((s) => Number(s.trim()));
  if (v.length !== 4 || v.some((n) => !Number.isFinite(n))) throw new Error('Map area must be four numbers: south,west,north,east');
  const [s, w, n, e] = v as [number, number, number, number];
  if (!(s < n && w < e && s >= -90 && n <= 90 && w >= -180 && e <= 180)) throw new Error('Map area must have south < north and west < east, in degrees');
  return [s, w, n, e];
}

/** Above this area the picker warns (Overpass and mapcore get slow); above MAX_MAP_AREA_KM2 it refuses. */
export const WARN_MAP_AREA_KM2 = 10;
export const MAX_MAP_AREA_KM2 = 25;

/** Rough area of a bbox in km² (Overpass and mapcore get slow above ~10 km²). */
export function bboxAreaKm2(bbox: GeoBBox): number {
  const [s, w, n, e] = bbox;
  const kmPerDegLat = 111.32;
  const kmPerDegLon = 111.32 * Math.cos((((s + n) / 2) * Math.PI) / 180);
  return (n - s) * kmPerDegLat * (e - w) * kmPerDegLon;
}

export interface FetchOsmOptions {
  endpoints?: readonly string[];
  /** Sent where allowed (Node). */
  userAgent?: string;
  fetch?: typeof fetch;
  signal?: AbortSignal;
  /** Called before each endpoint is tried. */
  onAttempt?: (url: string) => void;
  /** Called as the response streams in, with the bytes received so far. */
  onProgress?: (bytes: number) => void;
}

/** Reads a response body as text, reporting the bytes received so far. */
async function readText(res: Response, onProgress?: (bytes: number) => void): Promise<string> {
  if (!onProgress || !res.body) return res.text();
  const reader = res.body.getReader();
  const decoder = new TextDecoder();
  let bytes = 0;
  let text = '';
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    bytes += value.byteLength;
    text += decoder.decode(value, { stream: true });
    onProgress(bytes);
  }
  return text + decoder.decode();
}

/** Areas above this are downloaded as tiles of at most this size and merged (same as mapcore's CLI). */
export const OSM_TILE_KM2 = 5;

/**
 * Splits `bbox` into a grid of tiles of at most about `maxKm2` each, sharing edges exactly (mapcore
 * `Bbox::tiles`). One tile when the area is small enough.
 */
export function osmTiles(bbox: GeoBBox, maxKm2 = OSM_TILE_KM2): GeoBBox[] {
  const [s, w, n, e] = bbox;
  const lat0 = (((s + n) / 2) * Math.PI) / 180;
  const wKm = (e - w) * Math.cos(lat0) * 111.32;
  const hKm = (n - s) * 110.574;
  const side = Math.sqrt(Math.max(maxKm2, 0.01));
  const nx = Math.max(1, Math.ceil(wKm / side));
  const nz = Math.max(1, Math.ceil(hKm / side));
  const lon = (i: number): number => (i === nx ? e : w + ((e - w) * i) / nx);
  const lat = (j: number): number => (j === nz ? n : s + ((n - s) * j) / nz);
  const out: GeoBBox[] = [];
  for (let j = 0; j < nz; j++) for (let i = 0; i < nx; i++) out.push([lat(j), lon(i), lat(j + 1), lon(i + 1)]);
  return out;
}

/** Merges Overpass responses for tiles of one area, keeping each element (type and id) once, first seen first. */
export function mergeOsm(responses: readonly string[]): string {
  const seen = new Set<string>();
  const parts: string[] = [];
  for (const r of responses) {
    const parsed = JSON.parse(r) as { elements?: { type?: string; id?: number }[] };
    for (const el of parsed.elements ?? []) {
      const key = `${el.type}/${el.id}`;
      if (seen.has(key)) continue;
      seen.add(key);
      parts.push(JSON.stringify(el));
    }
  }
  return `{"elements":[${parts.join(',')}]}`;
}

/**
 * Downloads the OSM JSON for `bbox`, trying each mirror in turn. Areas above OSM_TILE_KM2 are fetched
 * as tiles (Overpass times out on large areas) and merged by element id. Throws if all mirrors fail.
 */
export async function fetchOsm(bbox: GeoBBox, options: FetchOsmOptions = {}): Promise<string> {
  const tiles = osmTiles(bbox);
  if (tiles.length === 1) return fetchOsmTile(bbox, options);
  const texts: string[] = [];
  let before = 0;
  for (const [i, tile] of tiles.entries()) {
    const text = await fetchOsmTile(tile, {
      ...options,
      onAttempt: options.onAttempt && ((url) => options.onAttempt!(`${url} (part ${i + 1} of ${tiles.length})`)),
      onProgress: options.onProgress && ((bytes) => options.onProgress!(before + bytes)),
    });
    before += text.length;
    texts.push(text);
  }
  return mergeOsm(texts);
}

async function fetchOsmTile(bbox: GeoBBox, options: FetchOsmOptions): Promise<string> {
  const doFetch = options.fetch ?? globalThis.fetch;
  const body = new URLSearchParams({ data: overpassQuery(bbox) });
  const errors: string[] = [];
  for (const url of options.endpoints ?? OVERPASS_ENDPOINTS) {
    options.onAttempt?.(url);
    try {
      const headers: Record<string, string> = { 'Content-Type': 'application/x-www-form-urlencoded' };
      if (options.userAgent) headers['User-Agent'] = options.userAgent;
      const res = await doFetch(url, { method: 'POST', body, headers, signal: options.signal });
      if (!res.ok) {
        errors.push(`${url}: HTTP ${res.status}`);
        continue;
      }
      const text = await readText(res, options.onProgress);
      if (!text.trimStart().startsWith('{')) {
        errors.push(`${url}: not JSON`);
        continue;
      }
      return text;
    } catch (err) {
      if (options.signal?.aborted) throw err;
      errors.push(`${url}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  throw new Error(`Could not download OpenStreetMap data (${errors.join('; ')})`);
}

/** Metres per degree of latitude (and of longitude at the equator). */
const M_PER_DEG = 111_320;

export interface MapEstimate {
  areaKm2: number;
  /** World size in blocks (east-west, north-south) at the chosen scale. */
  widthBlocks: number;
  depthBlocks: number;
  /** Expected OpenStreetMap download and MapPackage sizes (dense city figures, so an upper-ish guess). */
  osmBytes: number;
  packageBytes: number;
}

/**
 * Sizes for the map picker. Data sizes scale with area, calibrated on Bryant Park, Manhattan
 * (0.41 km²: 1.7 MB of OSM JSON, 318 KB package at 1 block per metre); the package also grows with
 * scale squared (it stores per-block rasters).
 */
export function estimateMap(bbox: GeoBBox, scale = 1): MapEstimate {
  const [s, w, n, e] = bbox;
  const midLat = ((s + n) / 2) * (Math.PI / 180);
  const widthM = (e - w) * M_PER_DEG * Math.cos(midLat);
  const depthM = (n - s) * M_PER_DEG;
  const areaKm2 = (widthM * depthM) / 1e6;
  return {
    areaKm2,
    widthBlocks: Math.round(widthM * scale),
    depthBlocks: Math.round(depthM * scale),
    osmBytes: Math.round(areaKm2 * 4.2e6),
    packageBytes: Math.round(areaKm2 * 7.9e5 * scale * scale),
  };
}

/** "1.7 MB" / "318 KB". */
export function formatBytes(bytes: number): string {
  return bytes >= 1e6 ? `${(bytes / 1e6).toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1e3))} KB`;
}
